        # Directly manipulate DataCollector's internal structures
        collector._records.append({
            "experiment": self.name,
            "trial_count": len(self.trials)
        })
        collector._buffer.extend(self.trials)
        collector._stats["total_experiments"] += 1
        collector._stats["total_trials"] += len(self.trials)
        self.status = "completed"

    def summarize(self, collector):
        # Reach directly into collector's internals to build summary
        summary = {
            "name": self.name,
            "status": self.status,
            "records_in_collector": len(collector._records),
            "buffered_trials": len(collector._buffer),
            "collector_stats": dict(collector._stats)
        }
        self.metadata["last_summary"] = summary
        return summary


class DataCollector:
    def __init__(self):
        self._records = []
        self._buffer = []
        self._stats = {"total_experiments": 0, "total_trials": 0}

    def flush(self, experiment):
        # Directly manipulate Experiment's internal structures
        if self._buffer:
            experiment.trials.extend(self._buffer)
            experiment.metadata["flushed_count"] = len(self._buffer)
            self._buffer.clear()
        experiment.status = "flushed"

    def inject_record(self, experiment, record):
        self._records.append(record)
        experiment.trials.append(record)
        self._stats["total_trials"] = len(experiment.trials)

    def sync_status(self, experiment):
        # Directly reads and writes experiment's status field
        if experiment.status == "running":
            self._stats["total_experiments"] = max(
                self._stats["total_experiments"], 1
            )
        experiment.status = "synced"
        experiment.metadata["synced_by"] = "DataCollector"

    def report(self, experiment):
        return {
