        self._log_audit("set_exchange_rate", {"currency": currency, "rate": str(rate)})

    def convert_currency(self, amount, from_currency, to_currency):
        amount = Decimal(amount)
        if from_currency == to_currency:
            return amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        if from_currency not in self.exchange_rates:
            raise ValueError(f"No exchange rate for currency {from_currency}")
        if to_currency not in self.exchange_rates:
            raise ValueError(f"No exchange rate for currency {to_currency}")
        base_amount = amount / self.exchange_rates[from_currency]
        converted = base_amount * self.exchange_rates[to_currency]
        return converted.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

