    def deposit(self, account_id, amount, description="Deposit"):
        amount = Decimal(amount)
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        account = self.get_account(account_id)
        if account.is_frozen:
            raise ComplianceViolationError(f"Account {account_id} is frozen")

        self._check_compliance(TransactionType.DEPOSIT, amount, account)

        tx = self._create_transaction_record(
            TransactionType.DEPOSIT, amount, account.currency,
            destination_account=account, description=description
        )
        account.balance += amount
        tx.status = TransactionStatus.COMPLETED
        self._log_audit("deposit", {
            "account_id": account_id, "amount": str(amount), "transaction_id": tx.transaction_id
        })
        return tx

    def withdraw(self, account_id, amount, description="Withdrawal"):
        amount = Decimal(amount)
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        account = self.get_account(account_id)
        if account.is_frozen:
            raise ComplianceViolationError(f"Account {account_id} is frozen")

        min_balance = self.compliance_rules["min_balance_after_withdrawal"]
        if account.balance - amount < min_balance:
            raise InsufficientFundsError(
                f"Insufficient funds in account {account_id}: balance {account.balance}, "
                f"requested {amount}"
            )

        self._check_compliance(TransactionType.WITHDRAWAL, amount, account)

        tx = self._create_transaction_record(
            TransactionType.WITHDRAWAL, amount, account.currency,
            source_account=account, description=description
