        destination = self.get_account(destination_account_id)

        if source.is_frozen or destination.is_frozen:
            raise ComplianceViolationError("One of the accounts is frozen")

        min_balance = self.compliance_rules["min_balance_after_withdrawal"]
        if source.balance - amount < min_balance:
            raise InsufficientFundsError(
                f"Insufficient funds in account {source_account_id}"
