from abc import ABC, abstractmethod
import math


class Renderer(ABC):
    @abstractmethod
    def render(self, shape):
        pass


class CircleRenderer(Renderer):
    def render(self, shape):
        return f"Rendering Circle at {shape.position} with radius {shape.radius}"


class RectangleRenderer(Renderer):
    def render(self, shape):
        return (f"Rendering Rectangle at {shape.position} with "
                f"width {shape.width} and height {shape.height}")


class TriangleRenderer(Renderer):
    def render(self, shape):
        return (f"Rendering Triangle at {shape.position} with vertices "
                f"{shape.vertices}")


class Shape(ABC):
    def __init__(self, renderer: Renderer, position=(0, 0)):
        self.renderer = renderer
        self.position = position

    @abstractmethod
    def area(self):
        pass

    @abstractmethod
    def perimeter(self):
        pass

    def draw(self):
        return self.renderer.render(self)


class Circle(Shape):
    def __init__(self, radius, position=(0, 0), renderer: Renderer = None):
        super().__init__(renderer or CircleRenderer(), position)
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2

    def perimeter(self):
        return 2 * math.pi * self.radius


class Rectangle(Shape):
    def __init__(self, width, height, position=(0, 0), renderer: Renderer = None):
        super().__init__(renderer or RectangleRenderer(), position)
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)


class Triangle(Shape):
    def __init__(self, vertices, position=(0, 0), renderer: Renderer = None):
        if len(vertices) != 3:
            raise ValueError("A triangle must have exactly 3 vertices")
        super().__init__(renderer or TriangleRenderer(), position)
        self.vertices = vertices

    def _side_lengths(self):
        (x1, y1), (x2, y2), (x3, y3) = self.vertices
        a = math.hypot(x2 - x1, y2 - y1)
        b = math.hypot(x3 - x2, y3 - y2)
        c = math.hypot(x1 - x3, y1 - y3)
        return a, b, c

    def area(self):
        (x1, y1), (x2, y2), (x3, y3) = self.vertices
        return abs((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2)

    def perimeter(self):
        a, b, c = self._side_lengths()
        return a + b + c


if __name__ == "__main__":
    shapes = [
        Circle(radius=5, position=(0, 0)),
        Rectangle(width=4, height=6, position=(1, 1)),
        Triangle(vertices=[(0, 0), (4, 0), (0, 3)], position=(2, 2)),
    ]

    for shape in shapes:
        print(shape.draw())
        print(f"Area: {shape.area():.2f}, Perimeter: {shape.perimeter():.2f}")
        print()
