class ResearchPlatform:
    """High-level façade that drives records through every concern."""

    def __init__(self, registry: Optional[DataTypeRegistry] = None):
        self.registry = registry or default_registry

    def _plugin(self, data_type: str) -> DataTypePlugin:
        return self.registry.get(data_type)

    def ingest(self, data_type: str, metadata: Optional[Dict[str, Any]] = None, **kwargs) -> DataRecord:
        """Create, validate metadata, validate data, check compliance, store."""
        plugin = self._plugin(data_type)
        metadata = metadata or {}

        meta_errors = plugin.metadata_schema.validate_metadata(metadata)
        if meta_errors:
            raise ValidationError(meta_errors)

        record = plugin.data_model.create(**kwargs)
        record.metadata.update(metadata)

        val_errors = plugin.validation_rules.validate(record)
        if val_errors:
            raise ValidationError(val_errors)

        violations = plugin.compliance_checker.check(record)
        if violations:
            raise ComplianceError(violations)

        plugin.storage_adapter.save(record)
        return record

    def process(self, data_type: str, record_id: str) -> DataRecord:
        plugin = self._plugin(data_type)
        record = plugin.storage_adapter.load(record_id)
        if record is None:
            raise PlatformError(f"Record {record_id!r} not found for type {data_type!r}")
        processed = plugin.processing_pipeline.process(record)
        plugin.storage_adapter.save(processed)
        return processed

