class TimeSeriesValidationRules(ValidationRules):
    def validate(self, record: DataRecord) -> List[str]:
        errors = []
        payload = record.payload
        if not isinstance(payload, dict):
            return ["Payload must be a dict"]
        values = payload.get("values")
        timestamps = payload.get("timestamps")
        if values is None or timestamps is None:
            errors.append("Payload must contain 'values' and 'timestamps'")
            return errors
        if len(values) != len(timestamps):
            errors.append("'values' and 'timestamps' must be equal length")
        if not all(isinstance(v, (int, float)) for v in values):
            errors.append("All 'values' must be numeric")
        if len(values) == 0:
            errors.append("Time series must contain at least one point")
        return errors


