    pass


class TimeSeriesProcessingPipeline(ProcessingPipeline):
    def process(self, record: DataRecord) -> DataRecord:
        values = record.payload.get("values", [])
        if values:
            mean = sum(values) / len(values)
            normalized = [v - mean for v in values]
        else:
            mean = 0.0
            normalized = []
        new_payload = dict(record.payload)
        new_payload["normalized_values"] = normalized
        new_payload["mean"] = mean
        return DataRecord(
            record_id=record.record_id,
            data_type=record.data_type,
            payload=new_payload,
            created_at=record.created_at,
            metadata=record.metadata,
        )


class TimeSeriesVisualizationEngine(VisualizationEngine):
    def render(self, record: DataRecord) -> str:
        values = record.payload.get("values", [])
        if not values:
            return "(empty series)"
        lo, hi = min(values), max(values)
        span = (hi - lo) or 1.0
        height = 8
        lines = []
        for level in range(height, 0, -1):
            threshold = lo + (level / height) * span
            row = "".join("*" if v >= threshold else " " for v in values)
            lines.append(row)
        return "\n".join(lines)


