    def supported_formats(self) -> List[str]:
        return ["json", "csv"]

    def export(self, record: DataRecord, fmt: str) -> bytes:
        if fmt == "json":
            return json.dumps(record.payload).encode("utf-8")
        if fmt == "csv":
            timestamps = record.payload.get("timestamps", [])
            values = record.payload.get("values", [])
            lines = ["timestamp,value"]
            for t, v in zip(timestamps, values):
