from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Type


# ---------------------------------------------------------------------------
# Core exceptions
# ---------------------------------------------------------------------------

class PlatformError(Exception):
    """Base exception for the research platform."""


class UnknownDataTypeError(PlatformError):
    def __init__(self, type_name: str):
        super().__init__(f"No data type registered under name: {type_name!r}")
        self.type_name = type_name


class ValidationError(PlatformError):
    def __init__(self, errors: List[str]):
        super().__init__("; ".join(errors) if errors else "Validation failed")
        self.errors = errors


class ComplianceError(PlatformError):
    def __init__(self, violations: List[str]):
        super().__init__("; ".join(violations) if violations else "Compliance check failed")
        self.violations = violations


# ---------------------------------------------------------------------------
# DataModel
# ---------------------------------------------------------------------------

@dataclass
class DataRecord:
    """Generic envelope wrapping a payload of a specific data type."""
    record_id: str
    data_type: str
    payload: Any
    created_at: float = field(default_factory=time.time)
    metadata: Dict[str, Any] = field(default_factory=dict)


class DataModel(abc.ABC):
    """Defines the shape/schema of a data type's payload."""

    data_type: str = "base"

    @abc.abstractmethod
    def create(self, **kwargs) -> DataRecord:
        """Construct a new DataRecord of this type."""

    @abc.abstractmethod
    def to_dict(self, record: DataRecord) -> Dict[str, Any]:
        """Serialize a record's payload to a plain dict."""

    @abc.abstractmethod
    def from_dict(self, data: Dict[str, Any]) -> DataRecord:
        """Reconstruct a DataRecord from a plain dict."""


# ---------------------------------------------------------------------------
# ValidationRules
# ---------------------------------------------------------------------------

class ValidationRules(abc.ABC):
    """Defines validation logic for a data type."""

    @abc.abstractmethod
    def validate(self, record: DataRecord) -> List[str]:
        """Return a list of validation error strings (empty if valid)."""

    def is_valid(self, record: DataRecord) -> bool:
        return len(self.validate(record)) == 0


# ---------------------------------------------------------------------------
# StorageAdapter
# ---------------------------------------------------------------------------

class StorageAdapter(abc.ABC):
    """Defines how a data type is persisted / retrieved."""

    @abc.abstractmethod
    def save(self, record: DataRecord) -> None:
        ...

    @abc.abstractmethod
    def load(self, record_id: str) -> Optional[DataRecord]:
        ...

    @abc.abstractmethod
    def delete(self, record_id: str) -> bool:
        ...

    @abc.abstractmethod
    def list_ids(self) -> List[str]:
        ...


class InMemoryStorageAdapter(StorageAdapter):
    """Convenient in-memory storage adapter reusable by plugins."""

    def __init__(self):
        self._store: Dict[str, DataRecord] = {}

    def save(self, record: DataRecord) -> None:
        self._store[record.record_id] = record

    def load(self, record_id: str) -> Optional[DataRecord]:
        return self._store.get(record_id)

    def delete(self, record_id: str) -> bool:
        return self._store.pop(record_id, None) is not None

    def list_ids(self) -> List[str]:
        return list(self._store.keys())


