        payload = {"sequence": sequence.upper(), "organism": organism}
        return DataRecord(
            record_id=record_id or str(uuid.uuid4()),
            data_type=self.data_type,
            payload=payload,
        )

    def to_dict(self, record: DataRecord) -> Dict[str, Any]:
        return {
            "record_id": record.record_id,
            "data_type": record.data_type,
            "payload": record.payload,
            "created_at": record.created_at,
            "metadata": record.metadata,
        }

    def from_dict(self, data: Dict[str, Any]) -> DataRecord:
        return DataRecord(
            record_id=data["record_id"],
            data_type=data["data_type"],
            payload=data["payload"],
            created_at=data.get("created_at", time.time()),
            metadata=data.get("metadata", {}),
        )


class GenomicSequenceValidationRules(ValidationRules):
    def validate(self, record: DataRecord) -> List[str]:
        errors = []
        seq = record.payload.get("sequence", "")
        if not seq:
            errors.append("Sequence must not be empty")
        invalid_chars = set(seq) - _VALID_BASES
        if invalid_chars:
            errors.append(f"Sequence contains invalid bases: {sorted(invalid_chars)}")
        return errors


class GenomicSequenceStorageAdapter(InMemoryStorageAdapter):
    pass


class GenomicSequenceProcessingPipeline(ProcessingPipeline):
    def process(self, record: DataRecord) -> DataRecord:
        seq = record.payload.get("sequence", "")
        gc_count = sum(1 for c in seq if c in "GC")
        gc_content = (gc_count / len(seq)) if seq else 0.0
        new_payload = dict(record.payload)
        new_payload["gc_content"] = gc_content
        new_payload["length"] = len(seq)
        return DataRecord(
            record_id=record.record_id,
            data_type=record.data_type,
            payload=new_payload,
            created_at=record.created_at,
            metadata=record.metadata,
        )


class GenomicSequenceVisualizationEngine(VisualizationEngine):
    _COLOR_MAP = {"A": "A", "C": "C", "G": "G", "T": "T", "N": "."}

    def render(self, record: DataRecord) -> str:
        seq = record.payload.get("sequence", "")
        wrapped = "\n".join(seq[i:i + 60] for i in range(0, len(seq), 60))
        return wrapped or "(empty sequence)"


class GenomicSequenceExportFormats(ExportFormats):
    def supported_formats(self) -> List[str]:
        return ["fasta", "json"]

    def export(self, record: DataRecord, fmt: str) -> bytes:
        seq = record.payload.get("sequence", "")
        organism = record.payload.get("organism", "unknown")
        if fmt == "fasta":
            header = f">{record.record_id} organism={organism}"
            body = "\n".join(seq[i:i + 70] for i in range(0, len(seq), 70))
            return f"{header}\n{body}\n".encode("utf-8")
        if fmt == "json":
            return json.dumps(record.payload).encode("utf-8")
