"""
E-commerce module implemented with primitive types (strings, floats, ints)
for order_id, total_amount, currency, status, shipping_address fields, and
payment_status, instead of dedicated value objects.
"""

import re
import uuid
from datetime import datetime


VALID_STATUSES = {"pending", "processing", "shipped", "delivered", "cancelled", "refunded"}
VALID_PAYMENT_STATUSES = {"unpaid", "pending", "paid", "failed", "refunded", "partially_refunded"}
VALID_CURRENCIES = {"USD", "EUR", "GBP", "JPY", "CAD", "AUD"}


class OrderError(Exception):
    """Raised for invalid order operations."""
    pass


class Order:
    def __init__(
        self,
        order_id: str = None,
        total_amount: float = 0.0,
        currency: str = "USD",
        status: str = "pending",
        shipping_street: str = "",
        shipping_city: str = "",
        shipping_state: str = "",
        shipping_postal_code: str = "",
        shipping_country: str = "",
        payment_status: str = "unpaid",
    ):
        self.order_id = order_id if order_id else str(uuid.uuid4())
        self.total_amount = self._validate_total_amount(total_amount)
        self.currency = self._validate_currency(currency)
        self.status = self._validate_status(status)

        self.shipping_street = str(shipping_street).strip()
        self.shipping_city = str(shipping_city).strip()
        self.shipping_state = str(shipping_state).strip()
        self.shipping_postal_code = str(shipping_postal_code).strip()
        self.shipping_country = str(shipping_country).strip()

        self.payment_status = self._validate_payment_status(payment_status)

        self.items = []  # list of dicts: {sku, name, quantity, unit_price}
        self.created_at = datetime.utcnow().isoformat()
        self.updated_at = self.created_at

    # ---------------------------
    # Validation helpers
    # ---------------------------
    @staticmethod
    def _validate_total_amount(total_amount) -> float:
        try:
            amount = float(total_amount)
        except (TypeError, ValueError):
            raise OrderError(f"Invalid total_amount: {total_amount!r} is not a valid float")
        if amount < 0:
            raise OrderError(f"total_amount cannot be negative: {amount}")
        return round(amount, 2)

    @staticmethod
    def _validate_currency(currency: str) -> str:
        if not isinstance(currency, str):
            raise OrderError(f"currency must be a string, got {type(currency)}")
        currency = currency.strip().upper()
        if currency not in VALID_CURRENCIES:
            raise OrderError(
                f"Invalid currency: {currency!r}. Must be one of {sorted(VALID_CURRENCIES)}"
            )
        return currency

    @staticmethod
    def _validate_status(status: str) -> str:
        if not isinstance(status, str):
            raise OrderError(f"status must be a string, got {type(status)}")
        status = status.strip().lower()
        if status not in VALID_STATUSES:
            raise OrderError(
                f"Invalid status: {status!r}. Must be one of {sorted(VALID_STATUSES)}"
            )
        return status

    @staticmethod
    def _validate_payment_status(payment_status: str) -> str:
        if not isinstance(payment_status, str):
            raise OrderError(f"payment_status must be a string, got {type(payment_status)}")
        payment_status = payment_status.strip().lower()
        if payment_status not in VALID_PAYMENT_STATUSES:
            raise OrderError(
                f"Invalid payment_status: {payment_status!r}. "
                f"Must be one of {sorted(VALID_PAYMENT_STATUSES)}"
            )
        return payment_status

    @staticmethod
    def _validate_postal_code(postal_code: str) -> bool:
        if not postal_code:
            return False
        return bool(re.match(r"^[A-Za-z0-9\s\-]{3,10}$", postal_code))

    # ---------------------------
    # Shipping address management
    # ---------------------------
    def set_shipping_address(
        self,
        street: str,
        city: str,
        state: str,
        postal_code: str,
        country: str,
    ):
        if not street or not str(street).strip():
            raise OrderError("shipping_street cannot be empty")
        if not city or not str(city).strip():
            raise OrderError("shipping_city cannot be empty")
        if not country or not str(country).strip():
            raise OrderError("shipping_country cannot be empty")
        if not self._validate_postal_code(str(postal_code).strip()):
            raise OrderError(f"Invalid shipping_postal_code: {postal_code!r}")

        self.shipping_street = str(street).strip()
        self.shipping_city = str(city).strip()
        self.shipping_state = str(state).strip()
        self.shipping_postal_code = str(postal_code).strip()
        self.shipping_country = str(country).strip()
        self._touch()

    def get_shipping_address_string(self) -> str:
        parts = [self.shipping_street, self.shipping_city]
        if self.shipping_state:
            parts.append(self.shipping_state)
        if self.shipping_postal_code:
            parts.append(self.shipping_postal_code)
        if self.shipping_country:
            parts.append(self.shipping_country)
        return ", ".join(p for p in parts if p)

    def has_valid_shipping_address(self) -> bool:
        return bool(
            self.shipping_street
            and self.shipping_city
            and self.shipping_country
            and self._validate_postal_code(self.shipping_postal_code)
        )

    # ---------------------------
    # Item management
    # ---------------------------
    def add_item(self, sku: str, name: str, quantity: int, unit_price: float):
        if not isinstance(sku, str) or not sku.strip():
            raise OrderError("sku must be a non-empty string")
        if not isinstance(name, str) or not name.strip():
            raise OrderError("name must be a non-empty string")
        try:
            quantity = int(quantity)
        except (TypeError, ValueError):
            raise OrderError(f"Invalid quantity: {quantity!r}")
        if quantity <= 0:
            raise OrderError("quantity must be a positive integer")
        try:
            unit_price = float(unit_price)
        except (TypeError, ValueError):
            raise OrderError(f"Invalid unit_price: {unit_price!r}")
        if unit_price < 0:
            raise OrderError("unit_price cannot be negative")

        self.items.append(
            {
                "sku": sku.strip(),
                "name": name.strip(),
                "quantity": quantity,
                "unit_price": round(unit_price, 2),
            }
        )
        self._recalculate_total()
        self._touch()

    def remove_item(self, sku: str):
        original_len = len(self.items)
        self.items = [item for item in self.items if item["sku"] != sku]
        if len(self.items) == original_len:
            raise OrderError(f"Item with sku {sku!r} not found in order")
        self._recalculate_total()
        self._touch()

    def _recalculate_total(self):
        total = sum(item["quantity"] * item["unit_price"] for item in self.items)
        self.total_amount = round(total, 2)

    # ---------------------------
    # Status transitions
    # ---------------------------
    def update_status(self, new_status: str):
        new_status = self._validate_status(new_status)

        allowed_transitions = {
            "pending": {"processing", "cancelled"},
            "processing": {"shipped", "cancelled"},
            "shipped": {"delivered", "cancelled"},
            "delivered": {"refunded"},
            "cancelled": set(),
            "refunded": set(),
        }

        if new_status == self.status:
            return

        if new_status not in allowed_transitions.get(self.status, set()):
            raise OrderError(
                f"Cannot transition order status from {self.status!r} to {new_status!r}"
            )

        self.status = new_status
        self._touch()

    def update_payment_status(self, new_payment_status: str):
        new_payment_status = self._validate_payment_status(new_payment_status)
        self.payment_status = new_payment_status
        self._touch()

        if new_payment_status == "paid" and self.status == "pending":
            self.status = "processing"

    def cancel(self):
        if self.status in ("shipped", "delivered"):
            raise OrderError(f"Cannot cancel an order with status {self.status!r}")
        self.status = "cancelled"
        self._touch()

    # ---------------------------
    # Utility
    # ---------------------------
    def _touch(self):
        self.updated_at = datetime.utcnow().isoformat()

    def format_total(self) -> str:
        return f"{self.total_amount:.2f} {self.currency}"

    def to_dict(self) -> dict:
        return {
            "order_id": self.order_id,
            "total_amount": self.total_amount,
            "currency": self.currency,
            "status": self.status,
            "shipping_street": self.shipping_street,
            "shipping_city": self.shipping_city,
            "shipping_state": self.shipping_state,
            "shipping_postal_code": self.shipping_postal_code,
            "shipping_country": self.shipping_country,
            "payment_status": self.payment_status,
            "items": self.items,
            "created_at": self.created_at,
            "updated_at": self.updated_at,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Order":
        order = cls(
            order_id=data.get("order_id"),
            total_amount=data.get("total_amount", 0.0),
            currency=data.get("currency", "USD"),
            status=data.get("status", "pending"),
            shipping_street=data.get("shipping_street", ""),
