def process_checkout(
    cart_items: List[CartItem],
    shipping_address: Address,
    payment_info: Dict[str, Any],
    customer_email: str,
    inventory_service: InventoryService,
    shipping_calculator: Optional[ShippingCalculator] = None,
    tax_calculator: Optional[TaxCalculator] = None,
    payment_processor: Optional[PaymentProcessor] = None,
    email_service: Optional[EmailService] = None,
    analytics_tracker: Optional[AnalyticsTracker] = None,
    order_repository: Optional[OrderRepository] = None,
) -> OrderResult:
    """
    Orchestrates the full e-commerce checkout flow:
    cart validation -> inventory reservation -> shipping calc ->
    tax calc -> payment processing -> order creation -> email -> analytics.

    Rolls back inventory reservation and refunds payment on failure where applicable.
    """
    shipping_calculator = shipping_calculator or ShippingCalculator()
    tax_calculator = tax_calculator or TaxCalculator()
    payment_processor = payment_processor or PaymentProcessor()
    email_service = email_service or EmailService()
    analytics_tracker = analytics_tracker or AnalyticsTracker()
    order_repository = order_repository or OrderRepository()

    reservation_id = None
    transaction_id = None

