    tax_amount: float
    total_amount: float
    payment_transaction_id: str
    reservation_id: str
    created_at: str
    customer_email: str
    metadata: Dict[str, Any] = field(default_factory=dict)


class InventoryService:
    def __init__(self, stock: Dict[str, int]):
        self._stock = stock
        self._reservations: Dict[str, Dict[str, int]] = {}

    def check_availability(self, product_id: str, quantity: int) -> bool:
        return self._stock.get(product_id, 0) >= quantity

    def reserve(self, items: List[CartItem]) -> str:
        for item in items:
            if not self.check_availability(item.product_id, item.quantity):
                raise InventoryError(
                    f"Insufficient stock for product '{item.product_id}'. "
                    f"Requested: {item.quantity}, Available: {self._stock.get(item.product_id, 0)}"
                )
        reservation_id = str(uuid.uuid4())
        reserved = {}
        for item in items:
            self._stock[item.product_id] -= item.quantity
            reserved[item.product_id] = item.quantity
        self._reservations[reservation_id] = reserved
        logger.info(f"Inventory reserved: {reservation_id} -> {reserved}")
        return reservation_id

    def release(self, reservation_id: str) -> None:
        reserved = self._reservations.pop(reservation_id, None)
        if reserved:
            for product_id, qty in reserved.items():
                self._stock[product_id] = self._stock.get(product_id, 0) + qty
            logger.info(f"Inventory released for reservation: {reservation_id}")

    def confirm(self, reservation_id: str) -> None:
        # In a real system, this would finalize the reservation (remove hold state).
        if reservation_id not in self._reservations:
            raise InventoryError(f"Unknown reservation id: {reservation_id}")
        logger.info(f"Inventory reservation confirmed: {reservation_id}")


class ShippingCalculator:
    BASE_RATE = 5.00
    RATE_PER_KG = 2.00
    FREE_SHIPPING_THRESHOLD = 100.00

    def calculate(self, items: List[CartItem], subtotal: float, address: Address) -> float:
        if subtotal >= self.FREE_SHIPPING_THRESHOLD:
            return 0.0

        total_weight = sum(item.weight * item.quantity for item in items)
        cost = self.BASE_RATE + (total_weight * self.RATE_PER_KG)

        # simple international surcharge
        if address.country.upper() != "US":
            cost += 15.00

        return round(cost, 2)


class TaxCalculator:
    TAX_RATES = {
        "US": 0.08,
        "CA": 0.13,
        "GB": 0.20,
        "DE": 0.19,
    }
    DEFAULT_RATE = 0.10

    def calculate(self, subtotal: float, shipping_cost: float, address: Address) -> float:
        rate = self.TAX_RATES.get(address.country.upper(), self.DEFAULT_RATE)
        taxable_amount = subtotal + shipping_cost
        return round(taxable_amount * rate, 2)


class PaymentProcessor:
    def charge(self, payment_info: Dict[str, Any], amount: float) -> str:
        if amount <= 0:
            raise PaymentError("Payment amount must be greater than zero.")

        card_number = payment_info.get("card_number", "")
        if not card_number or len(card_number.replace(" ", "")) < 12:
            raise PaymentError("Invalid card number provided.")

        if payment_info.get("simulate_failure"):
            raise PaymentError("Payment was declined by the processor.")

        transaction_id = f"txn_{uuid.uuid4().hex[:16]}"
        logger.info(f"Payment charged: {transaction_id} for amount {amount}")
        return transaction_id

    def refund(self, transaction_id: str, amount: float) -> None:
        logger.info(f"Payment refunded: {transaction_id} for amount {amount}")


