import uuid
import datetime
import random
import statistics
from enum import Enum
from collections import defaultdict, deque


class Severity(Enum):
    LOW = 1
    MEDIUM = 2
    HIGH = 3
    CRITICAL = 4


class Status(Enum):
    ACTIVE = "active"
    INACTIVE = "inactive"
    MAINTENANCE = "maintenance"
    FAULT = "fault"


def _now():
    return datetime.datetime.utcnow()


def _new_id(prefix="id"):
    return f"{prefix}-{uuid.uuid4().hex[:10]}"


class TrafficSystem:
    def __init__(self):
        self.intersections = {}
        self.sensors = {}
        self.incidents = {}
        self.history = deque(maxlen=5000)

    def add_intersection(self, name, location):
        iid = _new_id("isec")
        self.intersections[iid] = {
            "name": name,
            "location": location,
            "signal_state": "red",
            "cycle": ["green", "yellow", "red"],
            "cycle_index": 0,
            "status": Status.ACTIVE,
            "vehicle_count": 0,
        }
        return iid

    def add_sensor(self, intersection_id, sensor_type="flow"):
        if intersection_id not in self.intersections:
            raise ValueError("Unknown intersection")
        sid = _new_id("sensor")
        self.sensors[sid] = {
            "intersection_id": intersection_id,
            "type": sensor_type,
            "status": Status.ACTIVE,
            "last_reading": 0,
        }
        return sid

    def report_sensor_reading(self, sensor_id, value):
        if sensor_id not in self.sensors:
            raise ValueError("Unknown sensor")
        self.sensors[sensor_id]["last_reading"] = value
        isec = self.sensors[sensor_id]["intersection_id"]
        self.intersections[isec]["vehicle_count"] = value
        self.history.append((_now(), sensor_id, value))
        self._adaptive_signal_control(isec)

    def _adaptive_signal_control(self, intersection_id):
        isec = self.intersections[intersection_id]
        if isec["vehicle_count"] > 50:
            isec["signal_state"] = "green"
        elif isec["vehicle_count"] > 20:
            isec["signal_state"] = "yellow"
        else:
            isec["signal_state"] = "red"

    def cycle_signal(self, intersection_id):
        isec = self.intersections[intersection_id]
        isec["cycle_index"] = (isec["cycle_index"] + 1) % len(isec["cycle"])
        isec["signal_state"] = isec["cycle"][isec["cycle_index"]]
        return isec["signal_state"]

    def report_incident(self, location, severity: Severity, description=""):
        incident_id = _new_id("incident")
        self.incidents[incident_id] = {
            "location": location,
            "severity": severity,
            "description": description,
            "timestamp": _now(),
            "resolved": False,
        }
        return incident_id

    def resolve_incident(self, incident_id):
        if incident_id in self.incidents:
            self.incidents[incident_id]["resolved"] = True
            return True
        return False

    def get_congestion_report(self):
        report = {}
        for iid, isec in self.intersections.items():
            report[iid] = {
                "name": isec["name"],
                "vehicle_count": isec["vehicle_count"],
                "signal_state": isec["signal_state"],
            }
        return report

    def active_incidents(self):
        return {k: v for k, v in self.incidents.items() if not v["resolved"]}


class EnergyGrid:
    def __init__(self):
        self.plants = {}
        self.substations = {}
        self.consumers = {}
        self.total_generated = 0.0
        self.total_consumed = 0.0
        self.load_history = deque(maxlen=5000)

    def add_plant(self, name, capacity_mw, source_type="grid"):
        pid = _new_id("plant")
        self.plants[pid] = {
            "name": name,
            "capacity_mw": capacity_mw,
            "source_type": source_type,
            "current_output": 0.0,
            "status": Status.ACTIVE,
        }
        return pid

    def set_plant_output(self, plant_id, output_mw):
        if plant_id not in self.plants:
            raise ValueError("Unknown plant")
        plant = self.plants[plant_id]
        output_mw = max(0.0, min(output_mw, plant["capacity_mw"]))
        plant["current_output"] = output_mw
        self._recalculate_totals()
        return output_mw

    def add_substation(self, name, capacity_mw):
        sid = _new_id("sub")
        self.substations[sid] = {"name": name, "capacity_mw": capacity_mw, "load": 0.0}
        return sid

    def add_consumer(self, name, consumer_type="residential"):
        cid = _new_id("consumer")
        self.consumers[cid] = {"name": name, "type": consumer_type, "usage_kwh": 0.0}
        return cid

    def record_consumption(self, consumer_id, usage_kwh):
        if consumer_id not in self.consumers:
            raise ValueError("Unknown consumer")
        self.consumers[consumer_id]["usage_kwh"] += usage_kwh
        self.total_consumed += usage_kwh
        self.load_history.append((_now(), consumer_id, usage_kwh))
        self._check_grid_stability()

    def _recalculate_totals(self):
        self.total_generated = sum(p["current_output"] for p in self.plants.values())

    def _check_grid_stability(self):
        capacity = sum(p["capacity_mw"] for p in self.plants.values()) * 1000
        if self.total_consumed > capacity * 0.95:
            return "warning: near capacity"
        return "stable"

    def grid_status(self):
        return {
            "total_generated_mw": self.total_generated,
            "total_consumed_kwh": self.total_consumed,
            "plants": len(self.plants),
            "substations": len(self.substations),
            "stability": self._check_grid_stability(),
        }

    def renewable_percentage(self):
        total = sum(p["current_output"] for p in self.plants.values())
        if total == 0:
            return 0.0
        renewable = sum(
            p["current_output"] for p in self.plants.values()
            if p["source_type"] in ("solar", "wind", "hydro")
        )
        return (renewable / total) * 100


