            "to_zone": to_zone,
            "flow_rate": flow_rate,
            "status": Status.ACTIVE,
        }
        return pid

    def consume_water(self, reservoir_id, liters):
        if reservoir_id not in self.reservoirs:
            raise ValueError("Unknown reservoir")
        res = self.reservoirs[reservoir_id]
        res["current_level"] = max(0.0, res["current_level"] - liters)
        return res["current_level"]

    def replenish(self, reservoir_id, liters):
        if reservoir_id not in self.reservoirs:
            raise ValueError("Unknown reservoir")
        res = self.reservoirs[reservoir_id]
        res["current_level"] = min(res["capacity_liters"], res["current_level"] + liters)
        return res["current_level"]

    def report_quality(self, reservoir_id, ph, contaminants_ppm):
        self.quality_reports.append({
            "reservoir_id": reservoir_id,
            "ph": ph,
            "contaminants_ppm": contaminants_ppm,
            "timestamp": _now(),
        })
        if ph < 6.5 or ph > 8.5 or contaminants_ppm > 10:
            return self.raise_leak_alert(reservoir_id, "quality_issue")
        return "ok"

    def raise_leak_alert(self, pipeline_or_reservoir_id, reason="leak"):
        alert_id = _new_id("alert")
        self.leak_alerts[alert_id] = {
            "target": pipeline_or_reservoir_id,
            "reason": reason,
            "timestamp": _now(),
            "resolved": False,
        }
        return alert_id

    def resolve_alert(self, alert_id):
        if alert_id in self.leak_alerts:
            self.leak_alerts[alert_id]["resolved"] = True
            return True
        return False

    def reservoir_levels(self):
        return {
            rid: {
                "name": r["name"],
                "percent_full": (r["current_level"] / r["capacity_liters"] * 100)
                if r["capacity_liters"] else 0,
            }
            for rid, r in self.reservoirs.items()
        }


class WasteCollection:
    def __init__(self):
        self.bins = {}
        self.routes = {}
        self.vehicles = {}
        self.collection_log = deque(maxlen=5000)

    def add_bin(self, location, capacity_liters=1000):
        bid = _new_id("bin")
        self.bins[bid] = {
            "location": location,
            "capacity_liters": capacity_liters,
            "fill_level": 0.0,
            "status": Status.ACTIVE,
        }
        return bid

    def report_fill_level(self, bin_id, fill_percent):
        if bin_id not in self.bins:
            raise ValueError("Unknown bin")
        self.bins[bin_id]["fill_level"] = max(0.0, min(100.0, fill_percent))
        return self.bins[bin_id]["fill_level"]

    def add_vehicle(self, plate_number, capacity_liters):
        vid = _new_id("vehicle")
        self.vehicles[vid] = {
            "plate_number": plate_number,
            "capacity_liters": capacity_liters,
            "load": 0.0,
            "status": Status.ACTIVE,
        }
        return vid

    def create_route(self, name, bin_ids, vehicle_id):
        rid = _new_id("route")
        self.routes[rid] = {
            "name": name,
            "bin_ids": list(bin_ids),
            "vehicle_id": vehicle_id,
            "completed": False,
        }
        return rid

    def optimize_routes(self, threshold_percent=70):
        needing_collection = [bid for bid, b in self.bins.items() if b["fill_level"] >= threshold_percent]
        return needing_collection

    def collect_route(self, route_id):
        if route_id not in self.routes:
            raise ValueError("Unknown route")
        route = self.routes[route_id]
        for bid in route["bin_ids"]:
            if bid in self.bins:
                self.bins[bid]["fill_level"] = 0.0
                self.collection_log.append((_now(), bid, route_id))
        route["completed"] = True
        return True

    def bins_needing_attention(self, threshold=85):
        return {bid: b for bid, b in self.bins.items() if b["fill_level"] >= threshold}


