class EligibilityChecker:
    """
    Determines whether a patient's claim is eligible for processing.
    Each insurance type may have distinct eligibility logic, so this
    class must be updated whenever a new insurance type is added.
    """

    def check_eligibility(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        if not patient.is_active_member:
            return False, "Patient membership is inactive"

        if patient.insurance_type == InsuranceType.PRIVATE:
            return self._check_private(patient, claim)
        elif patient.insurance_type == InsuranceType.MEDICARE:
            return self._check_medicare(patient, claim)
        elif patient.insurance_type == InsuranceType.MEDICAID:
            return self._check_medicaid(patient, claim)
        elif patient.insurance_type == InsuranceType.HMO:
            return self._check_hmo(patient, claim)
        elif patient.insurance_type == InsuranceType.PPO:
            return self._check_ppo(patient, claim)
        else:
            return False, f"Unsupported insurance type: {patient.insurance_type}"

    def _check_private(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        for service in claim.services:
            if service.requires_preauth and not claim.preauth_obtained:
                return False, f"Preauthorization required for {service.code}"
        return True, None

    def _check_medicare(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        age = self._calculate_age(patient.date_of_birth, claim.date_of_service)
        if age < 65:
            return False, "Patient does not meet Medicare age requirement"
        return True, None

    def _check_medicaid(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        # Medicaid generally covers all in-network services without preauth
        return True, None

    def _check_hmo(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        if Coverage.requires_referral(patient.insurance_type) and not patient.referral_on_file:
            return False, "HMO requires referral on file"
        return True, None

    def _check_ppo(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        for service in claim.services:
            if service.requires_preauth and not claim.preauth_obtained:
                return False, f"Preauthorization required for {service.code}"
        return True, None

    @staticmethod
    def _calculate_age(dob: date, as_of: date) -> int:
        years = as_of.year - dob.year
        if (as_of.month, as_of.day) < (dob.month, dob.day):
            years -= 1
        return years


