    def submit_order(self, order: Order, current_price: float) -> Order:
        if order.quantity <= 0:
            order.status = OrderStatus.REJECTED
            order.rejection_reason = "Non-positive quantity"
            self.order_book[order.order_id] = order
            return order

        slip_factor = 1 + (self.slippage_bps / 10000.0) * (
            1 if order.side == OrderSide.BUY else -1
        )
        exec_price = round(current_price * slip_factor, 4)

        # Simulate partial fill: fill a portion now, rest may remain open
        fill_qty = round(order.quantity * self.fill_ratio, 4)
        fill_qty = min(fill_qty, order.quantity)
