class Indicators:

    @staticmethod
    def sma(prices: List[float], period: int) -> Optional[float]:
        if len(prices) < period:
            return None
        return sum(prices[-period:]) / period

    @staticmethod
    def ema(prices: List[float], period: int) -> Optional[float]:
        if len(prices) < period:
            return None
        k = 2 / (period + 1)
        ema_val = prices[0]
        for p in prices[1:]:
            ema_val = p * k + ema_val * (1 - k)
        return ema_val

    @staticmethod
    def rsi(prices: List[float], period: int = 14) -> Optional[float]:
        if len(prices) < period + 1:
            return None
        gains, losses = [], []
        for i in range(-period, 0):
            delta = prices[i] - prices[i - 1]
            if delta >= 0:
                gains.append(delta)
            else:
                losses.append(abs(delta))
        avg_gain = sum(gains) / period
        avg_loss = sum(losses) / period
        if avg_loss == 0:
            return 100.0
        rs = avg_gain / avg_loss
        return 100 - (100 / (1 + rs))

    @staticmethod
    def macd(prices: List[float], fast: int = 12, slow: int = 26, signal: int = 9):
        if len(prices) < slow + signal:
            return None, None, None
        ema_fast = Indicators.ema(prices, fast)
        ema_slow = Indicators.ema(prices, slow)
        if ema_fast is None or ema_slow is None:
            return None, None, None
        macd_line = ema_fast - ema_slow
        macd_series = []
        for i in range(slow, len(prices) + 1):
            sub = prices[:i]
            ef = Indicators.ema(sub, fast)
            es = Indicators.ema(sub, slow)
            if ef is not None and es is not None:
                macd_series.append(ef - es)
        signal_line = Indicators.ema(macd_series, signal) if len(macd_series) >= signal else None
        histogram = macd_line - signal_line if signal_line is not None else None
        return macd_line, signal_line, histogram

    @staticmethod
    def bollinger_bands(prices: List[float], period: int = 20, num_std: float = 2.0):
        if len(prices) < period:
            return None, None, None
        window = prices[-period:]
        mean = sum(window) / period
        std = statistics.pstdev(window)
        upper = mean + num_std * std
        lower = mean - num_std * std
        return upper, mean, lower

    @staticmethod
    def atr(bars: List[MarketDataPoint], period: int = 14) -> Optional[float]:
        if len(bars) < period + 1:
            return None
        trs = []
        for i in range(1, len(bars)):
            high, low, prev_close = bars[i].high, bars[i].low, bars[i - 1].close
            tr = max(high - low, abs(high - prev_close), abs(low - prev_close))
            trs.append(tr)
        return sum(trs[-period:]) / period


