class Portfolio:
    def __init__(self, starting_cash: float = 1_000_000.0):
        self.cash = starting_cash
        self.starting_equity = starting_cash
        self.positions: Dict[str, Position] = {}

    def get_position(self, symbol: str) -> Position:
        return self.positions.setdefault(symbol, Position(symbol=symbol))

    def apply_fill(self, symbol: str, side: OrderSide, qty: float, price: float):
        pos = self.get_position(symbol)
        signed_qty = qty if side == OrderSide.BUY else -qty
        notional = qty * price

        if side == OrderSide.BUY:
            self.cash -= notional
        else:
            self.cash += notional

        if pos.quantity == 0 or (pos.quantity > 0) == (signed_qty > 0):
            new_qty = pos.quantity + signed_qty
            if new_qty != 0:
                pos.avg_price = (
                    (pos.avg_price * abs(pos.quantity) + price * abs(signed_qty))
                    / abs(new_qty)
                )
            pos.quantity = new_qty
        else:
            closing_qty = min(abs(signed_qty), abs(pos.quantity))
            realized = closing_qty * (price - pos.avg_price) * (1 if pos.quantity > 0 else -1)
            pos.realized_pnl += realized
            pos.quantity += signed_qty
            if abs(pos.quantity) < 1e-9:
                pos.quantity = 0.0
                pos.avg_price = 0.0
            elif (pos.quantity > 0) != (signed_qty > 0) and abs(signed_qty) > closing_qty:
                pos.avg_price = price

        self.positions[symbol] = pos

    def total_equity(self, price_map: Dict[str, float]) -> float:
        equity = self.cash
        for sym, pos in self.positions.items():
            price = price_map.get(sym, pos.avg_price)
            equity += pos.market_value(price)
        return equity

    def total_exposure(self, price_map: Dict[str, float]) -> float:
        exposure = 0.0
        for sym, pos in self.positions.items():
            price = price_map.get(sym, pos.avg_price)
            exposure += abs(pos.market_value(price))
        return exposure

    def reconcile(self, broker: SimulatedBroker) -> List[Dict[str, Any]]:
        discrepancies = []
        all_symbols = set(self.positions.keys()) | set(broker.broker_positions.keys())
        for sym in all_symbols:
            local_pos = self.get_position(sym)
            broker_pos = broker.get_broker_position(sym)
            qty_diff = round(local_pos.quantity - broker_pos.quantity, 6)
            price_diff = round(local_pos.avg_price - broker_pos.avg_price, 6)
            if abs(qty_diff) > 1e-6 or abs(price_diff) > 1e-4:
                discrepancies.append({
                    "symbol": sym,
                    "local_quantity": local_pos.quantity,
                    "broker_quantity": broker_pos.quantity,
                    "quantity_diff": qty_diff,
                    "local_avg_price": local_pos.avg_price,
                    "broker_avg_price": broker_pos.avg_price,
                    "avg_price_diff": price_diff,
                })
        return discrepancies


