import uuid
import math
import statistics
from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from typing import List, Dict, Optional, Any


# ----------------------------------------------------------------------------
# Enums
# ----------------------------------------------------------------------------

class OrderSide(Enum):
    BUY = "BUY"
    SELL = "SELL"


class OrderStatus(Enum):
    NEW = "NEW"
    PARTIALLY_FILLED = "PARTIALLY_FILLED"
    FILLED = "FILLED"
    REJECTED = "REJECTED"
    CANCELLED = "CANCELLED"


class SignalType(Enum):
    BUY = "BUY"
    SELL = "SELL"
    HOLD = "HOLD"


# ----------------------------------------------------------------------------
# Data classes
# ----------------------------------------------------------------------------

@dataclass
class MarketDataPoint:
    symbol: str
    timestamp: datetime
    open: float
    high: float
    low: float
    close: float
    volume: float


@dataclass
class Order:
    order_id: str
    symbol: str
    side: OrderSide
    quantity: float
    price: float
    status: OrderStatus = OrderStatus.NEW
    filled_quantity: float = 0.0
    avg_fill_price: float = 0.0
    fills: List[Dict[str, Any]] = field(default_factory=list)
    created_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    updated_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    rejection_reason: Optional[str] = None


@dataclass
class Position:
    symbol: str
    quantity: float = 0.0
    avg_price: float = 0.0
    realized_pnl: float = 0.0

    def market_value(self, price: float) -> float:
        return self.quantity * price

    def unrealized_pnl(self, price: float) -> float:
        return (price - self.avg_price) * self.quantity if self.quantity else 0.0


# ----------------------------------------------------------------------------
# Simulated Broker Interface
# ----------------------------------------------------------------------------

class SimulatedBroker:
    """
    Simulates a broker execution venue with partial fill behavior
    and an independent record of positions for reconciliation purposes.
    """

    def __init__(self, fill_ratio: float = 0.7, slippage_bps: float = 2.0):
        self.fill_ratio = fill_ratio
        self.slippage_bps = slippage_bps
        self.broker_positions: Dict[str, Position] = {}
        self.order_book: Dict[str, Order] = {}

    def submit_order(self, order: Order, current_price: float) -> Order:
        if order.quantity <= 0:
            order.status = OrderStatus.REJECTED
            order.rejection_reason = "Non-positive quantity"
            self.order_book[order.order_id] = order
            return order

        slip_factor = 1 + (self.slippage_bps / 10000.0) * (
            1 if order.side == OrderSide.BUY else -1
        )
        exec_price = round(current_price * slip_factor, 4)

        # Simulate partial fill: fill a portion now, rest may remain open
        fill_qty = round(order.quantity * self.fill_ratio, 4)
        fill_qty = min(fill_qty, order.quantity)
        if fill_qty <= 0:
            fill_qty = order.quantity  # ensure at least a full fill if ratio rounds to 0

        order.fills.append({
            "quantity": fill_qty,
            "price": exec_price,
            "timestamp": datetime.now(timezone.utc),
        })
        order.filled_quantity += fill_qty
        total_notional = sum(f["quantity"] * f["price"] for f in order.fills)
        order.avg_fill_price = (
            total_notional / order.filled_quantity if order.filled_quantity else 0.0
        )

        if order.filled_quantity >= order.quantity - 1e-9:
            order.status = OrderStatus.FILLED
        else:
            order.status = OrderStatus.PARTIALLY_FILLED

        order.updated_at = datetime.now(timezone.utc)
        self.order_book[order.order_id] = order
        self._update_broker_position(order, fill_qty, exec_price)
        return order

    def try_fill_remaining(self, order: Order) -> Order:
        """Attempt to fill any remaining quantity on a resting order."""
        if order.status not in (OrderStatus.NEW, OrderStatus.PARTIALLY_FILLED):
            return order

        remaining = order.quantity - order.filled_quantity
        if remaining <= 1e-9:
            order.status = OrderStatus.FILLED
            return order

        last_price = order.fills[-1]["price"] if order.fills else order.price
        fill_qty = remaining  # complete the rest
        order.fills.append({
            "quantity": fill_qty,
            "price": last_price,
            "timestamp": datetime.now(timezone.utc),
        })
        order.filled_quantity += fill_qty
        total_notional = sum(f["quantity"] * f["price"] for f in order.fills)
        order.avg_fill_price = total_notional / order.filled_quantity
        order.status = OrderStatus.FILLED
        order.updated_at = datetime.now(timezone.utc)
        self._update_broker_position(order, fill_qty, last_price)
        return order

    def _update_broker_position(self, order: Order, qty: float, price: float):
        pos = self.broker_positions.setdefault(order.symbol, Position(symbol=order.symbol))
        signed_qty = qty if order.side == OrderSide.BUY else -qty

        if pos.quantity == 0 or (pos.quantity > 0) == (signed_qty > 0):
            new_qty = pos.quantity + signed_qty
            if new_qty != 0:
                pos.avg_price = (
                    (pos.avg_price * abs(pos.quantity) + price * abs(signed_qty))
                    / abs(new_qty)
                )
            pos.quantity = new_qty
        else:
            closing_qty = min(abs(signed_qty), abs(pos.quantity))
            realized = closing_qty * (price - pos.avg_price) * (1 if pos.quantity > 0 else -1)
            pos.realized_pnl += realized
            pos.quantity += signed_qty
            if abs(pos.quantity) < 1e-9:
                pos.quantity = 0.0
                pos.avg_price = 0.0
            elif (pos.quantity > 0) != (signed_qty > 0) and abs(signed_qty) > closing_qty:
                pos.avg_price = price

        self.broker_positions[order.symbol] = pos

    def get_broker_position(self, symbol: str) -> Position:
        return self.broker_positions.get(symbol, Position(symbol=symbol))


# ----------------------------------------------------------------------------
# Indicator Calculations
# ----------------------------------------------------------------------------

class Indicators:

    @staticmethod
    def sma(prices: List[float], period: int) -> Optional[float]:
        if len(prices) < period:
            return None
        return sum(prices[-period:]) / period

    @staticmethod
    def ema(prices: List[float], period: int) -> Optional[float]:
        if len(prices) < period:
            return None
        k = 2 / (period + 1)
        ema_val = prices[0]
        for p in prices[1:]:
            ema_val = p * k + ema_val * (1 - k)
        return ema_val

    @staticmethod
    def rsi(prices: List[float], period: int = 14) -> Optional[float]:
        if len(prices) < period + 1:
            return None
        gains, losses = [], []
        for i in range(-period, 0):
            delta = prices[i] - prices[i - 1]
            if delta >= 0:
                gains.append(delta)
            else:
                losses.append(abs(delta))
        avg_gain = sum(gains) / period
        avg_loss = sum(losses) / period
        if avg_loss == 0:
            return 100.0
        rs = avg_gain / avg_loss
        return 100 - (100 / (1 + rs))

    @staticmethod
    def macd(prices: List[float], fast: int = 12, slow: int = 26, signal: int = 9):
        if len(prices) < slow + signal:
            return None, None, None
        ema_fast = Indicators.ema(prices, fast)
        ema_slow = Indicators.ema(prices, slow)
        if ema_fast is None or ema_slow is None:
            return None, None, None
        macd_line = ema_fast - ema_slow
        macd_series = []
        for i in range(slow, len(prices) + 1):
            sub = prices[:i]
            ef = Indicators.ema(sub, fast)
            es = Indicators.ema(sub, slow)
            if ef is not None and es is not None:
                macd_series.append(ef - es)
        signal_line = Indicators.ema(macd_series, signal) if len(macd_series) >= signal else None
        histogram = macd_line - signal_line if signal_line is not None else None
        return macd_line, signal_line, histogram

    @staticmethod
    def bollinger_bands(prices: List[float], period: int = 20, num_std: float = 2.0):
        if len(prices) < period:
            return None, None, None
        window = prices[-period:]
        mean = sum(window) / period
        std = statistics.pstdev(window)
        upper = mean + num_std * std
        lower = mean - num_std * std
        return upper, mean, lower

    @staticmethod
    def atr(bars: List[MarketDataPoint], period: int = 14) -> Optional[float]:
        if len(bars) < period + 1:
            return None
        trs = []
        for i in range(1, len(bars)):
            high, low, prev_close = bars[i].high, bars[i].low, bars[i - 1].close
            tr = max(high - low, abs(high - prev_close), abs(low - prev_close))
            trs.append(tr)
        return sum(trs[-period:]) / period


