class RiskManager:
    def __init__(
        self,
        max_position_pct: float = 0.10,
        max_total_exposure_pct: float = 0.60,
        stop_loss_pct: float = 0.05,
        max_order_value: float = 100000.0,
    ):
        self.max_position_pct = max_position_pct
        self.max_total_exposure_pct = max_total_exposure_pct
        self.stop_loss_pct = stop_loss_pct
        self.max_order_value = max_order_value

    def calculate_position_size(
        self, equity: float, price: float, volatility: Optional[float]
    ) -> float:
        if price <= 0 or equity <= 0:
            return 0.0
        base_allocation = equity * self.max_position_pct
        if volatility and volatility > 0:
            vol_adjustment = min(1.0, 1.0 / (1 + volatility))
            base_allocation *= vol_adjustment
        qty = base_allocation / price
        return max(0.0, math.floor(qty * 100) / 100)

    def check_stop_loss(self, position: Position, current_price: float) -> bool:
        if position.quantity == 0 or position.avg_price == 0:
            return False
        if position.quantity > 0:
            drawdown = (position.avg_price - current_price) / position.avg_price
        else:
            drawdown = (current_price - position.avg_price) / position.avg_price
        return drawdown >= self.stop_loss_pct

    def validate_order(
        self,
        order_value: float,
        current_exposure: float,
        equity: float,
    ) -> (bool, Optional[str]):
        if order_value > self.max_order_value:
            return False, f"Order value {order_value:.2f} exceeds max order value {self.max_order_value:.2f}"
        if equity <= 0:
            return False, "Non-positive equity"
        projected_exposure = current_exposure + order_value
        if projected_exposure > equity * self.max_total_exposure_pct:
            return False, (
                f"Projected exposure {projected_exposure:.2f} exceeds "
                f"max allowed {equity * self.max_total_exposure_pct:.2f}"
            )
        return True, None


