# ---------------------------------------------------------------------------
# STOCK ORDER VALIDATION
# ---------------------------------------------------------------------------

def stock_order_validation(
    account: Account,
    symbol: str,
    side: str,
    quantity: float,
    order_type: str,
    limit_price: Optional[float] = None,
    stop_price: Optional[float] = None,
    time_in_force: str = "DAY",
    current_market_price: Optional[float] = None,
    existing_positions: Optional[List[Position]] = None,
    current_time: Optional[datetime.datetime] = None,
) -> ValidationResult:
    """Full validation pipeline for equity orders."""
    result = ValidationResult(is_valid=True)
    existing_positions = existing_positions or []
    now = current_time or datetime.datetime.utcnow()

    # -----------------------------------------------------------------
    # 1. Account verification
    # -----------------------------------------------------------------
    if account is None:
        result.add_error("Account not found.")
        return result

    if not account.kyc_verified:
        result.add_error("Account has not completed KYC verification.")

    if account.status == "CLOSED":
        result.add_error("Account is closed and cannot trade.")
    elif account.status == "SUSPENDED":
        result.add_error("Account is suspended.")
    elif account.status != "ACTIVE":
        result.add_error(f"Account status '{account.status}' is not eligible to trade.")

    if not account.account_id or not isinstance(account.account_id, str):
        result.add_error("Invalid account ID.")

    if account.daily_trade_count >= account.daily_trade_limit:
        result.add_error("Daily trade limit exceeded for this account.")

    # -----------------------------------------------------------------
    # 2. Basic order field validation
    # -----------------------------------------------------------------
    if not symbol or not re.match(r"^[A-Z.]{1,10}$", symbol or ""):
        result.add_error("Invalid stock symbol format.")

    if symbol in account.restricted_securities:
        result.add_error(f"Symbol {symbol} is restricted on this account.")

    if side not in VALID_SIDES:
        result.add_error(f"Invalid order side: {side}")

    if quantity is None or quantity <= 0:
        result.add_error("Quantity must be a positive number.")
    elif quantity != int(quantity):
        result.add_error("Stock order quantity must be a whole number of shares.")

    if order_type not in VALID_ORDER_TYPES:
        result.add_error(f"Invalid order type: {order_type}")

    if time_in_force not in VALID_TIME_IN_FORCE:
        result.add_error(f"Invalid time in force: {time_in_force}")

    if order_type in ("LIMIT", "STOP_LIMIT"):
        if limit_price is None or limit_price <= 0:
            result.add_error("Limit price must be provided and positive for LIMIT/STOP_LIMIT orders.")

    if order_type in ("STOP", "STOP_LIMIT"):
        if stop_price is None or stop_price <= 0:
            result.add_error("Stop price must be provided and positive for STOP/STOP_LIMIT orders.")

    if not result.is_valid:
        return result

    # -----------------------------------------------------------------
    # 3. Market hours check
    # -----------------------------------------------------------------
    local_time = now.time()
    is_market_hours = MARKET_OPEN <= local_time <= MARKET_CLOSE
    is_weekday = now.weekday() < 5
    if not (is_market_hours and is_weekday):
        if time_in_force == "IOC" or time_in_force == "FOK":
            result.add_error("IOC/FOK orders cannot be placed outside market hours.")
        else:
            result.add_warning("Order placed outside regular market hours; will queue for next session.")

    # -----------------------------------------------------------------
    # 4. Order value / notional calculation
    # -----------------------------------------------------------------
    ref_price = limit_price or stop_price or current_market_price
    if ref_price is None or ref_price <= 0:
        result.add_error("Unable to determine reference price for order valuation.")
        return result

    notional_value = ref_price * quantity

    if notional_value > account.max_order_value:
        result.add_error(
            f"Order notional value {notional_value:.2f} exceeds max allowed order value "
            f"{account.max_order_value:.2f}."
        )

    # -----------------------------------------------------------------
    # 5. Margin checks
    # -----------------------------------------------------------------
    existing_qty = sum(p.quantity for p in existing_positions if p.symbol == symbol)

    if side == "BUY":
        if account.account_type == "CASH":
            if notional_value > account.cash_balance:
                result.add_error(
                    f"Insufficient cash balance. Required: {notional_value:.2f}, "
                    f"available: {account.cash_balance:.2f}."
                )
        else:  # MARGIN account
            required_margin = notional_value * 0.5  # Reg T initial margin 50%
            result.required_margin = required_margin
            if required_margin > account.buying_power:
                result.add_error(
                    f"Insufficient buying power for margin purchase. Required: "
                    f"{required_margin:.2f}, available: {account.buying_power:.2f}."
                )

    elif side == "SELL":
        if existing_qty < quantity:
            result.add_error(
                f"Cannot sell {quantity} shares of {symbol}; only {existing_qty} held."
            )

    elif side == "SELL_SHORT":
        if account.account_type != "MARGIN":
            result.add_error("Short selling requires a margin account.")
        else:
            required_margin = notional_value * 1.5  # 150% margin requirement for shorts
            result.required_margin = required_margin
            if required_margin > account.buying_power:
                result.add_error(
                    f"Insufficient buying power for short sale. Required: "
                    f"{required_margin:.2f}, available: {account.buying_power:.2f}."
                )

    elif side == "BUY_TO_COVER":
        short_qty = sum(-p.quantity for p in existing_positions if p.symbol == symbol and p.quantity < 0)
        if short_qty < quantity:
            result.add_error(
                f"Cannot buy to cover {quantity} shares of {symbol}; only {short_qty} short."
            )

    # -----------------------------------------------------------------
    # 6. Pattern Day Trader (PDT) rule
    # -----------------------------------------------------------------
    if account.is_pattern_day_trader and account.equity < 25000:
        result.add_error("PDT accounts must maintain minimum equity of $25,000.")

    if not account.is_pattern_day_trader and account.day_trades_count >= 3 and account.equity < 25000:
        result.add_warning(
            "Account is approaching PDT day trade limit (3 day trades in 5 business days)."
        )

    # -----------------------------------------------------------------
    # 7. Risk assessment
    # -----------------------------------------------------------------
    risk_points = 0
    if notional_value > 100_000:
        risk_points += 30
    elif notional_value > 25_000:
        risk_points += 15
    elif notional_value > 5_000:
        risk_points += 5

    if account.risk_score > 70:
        risk_points += 25
    elif account.risk_score > 40:
        risk_points += 10

    if side in ("SELL_SHORT",):
        risk_points += 20

    if order_type == "MARKET":
        risk_points += 5

    concentration = 0.0
    if account.equity > 0:
        concentration = notional_value / account.equity
        if concentration > 0.5:
            risk_points += 20
            result.add_warning(
                f"Order represents {concentration*100:.1f}% of account equity — high concentration risk."
            )

    if risk_points >= 60:
        result.risk_level = "CRITICAL"
        result.add_warning("Order flagged as CRITICAL risk; manual review recommended.")
    elif risk_points >= 40:
        result.risk_level = "HIGH"
    elif risk_points >= 20:
        result.risk_level = "MEDIUM"
    else:
        result.risk_level = "LOW"

    # -----------------------------------------------------------------
    # 8. Compliance rules
    # -----------------------------------------------------------------
    if symbol.upper() in {"OTCX", "PENNYSTOCK"}:
        result.add_error("Trading in this security is prohibited by compliance policy.")

    if ref_price < 1.00 and notional_value > 10_000:
        result.add_warning("Large penny-stock order flagged for compliance review.")

    if account.day_trades_count > 0 and side in ("SELL", "SELL_SHORT") and existing_qty == 0:
        result.add_warning("Potential naked/day-trade pattern flagged for surveillance.")

    return result


# ---------------------------------------------------------------------------
# OPTIONS ORDER VALIDATION
# ---------------------------------------------------------------------------

def options_order_validation(
    account: Account,
    option_symbol: str,
    underlying_symbol: str,
    side: str,
    contracts: int,
    order_type: str,
    strategy: str = "LONG_CALL",
    limit_price: Optional[float] = None,
    stop_price: Optional[float] = None,
    time_in_force: str = "DAY",
    underlying_price: Optional[float] = None,
    strike_price: Optional[float] = None,
    expiration_date: Optional[datetime.date] = None,
    existing_positions: Optional[List[Position]] = None,
    current_time: Optional[datetime.datetime] = None,
) -> ValidationResult:
    """Full validation pipeline for options orders."""
    result = ValidationResult(is_valid=True)
    existing_positions = existing_positions or []
    now = current_time or datetime.datetime.utcnow()

    # -----------------------------------------------------------------
    # 1. Account verification
    # -----------------------------------------------------------------
    if account is None:
        result.add_error("Account not found.")
        return result

    if not account.kyc_verified:
        result.add_error("Account has not completed KYC verification.")

    if account.status == "CLOSED":
        result.add_error("Account is closed and cannot trade.")
    elif account.status == "SUSPENDED":
        result.add_error("Account is suspended.")
    elif account.status != "ACTIVE":
        result.add_error(f"Account status '{account.status}' is not eligible to trade.")

    if account.daily_trade_count >= account.daily_trade_limit:
        result.add_error("Daily trade limit exceeded for this account.")

    required_level = RESTRICTED_OPTION_STRATEGIES_MIN_LEVEL.get(strategy, 4)
    if account.options_approval_level < required_level:
        result.add_error(
            f"Account options approval level {account.options_approval_level} is insufficient "
            f"for strategy '{strategy}' (requires level {required_level})."
        )

    # -----------------------------------------------------------------
    # 2. Basic order field validation
    # -----------------------------------------------------------------
    if not option_symbol or not OPTION_SYMBOL_RE.match(option_symbol or ""):
        result.add_error("Invalid option symbol format (expected OCC-style symbol).")

    if not underlying_symbol or not re.match(r"^[A-Z.]{1,10}$", underlying_symbol or ""):
        result.add_error("Invalid underlying symbol format.")

    if underlying_symbol in account.restricted_securities:
        result.add_error(f"Underlying {underlying_symbol} is restricted on this account.")

    if side not in VALID_OPTION_SIDES:
        result.add_error(f"Invalid option order side: {side}")

    if contracts is None or contracts <= 0:
        result.add_error("Contract quantity must be a positive number.")
    elif contracts != int(contracts):
        result.add_error("Contract quantity must be a whole number.")

    if order_type not in VALID_ORDER_TYPES:
        result.add_error(f"Invalid order type: {order_type}")

    if time_in_force not in VALID_TIME_IN_FORCE:
        result.add_error(f"Invalid time in force: {time_in_force}")

    if order_type in ("LIMIT", "STOP_LIMIT"):
        if limit_price is None or limit_price <= 0:
            result.add_error("Limit price must be provided and positive for LIMIT/STOP_LIMIT orders.")

    if order_type in ("STOP", "STOP_LIMIT"):
        if stop_price is None or stop_price <= 0:
            result.add_error("Stop price must be provided and positive for STOP/STOP_LIMIT orders.")

    if strike_price is None or strike_price <= 0:
        result.add_error("Strike price must be provided and positive.")

    if expiration_date is None:
        result.add_error("Expiration date is required.")
    else:
        today = now.date()
        if expiration_date < today:
            result.add_error("Cannot trade an option that has already expired.")
        elif (expiration_date - today).days == 0:
            result.add_warning("This option expires today; assignment/exercise risk is elevated.")

    if not result.is_valid:
        return result

    # -----------------------------------------------------------------
    # 3. Market hours check
    # -----------------------------------------------------------------
    local_time = now.time()
    is_market_hours = MARKET_OPEN <= local_time <= MARKET_CLOSE
    is_weekday = now.weekday() < 5
    if not (is_market_hours and is_weekday):
        if time_in_force in ("IOC", "FOK"):
            result.add_error("IOC/FOK options orders cannot be placed outside market hours.")
        else:
            result.add_warning("Options order placed outside regular market hours; will queue.")

    # -----------------------------------------------------------------
    # 4. Notional / premium calculation
    # -----------------------------------------------------------------
    ref_price = limit_price or stop_price
    contract_multiplier = 100
    if ref_price is None:
        if underlying_price is None:
            result.add_error("Unable to determine reference premium for order valuation.")
            return result
        ref_price = max(underlying_price * 0.01, 0.01)  # rough placeholder premium estimate

    notional_value = ref_price * contracts * contract_multiplier

    if notional_value > account.max_order_value:
        result.add_error(
            f"Order notional value {notional_value:.2f} exceeds max allowed order value "
            f"{account.max_order_value:.2f}."
        )

    # -----------------------------------------------------------------
    # 5. Margin checks (opening vs closing, covered vs naked)
    # -----------------------------------------------------------------
    is_opening = side in ("BUY_TO_OPEN", "SELL_TO_OPEN")
    is_closing = side in ("BUY_TO_CLOSE", "SELL_TO_CLOSE")

    existing_contracts = sum(
        p.quantity for p in existing_positions if p.symbol == option_symbol
    )

    if is_closing:
        if side == "SELL_TO_CLOSE" and existing_contracts < contracts:
            result.add_error(
                f"Cannot sell to close {contracts} contracts; only {existing_contracts} held."
            )
        if side == "BUY_TO_CLOSE" and existing_contracts > -contracts:
            result.add_error(
                f"Cannot buy to close {contracts} contracts; short position insufficient."
            )

    if side == "BUY_TO_OPEN":
        premium_cost = ref_price * contracts * contract_multiplier
        if account.account_type == "CASH":
            if premium_cost > account.cash_balance:
                result.add_error(
                    f"Insufficient cash for option premium. Required: {premium_cost:.2f}, "
                    f"available: {account.cash_balance:.2f}."
                )
        else:
            if premium_cost > account.buying_power:
                result.add_error(
                    f"Insufficient buying power for option premium. Required: {premium_cost:.2f}, "
                    f"available: {account.buying_power:.2f}."
                )
        result.required_margin = premium_cost

    elif side == "SELL_TO_OPEN":
        is_covered = False
        if strategy in ("COVERED_CALL", "CASH_SECURED_PUT"):
            if strategy == "COVERED_CALL":
                underlying_qty = sum(
                    p.quantity for p in existing_positions
                    if p.symbol == underlying_symbol and p.asset_type == "STOCK"
                )
                is_covered = underlying_qty >= contracts * 100
                if not is_covered:
                    result.add_error(
                        "Insufficient underlying shares to cover the call; naked calls "
                        "require higher approval level and additional margin."
                    )
            elif strategy == "CASH_SECURED_PUT":
                cash_required = strike_price * contracts * 100
                is_covered = account.cash_balance >= cash_required
                if not is_covered:
                    result.add_error(
                        f"Insufficient cash to secure the put. Required: {cash_required:.2f}, "
                        f"available: {account.cash_balance:.2f}."
                    )
                result.required_margin = cash_required
        else:
            # Naked option margin approximation: 20% of underlying value + premium, min floor
            if underlying_price is None:
                result.add_error("Underlying price required to compute naked option margin.")
            else:
                naked_margin = max(
                    (0.20 * underlying_price - (underlying_price - strike_price)) * contracts * 100,
                    ref_price * contracts * 100 + 0.10 * strike_price * contracts * 100,
                )
                naked_margin = max(naked_margin, ref_price * contracts * 100)
                result.required_margin = naked_margin
                if naked_margin > account.buying_power:
                    result.add_error(
                        f"Insufficient buying power for naked option margin. Required: "
                        f"{naked_margin:.2f}, available: {account.buying_power:.2f}."
                    )
                if account.options_approval_level < 4:
                    result.add_error("Naked option selling requires level 4 options approval.")

    # -----------------------------------------------------------------
    # 6. Risk assessment
    # -----------------------------------------------------------------
    risk_points = 0
    if notional_value > 50_000:
        risk_points += 30
    elif notional_value > 10_000:
        risk_points += 15
    elif notional_value > 2_000:
        risk_points += 5

    if strategy in ("NAKED_CALL", "NAKED_PUT"):
        risk_points += 40
    elif strategy == "STRADDLE":
        risk_points += 25
    elif strategy == "SPREAD":
        risk_points += 10

    if expiration_date is not None:
        days_to_expiry = (expiration_date - now.date()).

