from datetime import datetime, date
from collections import defaultdict


class ReportGenerator:
    """
    Generates financial reports, sales analytics, inventory summaries,
    customer insights, performance dashboards, and supports exporting
    results to various formats.
    """

    def __init__(self):
        self.reports_history = []

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------
    @staticmethod
    def _parse_date(value):
        if isinstance(value, (datetime, date)):
            return value if isinstance(value, date) else value.date()
        if isinstance(value, str):
            for fmt in ("%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%Y/%m/%d", "%m/%d/%Y"):
                try:
                    return datetime.strptime(value, fmt).date()
                except ValueError:
                    continue
        raise ValueError(f"Unable to parse date: {value}")

    @staticmethod
    def _safe_div(a, b):
        return a / b if b else 0

    def _record_report(self, report_type, data):
        entry = {
            "type": report_type,
            "generated_at": datetime.now().isoformat(),
            "data": data,
        }
        self.reports_history.append(entry)
        return entry

    # ------------------------------------------------------------------
    # Financial Reports
    # ------------------------------------------------------------------
    def generate_financial_report(self, transactions):
        """
        transactions: list of dicts with keys:
            amount (float), type ('revenue'|'expense'), category (str), date
        """
        total_revenue = 0.0
        total_expenses = 0.0
        by_category = defaultdict(lambda: {"revenue": 0.0, "expense": 0.0})
        monthly = defaultdict(lambda: {"revenue": 0.0, "expense": 0.0})

        for tx in transactions:
            amount = float(tx.get("amount", 0))
            tx_type = tx.get("type", "revenue").lower()
            category = tx.get("category", "uncategorized")
            tx_date = self._parse_date(tx.get("date", date.today()))
            month_key = tx_date.strftime("%Y-%m")

            if tx_type == "revenue":
                total_revenue += amount
                by_category[category]["revenue"] += amount
                monthly[month_key]["revenue"] += amount
            elif tx_type == "expense":
                total_expenses += amount
                by_category[category]["expense"] += amount
                monthly[month_key]["expense"] += amount

        net_profit = total_revenue - total_expenses
        profit_margin = self._safe_div(net_profit, total_revenue) * 100

        report = {
            "total_revenue": round(total_revenue, 2),
            "total_expenses": round(total_expenses, 2),
            "net_profit": round(net_profit, 2),
            "profit_margin_pct": round(profit_margin, 2),
            "by_category": {
                k: {"revenue": round(v["revenue"], 2), "expense": round(v["expense"], 2)}
                for k, v in by_category.items()
            },
            "monthly_breakdown": {
                k: {
                    "revenue": round(v["revenue"], 2),
                    "expense": round(v["expense"], 2),
                    "net": round(v["revenue"] - v["expense"], 2),
                }
                for k, v in sorted(monthly.items())
            },
        }
        self._record_report("financial_report", report)
        return report

    # ------------------------------------------------------------------
    # Sales Analytics
    # ------------------------------------------------------------------
    def generate_sales_analytics(self, sales):
        """
        sales: list of dicts with keys:
            product (str), quantity (int), unit_price (float), date, region (str, optional)
        """
        total_sales = 0.0
        total_units = 0
        by_product = defaultdict(lambda: {"units": 0, "revenue": 0.0})
        by_region = defaultdict(lambda: {"units": 0, "revenue": 0.0})
        daily_sales = defaultdict(float)

        for sale in sales:
            qty = int(sale.get("quantity", 0))
            price = float(sale.get("unit_price", 0))
            revenue = qty * price
            product = sale.get("product", "unknown")
            region = sale.get("region", "unspecified")
            sale_date = self._parse_date(sale.get("date", date.today()))

            total_sales += revenue
            total_units += qty
            by_product[product]["units"] += qty
            by_product[product]["revenue"] += revenue
            by_region[region]["units"] += qty
            by_region[region]["revenue"] += revenue
            daily_sales[sale_date.isoformat()] += revenue

        top_products = sorted(
            by_product.items(), key=lambda x: x[1]["revenue"], reverse=True
        )[:5]

        avg_daily = self._safe_div(sum(daily_sales.values()), len(daily_sales))

        report = {
            "total_sales_revenue": round(total_sales, 2),
            "total_units_sold": total_units,
            "average_order_value": round(self._safe_div(total_sales, len(sales)), 2) if sales else 0,
            "average_daily_revenue": round(avg_daily, 2),
            "top_products": [
                {"product": p, "units": v["units"], "revenue": round(v["revenue"], 2)}
                for p, v in top_products
            ],
            "sales_by_region": {
                r: {"units": v["units"], "revenue": round(v["revenue"], 2)}
                for r, v in by_region.items()
            },
            "daily_revenue": {k: round(v, 2) for k, v in sorted(daily_sales.items())},
        }
        self._record_report("sales_analytics", report)
        return report

    # ------------------------------------------------------------------
    # Inventory Summaries
    # ------------------------------------------------------------------
    def generate_inventory_summary(self, inventory, low_stock_threshold=10):
        """
        inventory: list of dicts with keys:
            sku (str), name (str), quantity (int), unit_cost (float), reorder_level (int, optional)
        """
        total_items = 0
        total_value = 0.0
        low_stock_items = []
        out_of_stock_items = []
        by_item = []

        for item in inventory:
            sku = item.get("sku", "N/A")
            name = item.get("name", "unknown")
            qty = int(item.get("quantity", 0))
            unit_cost = float(item.get("unit_cost", 0))
            reorder_level = item.get("reorder_level", low_stock_threshold)
            value = qty * unit_cost

            total_items += qty
            total_value += value

            entry = {
                "sku": sku,
                "name": name,
                "quantity": qty,
                "unit_cost": unit_cost,
                "total_value": round(value, 2),
            }
            by_item.append(entry)

            if qty == 0:
                out_of_stock_items.append(entry)
            elif qty <= reorder_level:
                low_stock_items.append(entry)

        report = {
            "total_units_in_stock": total_items,
            "total_inventory_value": round(total_value, 2),
            "distinct_items": len(inventory),
            "low_stock_items": low_stock_items,
            "out_of_stock_items": out_of_stock_items,
            "items": by_item,
        }
        self._record_report("inventory_summary", report)
        return report

    # ------------------------------------------------------------------
    # Customer Insights
    # ------------------------------------------------------------------
    def generate_customer_insights(self, customers, orders):
        """
        customers: list of dicts with keys: customer_id, name, signup_date
        orders: list of dicts with keys: customer_id, amount, date
        """
        orders_by_customer = defaultdict(list)
        for order in orders:
            orders_by_customer[order.get("customer_id")].append(order)

        insights = []
        total_revenue = 0.0
        for customer in customers:
            cid = customer.get("customer_id")
            cust_orders = orders_by_customer.get(cid, [])
            spend = sum(float(o.get("amount", 0)) for o in cust_orders)
            order_count = len(cust_orders)
            avg_order_value = self._safe_div(spend, order_count)
            total_revenue += spend

            last_order_date = None
            if cust_orders:
                last_order_date = max(
                    self._parse_date(o.get("date", date.today())) for o in cust_orders
                )

            insights.append({
                "customer_id": cid,
                "name": customer.get("name", "unknown"),
                "total_spend": round(spend, 2),
                "order_count": order_count,
                "average_order_value": round(avg_order_value, 2),
                "last_order_date": last_order_date.isoformat() if last_order_date else None,
            })

        insights.sort(key=lambda x: x["total_spend"], reverse=True)
        top_customers = insights[:10]

        active_customers = [c for c in insights if c["order_count"] > 0]
        avg_customer_value = self._safe_div(
            sum(c["total_spend"] for c in active_customers), len(active_customers)
        )

        report = {
            "total_customers": len(customers),
            "active_customers": len(active_customers),
            "total_revenue_from_customers": round(total_revenue, 2),
            "average_customer_value": round(avg_customer_value, 2),
            "top_customers": top_customers,
            "all_customers": insights,
        }
        self._record_report("customer_insights", report)
        return report

    # ------------------------------------------------------------------
    # Performance Dashboards
    # ------------------------------------------------------------------
    def generate_performance_dashboard(self, metrics_data):
        """
        metrics_data: dict of metric_name -> list of numeric values over time
        Produces summary statistics for each metric.
        """
        dashboard = {}
        for metric_name, values in metrics_data.items():
            numeric_values = [float(v) for v in values if isinstance(v, (int, float))]
            if not numeric_values:
                dashboard[metric_name] = {
                    "current": None,
                    "average": None,
                    "min": None,
                    "max": None,
                    "trend": "no_data",
                }
                continue

            current = numeric_values[-1]
            average = statistics.mean(numeric_values)
            minimum = min(numeric_values)
            maximum = max(numeric_values)

            trend = "stable"
            if len(numeric_values) >= 2:
                delta = numeric_values[-1] - numeric_values[0]
                if delta > 0:
                    trend = "increasing"
                elif delta < 0:
                    trend = "decreasing"

            dashboard[metric_name] = {
                "current": round(current, 2),
                "average": round(average, 2),
                "min": round(minimum, 2),
                "max": round(maximum, 2),
                "std_dev": round(statistics.pstdev(numeric_values), 2) if len(numeric_values) > 1 else 0,
                "trend": trend,
                "data_points": len(numeric_values),
            }

        report = {"metrics": dashboard, "generated_at": datetime.now().isoformat()}
        self._record_report("performance_dashboard", report)
        return report

    # ------------------------------------------------------------------
    # Export Functionality
    # ------------------------------------------------------------------
    def export_to_json(self, report, filepath):
        with open(filepath, "w", encoding="utf-8") as f:
            json.dump(report, f, indent=2, default=str)
        return filepath

    def export_to_csv(self, report, filepath):
        """
        Attempts a flat CSV export. Works best with list-of-dicts reports
        or report dicts containing a list-of-dicts under some key.
        """
        rows = self._extract_rows(report)
        if not rows:
            raise ValueError("No tabular data found to export to CSV.")

        fieldnames = []
        for row in rows:
            for key in row.keys():
                if key not in fieldnames:
                    fieldnames.append(key)

        with open(filepath, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            for row in rows:
                writer.writerow(row)
        return filepath

    def _extract_rows(self, report):
        if isinstance(report, list) and report and isinstance(report[0], dict):
