                         order_by: Optional[List[str]], limit: Optional[int],
                         offset: Optional[int]) -> str:
        filter_sig = "|".join(f"{f}{op}" for f, op, _ in filters)
        order_sig = ",".join(order_by) if order_by else ""
        return f"{model_name}:{action}:{filter_sig}:{order_sig}:{limit}:{offset}"


