# SQL Compiler for relational backends
# ---------------------------------------------------------------------------

OP_MAP = {
    "exact": "=",
    "iexact": "ILIKE",
    "contains": "LIKE",
    "icontains": "ILIKE",
    "gt": ">",
    "gte": ">=",
    "lt": "<",
    "lte": "<=",
    "in": "IN",
    "isnull": "IS",
}


def parse_lookup(key: str) -> Tuple[str, str]:
    parts = key.split("__")
    if len(parts) == 1:
        return parts[0], "exact"
    field, lookup = "__".join(parts[:-1]), parts[-1]
    if lookup not in OP_MAP:
        return key, "exact"
    return field, lookup


class SQLCompiler:
    def __init__(self, backend: str, optimizer: QueryOptimizer):
        self.backend = backend
        self.optimizer = optimizer

    def _placeholder(self, idx: int) -> str:
        if self.backend in ("postgresql",):
            return f"%s"
        if self.backend == "sqlite":
            return "?"
        return "%s"

    def compile_select(self, table: str, model_name: str, columns: List[str],
                        filters: Dict[str, Any], order_by: Optional[List[str]] = None,
                        limit: Optional[int] = None, offset: Optional[int] = None,
                        indexed_fields: Optional[set] = None) -> Tuple[str, List[Any]]:
        indexed_fields = indexed_fields or set()

        parsed_filters: List[Tuple[str, str, Any]] = []
        for key, value in filters.items():
            field, lookup = parse_lookup(key)
            op = OP_MAP.get(lookup, "=")
            parsed_filters.append((field, op, value))
            self.optimizer.record_filter_usage(model_name, field)

        parsed_filters = self.optimizer.optimize_filter_order(parsed_filters, indexed_fields)

        col_list = ", ".join(columns) if columns else "*"
        sql_parts = [f"SELECT {col_list} FROM {table}"]
        params: List[Any] = []

        if parsed_filters:
            clauses = []
            for field, op, value in parsed_filters:
                if op == "IN":
                    if not isinstance(value, (list, tuple)):
                        value = [value]
                    placeholders = ", ".join(self._placeholder(i) for i in range(len(value)))
                    clauses.append(f"{field} IN ({placeholders})")
                    params.extend(value)
                elif op == "IS":
                    clauses.append(f"{field} IS {'NULL' if value else 'NOT NULL'}")
                elif op == "LIKE" and "contains" in op.lower():
                    clauses.append(f"{field} {op} {self._placeholder(0)}")
                    params.append(f"%{value}%")
                else:
                    if op in ("LIKE", "ILIKE"):
                        params.append(f"%{value}%")
                    else:
                        params.append(value)
                    clauses.append(f"{field} {op} {self._placeholder(0)}")
            sql_parts.append("WHERE " + " AND ".join(clauses))

        if order_by:
            order_clauses = []
            for field in order_by:
                if field.startswith("-"):
                    order_clauses.append(f"{field[1:]} DESC")
                else:
                    order_clauses.append(f"{field} ASC")
            sql_parts.append("ORDER BY " + ", ".join(order_clauses))

        if limit is not None:
            sql_parts.append(f"LIMIT {int(limit)}")
        if offset is not None:
            sql_parts.append(f"OFFSET {int(offset)}")

        return " ".join(sql_parts), params

    def compile_insert(self, table: str, data: Dict[str, Any],
                        returning: Optional[str] = None) -> Tuple[str, List[Any]]:
        columns = list(data.keys())
        placeholders = ", ".join(self._placeholder(i) for i in range(len(columns)))
        col_sql = ", ".join(columns)
        sql = f"INSERT INTO {table} ({col_sql}) VALUES ({placeholders})"
        if returning and self.backend == "postgresql":
            sql += f" RETURNING {returning}"
        return sql, list(data.values())

    def compile_update(self, table: str, data: Dict[str, Any],
                        filters: Dict[str, Any]) -> Tuple[str, List[Any]]:
        set_clauses = []
        params = []
        for k, v in data.items():
            set_clauses.append(f"{k} = {self._placeholder(0)}")
            params.append(v)
        sql = f"UPDATE {table} SET " + ", ".join(set_clauses)

        if filters:
            where_clauses = []
            for key, value in filters.items():
                field, lookup = parse_lookup(key)
                op = OP_MAP.get(lookup, "=")
                where_clauses.append(f"{field} {op} {self._placeholder(0)}")
                params.append(value)
            sql += " WHERE " + " AND ".join(where_clauses)

        return sql, params

    def compile_delete(self, table: str, filters: Dict[str, Any]) -> Tuple[str, List[Any]]:
        sql = f"DELETE FROM {table}"
        params = []
        if filters:
            where_clauses = []
            for key, value in filters.items():
                field, lookup = parse_lookup(key)
                op = OP_MAP.get(lookup, "=")
                where_clauses.append(f"{field} {op} {self._placeholder(0)}")
                params.append(value)
            sql += " WHERE " + " AND ".join(where_clauses)
        return sql, params

    def compile_create_table(self, table: str, fields: Dict[str, Field]) -> str:
        col_defs = []
        for name, field in fields.items():
            col_type = field.get_sql_type(self.backend)
            parts = [name, col_type]
            if field.primary_key:
                if self.backend == "postgresql" and field.field_type == "INTEGER":
                    parts[1] = "SERIAL"
                parts.append("PRIMARY KEY")
            if not field.null and not field.primary_key:
                parts.append("NOT NULL")
            if field.unique and not field.primary_key:
                parts.append("UNIQUE")
            col_defs.append(" ".join(parts))
        col_sql = ", ".join(col_defs)
        return f"CREATE TABLE IF NOT EXISTS {table} ({col_sql})"


