class ConnectionPoolBase(abc.ABC):
    @abc.abstractmethod
    def get_connection(self):
        ...

    @abc.abstractmethod
    def put_connection(self, conn):
        ...

    @abc.abstractmethod
    def close_all(self):
        ...

    @abc.abstractmethod
    def stats(self) -> Dict[str, Any]:
        ...


class PostgreSQLConnectionPool(ConnectionPoolBase):
    """
    Thread-safe connection pool for PostgreSQL backed by psycopg2's
    ThreadedConnectionPool. This is the active pool implementation used
    in this PostgreSQL-only deployment.
    """

    def __init__(self, dsn: Optional[str] = None, minconn: int = 2, maxconn: int = 20,
                 **connect_kwargs):
        self.dsn = dsn
        self.connect_kwargs = connect_kwargs
        self._lock = threading.Lock()
        self._checked_out = 0
        self._total_created = 0
        self._min = minconn
        self._max = maxconn

        try:
            if dsn:
                self._pool = ThreadedConnectionPool(minconn, maxconn, dsn)
            else:
                self._pool = ThreadedConnectionPool(minconn, maxconn, **connect_kwargs)
        except psycopg2.OperationalError as e:
            raise ConnectionPoolError(f"Failed to initialize PostgreSQL pool: {e}")

        self._total_created = minconn

    def get_connection(self):
        with self._lock:
            try:
                conn = self._pool.getconn()
            except Exception as e:
                raise ConnectionPoolError(f"Unable to acquire connection: {e}")
            self._checked_out += 1
            return conn

    def put_connection(self, conn, close: bool = False):
        with self._lock:
            try:
                self._pool.putconn(conn, close=close)
            finally:
                self._checked_out = max(0, self._checked_out - 1)

    def close_all(self):
        with self._lock:
            self._pool.closeall()

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "checked_out": self._checked_out,
                "min_connections": self._min,
                "max_connections": self._max,
            }

    @contextmanager
    def connection(self):
        conn = self.get_connection()
        try:
            yield conn
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            self.put_connection(conn)


