class GenericDBAPIPool(ConnectionPoolBase):
    """
    Generic pool for DB-API 2.0 compatible drivers (MySQL via mysql-connector
    or PyMySQL, SQLite via sqlite3). Provided for interface completeness.
    """

    def __init__(self, connect_fn, minconn: int = 1, maxconn: int = 10, **connect_kwargs):
        self.connect_fn = connect_fn
        self.connect_kwargs = connect_kwargs
        self._min = minconn
        self._max = maxconn
        self._lock = threading.Lock()
        self._pool: List[Any] = []
        self._checked_out = 0
        for _ in range(minconn):
            self._pool.append(self.connect_fn(**connect_kwargs))

    def get_connection(self):
        with self._lock:
            if self._pool:
                conn = self._pool.pop()
            elif self._checked_out < self._max:
                conn = self.connect_fn(**self.connect_kwargs)
            else:
                raise ConnectionPoolError("Connection pool exhausted")
            self._checked_out += 1
            return conn

    def put_connection(self, conn):
        with self._lock:
            self._pool.append(conn)
            self._checked_out = max(0, self._checked_out - 1)

    def close_all(self):
        with self._lock:
            for conn in self._pool:
                try:
                    conn.close()
                except Exception:
                    pass
            self._pool.clear()

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "idle": len(self._pool),
                "checked_out": self._checked_out,
                "max_connections": self._max,
            }


