class QueryPlanCache:
    """Caches compiled SQL strings and simple EXPLAIN based cost stats."""

    def __init__(self, max_size: int = 256):
        self._cache: Dict[str, Tuple[str, List[Any]]] = {}
        self._stats: Dict[str, Dict[str, Any]] = {}
        self._max_size = max_size
        self._lock = threading.Lock()

    def get(self, key: str) -> Optional[Tuple[str, List[Any]]]:
        with self._lock:
            return self._cache.get(key)

    def set(self, key: str, sql: str, params: List[Any]):
        with self._lock:
            if len(self._cache) >= self._max_size:
                oldest_key = next(iter(self._cache))
                del self._cache[oldest_key]
            self._cache[key] = (sql, params)

    def record_execution(self, key: str, duration: float):
        with self._lock:
            stat = self._stats.setdefault(key, {"count": 0, "total_time": 0.0})
            stat["count"] += 1
            stat["total_time"] += duration

    def get_stats(self) -> Dict[str, Dict[str, Any]]:
        with self._lock:
            return dict(self._stats)


class QueryOptimizer:
    """
    Lightweight query optimizer:
    - Reorders WHERE predicates to place indexed/equality filters first.
    - Recommends indexes based on frequently filtered columns.
    - Caches compiled query strings keyed by structural signature.
    """

    def __init__(self):
        self.plan_cache = QueryPlanCache()
        self._filter_frequency: Dict[str, int] = {}
        self._lock = threading.Lock()

    def record_filter_usage(self, model_name: str, field_name: str):
        key = f"{model_name}.{field_name}"
        with self._lock:
            self._filter_frequency[key] = self._filter_frequency.get(key, 0) + 1

    def suggest_indexes(self, threshold: int = 5) -> List[str]:
        with self._lock:
            return [k for k, v in self._filter_frequency.items() if v >= threshold]

    def optimize_filter_order(self, filters: List[Tuple[str, str, Any]],
                               indexed_fields: set) -> List[Tuple[str, str, Any]]:
        """
        Push equality filters on indexed fields to the front, since they are
        typically most selective and benefit from index usage.
        """

        def sort_key(item):
            field, op, _ = item
            is_indexed = field in indexed_fields
            is_equality = op == "="
            # Lower sort value = executed/considered first
            return (0 if (is_indexed and is_equality) else
                    1 if is_indexed else
                    2 if is_equality else 3)

        return sorted(filters, key=sort_key)

    def build_cache_key(self, model_name: str, action: str,
                         filters: List[Tuple[str, str, Any]],
                         order_by: Optional[List[str]], limit: Optional[int],
                         offset: Optional[int]) -> str:
        filter_sig = "|".join(f"{f}{op}" for f, op, _ in filters)
        order_sig = ",".join(order_by) if order_by else ""
        return f"{model_name}:{action}:{filter_sig}:{order_sig}:{limit}:{offset}"


