class WebSocketBackend:
    """
    Simulated WebSocket backend. Since only REST is served over the wire,
    WebSocket "sessions" are emulated: a REST call opens/sends/polls a
    virtual socket session that a registered handler manages.
    """

    def __init__(self):
        self._handlers: Dict[str, Callable[[str, Any], Any]] = {}
        self._sessions: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.Lock()

    def register(self, channel: str, handler: Callable[[str, Any], Any]):
        self._handlers[channel] = handler

    def open_session(self, channel: str) -> str:
        if channel not in self._handlers:
            raise GatewayError(404, f"Unknown WebSocket channel '{channel}'")
        session_id = str(uuid.uuid4())
        with self._lock:
            self._sessions[session_id] = {"channel": channel, "queue": [], "created": time.time()}
        return session_id

    def send(self, session_id: str, message: Any) -> Any:
        session = self._get_session(session_id)
        handler = self._handlers[session["channel"]]
        response = handler(session_id, message)
        with self._lock:
            session["queue"].append(response)
        return response

    def poll(self, session_id: str) -> List[Any]:
        session = self._get_session(session_id)
        with self._lock:
            messages = session["queue"]
            session["queue"] = []
        return messages

    def close_session(self, session_id: str):
        with self._lock:
            self._sessions.pop(session_id, None)

    def _get_session(self, session_id: str) -> Dict[str, Any]:
        with self._lock:
            session = self._sessions.get(session_id)
        if session is None:
            raise GatewayError(404, f"Unknown WebSocket session '{session_id}'")
        return session


class WebSocketTranslator(ProtocolTranslator):
    """
    Emulates WebSocket over REST via three sub-operations encoded in path:
      POST /ws/{channel}/open
      POST /ws/session/{id}/send      body: {"message": ...}
      GET  /ws/session/{id}/poll
      POST /ws/session/{id}/close
    """
    name = "websocket"

    def __init__(self, backend: WebSocketBackend):
        self.backend = backend

    def to_internal(self, request: GatewayRequest) -> Dict[str, Any]:
        path = request.path
        m_open = re.match(r"^/ws/([^/]+)/open$", path)
        m_send = re.match(r"^/ws/session/([^/]+)/send$", path)
        m_poll = re.match(r"^/ws/session/([^/]+)/poll$", path)
        m_close = re.match(r"^/ws/session/([^/]+)/close$", path)

        if m_open:
            return {"op": "open", "channel": m_open.group(1)}
        if m_send:
            body = request.body or {}
            return {"op": "send", "session_id": m_send.group(1), "message": body.get("message")}
        if m_poll:
            return {"op": "poll", "session_id": m_poll.group(1)}
        if m_close:
            return {"op": "close", "session_id": m_close.group(1)}
        raise GatewayError(400, "Invalid WebSocket emulation path")

    def call_backend(self, internal_call: Dict[str, Any]) -> Any:
        op = internal_call["op"]
        if op == "open":
            session_id = self.backend.open_session(internal_call["channel"])
            return {"session_id": session_id}
        if op == "send":
            result = self.backend.send(internal_call["session_id"], internal_call["message"])
            return {"ack": True, "result": result}
        if op == "poll":
            messages = self.backend.poll(internal_call["session_id"])
            return {"messages": messages}
        if op == "close":
            self.backend.close_session(internal_call["session_id"])
            return {"closed": True}
        raise GatewayError(400, f"Unknown WebSocket op '{op}'")

    def from_internal(self, result: Any) -> GatewayResponse:
        return GatewayResponse(status=200, body=result)


