class SOAPTranslator(ProtocolTranslator):
    """
    Accepts JSON REST requests (POST /soap/{operation}) and translates
    into a SOAP-envelope call internally, then unwraps the SOAP-style
    response back into JSON for the REST client. Optionally can also
    accept true SOAP/XML bodies if Content-Type is text/xml.
    """
    name = "soap"

    def __init__(self, backend: SOAPBackend):
        self.backend = backend

    def to_internal(self, request: GatewayRequest) -> Dict[str, Any]:
        m = re.match(r"^/soap/([^/]+)$", request.path)
        if not m:
            raise GatewayError(400, "Invalid SOAP path, expected /soap/{operation}")
        operation = m.group(1)
        content_type = request.headers.get("Content-Type", "")
        if "xml" in content_type and isinstance(request.body, (str, bytes)):
            params = self._parse_soap_xml(request.body)
        else:
            params = request.body or {}
        return {"operation": operation, "params": params}

    def call_backend(self, internal_call: Dict[str, Any]) -> Any:
        return self.backend.invoke(internal_call["operation"], internal_call["params"])

    def from_internal(self, result: Any) -> GatewayResponse:
        return GatewayResponse(status=200, body=result)

    @staticmethod
    def _parse_soap_xml(body) -> Dict[str, Any]:
        if isinstance(body, bytes):
            body = body.decode("utf-8")
        try:
            root = ET.fromstring(body)
        except ET.ParseError as exc:
            raise GatewayError(400, f"Invalid SOAP XML: {exc}")
        ns = {"soap": "http://schemas.xmlsoap.org/soap/envelope/"}
        body_el = root.find("soap:Body", ns)
        params: Dict[str, Any] = {}
        if body_el is not None:
            for child in body_el:
                for sub in child:
                    tag = sub.tag.split("}")[-1]
                    params[tag] = sub.text
        return params


