class GraphQLBackend:
    """A minimal in-process GraphQL execution engine (query field -> resolver)."""

    def __init__(self):
        self._resolvers: Dict[str, Callable[..., Any]] = {}

    def register(self, field_name: str, resolver: Callable[..., Any]):
        self._resolvers[field_name] = resolver

    def execute(self, query: str, variables: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        variables = variables or {}
        field_name, args = self._parse_query(query, variables)
        resolver = self._resolvers.get(field_name)
        if resolver is None:
            return {"errors": [{"message": f"Unknown field '{field_name}'"}]}
        try:
            data = resolver(**args)
            return {"data": {field_name: data}}
        except Exception as exc:
            return {"errors": [{"message": str(exc)}]}

    @staticmethod
    def _parse_query(query: str, variables: Dict[str, Any]) -> Tuple[str, Dict[str, Any]]:
        # Extremely small subset parser: `{ field(arg: "val", arg2: $var) }`
        match = re.search(r"\{?\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*(\(([^)]*)\))?\s*\}?", query.strip())
        if not match:
            raise ValueError("Cannot parse GraphQL query")
        field_name = match.group(1)
        args_str = match.group(3) or ""
        args: Dict[str, Any] = {}
        for part in filter(None, [p.strip() for p in args_str.split(",")]):
            if ":" not in part:
                continue
            key, value = part.split(":", 1)
            key = key.strip()
            value = value.strip()
            if value.startswith("$"):
                args[key] = variables.get(value[1:])
            elif value.startswith('"') and value.endswith('"'):
                args[key] = value[1:-1]
            else:
                try:
                    args[key] = json.loads(value)
                except json.JSONDecodeError:
                    args[key] = value
        return field_name, args


