            return {"op": "send", "session_id": m_send.group(1), "message": body.get("message")}
        if m_poll:
            return {"op": "poll", "session_id": m_poll.group(1)}
        if m_close:
            return {"op": "close", "session_id": m_close.group(1)}
        raise GatewayError(400, "Invalid WebSocket emulation path")

    def call_backend(self, internal_call: Dict[str, Any]) -> Any:
        op = internal_call["op"]
        if op == "open":
            session_id = self.backend.open_session(internal_call["channel"])
            return {"session_id": session_id}
        if op == "send":
            result = self.backend.send(internal_call["session_id"], internal_call["message"])
            return {"ack": True, "result": result}
        if op == "poll":
            messages = self.backend.poll(internal_call["session_id"])
            return {"messages": messages}
        if op == "close":
            self.backend.close_session(internal_call["session_id"])
            return {"closed": True}
        raise GatewayError(400, f"Unknown WebSocket op '{op}'")

    def from_internal(self, result: Any) -> GatewayResponse:
        return GatewayResponse(status=200, body=result)


# ---- SOAP -----------------------------------------------------------------

class SOAPBackend:
    """Registry of SOAP operations (operation name -> handler)."""

    def __init__(self):
        self._operations: Dict[str, Callable[[Dict[str, Any]], Dict[str, Any]]] = {}

    def register(self, operation: str, handler: Callable[[Dict[str, Any]], Dict[str, Any]]):
        self._operations[operation] = handler

    def invoke(self, operation: str, params: Dict[str, Any]) -> Dict[str, Any]:
        handler = self._operations.get(operation)
        if handler is None:
            raise GatewayError(404, f"Unknown SOAP operation '{operation}'")
        return handler(params)


class SOAPTranslator(ProtocolTranslator):
    """
    Accepts JSON REST requests (POST /soap/{operation}) and translates
    into a SOAP-envelope call internally, then unwraps the SOAP-style
    response back into JSON for the REST client. Optionally can also
    accept true SOAP/XML bodies if Content-Type is text/xml.
    """
    name = "soap"

    def __init__(self, backend: SOAPBackend):
        self.backend = backend

    def to_internal(self, request: GatewayRequest) -> Dict[str, Any]:
        m = re.match(r"^/soap/([^/]+)$", request.path)
        if not m:
            raise GatewayError(400, "Invalid SOAP path, expected /soap/{operation}")
        operation = m.group(1)
        content_type = request.headers.get("Content-Type", "")
        if "xml" in content_type and isinstance(request.body, (str, bytes)):
            params = self._parse_soap_xml(request.body)
        else:
            params = request.body or {}
        return {"operation": operation, "params": params}

    def call_backend(self, internal_call: Dict[str, Any]) -> Any:
        return self.backend.invoke(internal_call["operation"], internal_call["params"])

    def from_internal(self, result: Any) -> GatewayResponse:
        return GatewayResponse(status=200, body=result)

    @staticmethod
    def _parse_soap_xml(body) -> Dict[str, Any]:
        if isinstance(body, bytes):
            body = body.decode("utf-8")
        try:
            root = ET.fromstring(body)
        except ET.ParseError as exc:
            raise GatewayError(400, f"Invalid SOAP XML: {exc}")
        ns = {"soap": "http://schemas.xmlsoap.org/soap/envelope/"}
        body_el = root.find("soap:Body", ns)
        params: Dict[str, Any] = {}
        if body_el is not None:
            for child in body_el:
                for sub in child:
                    tag = sub.tag.split("}")[-1]
                    params[tag] = sub.text
        return params


# ---------------------------------------------------------------------------
# Middleware
# ---------------------------------------------------------------------------

Middleware = Callable[[GatewayRequest], Optional[GatewayResponse]]


def logging_middleware(request: GatewayRequest) -> Optional[GatewayResponse]:
    logger.info("Incoming %s %s", request.method, request.path)
    return None


def make_auth_middleware(required_token: str) -> Middleware:
    def _auth(request: GatewayRequest) -> Optional[GatewayResponse]:
        if request.path.startswith("/health"):
            return None
        token = request.headers.get("Authorization", "")
        if token != f"Bearer {required_token}":
            return GatewayResponse(status=401, body={"error": "Unauthorized"})
        return None
    return _auth


# ---------------------------------------------------------------------------
# Routing
# ---------------------------------------------------------------------------

@dataclass
class Route:
    method: str
    pattern: re.Pattern
    handler: Callable[[GatewayRequest, Dict[str, str]], GatewayResponse]
    raw_path: str


class Router:
    def __init__(self):
        self._routes: List[Route] = []

    def add_route(self, method: str, path: str, handler: Callable[[GatewayRequest, Dict[str, str]], GatewayResponse]):
        pattern = self._compile(path)
        self._routes.append(Route(method.upper(), pattern, handler, path))

    @staticmethod
    def _compile(path: str) -> re.Pattern:
        regex = re.sub(r"\{([a-zA-Z_][a-zA-Z0-9_]*)\}", r"(?P<\1>[^/]+)", path)
        return re.compile(f"^{regex}$")

    def match(self, method: str, path: str) -> Tuple[Optional[Route], Dict[str, str]]:
        for route in self._routes:
            if route.method != method.upper():
                continue
            m = route.pattern.match(path)
            if m:
                return route, m.groupdict()
        return None, {}


# ---------------------------------------------------------------------------
# API Gateway
# ---------------------------------------------------------------------------

class APIGateway:
    """
    REST-only-served gateway with internal protocol translation to
    GraphQL, gRPC, WebSocket, and SOAP backends.
    """

    def __init__(self):
        self.router = Router()
        self.middlewares: List[Middleware] = [logging_middleware]

        self.graphql_backend = GraphQLBackend()
        self.grpc_backend = GRPCBackend()
        self.ws_backend = WebSocketBackend()
        self.soap_backend = SOAPBackend()

        self.graphql_translator = GraphQLTranslator(self.graphql_backend)
        self.grpc_translator = GRPCTranslator(self.grpc_backend)
        self.ws_translator = WebSocketTranslator(self.ws_backend)
        self.soap_translator = SOAPTranslator(self.soap_backend)

        self._register_builtin_routes()

    # -- middleware -----------------------------------------------------

    def use(self, middleware: Middleware):
        self.middlewares.append(middleware)

    # -- backend registration convenience --------------------------------

    def add_graphql_field(self, field_name: str, resolver: Callable[..., Any]):
        self.graphql_backend.register(field_name, resolver)

    def add_grpc_method(self, service: str, method: str, handler: Callable[[Dict[str, Any]], Dict[str, Any]]):
        self.grpc_backend.register(service, method, handler)

    def add_ws_channel(self, channel: str, handler: Callable[[str, Any], Any]):
        self.ws_backend.register(channel, handler)

    def add_soap_operation(self, operation: str, handler: Callable[[Dict[str, Any]], Dict[str, Any]]):
        self.soap_backend.register(operation, handler)

    # -- custom REST routes -----------------------------------------------

    def add_rest_route(self, method: str, path: str, handler: Callable[[GatewayRequest, Dict[str, str]], GatewayResponse]):
        self.router.add_route(method, path, handler)

    # -- built-in translation routes ---------------------------------------

    def _register_builtin_routes(self):
        self.router.add_route("GET", "/health", self._handle_health)

        # GraphQL exposed via REST endpoint
        self.router.add_route("POST", "/graphql", self._make_translator_handler(self.graphql_translator))

        # gRPC exposed via REST endpoint: /grpc/{service}/{method}
        self.router.add_route("POST", "/grpc/{service}/{method}", self._make_translator_handler(self.grpc_translator))

        # WebSocket emulation endpoints
        self.router.add_route("POST", "/ws/{channel}/open", self._make_translator_handler(self.ws_translator))
        self.router.add_route("POST", "/ws/session/{id}/send", self._make_translator_handler(self.ws_translator))
        self.router.add_route("GET", "/ws/session/{id}/poll", self._make_translator_handler(self.ws_translator))
        self.router.add_route("POST", "/ws/session/{id}/close", self._make_translator_handler(self.ws_translator))

        # SOAP exposed via REST endpoint: /soap/{operation}
        self.router.add_route("POST", "/soap/{operation}", self._make_translator_handler(self.soap_translator))

    def _make_translator_handler(self, translator: ProtocolTranslator):
        def _handler(request: GatewayRequest, path_params: Dict[str, str]) -> GatewayResponse:
            try:
                return translator.dispatch(request)
            except GatewayError as e:
                return GatewayResponse(status=e.status, body={"error": e.message, "details": e.details})
            except Exception as exc:
                logger.exception("Unhandled error in %s translator", translator.name)
                return GatewayResponse(status=500, body={"error": str(exc)})
        return _handler

    @staticmethod
    def _handle_health(request: GatewayRequest, path_params: Dict[str, str]) -> GatewayResponse:
        return GatewayResponse(status=200, body={"status": "ok", "time": time.time()})

    # -- core dispatch -----------------------------------------------------

    def handle_request(self, request: GatewayRequest) -> GatewayResponse:
        for mw in self.middlewares:
            result = mw(request)
            if result is not None:
                return result

        route, path_params = self.router.match(request.method, request.path)
        if route is None:
            return GatewayResponse(status=404, body={"error": f"No REST route for {request.method} {request.path}"})

        try:
            return route.handler(request, path_params)
        except GatewayError as e:
            return GatewayResponse(status=e.status, body={"error": e.message, "details": e.details})
        except Exception as exc:
            logger.exception("Unhandled error handling request")
            return GatewayResponse(status=500, body={"error": str(exc)})


# ---------------------------------------------------------------------------
# HTTP server binding (REST is the only wire protocol served)
# ---------------------------------------------------------------------------

