class NotificationService:
    def __init__(self):
        self._notifications: Dict[str, Notification] = {}
        self._lock = threading.RLock()
        self._scheduled_queue: PriorityQueue = PriorityQueue()
        self._providers = {
            NotificationType.EMAIL: EmailProvider(),
            NotificationType.SMS: SMSProvider(),
            NotificationType.PUSH: PushProvider(),
            NotificationType.IN_APP: InAppProvider(),
        }
        self._subscribers: Dict[str, List[Callable]] = {}
        self._in_app_inbox: Dict[str, List[str]] = {}
        self._scheduler_thread: Optional[threading.Thread] = None
        self._scheduler_running = False
        self._retry_delay_seconds = 2

    # -------------------- Validation --------------------

    def _validate_recipient(self, notif_type: NotificationType, recipient: str):
        if not recipient or not isinstance(recipient, str):
            raise ValidationError("Recipient must be a non-empty string")

        if notif_type == NotificationType.EMAIL:
            pattern = r"^[^@\s]+@[^@\s]+\.[^@\s]+$"
            if not re.match(pattern, recipient):
                raise ValidationError(f"Invalid email format: {recipient}")
