                raise ValidationError(f"Invalid phone number format: {recipient}")
        elif notif_type in (NotificationType.PUSH, NotificationType.IN_APP):
            if len(recipient.strip()) == 0:
                raise ValidationError("Recipient identifier cannot be empty")

    def _validate_content(self, notif_type: NotificationType, content: Dict[str, Any]):
        if not isinstance(content, dict):
            raise ValidationError("Content must be a dictionary")

        if notif_type == NotificationType.EMAIL:
            if "subject" not in content or "body" not in content:
                raise ValidationError("Email content requires 'subject' and 'body'")
        elif notif_type == NotificationType.SMS:
            if "message" not in content:
                raise ValidationError("SMS content requires 'message'")
            if len(content["message"]) > 1600:
                raise ValidationError("SMS message too long")
        elif notif_type == NotificationType.PUSH:
            if "title" not in content or "body" not in content:
                raise ValidationError("Push content requires 'title' and 'body'")
        elif notif_type == NotificationType.IN_APP:
            if "message" not in content:
                raise ValidationError("In-app content requires 'message'")

    # -------------------- Core sending --------------------

    def _create_notification(
        self,
        notif_type: NotificationType,
        recipient: str,
        content: Dict[str, Any],
        scheduled_time: Optional[datetime] = None,
        max_retries: int = 3,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> Notification:
        self._validate_recipient(notif_type, recipient)
        self._validate_content(notif_type, content)

        notif_id = str(uuid.uuid4())
        notification = Notification(
            id=notif_id,
            type=notif_type,
            recipient=recipient,
            content=content,
            scheduled_time=scheduled_time,
            max_retries=max_retries,
            metadata=metadata or {},
            status=NotificationStatus.SCHEDULED if scheduled_time else NotificationStatus.PENDING,
        )

        with self._lock:
            self._notifications[notif_id] = notification

        return notification

    def _dispatch(self, notification: Notification) -> DeliveryRecord:
        provider = self._providers[notification.type]
        notification.attempts += 1

        try:
            response = provider.send(notification.recipient, notification.content)
            record = DeliveryRecord(
                notification_id=notification.id,
                status=NotificationStatus.DELIVERED,
                timestamp=datetime.now(),
                attempt=notification.attempts,
                provider_response=response,
            )
            notification.status = NotificationStatus.DELIVERED
            notification.add_history(record)

            if notification.type == NotificationType.IN_APP:
                self._in_app_inbox.setdefault(notification.recipient, []).append(notification.id)

            self._notify_subscribers(notification.id, record)
