                                    target=self._dispatch, args=(notification,), daemon=True
                                ).start()
                time.sleep(poll_interval)

        self._scheduler_thread = threading.Thread(target=run, daemon=True)
        self._scheduler_thread.start()

    def stop_scheduler(self):
        self._scheduler_running = False
        if self._scheduler_thread:
            self._scheduler_thread.join(timeout=2)

    def cancel_scheduled_notification(self, notification_id: str) -> bool:
        with self._lock:
            notification = self._notifications.get(notification_id)
            if notification and notification.status == NotificationStatus.SCHEDULED:
                notification.status = NotificationStatus.CANCELLED
                return True
        return False

    # -------------------- Tracking --------------------

    def get_notification(self, notification_id: str) -> Optional[Notification]:
        return self._notifications.get(notification_id)

    def get_status(self, notification_id: str) -> Optional[NotificationStatus]:
        notification = self._notifications.get(notification_id)
        return notification.status if notification else None

    def get_delivery_history(self, notification_id: str) -> List[DeliveryRecord]:
        notification = self._notifications.get(notification_id)
        return notification.history if notification else []

    def get_notifications_by_recipient(self, recipient: str) -> List[Notification]:
        with self._lock:
            return [n for n in self._notifications.values() if n.recipient == recipient]

    def get_notifications_by_status(self, status: NotificationStatus) -> List[Notification]:
        with self._lock:
            return [n for n in self._notifications.values() if n.status == status]

    def get_failed_notifications(self) -> List[Notification]:
        return self.get_notifications_by_status(NotificationStatus.FAILED)

    def get_in_app_inbox(self, recipient: str) -> List[Notification]:
        with self._lock:
            ids = self._in_app_inbox.get(recipient, [])
            return [self._notifications[i] for i in ids if i in self._notifications]

    def retry_notification(self, notification_id: str) -> Optional[Notification]:
        notification = self._notifications.get(notification_id)
        if notification and notification.status == NotificationStatus.FAILED:
            notification.attempts = 0
            notification.status = NotificationStatus.PENDING
            self._dispatch(notification)
            return notification
        return None

    def get_delivery_stats(self) -> Dict[str, int]:
        with self._lock:
            stats = {status.value: 0 for status in NotificationStatus}
            for notification in self._notifications.values():
                stats[notification.status.value] += 1
            return stats

    # -------------------- Subscriptions / Webhooks --------------------

    def subscribe(self, notification_id: str, callback: Callable[[str, DeliveryRecord], None]):
        self._subscribers.setdefault(notification_id, []).append(callback)

    def _notify_subscribers(self, notification_id: str, record: DeliveryRecord):
        for callback in self._subscribers.get(notification_id, []):
            try:
                callback(notification_id, record)
            except Exception:
                pass

    # -------------------- Bulk operations --------------------

    def send_bulk(
        self,
        notif_type: NotificationType,
        recipients: List[str],
        content: Dict[str, Any],
        max_retries: int = 3,
    ) -> List[Notification]:
        results = []
        for recipient in recipients:
            try:
                notification = self._create_notification(
                    notif_type, recipient, content, max_retries=max_retries
                )
                self._dispatch(notification)
                results.append(notification)
            except ValidationError as e:
                failed = Notification(
                    id=str(uuid.uuid4()),
                    type=notif_type,
                    recipient=recipient,
                    content=content,
                    status=NotificationStatus.FAILED,
                )
                failed.add_history(
                    DeliveryRecord(
                        notification_id=failed.id,
                        status=NotificationStatus.FAILED,
                        timestamp=datetime.now(),
                        error_message=str(e),
                    )
                )
                with self._lock:
                    self._notifications[failed.id] = failed
                results.append(failed)
        return results

    def clear_history(self, older_than: Optional[timedelta] = None):
        with self._lock:
            if older_than is None:
                self._notifications.clear()
                self._in_app_inbox.clear()
            else:
                cutoff = datetime.now() - older_than
                to_remove = [
                    nid for nid, n in self._notifications.items()
                    if n.created_at < cutoff
                ]
                for nid in to_remove:
