    # -------------------- Validation --------------------

    def _validate_recipient(self, notif_type: NotificationType, recipient: str):
        if not recipient or not isinstance(recipient, str):
            raise ValidationError("Recipient must be a non-empty string")

        if notif_type == NotificationType.EMAIL:
            pattern = r"^[^@\s]+@[^@\s]+\.[^@\s]+$"
            if not re.match(pattern, recipient):
                raise ValidationError(f"Invalid email format: {recipient}")
        elif notif_type == NotificationType.SMS:
            digits = re.sub(r"\D", "", recipient)
            if len(digits) < 7 or len(digits) > 15:
                raise ValidationError(f"Invalid phone number format: {recipient}")
        elif notif_type in (NotificationType.PUSH, NotificationType.IN_APP):
            if len(recipient.strip()) == 0:
                raise ValidationError("Recipient identifier cannot be empty")

