"""
Financial system module.

Note: Adding a new currency requires modifications in multiple places:
  1. Amount class (SUPPORTED_CURRENCIES, SYMBOLS, DECIMAL_PLACES)
  2. ExchangeService (RATES table)
  3. Transaction model (CURRENCY_CHOICES)
  4. Statement generator (CURRENCY_GROUP_ORDER)
  5. Report formatter (CURRENCY_LOCALE_FORMAT)
  6. API serializers (ALLOWED_CURRENCIES)
  7. UI components (CURRENCY_UI_META)
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal
from typing import Dict, List, Optional


# ---------------------------------------------------------------------------
# 1. Amount class
# ---------------------------------------------------------------------------
class Amount:
    """Represents a monetary amount in a specific currency."""

    SUPPORTED_CURRENCIES = {"USD", "EUR", "GBP", "JPY"}

    SYMBOLS = {
        "USD": "$",
        "EUR": "€",
        "GBP": "£",
        "JPY": "¥",
    }

    DECIMAL_PLACES = {
        "USD": 2,
        "EUR": 2,
        "GBP": 2,
        "JPY": 0,
    }

    def __init__(self, value, currency: str):
        currency = currency.upper()
        if currency not in self.SUPPORTED_CURRENCIES:
            raise ValueError(f"Unsupported currency: {currency}")

        self.currency = currency
        places = self.DECIMAL_PLACES[currency]
        quant = Decimal(1).scaleb(-places) if places > 0 else Decimal(1)
        self.value = Decimal(str(value)).quantize(quant, rounding=ROUND_HALF_UP)

    def __repr__(self):
        return f"Amount({self.value}, '{self.currency}')"

    def __eq__(self, other):
        if not isinstance(other, Amount):
            return NotImplemented
        return self.currency == other.currency and self.value == other.value

    def __add__(self, other):
        if not isinstance(other, Amount):
            return NotImplemented
        if other.currency != self.currency:
            raise ValueError("Cannot add amounts of different currencies")
        return Amount(self.value + other.value, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Amount):
            return NotImplemented
        if other.currency != self.currency:
            raise ValueError("Cannot subtract amounts of different currencies")
        return Amount(self.value - other.value, self.currency)

    def format(self) -> str:
        symbol = self.SYMBOLS[self.currency]
        places = self.DECIMAL_PLACES[self.currency]
        formatted_value = f"{self.value:,.{places}f}"
        return f"{symbol}{formatted_value}"

    def to_dict(self) -> dict:
        return {"value": str(self.value), "currency": self.currency}


# ---------------------------------------------------------------------------
# 2. ExchangeService
# ---------------------------------------------------------------------------
class ExchangeService:
    """Handles currency conversion using fixed exchange rates (relative to USD)."""

    # Rates expressed as: 1 USD = RATES[currency] units of currency
    RATES = {
        "USD": Decimal("1.0"),
        "EUR": Decimal("0.92"),
        "GBP": Decimal("0.79"),
        "JPY": Decimal("151.0"),
    }

    @classmethod
    def get_rate(cls, currency: str) -> Decimal:
        currency = currency.upper()
        if currency not in cls.RATES:
            raise ValueError(f"No exchange rate available for currency: {currency}")
        return cls.RATES[currency]

    @classmethod
    def convert(cls, amount: Amount, target_currency: str) -> Amount:
        target_currency = target_currency.upper()
        if target_currency not in Amount.SUPPORTED_CURRENCIES:
            raise ValueError(f"Unsupported currency: {target_currency}")

        if amount.currency == target_currency:
            return Amount(amount.value, target_currency)

        source_rate = cls.get_rate(amount.currency)
        target_rate = cls.get_rate(target_currency)

        # Convert to USD base, then to target currency.
        usd_value = amount.value / source_rate
        converted_value = usd_value * target_rate
        return Amount(converted_value, target_currency)


# ---------------------------------------------------------------------------
# 3. Transaction model
# ---------------------------------------------------------------------------
class Transaction:
    """Represents a single financial transaction."""

    CURRENCY_CHOICES = ("USD", "EUR", "GBP", "JPY")

    def __init__(
        self,
        amount: Amount,
        description: str,
        account_id: str,
        transaction_id: Optional[str] = None,
        timestamp: Optional[datetime] = None,
    ):
        if amount.currency not in self.CURRENCY_CHOICES:
            raise ValueError(f"Currency {amount.currency} not allowed for transactions")

        self.transaction_id = transaction_id or str(uuid.uuid4())
        self.amount = amount
        self.description = description
        self.account_id = account_id
        self.timestamp = timestamp or datetime.now(timezone.utc)

    def to_dict(self) -> dict:
        return {
            "transaction_id": self.transaction_id,
            "amount": self.amount.to_dict(),
            "description": self.description,
            "account_id": self.account_id,
            "timestamp": self.timestamp.isoformat(),
        }

    def __repr__(self):
        return f"Transaction({self.transaction_id}, {self.amount!r}, '{self.description}')"


# ---------------------------------------------------------------------------
# 4. Statement generator
# ---------------------------------------------------------------------------
class StatementGenerator:
    """Groups and orders transactions by currency for statement output."""

    CURRENCY_GROUP_ORDER = ["USD", "EUR", "GBP", "JPY"]

    def __init__(self, transactions: List[Transaction]):
        self.transactions = transactions

    def group_by_currency(self) -> Dict[str, List[Transaction]]:
        groups: Dict[str, List[Transaction]] = {c: [] for c in self.CURRENCY_GROUP_ORDER}
        for txn in self.transactions:
            groups.setdefault(txn.amount.currency, []).append(txn)
        return groups

    def generate(self) -> str:
        groups = self.group_by_currency()
        lines = ["=== Statement ==="]

        for currency in self.CURRENCY_GROUP_ORDER:
            txns = groups.get(currency, [])
            if not txns:
                continue
            lines.append(f"\n-- {currency} --")
            total = Amount(0, currency)
            for txn in txns:
                lines.append(
                    f"{txn.timestamp.date()} | {txn.description:<30} | {txn.amount.format()}"
                )
                total = total + txn.amount
            lines.append(f"Subtotal ({currency}): {total.format()}")

        # Handle any currencies not in the predefined order (future-proofing)
        for currency, txns in groups.items():
            if currency in self.CURRENCY_GROUP_ORDER or not txns:
                continue
            lines.append(f"\n-- {currency} (unordered) --")
            total = Amount(0, currency)
            for txn in txns:
                lines.append(
                    f"{txn.timestamp.date()} | {txn.description:<30} | {txn.amount.format()}"
                )
                total = total + txn.amount
            lines.append(f"Subtotal ({currency}): {total.format()}")

        return "\n".join(lines)


# ---------------------------------------------------------------------------
# 5. Report formatter
# ---------------------------------------------------------------------------
class ReportFormatter:
    """Formats monetary values according to currency-specific locale conventions."""

    CURRENCY_LOCALE_FORMAT = {
        "USD": {"symbol_position": "prefix", "thousands_sep": ",", "decimal_sep": "."},
        "EUR": {"symbol_position": "suffix", "thousands_sep": ".", "decimal_sep": ","},
        "GBP": {"symbol_position": "prefix", "thousands_sep": ",", "decimal_sep": "."},
        "JPY": {"symbol_position": "prefix", "thousands_sep": ",", "decimal_sep": "."},
    }

    @classmethod
    def format_amount(cls, amount: Amount) -> str:
        currency = amount.currency
        if currency not in cls.CURRENCY_LOCALE_FORMAT:
            raise ValueError(f"No locale format defined for currency: {currency}")

        fmt = cls.CURRENCY_LOCALE_FORMAT[currency]
        places = Amount.DECIMAL_PLACES[currency]
        symbol = Amount.SYMBOLS[currency]

        raw = f"{amount.value:,.{places}f}"
        int_part, _, dec_part = raw.partition(".")

        int_part = int_part.replace(",", fmt["thousands_sep"])
        if places > 0:
            number_str = f"{int_part}{fmt['decimal_sep']}{dec_part}"
        else:
            number_str = int_part

        if fmt["symbol_position"] == "prefix":
            return f"{symbol}{number_str}"
        return f"{number_str}{symbol}"

    @classmethod
    def build_report(cls, transactions: List[Transaction]) -> str:
        lines = ["=== Report ==="]
        for txn in transactions:
            formatted = cls.format_amount(txn.amount)
            lines.append(f"{txn.description}: {formatted}")
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# 6. API serializers
# ---------------------------------------------------------------------------
class TransactionSerializer:
    """Serializes/deserializes Transaction objects for API responses."""

    ALLOWED_CURRENCIES = {"USD", "EUR", "GBP", "JPY"}

    @classmethod
    def serialize(cls, transaction: Transaction) -> dict:
        if transaction.amount.currency not in cls.ALLOWED_CURRENCIES:
            raise ValueError(
                f"Currency {transaction.amount.currency} is not allowed by the API"
            )
        return {
            "id": transaction.transaction_id,
            "account_id": transaction.account_id,
            "description": transaction.description,
            "amount": {
                "value": str(transaction.amount.value),
                "currency": transaction.amount.currency,
            },
            "timestamp": transaction.timestamp.isoformat(),
        }

    @classmethod
    def deserialize(cls, data: dict) -> Transaction:
        currency = data["amount"]["currency"].upper()
        if currency not in cls.ALLOWED_CURRENCIES:
            raise ValueError(f"Currency {currency} is not allowed by the API")

        amount = Amount(data["amount"]["value"], currency)
        timestamp = None
        if "timestamp" in data and data["timestamp"]:
            timestamp = datetime.fromisoformat(data["timestamp"])

        return Transaction(
            amount=amount,
            description=data.get("description", ""),
            account_id=data["account_id"],
            transaction_id=data.get("id"),
            timestamp=timestamp,
        )


# ---------------------------------------------------------------------------
# 7. UI components
# ---------------------------------------------------------------------------
class CurrencyUIComponent:
    """Provides UI metadata (icons, colors, display names) per currency."""

    CURRENCY_UI_META = {
        "USD": {"display_name": "US Dollar", "icon": "flag-us.svg", "color": "#2E7D32"},
        "EUR": {"display_name": "Euro", "icon": "flag-eu.svg", "color": "#1565C0"},
        "GBP": {"display_name": "British Pound", "icon": "flag-gb.svg", "color": "#6A1B9A"},
        "JPY": {"display_name": "Japanese Yen", "icon": "flag-jp.svg", "color": "#C62828"},
    }

    @classmethod
    def get_meta(cls, currency: str) -> dict:
        currency = currency.upper()
        if currency not in cls.CURRENCY_UI_META:
            raise ValueError(f"No UI metadata configured for currency: {currency}")
        return cls.CURRENCY_UI_META[currency]

    @classmethod
    def render_currency_selector(cls) -> List[dict]:
        options = []
        for currency, meta in cls.CURRENCY_UI_META.items():
            options.append(
                {
                    "value": currency,
                    "label": meta["display_name"],
                    "icon": meta["icon"],
                    "color": meta["color"],
                }
            )
        return options

    @classmethod
    def render_amount_badge(cls, amount: Amount) -> str:
        meta = cls.get_meta(amount.currency)
        formatted = amount.format()
        return (
            f'<span class="currency-badge" style="color:{meta["color"]}">'
            f'<img src="{meta["icon"]}" alt="{meta["display_name"]}"/> {formatted}'
            f"</span>"
        )


# ---------------------------------------------------------------------------
# Example usage / simple demonstration
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    txn1 = Transaction(Amount("100.50", "USD"), "Groceries", "acc-1")
    txn2 = Transaction(Amount("75.25", "EUR"), "Rent", "acc-1")
    txn3 = Transaction(Amount("5000", "JPY"), "Electronics", "acc-2")

    transactions = [txn1, txn2, txn3]

    statement = StatementGenerator(transactions).generate()
    print(statement)
