        cutoff = datetime.now().timestamp() - days * 86400
        sales_counter = Counter()
        for entry in self.sales_log:
            if entry["timestamp"].timestamp() >= cutoff:
                sales_counter[entry["product_id"]] += entry["quantity"]
        ranked = sales_counter.most_common(limit)
        return [self.products[pid] for pid, _ in ranked if pid in self.products]

    def recommend_frequently_bought_together(self, product_id, limit=5):
        co_occurrence = Counter()
        order_map = defaultdict(set)
        for entry in self.sales_log:
