    - Applies environment variable overrides on top of file-based config.
    - If ALL provided config sources are JSON files (or no files, only remote),
      remote config server(s) may also be queried and merged in, with the
      highest priority given to remote > env > later files > earlier files.
    """

    def __init__(
        self,
        paths=None,
        env_prefix="APP_",
        env_separator="__",
        remote_urls=None,
        remote_timeout=5,
        remote_headers=None,
        remote_retries=3,
        auto_reload_interval=None,
    ):
        self.paths = list(paths) if paths else []
        self.env_resolver = EnvOverrideResolver(prefix=env_prefix, separator=env_separator)
        self.remote_urls = list(remote_urls) if remote_urls else []
        self.remote_timeout = remote_timeout
        self.remote_headers = remote_headers
        self.remote_retries = remote_retries

        self._lock = threading.RLock()
        self._config = {}
        self._auto_reload_interval = auto_reload_interval
        self._stop_event = threading.Event()
        self._reload_thread = None

        self.reload()

        if self._auto_reload_interval:
            self._start_auto_reload()

    def _all_sources_json(self):
        if not self.paths:
            return True
        for p in self.paths:
            if os.path.splitext(p)[1].lower() != ".json":
                return False
        return True

    def _load_file_configs(self):
        merged = {}
        for path in self.paths:
            data = ConfigLoader.load(path)
            if not isinstance(data, dict):
                raise ConfigFormatError(
                    f"Top-level config in {path} must be a mapping/object, got {type(data)}"
                )
            merged = _deep_merge(merged, data)
        return merged

    def _load_remote_configs(self):
        merged = {}
        for url in self.remote_urls:
            client = RemoteConfigClient(
                url,
                timeout=self.remote_timeout,
                headers=self.remote_headers,
                retries=self.remote_retries,
            )
            data = client.fetch()
            if not isinstance(data, dict):
                raise RemoteConfigError(
                    f"Remote config at {url} must be a JSON object, got {type(data)}"
                )
            merged = _deep_merge(merged, data)
        return merged

    def reload(self):
        with self._lock:
            merged = self._load_file_configs()

            if self.remote_urls:
                if not self._all_sources_json():
                    raise ConfigError(
                        "Remote config servers are only supported when all local "
                        "config files are JSON. Mixed formats detected."
                    )
                remote_data = self._load_remote_configs()
                merged = _deep_merge(merged, remote_data)

            merged = self.env_resolver.apply(merged)

            self._config = merged
            return self._config

