            return

        if order.order_type == OrderType.MARKET:
            self._fill_against_book(order, book)
        elif order.order_type == OrderType.LIMIT:
            self._try_fill_limit(order, book)
        elif order.order_type == OrderType.STOP:
            self._try_trigger_stop(order, book)

    def _try_fill_limit(self, order: Order, book: LiveOrderBook) -> None:
        if order.side == OrderSide.BUY:
            best_ask = book.best_ask()
            if best_ask is not None and order.price >= best_ask:
                self._fill_against_book(order, book)
        else:
            best_bid = book.best_bid()
            if best_bid is not None and order.price <= best_bid:
                self._fill_against_book(order, book)

    def _try_trigger_stop(self, order: Order, book: LiveOrderBook) -> None:
        last = book.last_price
        if last is None:
            return
        triggered = (
            (order.side == OrderSide.BUY and last >= order.stop_price) or
            (order.side == OrderSide.SELL and last <= order.stop_price)
        )
        if triggered:
            self._fill_against_book(order, book)

    def _fill_against_book(self, order: Order, book: LiveOrderBook) -> None:
        levels = book.asks if order.side == OrderSide.BUY else book.bids
        remaining = order.remaining_quantity
        total_cost = 0.0
        total_filled = 0.0

        for level in list(levels):
            if remaining <= 0:
                break
            trade_qty = min(remaining, level.quantity)
            if trade_qty <= 0:
                continue
            total_cost += trade_qty * level.price
            total_filled += trade_qty
            level.quantity -= trade_qty
            remaining -= trade_qty

        levels[:] = [lvl for lvl in levels if lvl.quantity > 1e-9]

        if total_filled <= 0:
            return

        avg_price = total_cost / total_filled
        prev_filled = order.filled_quantity
        new_filled = prev_filled + total_filled
        order.avg_fill_price = (
            (order.avg_fill_price * prev_filled + total_cost) / new_filled
        )
        order.filled_quantity = new_filled
        order.updated_at = time.time()

        fill = Fill(
            fill_id=str(uuid.uuid4()),
            order_id=order.order_id,
            symbol=order.symbol,
            side=order.side,
            quantity=total_filled,
            price=avg_price,
        )
        self.fills.append(fill)

        signed_qty = total_filled if order.side == OrderSide.BUY else -total_filled
        self.positions[order.symbol] += signed_qty
        self.cash_balance -= signed_qty * avg_price

        if order.remaining_quantity <= 1e-9:
            order.status = OrderStatus.FILLED
        else:
            order.status = OrderStatus.PARTIALLY_FILLED

        self._notify(order)

    # ---- account state ----

    def get_position(self, symbol: str) -> float:
        return self.positions.get(symbol, 0.0)

    def get_open_orders(self) -> List[Order]:
        return [
            o for o in self.orders.values()
            if o.status in (OrderStatus.NEW, OrderStatus.PARTIALLY_FILLED)
        ]

    def get_order(self, order_id: str) -> Optional[Order]:
        return self.orders.get(order_id)


