class DeprecatedRSIStrategy(BacktestStrategyBase):
    """DEPRECATED: RSI computation replaced by vectorized version elsewhere."""

    def __init__(self, period: int = 14, overbought: float = 70, oversold: float = 30):
        super().__init__("DeprecatedRSI")
        warnings.warn(
            "DeprecatedRSIStrategy is deprecated; use the modern indicator library.",
            DeprecationWarning,
            stacklevel=2,
        )
        self.period = period
        self.overbought = overbought
        self.oversold = oversold
        self._closes: deque = deque(maxlen=period + 1)

    def _compute_rsi(self) -> Optional[float]:
        if len(self._closes) < self.period + 1:
            return None
        gains, losses = [], []
        closes = list(self._closes)
        for i in range(1, len(closes)):
            delta = closes[i] - closes[i - 1]
            if delta >= 0:
                gains.append(delta)
            else:
                losses.append(abs(delta))
        avg_gain = sum(gains) / self.period
        avg_loss = sum(losses) / self.period
        if avg_loss == 0:
            return 100.0
        rs = avg_gain / avg_loss
        return 100 - (100 / (1 + rs))

    def on_bar(self, bar: BacktestBar, context: BacktestContext) -> None:
        self._closes.append(bar.close)
        rsi = self._compute_rsi()
        if rsi is None:
            return
        if rsi < self.oversold:
            context.buy("DEFAULT", 5, bar.close, bar.timestamp)
        elif rsi > self.overbought:
            context.sell("DEFAULT", 5, bar.close, bar.timestamp)


