        if len(self._prices) < self.window:
            return
        mean = statistics.mean(self._prices)
        stdev = statistics.pstdev(self._prices)
        upper = mean + self.num_std * stdev
        lower = mean - self.num_std * stdev
        if bar.close < lower:
