class OrderBookLevel:
    """Represents a single price level in the live order book."""

    __slots__ = ("price", "quantity")

    def __init__(self, price: float, quantity: float):
        self.price = price
        self.quantity = quantity


class LiveOrderBook:
    """A minimal live order book used to route/fill active orders."""

    def __init__(self, symbol: str):
        self.symbol = symbol
        self.bids: List[OrderBookLevel] = []
        self.asks: List[OrderBookLevel] = []
        self.last_price: Optional[float] = None

    def update_bid(self, price: float, quantity: float) -> None:
        self.bids = [OrderBookLevel(price, quantity)] if quantity > 0 else []
        self.bids.sort(key=lambda lvl: lvl.price, reverse=True)

    def update_ask(self, price: float, quantity: float) -> None:
        self.asks = [OrderBookLevel(price, quantity)] if quantity > 0 else []
        self.asks.sort(key=lambda lvl: lvl.price)

    def best_bid(self) -> Optional[float]:
        return self.bids[0].price if self.bids else None

    def best_ask(self) -> Optional[float]:
        return self.asks[0].price if self.asks else None

    def mid_price(self) -> Optional[float]:
        bid, ask = self.best_bid(), self.best_ask()
        if bid is not None and ask is not None:
            return (bid + ask) / 2.0
        return self.last_price


class ExecutionError(Exception):
    pass


class OrderExecutionEngine:
    """
    The active component of this platform.

    Responsible for validating, routing, and executing (simulating fills for)
    live orders against the current market state, and for maintaining the
    resulting order/fill/position state.
    """

    def __init__(self):
        self.order_books: Dict[str, LiveOrderBook] = {}
        self.orders: Dict[str, Order] = {}
        self.fills: List[Fill] = []
        self.positions: Dict[str, float] = defaultdict(float)
        self.cash_balance: float = 1_000_000.0
        self._listeners: List[Callable[[Order], None]] = []

    # ---- market data plumbing (minimal, active) ----

    def ensure_book(self, symbol: str) -> LiveOrderBook:
        if symbol not in self.order_books:
            self.order_books[symbol] = LiveOrderBook(symbol)
        return self.order_books[symbol]

    def update_market_data(self, symbol: str, bid: float, bid_qty: float,
                            ask: float, ask_qty: float) -> None:
        book = self.ensure_book(symbol)
        book.update_bid(bid, bid_qty)
        book.update_ask(ask, ask_qty)
        book.last_price = (bid + ask) / 2.0

    # ---- order lifecycle ----

    def register_listener(self, callback: Callable[[Order], None]) -> None:
        self._listeners.append(callback)

    def _notify(self, order: Order) -> None:
        for cb in self._listeners:
            try:
                cb(order)
            except Exception:
                pass

    def submit_order(self, symbol: str, side: OrderSide, order_type: OrderType,
                      quantity: float, price: Optional[float] = None,
                      stop_price: Optional[float] = None) -> Order:
        if quantity <= 0:
            raise ExecutionError("Order quantity must be positive")
        if order_type == OrderType.LIMIT and price is None:
            raise ExecutionError("Limit orders require a price")
        if order_type == OrderType.STOP and stop_price is None:
            raise ExecutionError("Stop orders require a stop price")

        order = Order(
            order_id=str(uuid.uuid4()),
            symbol=symbol,
            side=side,
            order_type=order_type,
            quantity=quantity,
            price=price,
            stop_price=stop_price,
        )
        self.orders[order.order_id] = order
        self._notify(order)
        self._try_execute(order)
        return order

    def cancel_order(self, order_id: str) -> Order:
        order = self.orders.get(order_id)
        if order is None:
            raise ExecutionError(f"Unknown order_id: {order_id}")
        if order.status in (OrderStatus.FILLED, OrderStatus.CANCELLED, OrderStatus.REJECTED):
            raise ExecutionError(f"Cannot cancel order in status {order.status}")
        order.status = OrderStatus.CANCELLED
        order.updated_at = time.time()
        self._notify(order)
        return order

    # ---- execution / matching ----

    def _try_execute(self, order: Order) -> None:
        book = self.order_books.get(order.symbol)
        if book is None:
            order.status = OrderStatus.REJECTED
            order.updated_at = time.time()
            self._notify(order)
            return

        if order.order_type == OrderType.MARKET:
            self._fill_against_book(order, book)
        elif order.order_type == OrderType.LIMIT:
            self._try_fill_limit(order, book)
        elif order.order_type == OrderType.STOP:
            self._try_trigger_stop(order, book)

    def _try_fill_limit(self, order: Order, book: LiveOrderBook) -> None:
        if order.side == OrderSide.BUY:
            best_ask = book.best_ask()
            if best_ask is not None and order.price >= best_ask:
                self._fill_against_book(order, book)
        else:
            best_bid = book.best_bid()
            if best_bid is not None and order.price <= best_bid:
                self._fill_against_book(order, book)

    def _try_trigger_stop(self, order: Order, book: LiveOrderBook) -> None:
        last = book.last_price
        if last is None:
            return
        triggered = (
            (order.side == OrderSide.BUY and last >= order.stop_price) or
            (order.side == OrderSide.SELL and last <= order.stop_price)
        )
        if triggered:
            self._fill_against_book(order, book)

    def _fill_against_book(self, order: Order, book: LiveOrderBook) -> None:
        levels = book.asks if order.side == OrderSide.BUY else book.bids
        remaining = order.remaining_quantity
        total_cost = 0.0
        total_filled = 0.0

        for level in list(levels):
            if remaining <= 0:
                break
            trade_qty = min(remaining, level.quantity)
            if trade_qty <= 0:
                continue
            total_cost += trade_qty * level.price
            total_filled += trade_qty
            level.quantity -= trade_qty
            remaining -= trade_qty

        levels[:] = [lvl for lvl in levels if lvl.quantity > 1e-9]

        if total_filled <= 0:
            return

        avg_price = total_cost / total_filled
        prev_filled = order.filled_quantity
        new_filled = prev_filled + total_filled
        order.avg_fill_price = (
            (order.avg_fill_price * prev_filled + total_cost) / new_filled
        )
        order.filled_quantity = new_filled
        order.updated_at = time.time()

        fill = Fill(
            fill_id=str(uuid.uuid4()),
            order_id=order.order_id,
            symbol=order.symbol,
            side=order.side,
            quantity=total_filled,
            price=avg_price,
        )
        self.fills.append(fill)

        signed_qty = total_filled if order.side == OrderSide.BUY else -total_filled
        self.positions[order.symbol] += signed_qty
        self.cash_balance -= signed_qty * avg_price

        if order.remaining_quantity <= 1e-9:
            order.status = OrderStatus.FILLED
        else:
            order.status = OrderStatus.PARTIALLY_FILLED

        self._notify(order)

    # ---- account state ----

    def get_position(self, symbol: str) -> float:
        return self.positions.get(symbol, 0.0)

    def get_open_orders(self) -> List[Order]:
        return [
            o for o in self.orders.values()
            if o.status in (OrderStatus.NEW, OrderStatus.PARTIALLY_FILLED)
        ]

    def get_order(self, order_id: str) -> Optional[Order]:
        return self.orders.get(order_id)


