    def update(self, quantity: float, price: float) -> None:
        new_qty = self.quantity + quantity
        if new_qty == 0:
            self.avg_price = 0.0
        elif self.quantity == 0 or (self.quantity > 0) == (quantity > 0):
            total_cost = self.avg_price * self.quantity + price * quantity
            self.avg_price = total_cost / new_qty
        self.quantity = new_qty


class BacktestContext:
    """Portfolio/order state container used only within the backtester."""

    def __init__(self, starting_cash: float = 100_000.0):
        self.cash = starting_cash
        self.positions: Dict[str, BacktestPosition] = {}
        self.trade_log: List[Dict[str, Any]] = []
        self.equity_curve: List[Tuple[float, float]] = []

    def get_position(self, symbol: str) -> BacktestPosition:
        if symbol not in self.positions:
            self.positions[symbol] = BacktestPosition(symbol)
        return self.positions[symbol]

    def buy(self, symbol: str, quantity: float, price: float, timestamp: float) -> None:
        cost = quantity * price
        if cost > self.cash:
            quantity = self.cash / price
            cost = quantity * price
        if quantity <= 0:
            return
        self.cash -= cost
        self.get_position(symbol).update(quantity, price)
        self.trade_log.append({
            "timestamp": timestamp, "symbol": symbol,
            "side": "BUY", "quantity": quantity, "price": price
        })

    def sell(self, symbol: str, quantity: float, price: float, timestamp: float) -> None:
        pos = self.get_position(symbol)
        quantity = min(quantity, pos.quantity) if pos.quantity > 0 else quantity
        if quantity <= 0:
            return
        proceeds = quantity * price
        self.cash += proceeds
        pos.update(-quantity, price)
        self.trade_log.append({
            "timestamp": timestamp, "symbol": symbol,
            "side": "SELL", "quantity": quantity, "price": price
        })

    def mark_to_market(self, timestamp: float, prices: Dict[str, float]) -> None:
        equity = self.cash
        for symbol, pos in self.positions.items():
            price = prices.get(symbol, pos.avg_price)
            equity += pos.quantity * price
        self.equity_curve.append((timestamp, equity))


class BacktestEngine:
    """
    Full backtesting engine. Extensive but entirely unused by the live
    order execution path. Retained for potential future research use.
    """

    def __init__(self, data_feed: BacktestDataFeed, strategy: BacktestStrategyBase,
                 starting_cash: float = 100_000.0):
        self.data_feed = data_feed
        self.strategy = strategy
        self.context = BacktestContext(starting_cash)

    def run(self) -> BacktestContext:
        self.data_feed.reset()
        while self.data_feed.has_next():
            bar = self.data_feed.next_bar()
            if bar is None:
                break
            self.strategy.on_bar(bar, self.context)
            self.context.mark_to_market(bar.timestamp, {"DEFAULT": bar.close})
        return self.context

    def compute_statistics(self) -> Dict[str, float]:
        equity_values = [e for _, e in self.context.equity_curve]
        if len(equity_values) < 2:
            return {}
        returns = [
            (equity_values[i] - equity_values[i - 1]) / equity_values[i - 1]
            for i in range(1, len(equity_values))
            if equity_values[i - 1] != 0
        ]
        if not returns:
            return {}
        mean_return = statistics.mean(returns)
        stdev_return = statistics.pstdev(returns) if len(returns) > 1 else 0.0
        sharpe = (mean_return / stdev_return) * (252 ** 0.5) if stdev_return else 0.0
        total_return = (equity_values[-1] - equity_values[0]) / equity_values[0]
        max_drawdown = self._max_drawdown(equity_values)
        return {
            "total_return": total_return,
            "sharpe_ratio": sharpe,
            "max_drawdown": max_drawdown,
            "num_trades": len(self.context.trade_log),
        }

    @staticmethod
    def _max_drawdown(equity_values: List[float]) -> float:
        peak = equity_values[0]
        max_dd = 0.0
        for value in equity_values:
            peak = max(peak, value)
            if peak > 0:
                dd = (peak - value) / peak
                max_dd = max(max_dd, dd)
        return max_dd


class BacktestMonteCarloSimulator:
    """Randomized resampling of trade returns. Unused research utility."""

    def __init__(self, trade_returns: List[float], num_simulations: int = 1000):
        self.trade_returns = trade_returns
        self.num_simulations = num_simulations

    def run(self) -> Dict[str, float]:
        if not self.trade_returns:
            return {}
        outcomes = []
        for _ in range(self.num_simulations):
            sample = [random.choice(self.trade_returns) for _ in self.trade_returns]
            outcomes.append(sum(sample))
        outcomes.sort()
        return {
            "mean_outcome": statistics.mean(outcomes),
            "worst_case_5pct": outcomes[int(0.05 * len(outcomes))],
            "best_case_95pct": outcomes[int(0.95 * len(outcomes))],
        }


class BacktestParameterOptimizer:
    """Grid-search optimizer over strategy parameters. Never invoked live."""

    def __init__(self, strategy_factory: Callable[..., BacktestStrategyBase],
                 data_feed: BacktestDataFeed):
        self.strategy_factory = strategy_factory
        self.data_feed = data_feed

    def optimize(self, param_grid: Dict[str, List[Any]]) -> Dict[str, Any]:
        best_result = None
        best_params = None
        keys = list(param_grid.keys())

        def combinations(idx: int, current: Dict[str, Any]):
            if idx == len(keys):
                yield dict(current)
                return
            key = keys[idx]
            for val in param_grid[key]:
                current[key] = val
                yield from combinations(idx + 1, current)

        for params in combinations(0, {}):
            strategy = self.strategy_factory(**params)
            engine = BacktestEngine(self.data_feed, strategy)
            engine.run()
            stats = engine.compute_statistics()
            score = stats.get("sharpe_ratio", float("-inf"))
            if best_result is None or score > best_result:
                best_result = score
                best_params = params

        return {"best_params": best_params, "best_sharpe": best_result}


