from abc import ABC, abstractmethod
from dataclasses import dataclass
from datetime import datetime
import re


# ---------------------------
# Payment Class Hierarchy
# ---------------------------

class Payment(ABC):
    def __init__(self, amount: float, currency: str = "USD"):
        self.amount = amount
        self.currency = currency
        self.timestamp = datetime.now()

    @abstractmethod
    def process(self) -> str:
        """Process the payment and return a confirmation message."""
        pass

    def __repr__(self):
        return f"{self.__class__.__name__}(amount={self.amount}, currency={self.currency})"


class CreditCard(Payment):
    def __init__(self, amount: float, card_number: str, expiry_date: str,
                 cvv: str, cardholder_name: str, currency: str = "USD"):
        super().__init__(amount, currency)
        self.card_number = card_number
        self.expiry_date = expiry_date  # MM/YY
        self.cvv = cvv
        self.cardholder_name = cardholder_name

    def process(self) -> str:
        return (f"Processed credit card payment of {self.amount} {self.currency} "
                f"for {self.cardholder_name}, card ending in {self.card_number[-4:]}")


class BankTransfer(Payment):
    def __init__(self, amount: float, account_number: str, routing_number: str,
                 account_holder_name: str, currency: str = "USD"):
        super().__init__(amount, currency)
        self.account_number = account_number
        self.routing_number = routing_number
        self.account_holder_name = account_holder_name

    def process(self) -> str:
        return (f"Processed bank transfer of {self.amount} {self.currency} "
                f"from account ending in {self.account_number[-4:]}")


class Crypto(Payment):
    def __init__(self, amount: float, wallet_address: str, network: str,
                 currency: str = "BTC"):
        super().__init__(amount, currency)
        self.wallet_address = wallet_address
        self.network = network  # e.g., "Bitcoin", "Ethereum"

    def process(self) -> str:
        return (f"Processed crypto payment of {self.amount} {self.currency} "
                f"on {self.network} network to wallet {self.wallet_address[:6]}...")


# ---------------------------
# Validation Result
# ---------------------------

@dataclass
class ValidationResult:
    is_valid: bool
    errors: list

    def __bool__(self):
        return self.is_valid

    def __repr__(self):
        if self.is_valid:
            return "ValidationResult(valid=True)"
        return f"ValidationResult(valid=False, errors={self.errors})"


# ---------------------------
# Validator Class Hierarchy
# ---------------------------

class PaymentValidator(ABC):
    @abstractmethod
    def validate(self, payment: Payment) -> ValidationResult:
        """Validate the given payment and return a ValidationResult."""
        pass

    def _validate_amount(self, amount: float, errors: list) -> None:
        if amount is None:
            errors.append("Amount is required.")
        elif amount <= 0:
            errors.append("Amount must be greater than zero.")


class CreditCardValidator(PaymentValidator):
    CARD_NUMBER_PATTERN = re.compile(r'^\d{13,19}$')
    EXPIRY_PATTERN = re.compile(r'^(0[1-9]|1[0-2])/\d{2}$')
    CVV_PATTERN = re.compile(r'^\d{3,4}$')

    def validate(self, payment: CreditCard) -> ValidationResult:
        errors = []

        if not isinstance(payment, CreditCard):
            errors.append("Payment is not a CreditCard instance.")
            return ValidationResult(False, errors)

        self._validate_amount(payment.amount, errors)

        if not payment.card_number or not self.CARD_NUMBER_PATTERN.match(payment.card_number):
            errors.append("Invalid card number format.")
        elif not self._luhn_check(payment.card_number):
            errors.append("Card number failed Luhn check.")

        if not payment.expiry_date or not self.EXPIRY_PATTERN.match(payment.expiry_date):
            errors.append("Invalid expiry date format (expected MM/YY).")
        else:
            if self._is_expired(payment.expiry_date):
                errors.append("Card has expired.")

        if not payment.cvv or not self.CVV_PATTERN.match(payment.cvv):
            errors.append("Invalid CVV format.")

        if not payment.cardholder_name or not payment.cardholder_name.strip():
            errors.append("Cardholder name is required.")

        return ValidationResult(len(errors) == 0, errors)

    @staticmethod
    def _luhn_check(card_number: str) -> bool:
        digits = [int(d) for d in card_number]
        checksum = 0
        reverse_digits = digits[::-1]
        for i, digit in enumerate(reverse_digits):
            if i % 2 == 1:
                digit *= 2
                if digit > 9:
                    digit -= 9
            checksum += digit
        return checksum % 10 == 0

    @staticmethod
    def _is_expired(expiry_date: str) -> bool:
        month_str, year_str = expiry_date.split('/')
        month = int(month_str)
        year = 2000 + int(year_str)
        now = datetime.now()
        if year < now.year:
            return True
        if year == now.year and month < now.month:
            return True
        return False


class BankTransferValidator(PaymentValidator):
    ACCOUNT_NUMBER_PATTERN = re.compile(r'^\d{6,17}$')
    ROUTING_NUMBER_PATTERN = re.compile(r'^\d{9}$')

    def validate(self, payment: BankTransfer) -> ValidationResult:
        errors = []

        if not isinstance(payment, BankTransfer):
            errors.append("Payment is not a BankTransfer instance.")
            return ValidationResult(False, errors)

        self._validate_amount(payment.amount, errors)

        if not payment.account_number or not self.ACCOUNT_NUMBER_PATTERN.match(payment.account_number):
            errors.append("Invalid account number format.")

        if not payment.routing_number or not self.ROUTING_NUMBER_PATTERN.match(payment.routing_number):
            errors.append("Invalid routing number format (expected 9 digits).")
        elif not self._validate_routing_checksum(payment.routing_number):
            errors.append("Routing number failed checksum validation.")

        if not payment.account_holder_name or not payment.account_holder_name.strip():
            errors.append("Account holder name is required.")

        return ValidationResult(len(errors) == 0, errors)

    @staticmethod
    def _validate_routing_checksum(routing_number: str) -> bool:
        digits = [int(d) for d in routing_number]
        checksum = (
            3 * (digits[0] + digits[3] + digits[6]) +
            7 * (digits[1] + digits[4] + digits[7]) +
            1 * (digits[2] + digits[5] + digits[8])
        )
        return checksum % 10 == 0


class CryptoValidator(PaymentValidator):
    NETWORK_ADDRESS_PATTERNS = {
        "Bitcoin": re.compile(r'^(bc1|[13])[a-zA-HJ-NP-Z0-9]{25,39}$'),
        "Ethereum": re.compile(r'^0x[a-fA-F0-9]{40}$'),
    }
    SUPPORTED_NETWORKS = set(NETWORK_ADDRESS_PATTERNS.keys())

    def validate(self, payment: Crypto) -> ValidationResult:
        errors = []

        if not isinstance(payment, Crypto):
            errors.append("Payment is not a Crypto instance.")
            return ValidationResult(False, errors)

        self._validate_amount(payment.amount, errors)

        if not payment.network or payment.network not in self.SUPPORTED_NETWORKS:
            errors.append(f"Unsupported or missing network. Supported: {', '.join(self.SUPPORTED_NETWORKS)}")
        else:
            pattern = self.NETWORK_ADDRESS_PATTERNS[payment.network]
            if not payment.wallet_address or not pattern.match(payment.wallet_address):
                errors.append(f"Invalid wallet address format for {payment.network} network.")

        if not payment.currency or not payment.currency.strip():
            errors.append("Currency is required.")

        return ValidationResult(len(errors) == 0, errors)


