    def set_position_limit(self, symbol, limit):
        self.position_limits[symbol] = limit

    def check_risk(self, client, order, price):
        notional = order.quantity * (price or 0)

        if order.side == OrderSide.BUY:
            required_cash = notional
            if required_cash > client.cash_balance:
                return False, "Insufficient cash balance"

