    # ---------- Order Routing & Execution ----------
    def submit_order(self, client_id, symbol, side, quantity, order_type=OrderType.MARKET,
                      price=None, stop_price=None):
        with self.lock:
            client = self._get_client(client_id)
            side_enum = side if isinstance(side, OrderSide) else OrderSide(side)
            type_enum = order_type if isinstance(order_type, OrderType) else OrderType(order_type)

            order = Order(client_id, symbol, side_enum, quantity, type_enum, price, stop_price)
            self.orders[order.order_id] = order
            client.orders[order.order_id] = order

            ref_price = self._determine_reference_price(order)

            passed_compliance, reason = self.compliance.check_order(client, order, ref_price)
            if not passed_compliance:
                order.status = OrderStatus.REJECTED
                order.reject_reason = reason
                self.compliance.log_violation(client_id, reason, order.order_id)
                self._log(f"Order {order.order_id} rejected (compliance): {reason}")
                return order.order_id

            passed_risk, risk_reason = self.risk_manager.check_risk(client, order, ref_price)
            if not passed_risk:
                order.status = OrderStatus.REJECTED
                order.reject_reason = risk_reason
                self.compliance.log_violation(client_id, risk_reason, order.order_id)
                self._log(f"Order {order.order_id} rejected (risk): {risk_reason}")
                return order.order_id

            order.status = OrderStatus.ACCEPTED
            self._log(f"Order {order.order_id} accepted")
            self._route_order(order)
            return order.order_id

    def _determine_reference_price(self, order):
        if order.order_type == OrderType.LIMIT and order.price:
            return order.price
        market_price = self.market_data.get_price(order.symbol)
        if market_price:
            return market_price
        return order.price or order.stop_price or 0.0

    def _route_order(self, order):
        market_price = self.market_data.get_price(order.symbol)

        if order.order_type == OrderType.MARKET:
            if market_price is None:
                order.status = OrderStatus.REJECTED
                order.reject_reason = "No market price available"
                self._log(f"Order {order.order_id} rejected: no market data")
                return
            self._execute_fill(order, order.quantity, market_price, is_maker=False)

        elif order.order_type == OrderType.LIMIT:
            if market_price is None:
                return  # remains accepted, awaiting market data
            can_fill = (
                (order.side == OrderSide.BUY and market_price <= order.price) or
                (order.side == OrderSide.SELL and market_price >= order.price)
            )
            if can_fill:
                self._execute_fill(order, order.quantity, market_price, is_maker=True)

        elif order.order_type == OrderType.STOP:
            if market_price is None:
                return
            triggered = (
                (order.side == OrderSide.BUY and market_price >= order.stop_price) or
                (order.side == OrderSide.SELL and market_price <= order.stop_price)
            )
            if triggered:
                self._execute_fill(order, order.quantity, market_price, is_maker=False)

    def _execute_fill(self, order, quantity, price, is_maker=False):
        client = self._get_client(order.client_id)
        notional = quantity * price
        fee = self.fee_schedule.calculate_fee(notional, is_maker)

        fill = Fill(order.order_id, order.symbol, order.side, quantity, price, fee)
        self.fills.append(fill)
        order.fills.append(fill)

        if order.side == OrderSide.BUY:
            total_cost_before = client.avg_cost[order.symbol] * client.positions[order.symbol]
            new_position = client.positions[order.symbol] + quantity
            total_cost = total_cost_before + notional
            client.avg_cost[order.symbol] = (total_cost / new_position) if new_position != 0 else 0
            client.positions[order.symbol] = new_position
            client.cash_balance -= (notional + fee)
        else:
            client.positions[order.symbol] -= quantity
            client.cash_balance += (notional - fee)

        order.filled_quantity += quantity
        order.remaining_quantity -= quantity
        total_filled_notional = order.avg_fill_price * (order.filled_quantity - quantity) + notional
        order.avg_fill_price = total_filled_notional / order.filled_quantity if order.filled_quantity else 0
        order.updated_at = datetime.utcnow()

        if order.remaining_quantity <= 0:
            order.status = OrderStatus.FILLED
        else:
            order.status = OrderStatus.PARTIALLY_FILLED

        client.trade_history.append(fill)
        self._log(f"Fill executed: order={order.order_id}, qty={quantity}, price={price}, fee={fee}")

    def cancel_order(self, order_id):
        with self.lock:
            order = self.orders.get(order_id)
            if order is None:
                raise ValueError(f"Unknown order_id: {order_id}")
            if order.status in (OrderStatus.FILLED, OrderStatus.CANCELLED, OrderStatus.REJECTED):
                return False
            order.status = OrderStatus.CANCELLED
            order.updated_at = datetime.utcnow()
            self._log(f"Order {order_id} cancelled")
            return True

    def process_pending_orders(self):
        """Re-evaluate accepted/partially-filled limit and stop orders against latest market data."""
        with self.lock:
            for order in list(self.orders.values()):
                if order.status in (OrderStatus.ACCEPTED, OrderStatus.PARTIALLY_FILLED):
                    if order.order_type in (OrderType.LIMIT, OrderType.STOP):
                        self._route_order(order)

