        return client.positions.get(symbol, 0.0)

    # ---------- Reporting ----------
    def generate_client_report(self, client_id):
        client = self._get_client(client_id)
        orders_report = [
            {
                "order_id": o.order_id,
                "symbol": o.symbol,
                "side": o.side.value,
                "quantity": o.quantity,
                "filled_quantity": o.filled_quantity,
