        if not raw or not raw.strip():
            raise ParsingError("Empty HL7v2 message")

        raw = raw.strip()
        lines = [l for l in self.SEGMENT_SEP_RE.split(raw) if l.strip()]
        if not lines or not lines[0].startswith("MSH"):
            raise ParsingError("HL7v2 message must start with MSH segment")

        msh_line = lines[0]
        if len(msh_line) < 8:
            raise ParsingError("MSH segment too short")

        field_sep = msh_line[3]
        encoding_chars = msh_line[4:8]
        comp_sep = encoding_chars[0] if len(encoding_chars) > 0 else "^"
        rep_sep = encoding_chars[1] if len(encoding_chars) > 1 else "~"
        esc_char = encoding_chars[2] if len(encoding_chars) > 2 else "\\"
        sub_comp_sep = encoding_chars[3] if len(encoding_chars) > 3 else "&"

        segments = []
        for line in lines:
            fields = line.split(field_sep)
            if fields[0] == "MSH":
                # MSH-1 is the field separator itself; reinsert as first data field
                fields = ["MSH", field_sep] + fields[1:]
            segments.append(fields)

        return HL7v2Message(
            segments=segments,
            field_sep=field_sep,
            comp_sep=comp_sep,
            rep_sep=rep_sep,
            esc_char=esc_char,
            sub_comp_sep=sub_comp_sep,
