def normalize_patient_id_step(message: Message) -> Message:
    """Strips whitespace and uppercases PID-3 patient identifier(s)."""
    msg: HL7v2Message = message.parsed
    pid = msg.get_segment("PID")
    if pid and len(pid) > 3 and pid[3]:
        components = pid[3].split(msg.comp_sep)
        if components:
            components[0] = components[0].strip().upper()
        pid[3] = msg.comp_sep.join(components)
    return message


def enrich_event_timestamp_step(message: Message) -> Message:
    """Ensures EVN-2 (recorded date/time) is populated."""
    msg: HL7v2Message = message.parsed
    evn = msg.get_segment("EVN")
    if evn:
        while len(evn) < 3:
            evn.append("")
        if not evn[2]:
            evn[2] = datetime.utcnow().strftime("%Y%m%d%H%M%S")
    return message


def add_processing_metadata_step(message: Message) -> Message:
    msg: HL7v2Message = message.parsed
    message.metadata["trigger_event"] = msg.trigger_event
    message.metadata["message_control_id"] = msg.message_control_id
    message.metadata["sending_application"] = msg.sending_application
    message.metadata["receiving_application"] = msg.receiving_application
    return message


def build_default_adt_pipeline() -> TransformationPipeline:
    pipeline = TransformationPipeline(name="default_adt_pipeline")
    pipeline.add_step(normalize_patient_id_step, "normalize_patient_id")
    pipeline.add_step(enrich_event_timestamp_step, "enrich_event_timestamp")
    pipeline.add_step(add_processing_metadata_step, "add_processing_metadata")
    return pipeline


# ---------------------------------------------------------------------------
# Routing Engine
# ---------------------------------------------------------------------------

@dataclass
class RoutingRule:
    name: str
    condition: Callable[[Message], bool]
    destination: str
    pipeline: Optional[TransformationPipeline] = None
    priority: int = 0


class Destination(ABC):
    name: str

    @abstractmethod
    def deliver(self, message: Message) -> bool:
        ...


class InMemoryDestination(Destination):
    """A destination that stores delivered messages -- useful for testing/demo."""

    def __init__(self, name: str):
        self.name = name
        self.received: List[Message] = []

    def deliver(self, message: Message) -> bool:
        self.received.append(message)
        logger.info(f"Destination '{self.name}' received message {message.message_id}")
        return True


class LoggingDestination(Destination):
    def __init__(self, name: str = "logger"):
        self.name = name

    def deliver(self, message: Message) -> bool:
        logger.info(f"[{self.name}] Delivered message {message.message_id}: "
                     f"{message.metadata}")
        return True


class Router:
    def __init__(self):
        self.rules: List[RoutingRule] = []
        self.destinations: Dict[str, Destination] = {}

    def register_destination(self, destination: Destination) -> None:
        self.destinations[destination.name] = destination

    def add_rule(self, rule: RoutingRule) -> None:
        self.rules.append(rule)
        self.rules.sort(key=lambda r: r.priority, reverse=True)

    def route(self, message: Message) -> List[str]:
        matched_destinations = []
        for rule in self.rules:
            try:
                if rule.condition(message):
                    target_message = message
                    if rule.pipeline:
                        target_message = rule.pipeline.run(message)
                    destination = self.destinations.get(rule.destination)
                    if destination is None:
                        raise RoutingError(f"Unknown destination: {rule.destination}")
                    success = destination.deliver(target_message)
                    if success:
                        matched_destinations.append(rule.destination)
            except Exception as e:
                logger.error(f"Routing rule '{rule.name}' failed: {e}")
        if not matched_destinations:
            logger.warning(f"No routing rule matched message {message.message_id}")
        return matched_destinations


