# ---------------------------------------------------------------------------

class AckGenerator(ABC):
    @abstractmethod
    def generate_ack(self, message: Message, status: AckStatus, text: str = "") -> AckResult:
        ...


class HL7v2AckGenerator(AckGenerator):
    def generate_ack(self, message: Message, status: AckStatus, text: str = "") -> AckResult:
        msg: HL7v2Message = message.parsed
        field_sep = msg.field_sep
        comp_sep = msg.comp_sep

        now = datetime.utcnow().strftime("%Y%m%d%H%M%S")
        ack_control_id = str(uuid.uuid4())[:20]

        msh_fields = [
            "MSH",
            field_sep,
            f"{comp_sep}~\\&",
            msg.receiving_application or "RECEIVER",
            "",
            msg.sending_application or "SENDER",
            "",
            now,
            "",
            f"ACK{comp_sep}{msg.trigger_event}",
            ack_control_id,
            msg.processing_id or "P",
            msg.version_id or "2.5",
        ]
        msh_line = "MSH" + field_sep + field_sep.join(msh_fields[3:])

        msa_line = field_sep.join([
            "MSA",
            status.value,
            msg.message_control_id,
            text,
        ])

        ack_raw = msh_line + "\r" + msa_line + "\r"

        return AckResult(
            status=status,
            message_id=message.message_id,
            text=text,
            ack_message=ack_raw,
        )


class AckManager:
    def __init__(self, generators: Optional[Dict[MessageFormat, AckGenerator]] = None):
        self.generators = generators or {
            MessageFormat.HL7V2: HL7v2AckGenerator(),
        }
        self.ack_log: Dict[str, AckResult] = {}

    def acknowledge(self, message: Message, status: AckStatus, text: str = "") -> AckResult:
        generator = self.generators.get(message.format)
        if generator is None:
            result = AckResult(status=status, message_id=message.message_id, text=text)
        else:
            result = generator.generate_ack(message, status, text)
        self.ack_log[message.message_id] = result
        return result

    def get_ack(self, message_id: str) -> Optional[AckResult]:
        return self.ack_log.get(message_id)


