    def __init__(self, symbol: str, currency: str, price: float):
        self.symbol = symbol
        self.currency = currency
        self.price = price

    @abstractmethod
    def contract_size(self) -> float:
        ...

    @abstractmethod
    def notional_value(self, quantity: float) -> float:
        return self.price * quantity * self.contract_size()

    def describe(self) -> str:
        return f"{self.__class__.__name__}({self.symbol}, px={self.price})"


class Stock(Instrument):
    def __init__(self, symbol: str, currency: str, price: float, dividend_yield: float = 0.0):
        super().__init__(symbol, currency, price)
        self.dividend_yield = dividend_yield

    def contract_size(self) -> float:
        return 1.0

    def notional_value(self, quantity: float) -> float:
        return self.price * quantity * self.contract_size()


class Option(Instrument):
    def __init__(self, symbol: str, currency: str, price: float, strike: float,
                 expiry: date, option_type: OptionType, multiplier: float = 100.0,
                 underlying_price: Optional[float] = None, implied_vol: float = 0.2):
        super().__init__(symbol, currency, price)
        self.strike = strike
        self.expiry = expiry
        self.option_type = option_type
        self.multiplier = multiplier
        self.underlying_price = underlying_price if underlying_price is not None else price
        self.implied_vol = implied_vol

    def contract_size(self) -> float:
        return self.multiplier

    def notional_value(self, quantity: float) -> float:
        return self.underlying_price * quantity * self.contract_size()

    def days_to_expiry(self, as_of: date) -> int:
        return max((self.expiry - as_of).days, 0)

    def is_itm(self) -> bool:
        if self.option_type == OptionType.CALL:
            return self.underlying_price > self.strike
        return self.underlying_price < self.strike


