class OrderHandler(ABC):
    """Base handler defining the common order lifecycle."""

    def handle(self, order: Order) -> Order:
        if not self.validate(order):
            order.status = OrderStatus.REJECTED
            return order
        order.status = OrderStatus.VALIDATED
        self.route(order)
        self.fill(order)
        return order

    @abstractmethod
    def validate(self, order: Order) -> bool:
        ...

    @abstractmethod
    def route(self, order: Order) -> None:
        ...

    def fill(self, order: Order) -> None:
        if order.order_type == OrderType.MARKET:
            order.fill_price = order.instrument.price
        elif order.order_type == OrderType.LIMIT:
            order.fill_price = order.limit_price
        else:
            order.fill_price = order.stop_price or order.instrument.price
        order.status = OrderStatus.FILLED


