class RiskCalculator(ABC):
    @abstractmethod
    def calculate_risk(self, instrument: Instrument, quantity: float) -> float:
        ...

    def value_at_risk(self, instrument: Instrument, quantity: float,
                       volatility: float, confidence_z: float = 1.65) -> float:
        notional = instrument.notional_value(quantity)
        return abs(notional) * volatility * confidence_z


class StockRiskCalculator(RiskCalculator):
    def calculate_risk(self, instrument: Stock, quantity: float) -> float:
        beta_adj = 1.0
        return instrument.notional_value(quantity) * 0.02 * beta_adj


class OptionRiskCalculator(RiskCalculator):
    def calculate_risk(self, instrument: Option, quantity: float) -> float:
        delta = 0.5 if not instrument.is_itm() else 0.8
        gamma_risk = instrument.implied_vol * instrument.notional_value(quantity) * 0.01
        return abs(delta) * instrument.notional_value(quantity) * 0.05 + gamma_risk

    def theta_decay_risk(self, instrument: Option, quantity: float) -> float:
        days = instrument.days_to_expiry(date.today())
        time_factor = 1 / max(days, 1)
        return instrument.notional_value(quantity) * time_factor * 0.01


class FutureRiskCalculator(RiskCalculator):
    def calculate_risk(self, instrument: Future, quantity: float) -> float:
        tick_risk = instrument.tick_size * instrument.multiplier * quantity
        return instrument.notional_value(quantity) * 0.03 + tick_risk


class ForexRiskCalculator(RiskCalculator):
    def calculate_risk(self, instrument: Forex, quantity: float) -> float:
        return instrument.notional_value(quantity) * 0.01


