                f"Fill Price: {order.fill_price}, Pair: {inst.base_currency}/{inst.quote_currency}")


# =========================================================================
# Factory to wire parallel hierarchies together
# =========================================================================

class TradingComponentFactory:
    _registry = {
        Stock: (StockOrderHandler, StockRiskCalculator, StockMarginCalculator,
                StockSettlementProcessor, StockReportGenerator),
        Option: (OptionOrderHandler, OptionRiskCalculator, OptionMarginCalculator,
                 OptionSettlementProcessor, OptionReportGenerator),
        Future: (FutureOrderHandler, FutureRiskCalculator, FutureMarginCalculator,
                 FutureSettlementProcessor, FutureReportGenerator),
        Forex: (ForexOrderHandler, ForexRiskCalculator, ForexMarginCalculator,
                ForexSettlementProcessor, ForexReportGenerator),
    }

    @classmethod
    def create_suite(cls, instrument_type: type):
        if instrument_type not in cls._registry:
            raise ValueError(f"No components registered for {instrument_type}")
        handler_cls, risk_cls, margin_cls, settle_cls, report_cls = cls._registry[instrument_type]
        return {
            "order_handler": handler_cls(),
            "risk_calculator": risk_cls(),
            "margin_calculator": margin_cls(),
            "settlement_processor": settle_cls(),
            "report_generator": report_cls(),
        }


# =========================================================================
# Example orchestration
# =========================================================================

class TradingWorkflow:
    def __init__(self, instrument: Instrument):
        self.instrument = instrument
        suite = TradingComponentFactory.create_suite(type(instrument))
        self.order_handler: OrderHandler = suite["order_handler"]
        self.risk_calculator: RiskCalculator = suite["risk_calculator"]
        self.margin_calculator: MarginCalculator = suite["margin_calculator"]
        self.settlement_processor: SettlementProcessor = suite["settlement_processor"]
        self.report_generator: ReportGenerator = suite["report_generator"]

    def execute(self, order: Order) -> str:
        order = self.order_handler.handle(order)
        if order.status == OrderStatus.REJECTED:
            return self.report_generator.generate_report(order)

        risk = self.risk_calculator.calculate_risk(order.instrument, order.quantity)
        margin = self.margin_calculator.initial_margin(order.instrument, order.quantity)
        self.settlement_processor.process(order)

        report = self.report_generator.generate_report(order)
        report += f"\nRisk: {risk:.2f} | Initial Margin: {margin:.2f}"
        return report
