        return self.BASE_SHIPPING_COST

    def checkout(self, cart_id, shipping_address=None):
        cart = self.get_cart(cart_id)
        if cart.is_empty():
            raise ECommerceEngineError("Cannot checkout an empty cart")

        customer = self.get_customer(cart.customer_id)
        address = shipping_address or customer.address

        # Reserve stock for all items first
        reserved = []
        try:
            for product_id, cart_item in cart.items.items():
                self._reserve_stock(product_id, cart_item.quantity)
                reserved.append((product_id, cart_item.quantity))
        except InsufficientInventoryError:
            for product_id, qty in reserved:
                self._release_reservation(product_id, qty)
            raise

        subtotal = cart.total()
        tax = self.calculate_tax(subtotal)
        shipping_cost = self.calculate_shipping(subtotal)
        total = round(subtotal + tax + shipping_cost, 2)

        order_id = self._generate_id("ORD")
        order_items = {pid: (item.quantity, item.unit_price) for pid, item in cart.items.items()}
        order = Order(order_id, cart.customer_id, order_items, address, subtotal, tax, shipping_cost, total)
        self.orders[order_id] = order

        customer.order_history.append(order_id)
        self.clear_cart(cart_id)

