            raise ECommerceEngineError("Cannot cancel an order that has already shipped")
        for product_id, (qty, _) in order.items.items():
            self._release_reservation(product_id, qty)
        order.set_status(OrderStatus.CANCELLED)
        if order.payment_id:
            payment = self.payments.get(order.payment_id)
            if payment and payment.status == PaymentStatus.SUCCESS:
                self.refund_payment(order.payment_id)
        return order

    # ---------- Payment Processing ----------

    def process_payment(self, order_id, method, card_info=None):
        order = self.get_order(order_id)
        if order.status != OrderStatus.PENDING:
            raise PaymentError(f"Order {order_id} is not eligible for payment")

        payment_id = self._generate_id("PAY")
        payment = Payment(payment_id, order_id, order.total, method)

        success = self._simulate_payment_gateway(method, card_info, order.total)

        if success:
            payment.status = PaymentStatus.SUCCESS
            payment.transaction_ref = str(uuid.uuid4())
            self.payments[payment_id] = payment
            order.payment_id = payment_id
            order.set_status(OrderStatus.PAID)

            for product_id, (qty, unit_price) in order.items.items():
                self._commit_stock_deduction(product_id, qty)
                self.analytics["product_purchases"][product_id] += qty
                product = self.products.get(product_id)
                if product:
                    self.analytics["category_revenue"][product.category] += qty * unit_price

            today = order.created_at.date().isoformat()
            self.analytics["revenue_by_day"][today] += order.total
            self.analytics["orders_by_day"][today] += 1

            customer = self.customers.get(order.customer_id)
            if customer:
                customer.lifetime_value += order.total

            return payment
        else:
            payment.status = PaymentStatus.FAILED
            self.payments[payment_id] = payment
            raise PaymentError("Payment processing failed")

    def _simulate_payment_gateway(self, method, card_info, amount):
        if amount <= 0:
