            return False
        return True

    def refund_payment(self, payment_id):
        payment = self.payments.get(payment_id)
        if not payment:
            raise PaymentError(f"Payment {payment_id} not found")
        if payment.status != PaymentStatus.SUCCESS:
            raise PaymentError("Only successful payments can be refunded")
        payment.status = PaymentStatus.REFUNDED
        order = self.orders.get(payment.order_id)
        if order:
            order.set_status(OrderStatus.REFUNDED)
            customer = self.customers.get(order.customer_id)
            if customer:
                customer.lifetime_value -= order.total
            for product_id, (qty, _) in order.items.items():
                self._restock(product_id, qty)
