        "in_progress": [EntityStatus.APPROVED, EntityStatus.ACTIVE, EntityStatus.ON_HOLD],
        "closed": [EntityStatus.REJECTED, EntityStatus.CANCELLED, EntityStatus.ARCHIVED],
    }

    @classmethod
    def filter_by_category(cls, entities: List[Entity], category: str) -> List[Entity]:
        statuses = cls.STATUS_CATEGORIES.get(category, [])
        return [e for e in entities if e.status in statuses]

    @classmethod
    def filter_by_status(cls, entities: List[Entity], status: EntityStatus) -> List[Entity]:
        return [e for e in entities if e.status == status]

    @classmethod
    def category_of(cls, status: EntityStatus) -> Optional[str]:
        for category, statuses in cls.STATUS_CATEGORIES.items():
            if status in statuses:
                return category
        return None

    @classmethod
    def summary(cls, entities: List[Entity]) -> Dict[str, int]:
        result = {category: 0 for category in cls.STATUS_CATEGORIES}
        for e in entities:
            category = cls.category_of(e.status)
            if category:
                result[category] += 1
        return result


