class ExportHandler:
    """Handles exporting entities to various formats, with status label mapping."""

    STATUS_EXPORT_LABELS: Dict[EntityStatus, str] = {
        EntityStatus.DRAFT: "Draft",
        EntityStatus.PENDING_APPROVAL: "Pending Approval",
        EntityStatus.APPROVED: "Approved",
        EntityStatus.ACTIVE: "Active",
        EntityStatus.ON_HOLD: "On Hold",
        EntityStatus.REJECTED: "Rejected",
        EntityStatus.CANCELLED: "Cancelled",
        EntityStatus.ARCHIVED: "Archived",
    }

    @classmethod
    def to_csv(cls, entities: List[Entity]) -> str:
        lines = ["id,name,status,created_at,updated_at"]
        for e in entities:
            label = cls.STATUS_EXPORT_LABELS.get(e.status, e.status.value)
            lines.append(f"{e.id},{e.name},{label},{e.created_at.isoformat()},{e.updated_at.isoformat()}")
        return "\n".join(lines)

    @classmethod
    def to_json(cls, entities: List[Entity]) -> str:
        data = []
        for e in entities:
            label = cls.STATUS_EXPORT_LABELS.get(e.status, e.status.value)
            data.append(
                {
                    "id": e.id,
                    "name": e.name,
                    "status": label,
                    "created_at": e.created_at.isoformat(),
                    "updated_at": e.updated_at.isoformat(),
                }
            )
        return json.dumps(data, indent=2)


