            EntityStatus.ON_HOLD: self._handle_on_hold,
            EntityStatus.REJECTED: self._handle_rejected,
            EntityStatus.CANCELLED: self._handle_cancelled,
            EntityStatus.ARCHIVED: self._handle_archived,
        }

    def transition(self, entity: Entity, new_status: EntityStatus, actor: str = "system") -> Entity:
        old_status = entity.status
        StatusTransitions.validate(old_status, new_status)

        entity.set_status(new_status)

        handler = self._status_handlers.get(new_status)
        if handler:
            handler(entity)

        self.notification_handler.notify(entity, old_status, new_status)
        self.audit_logger.log_transition(entity, old_status, new_status, actor)

        return entity

    # --- status handlers ---
    def _handle_draft(self, entity: Entity) -> None:
        entity.metadata["draft_touched_at"] = datetime.utcnow().isoformat()

    def _handle_pending_approval(self, entity: Entity) -> None:
        entity.metadata["submitted_for_approval_at"] = datetime.utcnow().isoformat()

    def _handle_approved(self, entity: Entity) -> None:
        entity.metadata["approved_at"] = datetime.utcnow().isoformat()

    def _handle_active(self, entity: Entity) -> None:
        entity.metadata["activated_at"] = datetime.utcnow().isoformat()

    def _handle_on_hold(self, entity: Entity) -> None:
        entity.metadata["held_at"] = datetime.utcnow().isoformat()

    def _handle_rejected(self, entity: Entity) -> None:
        entity.metadata["rejected_at"] = datetime.utcnow().isoformat()

    def _handle_cancelled(self, entity: Entity) -> None:
        entity.metadata["cancelled_at"] = datetime.utcnow().isoformat()

    def _handle_archived(self, entity: Entity) -> None:
        entity.metadata["archived_at"] = datetime.utcnow().isoformat()


# ---------------------------------------------------------------------------
# 4. Notification Handlers
# ---------------------------------------------------------------------------

class NotificationHandler:
    """Sends notifications based on status changes."""

    def __init__(self):
        self.sent_notifications: List[Dict[str, Any]] = []
        self._notification_map: Dict[EntityStatus, str] = {
            EntityStatus.DRAFT: "Entity '{name}' saved as draft.",
            EntityStatus.PENDING_APPROVAL: "Entity '{name}' is pending approval.",
            EntityStatus.APPROVED: "Entity '{name}' has been approved.",
            EntityStatus.ACTIVE: "Entity '{name}' is now active.",
            EntityStatus.ON_HOLD: "Entity '{name}' has been put on hold.",
            EntityStatus.REJECTED: "Entity '{name}' has been rejected.",
            EntityStatus.CANCELLED: "Entity '{name}' has been cancelled.",
            EntityStatus.ARCHIVED: "Entity '{name}' has been archived.",
        }

    def notify(self, entity: Entity, old_status: EntityStatus, new_status: EntityStatus) -> None:
        template = self._notification_map.get(new_status)
        if template is None:
            message = f"Entity '{entity.name}' status changed to {new_status.value}."
        else:
            message = template.format(name=entity.name)

        notification = {
            "entity_id": entity.id,
            "old_status": old_status.value,
            "new_status": new_status.value,
            "message": message,
            "timestamp": datetime.utcnow().isoformat(),
        }
        self.sent_notifications.append(notification)
        self._dispatch(notification)

    def _dispatch(self, notification: Dict[str, Any]) -> None:
        # Placeholder for real dispatch (email/SMS/push/websocket etc.)
        print(f"[NOTIFICATION] {notification['message']}")


# ---------------------------------------------------------------------------
# 5. Report Filters
# ---------------------------------------------------------------------------

class ReportFilter:
    """Categorizes statuses for reporting purposes."""

    STATUS_CATEGORIES: Dict[str, List[EntityStatus]] = {
        "open": [EntityStatus.DRAFT, EntityStatus.PENDING_APPROVAL],
        "in_progress": [EntityStatus.APPROVED, EntityStatus.ACTIVE, EntityStatus.ON_HOLD],
        "closed": [EntityStatus.REJECTED, EntityStatus.CANCELLED, EntityStatus.ARCHIVED],
    }

    @classmethod
    def filter_by_category(cls, entities: List[Entity], category: str) -> List[Entity]:
        statuses = cls.STATUS_CATEGORIES.get(category, [])
        return [e for e in entities if e.status in statuses]

    @classmethod
    def filter_by_status(cls, entities: List[Entity], status: EntityStatus) -> List[Entity]:
        return [e for e in entities if e.status == status]

    @classmethod
    def category_of(cls, status: EntityStatus) -> Optional[str]:
        for category, statuses in cls.STATUS_CATEGORIES.items():
            if status in statuses:
                return category
        return None

    @classmethod
    def summary(cls, entities: List[Entity]) -> Dict[str, int]:
        result = {category: 0 for category in cls.STATUS_CATEGORIES}
        for e in entities:
            category = cls.category_of(e.status)
            if category:
                result[category] += 1
        return result


# ---------------------------------------------------------------------------
# 6. API Response Builder
# ---------------------------------------------------------------------------

class APIResponseBuilder:
    """Builds API-facing representations of entities, including status metadata."""

    STATUS_METADATA: Dict[EntityStatus, Dict[str, Any]] = {
        EntityStatus.DRAFT: {"label": "Draft", "editable": True, "color": "#9e9e9e"},
        EntityStatus.PENDING_APPROVAL: {"label": "Pending Approval", "editable": False, "color": "#ffb300"},
        EntityStatus.APPROVED: {"label": "Approved", "editable": False, "color": "#43a047"},
        EntityStatus.ACTIVE: {"label": "Active", "editable": True, "color": "#1e88e5"},
        EntityStatus.ON_HOLD: {"label": "On Hold", "editable": False, "color": "#f4511e"},
        EntityStatus.REJECTED: {"label": "Rejected", "editable": True, "color": "#e53935"},
        EntityStatus.CANCELLED: {"label": "Cancelled", "editable": False, "color": "#6d4c41"},
        EntityStatus.ARCHIVED: {"label": "Archived", "editable": False, "color": "#546e7a"},
    }

    @classmethod
    def build(cls, entity: Entity) -> Dict[str, Any]:
        meta = cls.STATUS_METADATA.get(
            entity.status, {"label": entity.status.value.title(), "editable": False, "color": "#000000"}
        )
        return {
            "id": entity.id,
            "name": entity.name,
            "status": {
                "value": entity.status.value,
                "label": meta["label"],
                "editable": meta["editable"],
                "color": meta["color"],
            },
            "created_at": entity.created_at.isoformat(),
            "updated_at": entity.updated_at.isoformat(),
            "status_history": entity.status_history,
            "metadata": entity.metadata,
        }

    @classmethod
    def build_list(cls, entities: List[Entity]) -> List[Dict[str, Any]]:
        return [cls.build(e) for e in entities]


# ---------------------------------------------------------------------------
# 7. UI Components
# ---------------------------------------------------------------------------

class UIComponents:
    """Provides UI configuration hints (icons, badges, allowed actions) per status."""

    STATUS_UI_CONFIG: Dict[EntityStatus, Dict[str, Any]] = {
        EntityStatus.DRAFT: {"icon": "pencil", "badge": "secondary", "actions": ["edit", "submit", "delete"]},
        EntityStatus.PENDING_APPROVAL: {"icon": "clock", "badge": "warning", "actions": ["approve", "reject", "recall"]},
        EntityStatus.APPROVED: {"icon": "check", "badge": "success", "actions": ["activate", "cancel"]},
        EntityStatus.ACTIVE: {"icon": "play", "badge": "primary", "actions": ["hold", "archive", "cancel"]},
        EntityStatus.ON_HOLD: {"icon": "pause", "badge": "danger", "actions": ["resume", "cancel"]},
        EntityStatus.REJECTED: {"icon": "x-circle", "badge": "danger", "actions": ["revise", "archive"]},
        EntityStatus.CANCELLED: {"icon": "slash", "badge": "dark", "actions": ["archive"]},
        EntityStatus.ARCHIVED: {"icon": "archive", "badge": "light", "actions": []},
    }

    @classmethod
    def render_badge(cls, entity: Entity) -> str:
        config = cls.STATUS_UI_CONFIG.get(entity.status, {"icon": "help", "badge": "light", "actions": []})
        return f'<span class="badge badge-{config["badge"]}"><i class="icon-{config["icon"]}"></i> {entity.status.value}</span>'

    @classmethod
    def get_available_actions(cls, entity: Entity) -> List[str]:
        config = cls.STATUS_UI_CONFIG.get(entity.status, {"actions": []})
        return config["actions"]

    @classmethod
    def render_dropdown_options(cls, entity: Entity) -> List[Dict[str, str]]:
        next_statuses = StatusTransitions.ALLOWED_TRANSITIONS.get(entity.status, [])
        return [{"value": s.value, "label": s.value.replace("_", " ").title()} for s in next_statuses]


# ---------------------------------------------------------------------------
# 8. Export Handlers
# ---------------------------------------------------------------------------

class ExportHandler:
    """Handles exporting entities to various formats, with status label mapping."""

    STATUS_EXPORT_LABELS: Dict[EntityStatus, str] = {
        EntityStatus.DRAFT: "Draft",
        EntityStatus.PENDING_APPROVAL: "Pending Approval",
        EntityStatus.APPROVED: "Approved",
        EntityStatus.ACTIVE: "Active",
        EntityStatus.ON_HOLD: "On Hold",
        EntityStatus.REJECTED: "Rejected",
        EntityStatus.CANCELLED: "Cancelled",
        EntityStatus.ARCHIVED: "Archived",
    }

    @classmethod
    def to_csv(cls, entities: List[Entity]) -> str:
        lines = ["id,name,status,created_at,updated_at"]
        for e in entities:
            label = cls.STATUS_EXPORT_LABELS.get(e.status, e.status.value)
            lines.append(f"{e.id},{e.name},{label},{e.created_at.isoformat()},{e.updated_at.isoformat()}")
        return "\n".join(lines)

    @classmethod
    def to_json(cls, entities: List[Entity]) -> str:
        data = []
        for e in entities:
            label = cls.STATUS_EXPORT_LABELS.get(e.status, e.status.value)
            data.append(
                {
                    "id": e.id,
                    "name": e.name,
                    "status": label,
                    "created_at": e.created_at.isoformat(),
                    "updated_at": e.updated_at.isoformat(),
                }
            )
        return json.dumps(data, indent=2)


# ---------------------------------------------------------------------------
# 9. Audit Logging
# ---------------------------------------------------------------------------

class AuditLogger:
    """Logs all status transitions with severity classification."""

    SEVERITY_MAP: Dict[EntityStatus, str] = {
        EntityStatus.DRAFT: "INFO",
        EntityStatus.PENDING_APPROVAL: "INFO",
        EntityStatus.APPROVED: "INFO",
        EntityStatus.ACTIVE: "INFO",
        EntityStatus.ON_HOLD: "WARNING",
        EntityStatus.REJECTED: "WARNING",
        EntityStatus.CANCELLED: "CRITICAL",
        EntityStatus.ARCHIVED: "INFO",
    }

    def __init__(self):
        self.logs: List[Dict[str, Any]] = []

    def log_transition(
        self, entity: Entity, old_status: EntityStatus, new_status: EntityStatus, actor: str
    ) -> None:
        severity = self.SEVERITY_MAP.get(new_status, "INFO")
        entry = {
            "entity_id": entity.id,
            "entity_name": entity.name,
            "actor": actor,
            "from_status": old_status.value,
            "to_status": new_status.value,
            "severity": severity,
            "timestamp": datetime.utcnow().isoformat(),
        }
        self.logs.append(entry)
        print(f"[AUDIT:{severity}] {entry['entity_name']}: {old_status.value} -> {new_status.value} by {actor}")

    def get_logs_for_entity(self, entity_id: str) -> List[Dict[str, Any]]:
        return [log for log in self.logs if log["entity_id"] == entity_id]

    def get_logs_by_severity(self, severity: str) -> List[Dict[str, Any]]:
        return [log for log in self.logs if log["severity"] == severity]


# ---------------------------------------------------------------------------
# Example usage / simple demo
# ---------------------------------------------------------------------------

class EntityRepository:
    """Simple in-memory repository."""

    def __init__(self):
