class ResearchPlatform:
    def __init__(self, name="ResearchPlatform"):
        self.name = name
        self.experiments = {}
        self.datasets = {}
        self.analyses = {}
        self.visualizations = {}
        self.collaborators = {}
        self.publications = {}
