class GestationalCalculator:
    """
    Calculates gestational age and estimated due dates (EDD) using
    various clinical reference methods.
    """

    AVERAGE_GESTATION_DAYS = 280  # 40 weeks from LMP

    def __init__(
        self,
        lmp: Optional[Union[date, datetime]] = None,
        edd: Optional[Union[date, datetime]] = None,
        ultrasound_date: Optional[Union[date, datetime]] = None,
        ultrasound_ga_days: Optional[int] = None,
    ):
        """
        Provide either:
          - lmp (last menstrual period), or
          - edd (estimated due date), or
          - ultrasound_date + ultrasound_ga_days (GA measured at that scan)
        """
        self.lmp: Optional[datetime] = _to_datetime(lmp) if lmp else None
        self._edd_direct: Optional[datetime] = _to_datetime(edd) if edd else None
        self.ultrasound_date: Optional[datetime] = (
            _to_datetime(ultrasound_date) if ultrasound_date else None
        )
        self.ultrasound_ga_days = ultrasound_ga_days

        if not any([self.lmp, self._edd_direct,
                    (self.ultrasound_date and ultrasound_ga_days is not None)]):
            raise GestationalAgeError(
                "Must provide lmp, edd, or ultrasound_date with ultrasound_ga_days"
            )

    def _effective_lmp(self) -> datetime:
        """Derive an effective LMP date depending on available inputs."""
        if self.lmp is not None:
            return self.lmp
        if self._edd_direct is not None:
            return self._edd_direct - timedelta(days=self.AVERAGE_GESTATION_DAYS)
        if self.ultrasound_date is not None and self.ultrasound_ga_days is not None:
            return self.ultrasound_date - timedelta(days=self.ultrasound_ga_days)
        raise GestationalAgeError("Insufficient data to determine LMP")

    def estimated_due_date(self) -> datetime:
        """Naegele's rule based EDD (or direct EDD if given)."""
        if self._edd_direct is not None:
            return self._edd_direct
        return self._effective_lmp() + timedelta(days=self.AVERAGE_GESTATION_DAYS)

    def gestational_age_at(
        self, as_of: Optional[Union[date, datetime]] = None
    ) -> GestationalAge:
        """Compute gestational age as of a given date (default: now)."""
        as_of_dt = _to_datetime(as_of) if as_of else datetime.now()
        lmp = self._effective_lmp()
        delta_days = (as_of_dt - lmp).days
        if delta_days < 0:
            raise GestationalAgeError("Reference date is before LMP")
        weeks, days = divmod(delta_days, 7)
        return GestationalAge(weeks=weeks, days=days)

    def days_until_due(self, as_of: Optional[Union[date, datetime]] = None) -> int:
        as_of_dt = _to_datetime(as_of) if as_of else datetime.now()
        return (self.estimated_due_date() - as_of_dt).days

    def trimester_at(self, as_of: Optional[Union[date, datetime]] = None) -> int:
        """Return trimester (1, 2, or 3) at a given date."""
        ga = self.gestational_age_at(as_of)
        td = ga.total_days
        if td <= 13 * 7:
            return 1
        if td <= 27 * 7:
            return 2
        return 3

    def corrected_age(
        self,
        birth_date: Union[date, datetime],
        as_of: Optional[Union[date, datetime]] = None,
    ) -> timedelta:
        """
        Corrected (adjusted) age for premature infants: chronological age
        minus the degree of prematurity (weeks before 40wk at birth).
        """
        birth_dt = _to_datetime(birth_date)
        as_of_dt = _to_datetime(as_of) if as_of else datetime.now()
        ga_at_birth = self.gestational_age_at(birth_dt)
        prematurity_days = max(0, (40 * 7) - ga_at_birth.total_days)
        chronological_age = as_of_dt - birth_dt
        corrected = chronological_age - timedelta(days=prematurity_days)
        return corrected if corrected.total_seconds() > 0 else timedelta(0)


