class WindowStatus(Enum):
    BEFORE = "before window"
    WITHIN = "within window"
    AFTER = "after window"


@dataclass
class ClinicalTimeWindow:
    """
    Represents a clinical time window relative to an index event,
    e.g., "give thrombolytics within 4.5 hours of symptom onset" or
    "post-op follow-up window: 7-14 days".
    """
    index_event: datetime
    window_start_hours: float
    window_end_hours: float
    label: str = ""

    def __post_init__(self):
        if self.window_start_hours > self.window_end_hours:
            raise ValueError("window_start_hours must be <= window_end_hours")

    @property
    def window_start(self) -> datetime:
        return self.index_event + timedelta(hours=self.window_start_hours)

    @property
    def window_end(self) -> datetime:
        return self.index_event + timedelta(hours=self.window_end_hours)

    def status_at(self, moment: Optional[Union[date, datetime]] = None) -> WindowStatus:
        """Determine whether a given moment falls before/within/after the window."""
        moment_dt = _to_datetime(moment) if moment else datetime.now()
        if moment_dt < self.window_start:
            return WindowStatus.BEFORE
        if moment_dt > self.window_end:
            return WindowStatus.AFTER
        return WindowStatus.WITHIN

    def is_within(self, moment: Optional[Union[date, datetime]] = None) -> bool:
        return self.status_at(moment) == WindowStatus.WITHIN

    def time_remaining(
        self, moment: Optional[Union[date, datetime]] = None
    ) -> Optional[timedelta]:
        """Time remaining until window closes; None if already past."""
        moment_dt = _to_datetime(moment) if moment else datetime.now()
        if moment_dt > self.window_end:
            return None
        if moment_dt < self.window_start:
            return self.window_end - self.window_start
        return self.window_end - moment_dt

    def time_until_open(
        self, moment: Optional[Union[date, datetime]] = None
    ) -> Optional[timedelta]:
        """Time until the window opens; None if already open or passed."""
        moment_dt = _to_datetime(moment) if moment else datetime.now()
        if moment_dt >= self.window_start:
            return None
        return self.window_start - moment_dt


