class HealthClaimProcessor:
    def __init__(self):
        self.policies = {}
        self.claims = {}
        self.payment_log = []

    def add_policy(self, policy_id, holder_name, start_date, end_date,
                    coverage_limit, deductible, premium_paid=True, annual_max=1000000):
        self.policies[policy_id] = {
            "holder_name": holder_name,
            "start_date": start_date,
            "end_date": end_date,
            "coverage_limit": coverage_limit,
            "deductible": deductible,
            "premium_paid": premium_paid,
            "annual_max": annual_max,
            "used_this_year": 0,
        }

    def verify_eligibility(self, policy_id, incident_date):
        policy = self.policies.get(policy_id)
        if not policy:
            return False, "Policy not found"
        if not policy["premium_paid"]:
            return False, "Premium not paid; policy inactive"
        if incident_date < policy["start_date"] or incident_date > policy["end_date"]:
            return False, "Incident date outside policy coverage period"
        return True, "Eligible"

    def calculate_coverage(self, policy_id, claim_amount, treatment_type="general"):
        policy = self.policies[policy_id]
        deductible = policy["deductible"]
        coverage_limit = policy["coverage_limit"]

        if treatment_type == "emergency":
            payout_ratio = 0.95
        elif treatment_type == "surgery":
            payout_ratio = 0.9
        elif treatment_type == "outpatient":
            payout_ratio = 0.7
        elif treatment_type == "dental":
            payout_ratio = 0.5
        else:
            payout_ratio = 0.6

        adjusted_amount = max(0, claim_amount - deductible)
        payout = adjusted_amount * payout_ratio
        payout = min(payout, coverage_limit)

        remaining_annual = policy["annual_max"] - policy["used_this_year"]
        payout = min(payout, remaining_annual)
        payout = max(payout, 0)
        return round(payout, 2)

    def detect_fraud(self, policy_id, claim_amount, incident_date, claim_history=None):
        risk_score = 0
        reasons = []

        policy = self.policies[policy_id]

        if claim_amount > policy["annual_max"] * 0.5:
            risk_score += 30
            reasons.append("Claim amount unusually large relative to annual max")

        policy_start = policy["start_date"]
        if (incident_date - policy_start).days < 7:
            risk_score += 25
            reasons.append("Incident shortly after policy start")

        if claim_history:
            recent_claims = [c for c in claim_history
                              if (incident_date - c["date"]).days < 30]
            if len(recent_claims) >= 3:
                risk_score += 25
                reasons.append("Multiple claims within past month")

        if claim_amount % 500 == 0 and claim_amount > 3000:
            risk_score += 10
            reasons.append("Suspiciously round claim amount")

        is_fraudulent = risk_score >= 40
        return is_fraudulent, risk_score, reasons

    def process_payment(self, claim_id, payout_amount, holder_name):
        payment_id = str(uuid.uuid4())
        payment_record = {
            "payment_id": payment_id,
            "claim_id": claim_id,
            "amount": payout_amount,
            "payee": holder_name,
            "status": "PROCESSED",
            "timestamp": datetime.now().isoformat(),
        }
        self.payment_log.append(payment_record)
        return payment_record

    def submit_claim(self, policy_id, incident_date, claim_amount,
                      treatment_type="general", claim_history=None):
        claim_id = str(uuid.uuid4())

        eligible, message = self.verify_eligibility(policy_id, incident_date)
        if not eligible:
            self.claims[claim_id] = {"status": "REJECTED", "reason": message}
            return self.claims[claim_id]

        is_fraud, risk_score, reasons = self.detect_fraud(
            policy_id, claim_amount, incident_date, claim_history)
        if is_fraud:
            self.claims[claim_id] = {
                "status": "FLAGGED_FOR_FRAUD",
                "risk_score": risk_score,
                "reasons": reasons,
            }
            return self.claims[claim_id]

        payout = self.calculate_coverage(policy_id, claim_amount, treatment_type)
        holder_name = self.policies[policy_id]["holder_name"]
        payment = self.process_payment(claim_id, payout, holder_name)

        self.policies[policy_id]["used_this_year"] += payout

        self.claims[claim_id] = {
            "status": "APPROVED",
            "payout": payout,
            "payment": payment,
        }
        return self.claims[claim_id]


