        "timezone": scheduling.get("timezone", "UTC"),
        "start_date": scheduling.get("start_date"),
        "end_date": scheduling.get("end_date"),
    }

    if schedule_type == "cron" and not is_non_empty_str(scheduling_config["expression"]):
        add_error("scheduling.expression is required for cron scheduling.")

    if schedule_type == "interval" and not isinstance(scheduling_config["interval_seconds"], (int, float)):
        add_error("scheduling.interval_seconds is required for interval scheduling.")

    # ---------- monitoring / alerting ----------

    monitoring_enabled = bool(monitoring_enabled)

    if alert_thresholds is None:
        alert_thresholds = {}
    if not isinstance(alert_thresholds, dict):
        add_error("alert_thresholds must be a dictionary.")
        alert_thresholds = {}

