        engagement_frequency = behaviors.get('engagement_frequency', 0.5)
        avg_session_duration = behaviors.get('avg_session_duration', 0)
        device_diversity = len(behaviors.get('devices', []))

        score = (purchase_intent * 0.4) + (engagement_frequency * 0.3)
        score += min(avg_session_duration / 300, 1.0) * 0.2
        score += min(device_diversity / 3, 1.0) * 0.1

        return max(0.0, min(1.0, score))

