        score += max(0.0, min(1.0, (growth_rate + 0.5))) * 0.4
        score += max(0.0, min(2.0, seasonality_factor)) / 2 * 0.3
        score += max(0.0, min(1.0, demand_index)) * 0.3

        return max(0.0, min(1.0, score))

