    def __init__(
        self,
        redis_config: Optional[dict] = None,
        memcached_config: Optional[dict] = None,
        filesystem_config: Optional[dict] = None,
        database_config: Optional[dict] = None,
        use_dict_fallback: bool = True,
        backend_order: Optional[List[str]] = None,
    ):
        self._lock = threading.RLock()
        self._backends: List[BaseCacheBackend] = []
        self._failed_backends: set = set()

        default_order = ["redis", "memcached", "database", "filesystem", "dict"]
        self._order = backend_order or default_order

        available = {}

        if redis_config is not None:
            available["redis"] = lambda: RedisCacheBackend(**redis_config)
        if memcached_config is not None:
            available["memcached"] = lambda: MemcachedCacheBackend(**memcached_config)
        if filesystem_config is not None:
            available["filesystem"] = lambda: FilesystemCacheBackend(**filesystem_config)
        if database_config is not None:
            available["database"] = lambda: DatabaseCacheBackend(**database_config)
        if use_dict_fallback:
            available["dict"] = lambda: DictCacheBackend()

        for name in self._order:
            if name not in available:
                continue
            try:
                backend = available[name]()
                self._backends.append(backend)
            except CacheBackendError:
                self._failed_backends.add(name)
            except Exception:
                self._failed_backends.add(name)

        if not self._backends:
            # Guarantee at least dict cache is available
            self._backends.append(DictCacheBackend())

    def _iter_backends(self):
        """Yield backends in order, skipping ones known to be dead until re-checked."""
        for backend in self._backends:
            yield backend

    def _run_with_failover(self, operation_name: str, func, *args, default=None, **kwargs):
        """
        Run `func(backend, *args, **kwargs)` against each backend in order,
        returning the first successful result. Falls through to the next
        backend on failure.
        """
        last_exc = None
        with self._lock:
            backends_snapshot = list(self._backends)

        for backend in backends_snapshot:
            try:
                result = func(backend, *args, **kwargs)
                return result
            except CacheBackendError as exc:
                last_exc = exc
                continue
            except Exception as exc:
                last_exc = exc
                continue

        if last_exc is not None and operation_name in ("get",):
            return default
        if last_exc is not None and operation_name in ("exists",):
            return False
        if last_exc is not None and operation_name in ("set", "delete", "clear"):
            return None

        return default

    def get(self, key: str, default: Any = None) -> Any:
        """Get a value from the cache, trying each backend in order."""
        def op(backend):
            value = backend.get(key)
            if value is None:
                raise CacheBackendError("miss")  # not real error, trigger fallback search
            return value

