        """Delete a key from all backends (best-effort)."""
        with self._lock:
            backends_snapshot = list(self._backends)

        success = False
        for backend in backends_snapshot:
            try:
                backend.delete(key)
                success = True
            except CacheBackendError:
                continue
            except Exception:
                continue
        return success

    def clear(self) -> bool:
        """Clear all backends (best-effort)."""
        with self._lock:
            backends_snapshot = list(self._backends)

        success = False
        for backend in backends_snapshot:
            try:
                backend.clear()
                success = True
            except CacheBackendError:
                continue
            except Exception:
                continue
        return success

    def exists(self, key: str) -> bool:
        """Check if a key exists in any backend."""
        with self._lock:
            backends_snapshot = list(self._backends)

        for backend in backends_snapshot:
            try:
                if backend.exists(key):
                    return True
            except CacheBackendError:
                continue
            except Exception:
                continue
        return False

    def health_check(self) -> dict:
        """Return a dict of backend name -> health status (True/False)."""
        with self._lock:
            backends_snapshot = list(self._backends)

        status = {}
        for backend in backends_snapshot:
            try:
                status[backend.name] = backend.ping()
            except Exception:
                status[backend.name] = False
