    def get_or_set(self, key: str, default_factory, ttl: Optional[int] = None) -> Any:
        """Get a value, or compute and cache it via default_factory if missing."""
        value = self.get(key)
        if value is not None:
            return value
        value = default_factory()
        self.set(key, value, ttl=ttl)
        return value

    def active_backends(self) -> List[str]:
        """Return the list of currently configured backend names, in priority order."""
        with self._lock:
            return [b.name for b in self._backends]

    def close(self) -> None:
        """Close all backend connections."""
        with self._lock:
            backends_snapshot = list(self._backends)
        for backend in backends_snapshot:
            try:
                backend.close()
            except Exception:
