class FilesystemCacheBackend(BaseCacheBackend):
    """Filesystem-based cache. Stores each entry as a pickled file."""

    name = "filesystem"

    def __init__(self, directory: str = ".cache"):
        self._dir = directory
        self._lock = threading.RLock()
        try:
            os.makedirs(self._dir, exist_ok=True)
        except Exception as exc:
            raise CacheBackendError(
                f"Could not initialize filesystem cache dir: {exc}"
            ) from exc

    def _path_for_key(self, key: str) -> str:
        hashed = hashlib.sha256(key.encode("utf-8")).hexdigest()
        return os.path.join(self._dir, f"{hashed}.cache")

    def get(self, key: str) -> Any:
        path = self._path_for_key(key)
        with self._lock:
            if not os.path.exists(path):
                return None
            try:
                with open(path, "rb") as f:
                    data = pickle.load(f)
            except Exception as exc:
                raise CacheBackendError(f"Filesystem get failed: {exc}") from exc

            expires_at = data.get("expires_at")
            if expires_at is not None and time.time() > expires_at:
                self._safe_remove(path)
                return None
            return data.get("value")

    def set(self, key: str, value: Any, ttl: Optional[int] = None) -> None:
        path = self._path_for_key(key)
        expires_at = time.time() + ttl if ttl else None
        payload = {"value": value, "expires_at": expires_at}
        with self._lock:
            try:
                tmp_path = f"{path}.tmp"
                with open(tmp_path, "wb") as f:
                    pickle.dump(payload, f)
                os.replace(tmp_path, path)
            except Exception as exc:
                raise CacheBackendError(f"Filesystem set failed: {exc}") from exc

    def delete(self, key: str) -> None:
        path = self._path_for_key(key)
        with self._lock:
            self._safe_remove(path)

    def clear(self) -> None:
        with self._lock:
            try:
                for fname in os.listdir(self._dir):
                    if fname.endswith(".cache"):
                        os.remove(os.path.join(self._dir, fname))
            except Exception as exc:
                raise CacheBackendError(f"Filesystem clear failed: {exc}") from exc

    def exists(self, key: str) -> bool:
        return self.get(key) is not None

    def ping(self) -> bool:
        try:
            return os.path.isdir(self._dir) and os.access(self._dir, os.W_OK)
        except Exception:
            return False

    def _safe_remove(self, path: str) -> None:
        try:
            if os.path.exists(path):
                os.remove(path)
        except Exception:
            pass


