class CreditCardPayment(PaymentMethod):
    method_type = PaymentMethodType.CREDIT_CARD

    def __init__(
        self,
        card_number: str,
        cardholder_name: str,
        expiry_month: int,
        expiry_year: int,
        cvv: str,
        billing_zip: Optional[str] = None,
    ):
        self.card_number = card_number.replace(" ", "").replace("-", "")
        self.cardholder_name = cardholder_name
        self.expiry_month = expiry_month
        self.expiry_year = expiry_year
        self.cvv = cvv
        self.billing_zip = billing_zip

        # internal transaction ledger: transaction_id -> details
        self._transactions: Dict[str, Dict[str, Any]] = {}

        self.validate()

    # ---------------------- Validation helpers ----------------------

    @staticmethod
    def _luhn_check(card_number: str) -> bool:
        digits = [int(d) for d in card_number]
        checksum = 0
        parity = len(digits) % 2
        for i, digit in enumerate(digits):
            if i % 2 == parity:
                digit *= 2
                if digit > 9:
                    digit -= 9
            checksum += digit
        return checksum % 10 == 0

    def detect_network(self) -> CardNetwork:
        num = self.card_number
        if re.match(r"^4\d{12}(\d{3})?(\d{3})?$", num):
            return CardNetwork.VISA
        if re.match(r"^5[1-5]\d{14}$", num) or re.match(r"^2(2[2-9][1-9]|2[3-9]\d|[3-6]\d\d|7[01]\d|720)\d{12}$", num):
            return CardNetwork.MASTERCARD
        if re.match(r"^3[47]\d{13}$", num):
            return CardNetwork.AMEX
        if re.match(r"^6(?:011|5\d{2})\d{12}$", num):
            return CardNetwork.DISCOVER
        return CardNetwork.UNKNOWN

    def validate(self) -> None:
        if not self.card_number.isdigit() or not (12 <= len(self.card_number) <= 19):
            raise PaymentValidationError("Invalid card number length")

        if not self._luhn_check(self.card_number):
            raise PaymentValidationError("Card number failed Luhn validation")

        if not self.cardholder_name or not self.cardholder_name.strip():
            raise PaymentValidationError("Cardholder name is required")

        if not (1 <= self.expiry_month <= 12):
            raise PaymentValidationError("Invalid expiry month")

        today = date.today()
        expiry_date = date(self.expiry_year, self.expiry_month, 1)
        # move to last day-ish of the month for comparison purposes
        if expiry_date.year < today.year or (
            expiry_date.year == today.year and expiry_date.month < today.month
        ):
            raise PaymentValidationError("Card has expired")

        network = self.detect_network()
        expected_cvv_len = 4 if network == CardNetwork.AMEX else 3
        if not self.cvv.isdigit() or len(self.cvv) != expected_cvv_len:
            raise PaymentValidationError(
                f"Invalid CVV length for {network.value}, expected {expected_cvv_len} digits"
            )

    def _mask_card_number(self) -> str:
        return "*" * (len(self.card_number) - 4) + self.card_number[-4:]

    def _generate_transaction_id(self) -> str:
        return f"cc_{uuid.uuid4().hex[:16]}"

    def _simulate_gateway_response(self, amount: Money) -> bool:
        """
        Simulate a payment gateway approval process.
        In a real system this would call out to Stripe/Adyen/etc.
        Simple deterministic-ish simulation: fails if amount is exactly 0
        or if card number ends in '0000' (used for testing declines).
        """
        if amount.amount == Decimal("0.00"):
            return False
        if self.card_number.endswith("0000"):
            return False
        return True

    # ---------------------- PaymentMethod interface ----------------------

    def authorize(self, amount: Money) -> PaymentResult:
        self.validate()
        approved = self._simulate_gateway_response(amount)
        transaction_id = self._generate_transaction_id()

        if not approved:
            return PaymentResult(
                success=False,
                transaction_id=transaction_id,
                status=PaymentStatus.FAILED,
                amount=amount,
                method_type=self.method_type,
                message="Card declined during authorization",
            )

        self._transactions[transaction_id] = {
            "status": PaymentStatus.AUTHORIZED,
            "amount": amount,
            "captured_amount": Decimal("0.00"),
        }

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.AUTHORIZED,
            amount=amount,
            method_type=self.method_type,
            message="Authorization successful",
            raw_response={
                "card": self._mask_card_number(),
                "network": self.detect_network().value,
            },
        )

    def capture(self, transaction_id: str, amount: Money) -> PaymentResult:
        record = self._transactions.get(transaction_id)
        if record is None:
            raise PaymentNotFoundError(f"No authorization found for transaction {transaction_id}")

        if record["status"] != PaymentStatus.AUTHORIZED:
            raise PaymentProcessingError(
                f"Transaction {transaction_id} is not in an authorized state"
            )

        if amount.amount > record["amount"].amount:
            raise PaymentValidationError("Capture amount exceeds authorized amount")

        record["status"] = PaymentStatus.CAPTURED
        record["captured_amount"] = amount.amount

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.CAPTURED,
            amount=amount,
            method_type=self.method_type,
            message="Capture successful",
        )

    def charge(self, amount: Money) -> PaymentResult:
        auth_result = self.authorize(amount)
        if not auth_result.success:
            return auth_result
        return self.capture(auth_result.transaction_id, amount)

    def refund(self, transaction_id: str, amount: Money) -> RefundResult:
        record = self._transactions.get(transaction_id)
        if record is None:
            raise PaymentNotFoundError(f"No transaction found with id {transaction_id}")

        if record["status"] != PaymentStatus.CAPTURED:
            raise PaymentProcessingError(
                f"Transaction {transaction_id} must be captured before it can be refunded"
            )

        if amount.amount > record["captured_amount"]:
            raise PaymentValidationError("Refund amount exceeds captured amount")

        refund_id = f"rf_{uuid.uuid4().hex[:16]}"
        record["status"] = PaymentStatus.REFUNDED

        return RefundResult(
            success=True,
            refund_id=refund_id,
            original_transaction_id=transaction_id,
            amount=amount,
            status=PaymentStatus.REFUNDED,
            message="Refund processed successfully",
        )

    def void(self, transaction_id: str) -> PaymentResult:
        record = self._transactions.get(transaction_id)
        if record is None:
            raise PaymentNotFoundError(f"No transaction found with id {transaction_id}")

        if record["status"] != PaymentStatus.AUTHORIZED:
            raise PaymentProcessingError(
                "Only authorized (not yet captured) transactions can be voided"
            )

        record["status"] = PaymentStatus.VOIDED

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.VOIDED,
            amount=record["amount"],
            method_type=self.method_type,
            message="Authorization voided",
        )


