# --------------------------------------------------------------------------

class PaymentMethodFactory(ABC):
    """Abstract factory interface for creating PaymentMethod instances."""

    @abstractmethod
    def create(self, **kwargs) -> PaymentMethod:
        raise NotImplementedError

    @property
    @abstractmethod
    def method_type(self) -> PaymentMethodType:
        raise NotImplementedError


class CreditCardPaymentFactory(PaymentMethodFactory):
    method_type = PaymentMethodType.CREDIT_CARD

    def create(self, **kwargs) -> PaymentMethod:
        required = {"card_number", "cardholder_name", "expiry_month", "expiry_year", "cvv"}
        missing = required - kwargs.keys()
        if missing:
            raise PaymentValidationError(f"Missing required credit card fields: {missing}")
        return CreditCardPayment(**kwargs)


class PayPalPaymentFactory(PaymentMethodFactory):
    method_type = PaymentMethodType.PAYPAL

    def create(self, **kwargs) -> PaymentMethod:
        return PayPalPayment(**kwargs)


class CryptocurrencyPaymentFactory(PaymentMethodFactory):
    method_type = PaymentMethodType.CRYPTOCURRENCY

    def create(self, **kwargs) -> PaymentMethod:
        return CryptocurrencyPayment(**kwargs)


class BankTransferPaymentFactory(PaymentMethodFactory):
    method_type = PaymentMethodType.BANK_TRANSFER

    def create(self, **kwargs) -> PaymentMethod:
        return BankTransferPayment(**kwargs)


class BuyNowPayLaterPaymentFactory(PaymentMethodFactory):
    method_type = PaymentMethodType.BUY_NOW_PAY_LATER

    def create(self, **kwargs) -> PaymentMethod:
        return BuyNowPayLaterPayment(**kwargs)


class PaymentMethodFactoryRegistry:
    """
    Central registry / abstract-factory-of-factories that resolves the
    correct concrete factory based on the requested PaymentMethodType.

    Even though only credit cards are enabled for real transactions,
    all method types are registered here to preserve the extensible
    architecture. Enabled/disabled status is tracked separately.
    """

    _factories: Dict[PaymentMethodType, Type[PaymentMethodFactory]] = {
        PaymentMethodType.CREDIT_CARD: CreditCardPaymentFactory,
        PaymentMethodType.PAYPAL: PayPalPaymentFactory,
        PaymentMethodType.CRYPTOCURRENCY: CryptocurrencyPaymentFactory,
        PaymentMethodType.BANK_TRANSFER: BankTransferPaymentFactory,
        PaymentMethodType.BUY_NOW_PAY_LATER: BuyNowPayLaterPaymentFactory,
    }

    _enabled_methods = {PaymentMethodType.CREDIT_CARD}

    @classmethod
    def register_factory(
        cls, method_type: PaymentMethodType, factory_cls: Type[PaymentMethodFactory]
    ) -> None:
        cls._factories[method_type] = factory_cls

    @classmethod
    def is_enabled(cls, method_type: PaymentMethodType) -> bool:
        return method_type in cls._enabled_methods

    @classmethod
    def enable_method(cls, method_type: PaymentMethodType) -> None:
        """Hook for future activation of additional payment methods."""
        cls._enabled_methods.add(method_type)

    @classmethod
    def get_factory(cls, method_type: PaymentMethodType) -> PaymentMethodFactory:
        factory_cls = cls._factories.get(method_type)
        if factory_cls is None:
            raise PaymentMethodNotSupportedError(f"No factory registered for {method_type}")
        return factory_cls()

    @classmethod
    def create_payment_method(cls, method_type: PaymentMethodType, **kwargs) -> PaymentMethod:
        if not cls.is_enabled(method_type):
            raise PaymentMethodNotSupportedError(
                f"Payment method '{method_type.value}' is defined but not currently enabled. "
                f"Only credit card payments are active."
            )
        factory = cls.get_factory(method_type)
        return factory.create(**kwargs)


# --------------------------------------------------------------------------
# Payment Processor / Orchestrator
# --------------------------------------------------------------------------

class PaymentProcessor:
    """
    High-level orchestrator that ties together the factory registry
    and the payment method interface to process transactions.
    """

    def __init__(self):
        self._history: Dict[str, PaymentResult] = {}
        self._refund_history: Dict[str, RefundResult] = {}

    def process_payment(
        self, method_type: PaymentMethodType, amount: Money, **payment_details
    ) -> PaymentResult:
        payment_method = PaymentMethodFactoryRegistry.create_payment_method(
            method_type, **payment_details
        )
        result = payment_method.charge(amount)
        self._history[result.transaction_id] = result
        # Stash the live payment method object for subsequent operations
        result.raw_response["_method_instance"] = payment_method
        return result

    def authorize_payment(
        self, method_type: PaymentMethodType, amount: Money, **payment_details
    ) -> PaymentResult:
        payment_method = PaymentMethodFactoryRegistry.create_payment_method(
            method_type, **payment_details
        )
        result = payment_method.authorize(amount)
        self._history[result.transaction_id] = result
        result.raw_response["_method_instance"] = payment_method
        return result

    def capture_payment(
        self, original_result: PaymentResult, amount: Optional[Money] = None
    ) -> PaymentResult:
        method_instance: PaymentMethod = original_result.raw_response.get("_method_instance")
        if method_instance is None:
            raise PaymentProcessingError("Cannot capture: original payment method instance unavailable")
        capture_amount = amount or original_result.amount
        result = method_instance.capture(original_result.transaction_id, capture_amount)
        self._history[result.transaction_id] = result
        return result

    def refund_payment(
        self, original_result: PaymentResult, amount: Optional[Money] = None
    ) -> RefundResult:
        method_instance: PaymentMethod = original_result.raw_response.get("_method_instance")
        if method_instance is None:
            raise PaymentProcessingError("Cannot refund: original payment method instance unavailable")
        refund_amount = amount or original_result.amount
        refund_result = method_instance.refund(original_result.transaction_id, refund_amount)
        self._refund_history[refund_result.refund_id] = refund_result
        return refund_result

    def void_payment(self, original_result: PaymentResult) -> PaymentResult:
        method_instance: PaymentMethod = original_result.raw_response.get("_method_instance")
        if method_instance is None:
            raise PaymentProcessingError("Cannot void: original payment method instance unavailable")
        result = method_instance.void(original_result.transaction_id)
        self._history[result.transaction_id] = result
        return result

    def get_transaction(self, transaction_id: str) -> PaymentResult:
        result = self._history.get(transaction_id)
        if result is None:
            raise PaymentNotFoundError(f"Transaction {transaction_id} not found")
        return result


