import numpy as np
import pandas as pd
from pandas.api.extensions import register_dataframe_accessor


@register_dataframe_accessor("fin")
class FinancialAccessor:
    """
    Pandas DataFrame accessor providing financial calculations, time series
    analysis, and market data specific operations.

