            result = np.log(series / series.shift(periods))
        else:
            result = series.pct_change(periods=periods)
        return result.rename("returns")

    def cumulative_returns(self, column=None, log=False):
        """Compute cumulative returns series."""
        rets = self.returns(column=column, log=log)
        if log:
            cum = rets.cumsum()
            cum = np.exp(cum) - 1
        else:
            cum = (1 + rets.fillna(0)).cumprod() - 1
        return cum.rename("cumulative_returns")

    def total_return(self, column=None):
        """Compute total return over the entire period."""
        series = self._get_series(column).dropna()
        if len(series) < 2:
            return np.nan
        return series.iloc[-1] / series.iloc[0] - 1

    def annualized_return(self, column=None, periods_per_year=252):
        """Compute CAGR-style annualized return."""
        series = self._get_series(column).dropna()
        n = len(series)
        if n < 2:
            return np.nan
        total_ret = series.iloc[-1] / series.iloc[0]
        years = n / periods_per_year
        if years <= 0:
            return np.nan
        return total_ret ** (1 / years) - 1

    # ------------------------------------------------------------------
    # Moving averages / smoothing
    # ------------------------------------------------------------------
    def sma(self, column=None, window=20):
        """Simple Moving Average."""
        series = self._get_series(column)
        return series.rolling(window=window, min_periods=window).mean().rename(
            f"sma_{window}"
        )

    def ema(self, column=None, span=20):
        """Exponential Moving Average."""
        series = self._get_series(column)
        return series.ewm(span=span, adjust=False).mean().rename(f"ema_{span}")

    def wma(self, column=None, window=20):
        """Weighted Moving Average."""
        series = self._get_series(column)
        weights = np.arange(1, window + 1)

        def _wma(x):
            return np.dot(x, weights) / weights.sum()

        return series.rolling(window=window).apply(_wma, raw=True).rename(
            f"wma_{window}"
        )

    # ------------------------------------------------------------------
    # Volatility
    # ------------------------------------------------------------------
    def volatility(self, column=None, window=20, periods_per_year=252, annualize=True):
        """Rolling volatility (std dev of returns)."""
        rets = self.returns(column=column)
        vol = rets.rolling(window=window).std()
        if annualize:
            vol = vol * np.sqrt(periods_per_year)
        return vol.rename(f"volatility_{window}")

    def historical_volatility(self, column=None, periods_per_year=252, annualize=True):
        """Full-sample historical volatility."""
        rets = self.returns(column=column).dropna()
        vol = rets.std()
        if annualize:
            vol = vol * np.sqrt(periods_per_year)
        return vol

    def rolling_std(self, column=None, window=20):
        """Rolling standard deviation of price/level series."""
        series = self._get_series(column)
        return series.rolling(window=window).std().rename(f"rolling_std_{window}")

    # ------------------------------------------------------------------
    # Bollinger Bands
    # ------------------------------------------------------------------
    def bollinger_bands(self, column=None, window=20, num_std=2.0):
        """Compute Bollinger Bands. Returns DataFrame with middle/upper/lower bands."""
        series = self._get_series(column)
        mid = series.rolling(window=window).mean()
        std = series.rolling(window=window).std()
        upper = mid + num_std * std
        lower = mid - num_std * std
        return pd.DataFrame(
            {
                "bb_mid": mid,
                "bb_upper": upper,
                "bb_lower": lower,
            },
            index=series.index,
        )

    # ------------------------------------------------------------------
    # Momentum indicators
    # ------------------------------------------------------------------
    def rsi(self, column=None, window=14):
        """Relative Strength Index."""
        series = self._get_series(column)
        delta = series.diff()
        gain = delta.clip(lower=0)
        loss = -delta.clip(upper=0)

        avg_gain = gain.ewm(alpha=1 / window, min_periods=window, adjust=False).mean()
        avg_loss = loss.ewm(alpha=1 / window, min_periods=window, adjust=False).mean()

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        rsi = rsi.where(avg_loss != 0, 100)
        return rsi.rename(f"rsi_{window}")

    def macd(self, column=None, fast=12, slow=26, signal=9):
        """MACD indicator. Returns DataFrame with macd, signal, histogram."""
        series = self._get_series(column)
        ema_fast = series.ewm(span=fast, adjust=False).mean()
        ema_slow = series.ewm(span=slow, adjust=False).mean()
        macd_line = ema_fast - ema_slow
        signal_line = macd_line.ewm(span=signal, adjust=False).mean()
        histogram = macd_line - signal_line
        return pd.DataFrame(
            {
                "macd": macd_line,
                "macd_signal": signal_line,
                "macd_hist": histogram,
            },
            index=series.index,
        )

    def momentum(self, column=None, window=10):
        """Price momentum: difference from N periods ago."""
        series = self._get_series(column)
        return (series - series.shift(window)).rename(f"momentum_{window}")

    def roc(self, column=None, window=10):
        """Rate of Change (%)."""
        series = self._get_series(column)
        return (
            (series - series.shift(window)) / series.shift(window) * 100
        ).rename(f"roc_{window}")

    # ------------------------------------------------------------------
    # Risk-adjusted performance metrics
    # ------------------------------------------------------------------
    def sharpe_ratio(self, column=None, risk_free_rate=0.0, periods_per_year=252):
        """Annualized Sharpe Ratio."""
        rets = self.returns(column=column).dropna()
        if len(rets) == 0:
            return np.nan
        excess_rets = rets - risk_free_rate / periods_per_year
        std = excess_rets.std()
        if std == 0 or np.isnan(std):
            return np.nan
        return (excess_rets.mean() / std) * np.sqrt(periods_per_year)

    def sortino_ratio(self, column=None, risk_free_rate=0.0, periods_per_year=252):
        """Annualized Sortino Ratio."""
        rets = self.returns(column=column).dropna()
        if len(rets) == 0:
            return np.nan
        excess_rets = rets - risk_free_rate / periods_per_year
        downside = excess_rets[excess_rets < 0]
        downside_std = downside.std()
        if downside_std == 0 or np.isnan(downside_std):
            return np.nan
        return (excess_rets.mean() / downside_std) * np.sqrt(periods_per_year)

    def calmar_ratio(self, column=None, periods_per_year=252):
        """Calmar Ratio: annualized return / max drawdown."""
        ann_ret = self.annualized_return(column=column, periods_per_year=periods_per_year)
        mdd = self.max_drawdown(column=column)
        if mdd == 0 or np.isnan(mdd):
            return np.nan
        return ann_ret / abs(mdd)

    def max_drawdown(self, column=None):
        """Compute maximum drawdown (negative value)."""
        series = self._get_series(column).dropna()
        if len(series) == 0:
            return np.nan
        cum_max = series.cummax()
        drawdown = (series - cum_max) / cum_max
        return drawdown.min()

    def drawdown_series(self, column=None):
        """Return the full drawdown series."""
        series = self._get_series(column)
        cum_max = series.cummax()
        return ((series - cum_max) / cum_max).rename("drawdown")

    def value_at_risk(self, column=None, confidence=0.95):
        """Historical Value at Risk (as a negative return threshold)."""
        rets = self.returns(column=column).dropna()
        if len(rets) == 0:
            return np.nan
        return np.percentile(rets, (1 - confidence) * 100)

    def conditional_value_at_risk(self, column=None, confidence=0.95):
        """Conditional VaR (Expected Shortfall)."""
        rets = self.returns(column=column).dropna()
        if len(rets) == 0:
            return np.nan
        var = self.value_at_risk(column=column, confidence=confidence)
        tail = rets[rets <= var]
        if len(tail) == 0:
            return var
        return tail.mean()

    def beta(self, benchmark, column=None, benchmark_column=None):
        """Compute beta relative to a benchmark price series/DataFrame."""
        rets = self.returns(column=column).dropna()

        if isinstance(benchmark, pd.DataFrame):
            bench_accessor = FinancialAccessor(benchmark)
            bench_rets = bench_accessor.returns(column=benchmark_column).dropna()
        elif isinstance(benchmark, pd.Series):
            bench_rets = benchmark.pct_change().dropna()
        else:
            raise TypeError("benchmark must be a pandas Series or DataFrame")

        aligned = pd.concat([rets, bench_rets], axis=1, join="inner").dropna()
        aligned.columns = ["asset", "benchmark"]
        if len(aligned) < 2:
            return np.nan
        cov = aligned["asset"].cov(aligned["benchmark"])
        var = aligned["benchmark"].var()
        if var == 0:
            return np.nan
        return cov / var

    # ------------------------------------------------------------------
    # Time series utilities
    # ------------------------------------------------------------------
    def resample_ohlc(self, rule, open_col="open", high_col="high",
                       low_col="low", close_col="close", volume_col=None):
        """Resample OHLC(V) data to a new frequency."""
        agg = {
            open_col: "first",
            high_col: "max",
            low_col: "min",
            close_col: "last",
        }
        if volume_col and volume_col in self._obj.columns:
            agg[volume_col] = "sum"
        cols = [c for c in agg if c in self._obj.columns]
        return self._obj[cols].resample(rule).agg({c: agg[c] for c in cols})

    def zscore(self, column=None, window=None):
        """Z-score normalization, optionally rolling."""
        series = self._get_series(column)
        if window is None:
            return ((series - series.mean()) / series.std()).rename("zscore")
        mean = series.rolling(window=window).mean()
        std = series.rolling(window=window).std()
        return ((series - mean) / std).rename(f"zscore_{window}")

    def lag(self, column=None, periods=1):
        """Lag a series by n periods."""
        series = self._get_series(column)
        return series.shift(periods).rename(f"lag_{periods}")

    def rolling_correlation(self, other, column=None, other_column=None, window=20):
        """Rolling correlation between this series and another series/DataFrame."""
        series = self._get_series(column)

        if isinstance(other, pd.DataFrame):
            other_accessor = FinancialAccessor(other)
            other_series = other_accessor._get_series(other_column)
        elif isinstance(other, pd.Series):
            other_series = other
        else:
            raise TypeError("other must be a pandas Series or DataFrame")

        aligned = pd.concat([series, other_series], axis=1, join="inner")
        aligned.columns = ["a", "b"]
        return aligned["a"].rolling(window=window).corr(aligned["b"]).rename(
            f"rolling_corr_{window}"
        )

    def fill_missing_business_days(self, method="ffill"):
        """Reindex to full business-day range and fill missing values."""
        if not isinstance(self._obj.index, pd.DatetimeIndex):
            raise TypeError("DataFrame index must be a DatetimeIndex")
        full_range = pd.date_range(
            start=self._obj.index.min(), end=self._obj.index.max(), freq="B"
        )
        reindexed = self._obj.reindex(full_range)
        if method == "ffill":
            reindexed = reindexed.ffill()
        elif method == "bfill":
            reindexed = reindexed.bfill()
        elif method == "interpolate":
            reindexed = reindexed.interpolate()
        return reindexed

    def normalize_prices(self, column=None, base=100.0):
        """Normalize price series to a common base (e.g. 100)."""
        series = self._get_series(column).dropna()
        if len(series) == 0:
            return series
        return (series / series.iloc[0] * base).rename("normalized")

    # ------------------------------------------------------------------
    # Market microstructure / OHLC based metrics
    # ------------------------------------------------------------------
    def true_range(self, high_col="high", low_col="low", close_col="close"):
        """Average True Range component: True Range series."""
        high = self._obj[high_col]
        low = self._obj[low_col]
        close = self._obj[close_col]
        prev_close = close.shift(1)

        tr1 = high - low
        tr2 = (high - prev_close).abs()
        tr3 = (low - prev_close).abs()
        tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
        return tr.rename("true_range")

    def atr(self, window=14, high_col="high", low_col="low", close_col="close"):
        """Average True Range."""
        tr = self.true_range(high_col=high_col, low_col=low_col, close_col=close_col)
        return tr.ewm(alpha=1 / window, min_periods=window, adjust=False).mean().rename(
            f"atr_{window}"
        )

    def vwap(self, high_col="high", low_col="low", close_col="close", volume_col="volume"):
        """Volume Weighted Average Price."""
        typical_price = (
            self._obj[high_col] + self._obj[low_col] + self._obj[close_col]
        ) / 3
        pv = typical_price * self._obj[volume_col]
        cum_pv = pv.cumsum()
        cum_vol = self._obj[volume_col].cumsum()
        return (cum_pv / cum_vol).rename("vwap")

    def obv(self, close_col="close", volume_col="volume"):
        """On-Balance Volume."""
        close = self._obj[close_col]
        volume = self._obj[volume_col]
        direction = np.sign(close.diff()).fillna(0)
        return (direction * volume).cumsum().rename("obv")

    # ------------------------------------------------------------------
    # Correlation / covariance matrices for multi-asset DataFrames
    # ------------------------------------------------------------------
    def correlation_matrix(self, log=False):
        """Correlation matrix of returns across all numeric columns."""
        rets = self._obj.apply(
            lambda col: np.log(col / col.shift(1)) if log else col.pct_change()
        )
        return rets.corr()

    def covariance_matrix(self, log=False, annualize=False, periods_per_year=252):
        """Covariance matrix of returns across all numeric columns."""
        rets = self._obj.apply(
            lambda col: np.log(col / col.shift(1)) if log else col.pct_change()
        )
        cov = rets.cov()
        if annualize:
            cov = cov * periods_per_year
        return cov

    # ------------------------------------------------------------------
    # Summary
    # ------------------------------------------------------------------
    def summary(self, column=None, periods_per_year=252, risk_free_rate=0.0):
        """Return a dict of key financial metrics for a series."""
        return {
            "total_return": self.total_return(column=column),
            "annualized_return": self.annualized_return(
                column=column, periods_per_year=periods_per_year
            ),
            "volatility": self.historical_volatility(
                column=column, periods_per_year=periods_per_year
            ),
            "sharpe_ratio": self.sharpe_ratio(
                column=column,
                risk_free_rate=risk_free_rate,
                periods_per_year=periods_per_year,
            ),
            "sortino_ratio": self.sortino_ratio(
                column=column,
                risk_free_rate=risk_free_rate,
                periods_per_year=periods_per_year,
            ),
            "max_drawdown": self.max_drawdown(column=column),
            "value_at_risk_95": self.value_at_risk(column=column, confidence=0.95),
            "cvar_95": self.conditional_value_at_risk(column=column, confidence=0.95),
        }
