import math
import statistics
import uuid
from datetime import datetime, timedelta
from collections import defaultdict


# ----------------------------- Utility Helpers ----------------------------- #

def _safe_mean(values, default=0.0):
    return statistics.mean(values) if values else default


def _safe_stdev(values, default=0.0):
    return statistics.stdev(values) if len(values) > 1 else default


def _moving_average_forecast(history, window=3):
    if not history:
        return 0.0
    window = min(window, len(history))
    return _safe_mean(history[-window:])


def _exponential_smoothing_forecast(history, alpha=0.3):
    if not history:
        return 0.0
    forecast = history[0]
    for value in history[1:]:
        forecast = alpha * value + (1 - alpha) * forecast
    return forecast


def _linear_trend_forecast(history, periods_ahead=1):
    n = len(history)
    if n == 0:
        return 0.0
    if n == 1:
        return history[0]
    x = list(range(n))
    x_mean = _safe_mean(x)
    y_mean = _safe_mean(history)
    numerator = sum((x[i] - x_mean) * (history[i] - y_mean) for i in range(n))
    denominator = sum((x[i] - x_mean) ** 2 for i in range(n))
    slope = numerator / denominator if denominator != 0 else 0.0
    intercept = y_mean - slope * x_mean
    return max(0.0, intercept + slope * (n - 1 + periods_ahead))


def _z_score_for_service_level(service_level):
    table = {
        0.50: 0.00, 0.60: 0.25, 0.70: 0.52, 0.75: 0.6745,
        0.80: 0.84, 0.85: 1.0364, 0.90: 1.2816, 0.95: 1.6449,
        0.97: 1.8808, 0.98: 2.0537, 0.99: 2.3263, 0.995: 2.5758,
        0.999: 3.0902,
    }
    closest = min(table.keys(), key=lambda k: abs(k - service_level))
    return table[closest]


# ----------------------------- Demand Forecasting ----------------------------- #

def forecast_demand(historical_demand, periods_ahead=1, method="blended"):
    """
    Forecast future demand per SKU.

    historical_demand: dict {sku: [demand_values_over_time]}
    Returns: dict {sku: {"forecast": float, "method": str,
                          "mean": float, "std_dev": float}}
    """
    results = {}
    for sku, history in historical_demand.items():
        history = [max(0, h) for h in history]
        ma = _moving_average_forecast(history)
        es = _exponential_smoothing_forecast(history)
        lt = _linear_trend_forecast(history, periods_ahead)

        if method == "moving_average":
            forecast_value = ma
        elif method == "exponential_smoothing":
            forecast_value = es
        elif method == "linear_trend":
            forecast_value = lt
        else:  # blended ensemble
            forecast_value = _safe_mean([ma, es, lt])

        mean_demand = _safe_mean(history)
        std_dev = _safe_stdev(history)

        results[sku] = {
            "forecast": round(max(0.0, forecast_value), 2),
            "method": method,
            "mean": round(mean_demand, 2),
            "std_dev": round(std_dev, 2),
            "periods_ahead": periods_ahead,
        }
    return results


# ----------------------------- Inventory Optimization ----------------------------- #

def optimize_inventory(sku_data, forecasts, service_level=0.95, lead_time_days=7):
    """
    Compute EOQ, safety stock, reorder point, and reorder recommendation per SKU.

    sku_data: dict {sku: {"annual_demand": float, "ordering_cost": float,
                           "holding_cost_per_unit": float, "current_stock": float,
                           "unit_cost": float}}
    forecasts: dict from forecast_demand()
    """
    z = _z_score_for_service_level(service_level)
    inventory_plan = {}

    for sku, data in sku_data.items():
        annual_demand = max(data.get("annual_demand", 0.0), 0.0)
        ordering_cost = max(data.get("ordering_cost", 1.0), 0.01)
        holding_cost = max(data.get("holding_cost_per_unit", 1.0), 0.01)
        current_stock = data.get("current_stock", 0.0)
        unit_cost = data.get("unit_cost", 0.0)

        eoq = math.sqrt((2 * annual_demand * ordering_cost) / holding_cost) if annual_demand > 0 else 0.0

        forecast_info = forecasts.get(sku, {})
        daily_demand_mean = forecast_info.get("mean", annual_demand / 365 if annual_demand else 0.0)
        daily_demand_std = forecast_info.get("std_dev", 0.0)

        safety_stock = z * daily_demand_std * math.sqrt(lead_time_days)
        reorder_point = (daily_demand_mean * lead_time_days) + safety_stock

        needs_reorder = current_stock <= reorder_point
        reorder_qty = eoq if needs_reorder else 0.0

        holding_cost_total = (eoq / 2 if eoq else 0.0) * holding_cost
        ordering_cost_total = (annual_demand / eoq * ordering_cost) if eoq > 0 else 0.0
        total_inventory_cost = holding_cost_total + ordering_cost_total

        inventory_plan[sku] = {
            "eoq": round(eoq, 2),
            "safety_stock": round(safety_stock, 2),
            "reorder_point": round(reorder_point, 2),
            "current_stock": current_stock,
            "needs_reorder": needs_reorder,
            "recommended_order_qty": round(reorder_qty, 2),
            "estimated_annual_cost": round(total_inventory_cost, 2),
            "inventory_value": round(current_stock * unit_cost, 2),
        }
    return inventory_plan


# ----------------------------- Production Scheduling ----------------------------- #

def plan_production_schedule(inventory_plan, production_capacity, priority_weights=None):
    """
    Allocate limited production capacity across SKUs based on need & priority.

    inventory_plan: dict from optimize_inventory()
    production_capacity: total units of capacity available per period
    priority_weights: dict {sku: weight} optional, default 1.0
    """
    priority_weights = priority_weights or {}
    candidates = []

    for sku, plan in inventory_plan.items():
        if plan["needs_reorder"] and plan["recommended_order_qty"] > 0:
            weight = priority_weights.get(sku, 1.0)
            urgency = max(0.0, plan["reorder_point"] - plan["current_stock"]) + 1e-6
            score = urgency * weight
            candidates.append({
                "sku": sku,
                "requested_qty": plan["recommended_order_qty"],
                "urgency_score": score,
            })

    total_score = sum(c["urgency_score"] for c in candidates) or 1.0
    remaining_capacity = production_capacity
    schedule = []

    candidates.sort(key=lambda c: c["urgency_score"], reverse=True)

    for c in candidates:
        proportional_alloc = (c["urgency_score"] / total_score) * production_capacity
        allocated = min(c["requested_qty"], proportional_alloc, remaining_capacity)
        allocated = max(0.0, round(allocated, 2))
        remaining_capacity -= allocated
        remaining_capacity = max(0.0, remaining_capacity)

        schedule.append({
            "sku": c["sku"],
            "scheduled_qty": allocated,
            "requested_qty": round(c["requested_qty"], 2),
            "fulfillment_rate": round(allocated / c["requested_qty"], 3) if c["requested_qty"] else 0.0,
            "production_start": datetime.now().strftime("%Y-%m-%d"),
            "estimated_completion": (datetime.now() + timedelta(days=3)).strftime("%Y-%m-%d"),
        })

    # Distribute any leftover capacity to unmet demand, in order of urgency
    if remaining_capacity > 0:
        for item in schedule:
            if remaining_capacity <= 0:
                break
            shortfall = item["requested_qty"] - item["scheduled_qty"]
            if shortfall > 0:
                extra = min(shortfall, remaining_capacity)
                item["scheduled_qty"] = round(item["scheduled_qty"] + extra, 2)
                item["fulfillment_rate"] = round(
                    item["scheduled_qty"] / item["requested_qty"], 3
                ) if item["requested_qty"] else 0.0
                remaining_capacity -= extra

    return {
        "schedule": schedule,
        "total_capacity": production_capacity,
        "capacity_utilized": round(production_capacity - remaining_capacity, 2),
        "capacity_remaining": round(remaining_capacity, 2),
    }


