            "lead_time_score": round(lead_time_score, 2),
            "recommendation": (
                "Increase order allocation" if composite_score >= 85
                else "Maintain relationship" if composite_score >= 70
                else "Monitor closely" if composite_score >= 50
                else "Consider alternative suppliers"
            ),
        }

    ranked = dict(sorted(supplier_scores.items(), key=lambda kv: kv[1]["composite_score"], reverse=True))
    return ranked


# ----------------------------- Shipment Tracking ----------------------------- #

class ShipmentTracker:
    """Tracks shipment lifecycle and status history."""

    STATUS_FLOW = ["created", "picked_up", "in_transit", "out_for_delivery", "delivered", "delayed", "exception"]

    def __init__(self):
        self.shipments = {}

    def create_shipment(self, order_id, origin, destination, carrier="default_carrier"):
        shipment_id = str(uuid.uuid4())[:8]
        self.shipments[shipment_id] = {
            "shipment_id": shipment_id,
            "order_id": order_id,
            "origin": origin,
            "destination": destination,
            "carrier": carrier,
            "status": "created",
            "history": [{
                "status": "created",
                "timestamp": datetime.now().isoformat(),
            }],
            "current_location": origin,
        }
        return shipment_id

    def update_status(self, shipment_id, status, location=None):
        if shipment_id not in self.shipments:
            raise ValueError(f"Unknown shipment_id: {shipment_id}")
        if status not in self.STATUS_FLOW:
            raise ValueError(f"Invalid status: {status}")

        shipment = self.shipments[shipment_id]
        shipment["status"] = status
        if location:
            shipment["current_location"] = location
        shipment["history"].append({
            "status": status,
            "timestamp": datetime.now().isoformat(),
            "location": location,
        })
        return shipment

    def get_shipment_status(self, shipment_id):
        return self.shipments.get(shipment_id)

    def get_delayed_shipments(self):
        return [s for s in self.shipments.values() if s["status"] in ("delayed", "exception")]

    def get_all_shipments(self):
        return list(self.shipments.values())


