class Deidentifier:
    """HIPAA-compliant de-identification transformations for pandas objects."""

    def __init__(self, secret_key: Optional[bytes] = None, date_shift_days: Optional[int] = None):
        self.secret_key = secret_key or b'default-clinical-deid-key-change-me'
        self._date_shift_days = date_shift_days if date_shift_days is not None else random.randint(-365, 365)
        self._pseudonym_cache: Dict[str, str] = {}

    def hash_identifier(self, identifier: Any) -> str:
        """Deterministically hash an identifier (e.g., patient ID) using HMAC-SHA256."""
        if identifier is None or (isinstance(identifier, float) and np.isnan(identifier)):
            return None
        key = str(identifier)
        if key in self._pseudonym_cache:
            return self._pseudonym_cache[key]
        digest = hmac.new(self.secret_key, key.encode('utf-8'), hashlib.sha256).hexdigest()
        pseudo_id = f"PT-{digest[:16].upper()}"
        self._pseudonym_cache[key] = pseudo_id
        return pseudo_id

