class ClinicalTerminology:
    """Static mappings for common clinical terminology systems."""

    ICD10_PATTERN = re.compile(r'^[A-TV-Z][0-9][0-9AB](\.[0-9A-Z]{1,4})?$')
    CPT_PATTERN = re.compile(r'^\d{5}$')
    LOINC_PATTERN = re.compile(r'^\d{1,5}-\d$')
    NDC_PATTERN = re.compile(r'^\d{4,5}-\d{3,4}-\d{1,2}$')
    RXNORM_PATTERN = re.compile(r'^\d{1,7}$')

    GENDER_MAP = {
        'M': 'Male', 'F': 'Female', 'O': 'Other', 'U': 'Unknown',
        'MALE': 'Male', 'FEMALE': 'Female', 'OTHER': 'Other', 'UNKNOWN': 'Unknown'
    }

    UNITS_OF_MEASURE = {
        'mg/dL': 'milligrams per deciliter',
        'mmol/L': 'millimoles per liter',
        'mmHg': 'millimeters of mercury',
        'bpm': 'beats per minute',
        'kg': 'kilograms',
        'cm': 'centimeters',
        'lb': 'pounds',
        'in': 'inches',
        '%': 'percent',
        'F': 'Fahrenheit',
        'C': 'Celsius'
    }

    VITAL_SIGN_RANGES = {
        'heart_rate': (40, 200, 'bpm'),
        'systolic_bp': (70, 200, 'mmHg'),
        'diastolic_bp': (40, 130, 'mmHg'),
        'respiratory_rate': (8, 40, 'breaths/min'),
        'temperature_f': (95.0, 106.0, 'F'),
        'temperature_c': (35.0, 41.0, 'C'),
        'spo2': (70, 100, '%'),
        'bmi': (10.0, 70.0, 'kg/m2'),
    }

    @classmethod
    def validate_icd10(cls, code: str) -> bool:
        if not isinstance(code, str):
            return False
        return bool(cls.ICD10_PATTERN.match(code.strip().upper()))

    @classmethod
    def validate_cpt(cls, code: str) -> bool:
        if not isinstance(code, str):
            return False
        return bool(cls.CPT_PATTERN.match(code.strip()))

    @classmethod
    def validate_loinc(cls, code: str) -> bool:
        if not isinstance(code, str):
            return False
        return bool(cls.LOINC_PATTERN.match(code.strip()))

    @classmethod
    def validate_ndc(cls, code: str) -> bool:
        if not isinstance(code, str):
            return False
        return bool(cls.NDC_PATTERN.match(code.strip()))

    @classmethod
    def validate_rxnorm(cls, code: str) -> bool:
        if not isinstance(code, str):
            return False
        return bool(cls.RXNORM_PATTERN.match(code.strip()))

    @classmethod
    def normalize_gender(cls, value: str) -> str:
        if not isinstance(value, str):
            return 'Unknown'
        key = value.strip().upper()
        return cls.GENDER_MAP.get(key, 'Unknown')

    @classmethod
    def is_vital_in_range(cls, vital_name: str, value: float) -> Optional[bool]:
        if vital_name not in cls.VITAL_SIGN_RANGES:
            return None
        low, high, _ = cls.VITAL_SIGN_RANGES[vital_name]
        try:
            v = float(value)
        except (TypeError, ValueError):
            return None
        return low <= v <= high


