class ClinicalDateTime:
    """Healthcare-specific datetime utilities extending datetime module."""

    DATE_FORMATS = [
        '%Y-%m-%d',
        '%m/%d/%Y',
        '%d-%m-%Y',
        '%Y%m%d',
        '%Y-%m-%dT%H:%M:%S',
        '%Y-%m-%dT%H:%M:%S.%f',
        '%m/%d/%Y %H:%M',
    ]

    HIPAA_SAFE_HARBOR_AGE_THRESHOLD = 89

    @classmethod
    def parse_clinical_date(cls, date_str: str) -> Optional[datetime.datetime]:
        """Attempt to parse a date using multiple clinical formats."""
        if date_str is None:
            return None
        if isinstance(date_str, (datetime.datetime, datetime.date)):
            if isinstance(date_str, datetime.date) and not isinstance(date_str, datetime.datetime):
                return datetime.datetime(date_str.year, date_str.month, date_str.day)
            return date_str

        date_str = str(date_str).strip()
        for fmt in cls.DATE_FORMATS:
            try:
                return datetime.datetime.strptime(date_str, fmt)
            except ValueError:
                continue
        try:
            return pd.to_datetime(date_str).to_pydatetime()
        except Exception:
            return None

    @classmethod
    def calculate_age(cls, birth_date: Union[str, datetime.date, datetime.datetime],
                       reference_date: Optional[Union[str, datetime.date, datetime.datetime]] = None) -> Optional[int]:
        """Calculate age in years given a birth date and an optional reference date."""
        bd = cls.parse_clinical_date(birth_date) if not isinstance(birth_date, (datetime.date, datetime.datetime)) else birth_date
        if bd is None:
            return None
        if isinstance(bd, datetime.datetime):
            bd = bd.date()

        if reference_date is None:
            ref = datetime.date.today()
        else:
            rd = cls.parse_clinical_date(reference_date) if not isinstance(reference_date, (datetime.date, datetime.datetime)) else reference_date
            if rd is None:
                return None
            ref = rd.date() if isinstance(rd, datetime.datetime) else rd

        if bd > ref:
            return None

        age = ref.year - bd.year - ((ref.month, ref.day) < (bd.month, bd.day))
        return age

    @classmethod
    def is_hipaa_identifiable_age(cls, age: int) -> bool:
        """HIPAA Safe Harbor: ages over 89 must be aggregated into a single category."""
        return age is not None and age > cls.HIPAA_SAFE_HARBOR_AGE_THRESHOLD

    @classmethod
    def hipaa_safe_age(cls, age: int) -> Union[int, str]:
        """Return HIPAA-compliant age representation."""
        if age is None:
            return "Unknown"
        if cls.is_hipaa_identifiable_age(age):
            return "90+"
        return age

    @classmethod
    def generalize_date_to_year(cls, date_val: Union[str, datetime.date, datetime.datetime]) -> Optional[int]:
        """HIPAA de-identification: reduce a date to just the year."""
        d = cls.parse_clinical_date(date_val) if not isinstance(date_val, (datetime.date, datetime.datetime)) else date_val
        if d is None:
            return None
        return d.year

    @classmethod
    def shift_date(cls, date_val: Union[str, datetime.date, datetime.datetime],
                    days: int) -> Optional[datetime.datetime]:
        """Shift a date by a fixed offset (for date-shifting de-identification)."""
        d = cls.parse_clinical_date(date_val) if not isinstance(date_val, (datetime.date, datetime.datetime)) else date_val
        if d is None:
            return None
        if isinstance(d, datetime.date) and not isinstance(d, datetime.datetime):
            d = datetime.datetime(d.year, d.month, d.day)
        return d + datetime.timedelta(days=days)

    @classmethod
    def is_future_date(cls, date_val: Union[str, datetime.date, datetime.datetime]) -> bool:
        d = cls.parse_clinical_date(date_val) if not isinstance(date_val, (datetime.date, datetime.datetime)) else date_val
        if d is None:
            return False
        d_cmp = d.date() if isinstance(d, datetime.datetime) else d
        return d_cmp > datetime.date.today()

    @classmethod
    def days_between(cls, start: Union[str, datetime.date, datetime.datetime],
                      end: Union[str, datetime.date, datetime.datetime]) -> Optional[int]:
        s = cls.parse_clinical_date(start) if not isinstance(start, (datetime.date, datetime.datetime)) else start
        e = cls.parse_clinical_date(end) if not isinstance(end, (datetime.date, datetime.datetime)) else end
        if s is None or e is None:
            return None
        s_d = s.date() if isinstance(s, datetime.datetime) else s
        e_d = e.date() if isinstance(e, datetime.datetime) else e
        return (e_d - s_d).days


