class HIPAAIdentifiers:
    """Detection and handling of the 18 HIPAA Safe Harbor identifiers."""

    PATTERNS = {
        'ssn': re.compile(r'\b\d{3}-\d{2}-\d{4}\b'),
        'phone': re.compile(r'\b(\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b'),
        'email': re.compile(r'\b[\w.+-]+@[\w-]+\.[\w.-]+\b'),
        'mrn': re.compile(r'\bMRN[:\s]?\d{6,10}\b', re.IGNORECASE),
        'zip_code': re.compile(r'\b\d{5}(-\d{4})?\b'),
        'ip_address': re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b'),
        'url': re.compile(r'https?://[^\s]+'),
        'date_of_birth': re.compile(r'\bDOB[:\s]?\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b', re.IGNORECASE),
    }

    NAME_INDICATORS = re.compile(
        r'\b(?:Mr|Mrs|Ms|Dr|Miss)\.?\s+[A-Z][a-z]+(?:\s+[A-Z][a-z]+)?\b'
    )

    SAFE_HARBOR_FIELDS = [
        'name', 'address', 'dates', 'phone_number', 'fax_number', 'email',
        'ssn', 'mrn', 'health_plan_beneficiary_number', 'account_number',
        'certificate_license_number', 'vehicle_identifier', 'device_identifier',
        'url', 'ip_address', 'biometric_identifier', 'photo', 'other_unique_id'
    ]

    @classmethod
    def detect_phi(cls, text: str) -> Dict[str, List[str]]:
        """Scan text for potential PHI patterns."""
        if not isinstance(text, str):
            return {}
        findings = {}
        for label, pattern in cls.PATTERNS.items():
            matches = pattern.findall(text)
            if matches:
                findings[label] = [m if isinstance(m, str) else ''.join(m) for m in matches]
        name_matches = cls.NAME_INDICATORS.findall(text)
        if name_matches:
            findings['possible_name'] = name_matches
        return findings

    @classmethod
    def contains_phi(cls, text: str) -> bool:
        return bool(cls.detect_phi(text))

    @classmethod
    def redact_phi(cls, text: str, redaction_token: str = "[REDACTED]") -> str:
        """Replace detected PHI patterns with a redaction token."""
        if not isinstance(text, str):
            return text
        result = text
        for pattern in cls.PATTERNS.values():
            result = pattern.sub(redaction_token, result)
        result = cls.NAME_INDICATORS.sub(redaction_token, result)
        return result

    @classmethod
    def generalize_zip(cls, zip_code: str) -> str:
        """HIPAA safe harbor: truncate ZIP to first 3 digits (with population rule caveat)."""
        if not isinstance(zip_code, str):
            zip_code = str(zip_code)
        digits = re.sub(r'\D', '', zip_code)
        if len(digits) >= 3:
            return digits[:3] + "00"
        return "000"


