class Deidentifier:
    """HIPAA-compliant de-identification transformations for pandas objects."""

    def __init__(self, secret_key: Optional[bytes] = None, date_shift_days: Optional[int] = None):
        self.secret_key = secret_key or b'default-clinical-deid-key-change-me'
        self._date_shift_days = date_shift_days if date_shift_days is not None else random.randint(-365, 365)
        self._pseudonym_cache: Dict[str, str] = {}

    def hash_identifier(self, identifier: Any) -> str:
        """Deterministically hash an identifier (e.g., patient ID) using HMAC-SHA256."""
        if identifier is None or (isinstance(identifier, float) and np.isnan(identifier)):
            return None
        key = str(identifier)
        if key in self._pseudonym_cache:
            return self._pseudonym_cache[key]
        digest = hmac.new(self.secret_key, key.encode('utf-8'), hashlib.sha256).hexdigest()
        pseudo_id = f"PT-{digest[:16].upper()}"
        self._pseudonym_cache[key] = pseudo_id
        return pseudo_id

    def shift_date(self, date_val: Union[str, datetime.date, datetime.datetime]) -> Optional[datetime.datetime]:
        return ClinicalDateTime.shift_date(date_val, self._date_shift_days)

    def deidentify_dataframe(
        self,
        df: pd.DataFrame,
        id_columns: Optional[List[str]] = None,
        date_columns: Optional[List[str]] = None,
        text_columns: Optional[List[str]] = None,
        zip_columns: Optional[List[str]] = None,
        drop_columns: Optional[List[str]] = None,
        age_columns: Optional[List[str]] = None,
    ) -> pd.DataFrame:
        """Apply full de-identification pipeline to a clinical dataframe."""
        result = df.copy()

        drop_columns = drop_columns or []
        for col in drop_columns:
            if col in result.columns:
                result = result.drop(columns=[col])

        id_columns = id_columns or []
        for col in id_columns:
            if col in result.columns:
                result[col] = result[col].apply(self.hash_identifier)

        date_columns = date_columns or []
        for col in date_columns:
            if col in result.columns:
                result[col] = result[col].apply(self.shift_date)

        text_columns = text_columns or []
        for col in text_columns:
            if col in result.columns:
                result[col] = result[col].apply(
                    lambda x: HIPAAIdentifiers.redact_phi(x) if isinstance(x, str) else x
                )

        zip_columns = zip_columns or []
        for col in zip_columns:
            if col in result.columns:
                result[col] = result[col].apply(
                    lambda x: HIPAAIdentifiers.generalize_zip(x) if pd.notna(x) else x
                )

        age_columns = age_columns or []
        for col in age_columns:
            if col in result.columns:
                result[col] = result[col].apply(
                    lambda x: ClinicalDateTime.hipaa_safe_age(int(x)) if pd.notna(x) else x
                )

