    def serialize(cls, envelope: MessageEnvelope, pretty: bool = False) -> str:
        try:
            root = ET.Element(cls.ROOT_TAG, attrib={"version": envelope.version})
            header_el = ET.SubElement(root, cls.HEADER_TAG)

            header_fields = {
                "MessageId": envelope.message_id,
                "CorrelationId": envelope.correlation_id or "",
                "SenderId": envelope.sender_id,
