            el = header_el.find(tag)
            return el.text if (el is not None and el.text is not None) else default

        doc_type_raw = get_text("DocumentType", DocumentType.PURCHASE_ORDER.value)
        try:
            doc_type = DocumentType(doc_type_raw)
        except ValueError:
            doc_type = DocumentType.PURCHASE_ORDER

