            "execution_status": dict(self.execution_status),
            "performance_attribution": dict(self.performance_attribution),
            "reconciliation_data": dict(self.reconciliation_data),
        }
        self.rebalance_history.append(summary)

        self._reset_temp_fields()
        self._is_rebalancing = False
        return summary

    def _ensure_active(self):
        if not self._is_rebalancing:
            raise RuntimeError(
                "This operation requires an active rebalancing session. "
                "Call start_rebalance() first."
            )

    # ------------------------------------------------------------------
    # Step 1: Drift calculation
    # ------------------------------------------------------------------
    def calculate_drift(self) -> Dict[str, float]:
        self._ensure_active()
        self.drift_calculations = {}
        symbols = set(self.current_allocations) | set(self.target_allocations)
        for symbol in symbols:
            current = self.current_allocations.get(symbol, 0.0)
            target = self.target_allocations.get(symbol, 0.0)
            self.drift_calculations[symbol] = current - target
        return self.drift_calculations

    # ------------------------------------------------------------------
    # Step 2: Trade candidate generation
    # ------------------------------------------------------------------
    def generate_trade_candidates(self, drift_threshold: float = 0.01) -> List[Dict[str, Any]]:
        self._ensure_active()
        if not self.drift_calculations:
            self.calculate_drift()

        self.trade_candidates = []
        for symbol, drift in self.drift_calculations.items():
            if abs(drift) < drift_threshold:
                continue
            action = "SELL" if drift > 0 else "BUY"
            self.trade_candidates.append({
                "symbol": symbol,
                "action": action,
                "drift": drift,
                "magnitude": abs(drift),
            })
        return self.trade_candidates

    # ------------------------------------------------------------------
    # Step 3: Tax lot selection (for sells)
    # ------------------------------------------------------------------
    def select_tax_lots(self, method: str = "HIFO") -> Dict[str, List[TaxLot]]:
        self._ensure_active()
        self.tax_lot_selections = {}

        for candidate in self.trade_candidates:
            if candidate["action"] != "SELL":
                continue
            symbol = candidate["symbol"]
            lots = [lot for lot in self.tax_lots if lot.symbol == symbol]

            if method == "HIFO":
                lots = sorted(lots, key=lambda l: l.cost_basis, reverse=True)
            elif method == "FIFO":
                lots = sorted(lots, key=lambda l: l.purchase_date)
            elif method == "LIFO":
                lots = sorted(lots, key=lambda l: l.purchase_date, reverse=True)

            self.tax_lot_selections[symbol] = lots

        return self.tax_lot_selections

    # ------------------------------------------------------------------
    # Step 4: Wash sale checks
    # ------------------------------------------------------------------
    def check_wash_sales(self, recent_purchases: Optional[Dict[str, datetime]] = None,
                          window_days: int = 30) -> Dict[str, bool]:
        self._ensure_active()
        recent_purchases = recent_purchases or {}
        self.wash_sale_checks = {}

        now = datetime.now()
        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]
            if candidate["action"] != "SELL":
                self.wash_sale_checks[symbol] = False
                continue

            last_purchase = recent_purchases.get(symbol)
            if last_purchase and (now - last_purchase) <= timedelta(days=window_days):
                self.wash_sale_checks[symbol] = True
            else:
                self.wash_sale_checks[symbol] = False

        return self.wash_sale_checks

    # ------------------------------------------------------------------
    # Step 5: Order generation
    # ------------------------------------------------------------------
    def generate_orders(self, portfolio_value: float) -> List[Order]:
        self._ensure_active()
        orders: List[Order] = []

        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]

            if self.wash_sale_checks.get(symbol, False):
                self.execution_status.setdefault("skipped", []).append(
                    {"symbol": symbol, "reason": "wash_sale"}
                )
                continue

            trade_value = candidate["magnitude"] * portfolio_value
            quantity = trade_value  # simplified; real impl needs price data

            order = Order(symbol=symbol, action=candidate["action"], quantity=quantity)
            orders.append(order)

        self.order_generation_state["orders"] = orders
        self.order_generation_state["generated_at"] = datetime.now()
        return orders

    # ------------------------------------------------------------------
    # Step 6: Execution
    # ------------------------------------------------------------------
    def execute_orders(self) -> Dict[str, Any]:
        self._ensure_active()
        orders = self.order_generation_state.get("orders", [])

        self.execution_status["phase"] = "EXECUTING"
        executed = []
        errors = self.execution_status.get("errors", [])

        for order in orders:
            try:
                order.status = "FILLED"
                executed.append(order)
            except Exception as e:
                errors.append({"symbol": order.symbol, "error": str(e)})
                order.status = "FAILED"

        self.execution_status.update({
            "phase": "COMPLETED",
            "executed_count": len(executed),
            "error_count": len(errors),
            "errors": errors,
        })
        return self.execution_status

    # ------------------------------------------------------------------
    # Step 7: Reconciliation
    # ------------------------------------------------------------------
    def reconcile(self, actual_fills: Dict[str, float]) -> Dict[str, Any]:
        self._ensure_active()
        self.reconciliation_data = {"mismatches": [], "matched": []}

        orders = self.order_generation_state.get("orders", [])
        for order in orders:
            expected = order.quantity
            actual = actual_fills.get(order.symbol)

            if actual is None:
                self.reconciliation_data["mismatches"].append({
                    "symbol": order.symbol,
                    "reason": "no_fill_data",
                })
                continue

            if abs(expected - actual) > 1e-6:
                self.reconciliation_data["mismatches"].append({
                    "symbol": order.symbol,
                    "expected": expected,
                    "actual": actual,
                })
            else:
                self.reconciliation_data["matched"].append(order.symbol)

        return self.reconciliation_data

    # ------------------------------------------------------------------
    # Step 8: Performance attribution
    # ------------------------------------------------------------------
    def calculate_performance_attribution(self) -> Dict[str, Any]:
        self._ensure_active()
        self.performance_attribution = {}

        for symbol, drift in self.drift_calculations.items():
            self.performance_attribution[symbol] = {
                "drift_before_rebalance": drift,
                "wash_sale_blocked": self.wash_sale_checks.get(symbol, False),
            }

        return self.performance_attribution

    # ------------------------------------------------------------------
    # Full rebalance workflow convenience method
    # ------------------------------------------------------------------
    def run_full_rebalance(self, current_allocations: Dict[str, float],
                            target_allocations: Dict[str, float],
                            portfolio_value: float,
                            recent_purchases: Optional[Dict[str, datetime]] = None,
                            actual_fills: Optional[Dict[str, float]] = None,
                            drift_threshold: float = 0.01,
                            tax_lot_method: str = "HIFO") -> Dict[str, Any]:
        self.start_rebalance(current_allocations, target_allocations)
        self.calculate_drift()
        self.generate_trade_candidates(drift_threshold=drift_threshold)
        self.select_tax_lots(method=tax_lot_method)
        self.check_wash_sales(recent_purchases=recent_purchases)
        self.generate_orders(portfolio_value=portfolio_value)
        self.execute_orders()
        self.reconcile(actual_fills=actual_fills or {})
        self.calculate_performance_attribution()
        return self.finish_rebalance()
