                appt_end = appt_start + timedelta(minutes=duration_minutes)
                if start < appt_end and end > appt_start:
                    return False
        return True

    def _get_appointment(self, appointment_id):
        if appointment_id not in self.appointments:
            raise HospitalManagementError(f"Appointment {appointment_id} not found")
        return self.appointments[appointment_id]

    def list_appointments_for_patient(self, patient_id):
        return [a for a in self.appointments.values() if a["patient_id"] == patient_id]

    def list_appointments_for_doctor(self, doctor_id):
        return [a for a in self.appointments.values() if a["doctor_id"] == doctor_id]

    # ---------------------- MEDICAL RECORDS ----------------------
    def add_medical_record(self, patient_id, doctor_id, diagnosis, treatment="", notes=""):
        self._get_patient(patient_id)
        self._get_staff(doctor_id, role="doctor")

        record_id = next(self._record_id_counter)
        self.medical_records[record_id] = {
            "id": record_id,
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "diagnosis": diagnosis,
            "treatment": treatment,
            "notes": notes,
            "date": datetime.now(),
        }
        return record_id

    def get_patient_history(self, patient_id):
        self._get_patient(patient_id)
        return [r for r in self.medical_records.values() if r["patient_id"] == patient_id]

    def get_medical_record(self, record_id):
        if record_id not in self.medical_records:
            raise HospitalManagementError(f"Medical record {record_id} not found")
        return self.medical_records[record_id]

    # ---------------------- BILLING ----------------------
    def create_bill(self, patient_id, items=None):
        self._get_patient(patient_id)
        items = items or []
        total = sum(item.get("cost", 0) * item.get("quantity", 1) for item in items)

        bill_id = next(self._bill_id_counter)
        self.bills[bill_id] = {
            "id": bill_id,
            "patient_id": patient_id,
            "items": items,
            "total": total,
            "paid": False,
            "created_at": datetime.now(),
        }
