    def add_bill_item(self, bill_id, description, cost, quantity=1):
        bill = self._get_bill(bill_id)
        bill["items"].append({"description": description, "cost": cost, "quantity": quantity})
        bill["total"] += cost * quantity
        return bill

    def pay_bill(self, bill_id, amount):
        bill = self._get_bill(bill_id)
        if amount < bill["total"]:
            raise HospitalManagementError("Insufficient payment amount")
        bill["paid"] = True
        bill["paid_at"] = datetime.now()
        return bill

    def get_bill(self, bill_id):
        return self._get_bill(bill_id)

    def get_patient_bills(self, patient_id):
        return [b for b in self.bills.values() if b["patient_id"] == patient_id]

    def _get_bill(self, bill_id):
        if bill_id not in self.bills:
            raise HospitalManagementError(f"Bill {bill_id} not found")
        return self.bills[bill_id]

