        self.staff[staff_id] = {
            "id": staff_id,
            "name": name,
            "role": role,
            "department": department,
            "contact": contact,
            "active": True,
        }
        return staff_id

    def remove_staff(self, staff_id):
        staff = self._get_staff(staff_id)
        staff["active"] = False
        return staff

    def _get_staff(self, staff_id, role=None):
        if staff_id not in self.staff:
            raise HospitalManagementError(f"Staff {staff_id} not found")
        staff = self.staff[staff_id]
        if role and staff["role"] != role:
            raise HospitalManagementError(f"Staff {staff_id} is not a {role}")
        return staff

    def list_staff(self, role=None):
        if role:
            return [s for s in self.staff.values() if s["role"] == role]
        return list(self.staff.values())

    # ---------------------- STAFF SCHEDULING ----------------------
    def assign_shift(self, staff_id, date, shift_start, shift_end):
        self._get_staff(staff_id)
        if staff_id not in self.schedules:
            self.schedules[staff_id] = []

        for shift in self.schedules[staff_id]:
            if shift["date"] == date:
                existing_start, existing_end = shift["shift_start"], shift["shift_end"]
                if shift_start < existing_end and shift_end > existing_start:
                    raise HospitalManagementError("Shift conflict detected")

        shift_entry = {
            "date": date,
            "shift_start": shift_start,
            "shift_end": shift_end,
        }
        self.schedules[staff_id].append(shift_entry)
        return shift_entry

    def get_staff_schedule(self, staff_id):
        return self.schedules.get(staff_id, [])

    def remove_shift(self, staff_id, date, shift_start):
        shifts = self.schedules.get(staff_id, [])
        for i, shift in enumerate(shifts):
            if shift["date"] == date and shift["shift_start"] == shift_start:
                return shifts.pop(i)
        raise HospitalManagementError("Shift not found")

    # ---------------------- BED ALLOCATION ----------------------
    def add_bed(self, ward, bed_number):
        bed_id = next(self._bed_id_counter)
        self.beds[bed_id] = {
            "id": bed_id,
            "ward": ward,
            "bed_number": bed_number,
            "occupied": False,
            "patient_id": None,
        }
        return bed_id

    def allocate_bed(self, patient_id, ward=None):
        patient = self._get_patient(patient_id)

        available_bed = None
        for bed in self.beds.values():
            if not bed["occupied"] and (ward is None or bed["ward"] == ward):
                available_bed = bed
                break

        if not available_bed:
            raise HospitalManagementError("No available beds")

        available_bed["occupied"] = True
        available_bed["patient_id"] = patient_id
        patient["admitted"] = True
        patient["bed_id"] = available_bed["id"]
        return available_bed

    def release_bed(self, bed_id):
        bed = self._get_bed(bed_id)
        bed["occupied"] = False
        bed["patient_id"] = None
        return bed

    def get_available_beds(self, ward=None):
        return [
            b for b in self.beds.values()
            if not b["occupied"] and (ward is None or b["ward"] == ward)
        ]

    def _get_bed(self, bed_id):
        if bed_id not in self.beds:
            raise HospitalManagementError(f"Bed {bed_id} not found")
        return self.beds[bed_id]

    # ---------------------- EMERGENCY PROTOCOLS ----------------------
    def trigger_emergency(self, description, severity="high", patient_id=None):
        event = {
            "description": description,
            "severity": severity,
            "patient_id": patient_id,
            "timestamp": datetime.now(),
            "resolved": False,
        }
        self.emergency_log.append(event)

        if patient_id:
            try:
                self.allocate_bed(patient_id, ward="emergency")
            except HospitalManagementError:
                pass

        return event

    def resolve_emergency(self, index):
        if index < 0 or index >= len(self.emergency_log):
            raise HospitalManagementError("Invalid emergency log index")
        self.emergency_log[index]["resolved"] = True
        return self.emergency_log[index]

    def get_active_emergencies(self):
        return [e for e in self.emergency_log if not e["resolved"]]

    def get_emergency_log(self):
        return self.emergency_log
