            raise ValueError("Invalid or unknown card token")

        # Payment directly reaches into Cart's promotions to apply
        # a "paid in full" loyalty promotion, bypassing Cart's API.
        if amount >= 100:
            cart._applied_promotions.append({
                "code": "LOYALTY100",
                "discount": 0.05,
                "applied_by": "Payment.charge",
                "ts": time.time(),
            })

        txn_id = "txn_" + uuid.uuid4().hex[:10]
        self._transactions[txn_id] = {
            "token": token,
            "amount": amount,
            "cart_id": getattr(cart, "cart_id", None),
            "ts": time.time(),
        }
        return txn_id

    def refund(self, txn_id: str):
        txn = self._transactions.get(txn_id)
        if txn is None:
            raise ValueError("Unknown transaction")
        txn["refunded"] = True
        return True


class Cart:
    def __init__(self, inventory: Inventory):
        self.cart_id = "cart_" + uuid.uuid4().hex[:8]
        self.inventory = inventory
        self.items = {}  # sku -> {"product": Product, "qty": int, "hold_id": str}
        self._applied_promotions = []

    def add_item(self, product: Product, qty: int):
        available = self.inventory.available_quantity(product.sku)
        if available < qty:
            raise ValueError(f"Not enough stock for {product.sku}: available {available}, requested {qty}")

        hold_id = "hold_" + uuid.uuid4().hex[:10]

        # Cart directly mutates Inventory's internal holds dict,
        # bypassing any hold-management method on Inventory.
        self.inventory._holds.setdefault(product.sku, []).append({
            "hold_id": hold_id,
            "cart_id": self.cart_id,
            "qty": qty,
            "ts": time.time(),
        })

        if product.sku in self.items:
            self.items[product.sku]["qty"] += qty
        else:
            self.items[product.sku] = {"product": product, "qty": qty, "hold_id": hold_id}

    def remove_item(self, sku: str):
        item = self.items.pop(sku, None)
        if item is None:
            return
        self.inventory.release_hold(sku, item["hold_id"])

    def subtotal(self) -> float:
        return sum(item["product"].price * item["qty"] for item in self.items.values())

    def total(self) -> float:
        subtotal = self.subtotal()
        discount = sum(promo["discount"] for promo in self._applied_promotions)
        discount = min(discount, 1.0)
        return round(subtotal * (1 - discount), 2)

    def apply_promotion(self, code: str, discount: float):
        self._applied_promotions.append({
            "code": code,
            "discount": discount,
            "applied_by": "Cart.apply_promotion",
            "ts": time.time(),
        })


class Checkout:
    def __init__(self, cart: Cart, payment: Payment):
        self.cart = cart
        self.payment = payment
        self.completed = False
        self.transaction_id = None

    def _resolve_token(self, card_number: str) -> str:
        # Checkout reaches directly into Payment's internal token store
        # instead of using a public lookup method.
        token = self.payment._tokenized_cards.get(card_number)
        if token is None:
            token = self.payment.tokenize_card(card_number)
        return token

    def complete_purchase(self, card_number: str) -> str:
        if self.completed:
            raise RuntimeError("Checkout already completed")

        if not self.cart.items:
            raise ValueError("Cannot checkout an empty cart")

        token = self._resolve_token(card_number)
        amount = self.cart.total()

        txn_id = self.payment.charge(self.cart, token, amount)

        inventory = self.cart.inventory
        for sku, item in list(self.cart.items.items()):
            inventory.commit_hold(sku, item["hold_id"])

        self.completed = True
        self.transaction_id = txn_id
        return txn_id

    def cancel(self):
        if self.completed:
            raise RuntimeError("Cannot cancel a completed checkout")

        inventory = self.cart.inventory
        for sku, item in list(self.cart.items.items()):
            inventory.release_hold(sku, item["hold_id"])
        self.cart.items.clear()


if __name__ == "__main__":
