    inventory.add_stock("SKU2", 5)

    payment = Payment()

    cart = Cart(inventory)
    product1 = Product("SKU1", "Widget", 60.0)
    product2 = Product("SKU2", "Gadget", 45.0)

    cart.add_item(product1, 1)
    cart.add_item(product2, 1)

    print("Subtotal:", cart.subtotal())

    checkout = Checkout(cart, payment)
    txn = checkout.complete_purchase("4111111111111111")

    print("Transaction:", txn)
    print("Total charged:", cart.total())
    print("Promotions applied:", cart._applied_promotions)
    print("Remaining stock SKU1:", inventory.available_quantity("SKU1"))
    print("Remaining stock SKU2:", inventory.available_quantity("SKU2"))
