"""
E-commerce module.

Cart operations, checkout, invoice generation, and inventory updates all
accept the core line-item data as separate parameters:
    (product_id, quantity, unit_price, discount_percent, tax_rate)
"""

from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, List, Optional
import uuid


# --------------------------------------------------------------------------
# Exceptions
# --------------------------------------------------------------------------

class EcommerceError(Exception):
    """Base exception for the e-commerce module."""


class InvalidLineItemError(EcommerceError):
    """Raised when line item parameters are invalid."""


class InsufficientInventoryError(EcommerceError):
    """Raised when there isn't enough stock to fulfill a request."""


class ProductNotFoundError(EcommerceError):
    """Raised when a product_id is not found in inventory or cart."""


class EmptyCartError(EcommerceError):
    """Raised when checkout is attempted on an empty cart."""


# --------------------------------------------------------------------------
# Helper validation
# --------------------------------------------------------------------------

def _validate_line_item(
    product_id: str,
    quantity: int,
    unit_price: float,
    discount_percent: float,
    tax_rate: float,
) -> None:
    if not product_id or not isinstance(product_id, str):
        raise InvalidLineItemError("product_id must be a non-empty string.")
    if not isinstance(quantity, int) or quantity <= 0:
        raise InvalidLineItemError("quantity must be a positive integer.")
    if not isinstance(unit_price, (int, float)) or unit_price < 0:
        raise InvalidLineItemError("unit_price must be a non-negative number.")
    if not isinstance(discount_percent, (int, float)) or not (0 <= discount_percent <= 100):
        raise InvalidLineItemError("discount_percent must be between 0 and 100.")
    if not isinstance(tax_rate, (int, float)) or not (0 <= tax_rate <= 100):
        raise InvalidLineItemError("tax_rate must be between 0 and 100.")


def _compute_line_totals(
    quantity: int,
    unit_price: float,
    discount_percent: float,
    tax_rate: float,
) -> Dict[str, float]:
    gross = quantity * unit_price
    discount_amount = gross * (discount_percent / 100.0)
    net_before_tax = gross - discount_amount
    tax_amount = net_before_tax * (tax_rate / 100.0)
    total = net_before_tax + tax_amount

    return {
        "gross": round(gross, 2),
        "discount_amount": round(discount_amount, 2),
        "net_before_tax": round(net_before_tax, 2),
        "tax_amount": round(tax_amount, 2),
        "total": round(total, 2),
    }


# --------------------------------------------------------------------------
# Inventory
# --------------------------------------------------------------------------

@dataclass
class InventoryItem:
    product_id: str
    stock: int
    unit_price: float


class Inventory:
    """Tracks stock levels for products."""

    def __init__(self) -> None:
        self._items: Dict[str, InventoryItem] = {}

    def add_stock(
        self,
        product_id: str,
        quantity: int,
        unit_price: float,
        discount_percent: float = 0.0,
        tax_rate: float = 0.0,
    ) -> None:
        """
        Add stock for a product. discount_percent and tax_rate are accepted
        for API consistency with other operations but do not affect stock
        levels; unit_price updates the reference price for the product.
        """
        _validate_line_item(product_id, quantity, unit_price, discount_percent, tax_rate)

        if product_id in self._items:
            item = self._items[product_id]
            item.stock += quantity
            item.unit_price = unit_price
        else:
            self._items[product_id] = InventoryItem(
                product_id=product_id, stock=quantity, unit_price=unit_price
            )

    def reduce_stock(
        self,
        product_id: str,
        quantity: int,
        unit_price: float,
        discount_percent: float = 0.0,
        tax_rate: float = 0.0,
    ) -> None:
        """
        Reduce stock for a product (e.g. after checkout). discount_percent
        and tax_rate are accepted for signature consistency but not used
        in the stock calculation itself.
        """
        _validate_line_item(product_id, quantity, unit_price, discount_percent, tax_rate)

        item = self._items.get(product_id)
        if item is None:
            raise ProductNotFoundError(f"Product '{product_id}' not found in inventory.")
        if item.stock < quantity:
            raise InsufficientInventoryError(
                f"Insufficient inventory for product '{product_id}': "
                f"requested {quantity}, available {item.stock}."
            )
        item.stock -= quantity

