def _compute_line_totals(
    quantity: int,
    unit_price: float,
    discount_percent: float,
    tax_rate: float,
) -> Dict[str, float]:
    gross = quantity * unit_price
    discount_amount = gross * (discount_percent / 100.0)
    net_before_tax = gross - discount_amount
    tax_amount = net_before_tax * (tax_rate / 100.0)
    total = net_before_tax + tax_amount

