@dataclass
class Order:
    """
    Generic order model. Order-type-specific fields live in `params`,
    a free-form dict interpreted only by the corresponding
    OrderTypeHandler. This keeps the Order model stable as new order
    types are added.
    """
    symbol: str
    side: OrderSide
    quantity: Decimal
    order_type: str  # string key into OrderTypeRegistry
    order_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    status: OrderStatus = OrderStatus.NEW
    params: Dict[str, Any] = field(default_factory=dict)
    filled_quantity: Decimal = Decimal("0")
    avg_fill_price: Optional[Decimal] = None
    created_at: float = field(default_factory=time.time)

    def remaining_quantity(self) -> Decimal:
        return self.quantity - self.filled_quantity


