@dataclass
class Fill:
    order_id: str
    quantity: Decimal
    price: Decimal
    timestamp: float = field(default_factory=time.time)


class ExecutionHandler:
    def __init__(self):
        self.fills: List[Fill] = []

    def build_instructions(self, order: Order) -> Dict[str, Any]:
        handler = OrderTypeRegistry.get(order.order_type)
        return handler.build_execution_instructions(order)

    def execute(self, order: Order, market_price: Decimal) -> Fill:
        instructions = self.build_instructions(order)
        fill_price = instructions.get("limit_price") or instructions.get("stop_price") or market_price
        fill_qty = order.remaining_quantity()

        order.filled_quantity += fill_qty
        order.avg_fill_price = fill_price
        order.status = (
            OrderStatus.FILLED
            if order.filled_quantity >= order.quantity
            else OrderStatus.PARTIALLY_FILLED
        )

        fill = Fill(order_id=order.order_id, quantity=fill_qty, price=fill_price)
        self.fills.append(fill)
        return fill


