class RiskCalculator:
    def calculate_exposure(self, order: Order, market_price: Decimal) -> Decimal:
        handler = OrderTypeRegistry.get(order.order_type)
        return handler.calculate_risk_exposure(order, market_price)

    def aggregate_exposure(self, orders: List[Order], market_price: Decimal) -> Decimal:
        return sum((self.calculate_exposure(o, market_price) for o in orders), Decimal("0"))


