class PositionTracker:
    def __init__(self):
        self._positions: Dict[str, Decimal] = {}
        self._lock = threading.Lock()

    def apply_fill(self, order: Order, fill: Fill) -> Decimal:
        handler = OrderTypeRegistry.get(order.order_type)
        delta = handler.position_delta(order, fill.quantity)
        with self._lock:
            current = self._positions.get(order.symbol, Decimal("0"))
            new_position = current + delta
            self._positions[order.symbol] = new_position
        return new_position

    def get_position(self, symbol: str) -> Decimal:
        return self._positions.get(symbol, Decimal("0"))


