class SettlementProcessor:
    def prepare_settlement(self, order: Order, fill: Fill) -> SettlementInstruction:
        handler = OrderTypeRegistry.get(order.order_type)
        terms = handler.settlement_terms(order)
        amount = fill.quantity * fill.price
        order.status = OrderStatus.SETTLED
        return SettlementInstruction(
            order_id=order.order_id,
            settlement_days=terms.get("settlement_days", 2),
            cash_settled=terms.get("cash_settled", False),
            amount=amount,
        )


