class DatabaseConnectionManager:
    """Manages a pool of thread-local sqlite database connections."""

    def __init__(self, db_path=":memory:", timeout=5.0):
        self.db_path = db_path
        self.timeout = timeout
        self._local = threading.local()
        self._lock = threading.Lock()
        self._connections = []

    def get_connection(self):
        conn = getattr(self._local, "connection", None)
        if conn is None:
            conn = sqlite3.connect(
                self.db_path, timeout=self.timeout, check_same_thread=False
            )
            conn.row_factory = sqlite3.Row
            self._local.connection = conn
            with self._lock:
                self._connections.append(conn)
        return conn

    def execute(self, query, params=None):
        conn = self.get_connection()
        cursor = conn.cursor()
        try:
            cursor.execute(query, params or [])
            conn.commit()
            return cursor
        except Exception:
            conn.rollback()
            raise

    def execute_many(self, query, param_list):
        conn = self.get_connection()
        cursor = conn.cursor()
        try:
            cursor.executemany(query, param_list)
            conn.commit()
            return cursor
        except Exception:
            conn.rollback()
            raise

    def fetch_one(self, query, params=None):
        cursor = self.execute(query, params)
        row = cursor.fetchone()
        return dict(row) if row else None

    def fetch_all(self, query, params=None):
        cursor = self.execute(query, params)
        rows = cursor.fetchall()
        return [dict(r) for r in rows]

    def transaction(self):
        return _TransactionContext(self)

    def close_all(self):
        with self._lock:
            for conn in self._connections:
                try:
                    conn.close()
                except Exception:
                    pass
            self._connections = []

    def close(self):
        conn = getattr(self._local, "connection", None)
        if conn is not None:
            try:
                conn.close()
            finally:
                self._local.connection = None


class _TransactionContext:
    def __init__(self, manager):
        self.manager = manager
        self.conn = None

    def __enter__(self):
        self.conn = self.manager.get_connection()
        return self.conn

    def __exit__(self, exc_type, exc_val, exc_tb):
        if exc_type is None:
            self.conn.commit()
        else:
            self.conn.rollback()
        return False


class SimpleCache:
    """Thread-safe in-memory cache with TTL support."""

    def __init__(self, default_ttl=60):
        self.default_ttl = default_ttl
        self._store = {}
        self._lock = threading.Lock()

    def _make_key(self, key):
        if isinstance(key, str):
            return key
        return hashlib.sha256(json.dumps(key, sort_keys=True, default=str).encode()).hexdigest()

    def get(self, key):
        k = self._make_key(key)
        with self._lock:
            entry = self._store.get(k)
            if entry is None:
                return None
            value, expires_at = entry
            if expires_at is not None and expires_at < time.time():
                del self._store[k]
                return None
            return value

    def set(self, key, value, ttl=None):
        k = self._make_key(key)
        ttl = self.default_ttl if ttl is None else ttl
        expires_at = time.time() + ttl if ttl is not None else None
        with self._lock:
            self._store[k] = (value, expires_at)

    def delete(self, key):
        k = self._make_key(key)
        with self._lock:
            self._store.pop(k, None)

    def clear(self):
        with self._lock:
            self._store.clear()

    def cached(self, ttl=None, key_prefix=""):
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                cache_key = f"{key_prefix}:{func.__name__}:{args}:{kwargs}"
                cached_val = self.get(cache_key)
                if cached_val is not None:
                    return cached_val
                result = func(*args, **kwargs)
                self.set(cache_key, result, ttl)
                return result
            return wrapper
        return decorator


class Route:
    def __init__(self, method, path, handler, validators=None):
        self.method = method.upper()
        self.path = path
        self.handler = handler
        self.validators = validators or {}
        self.param_names = []
        self.pattern = self._compile_path(path)

    def _compile_path(self, path):
        import re
        parts = path.strip("/").split("/")
        regex_parts = []
        for part in parts:
            if part.startswith(":"):
                name = part[1:]
                self.param_names.append(name)
                regex_parts.append(r"([^/]+)")
            else:
                regex_parts.append(re.escape(part))
        pattern = "^/" + "/".join(regex_parts) + "/?$"
        return re.compile(pattern)

    def match(self, method, path):
        if method.upper() != self.method:
            return None
        m = self.pattern.match(path)
        if not m:
            return None
        return dict(zip(self.param_names, m.groups()))


