class Validator:
    """Basic rule-based validator."""

    @staticmethod
    def validate(data, rules):
        errors = {}
        for field, rule_set in rules.items():
            value = data.get(field)
            required = rule_set.get("required", False)
            field_type = rule_set.get("type")
            min_len = rule_set.get("min_length")
            max_len = rule_set.get("max_length")
            min_val = rule_set.get("min")
            max_val = rule_set.get("max")
            custom = rule_set.get("validator")

            if required and (value is None or value == ""):
                errors.setdefault(field, []).append("This field is required")
                continue

            if value is None:
                continue

            if field_type is not None:
                if field_type == "int":
                    try:
                        value = int(value)
                    except (ValueError, TypeError):
                        errors.setdefault(field, []).append("Must be an integer")
                        continue
                elif field_type == "float":
                    try:
                        value = float(value)
                    except (ValueError, TypeError):
                        errors.setdefault(field, []).append("Must be a number")
                        continue
                elif field_type == "str":
                    if not isinstance(value, str):
                        errors.setdefault(field, []).append("Must be a string")
                        continue
                elif field_type == "bool":
                    if not isinstance(value, bool):
                        errors.setdefault(field, []).append("Must be a boolean")
                        continue
                elif field_type == "list":
                    if not isinstance(value, list):
                        errors.setdefault(field, []).append("Must be a list")
                        continue
                elif field_type == "dict":
                    if not isinstance(value, dict):
                        errors.setdefault(field, []).append("Must be an object")
                        continue

            if min_len is not None and hasattr(value, "__len__") and len(value) < min_len:
                errors.setdefault(field, []).append(f"Minimum length is {min_len}")

            if max_len is not None and hasattr(value, "__len__") and len(value) > max_len:
                errors.setdefault(field, []).append(f"Maximum length is {max_len}")

            if min_val is not None and isinstance(value, (int, float)) and value < min_val:
                errors.setdefault(field, []).append(f"Minimum value is {min_val}")

            if max_val is not None and isinstance(value, (int, float)) and value > max_val:
                errors.setdefault(field, []).append(f"Maximum value is {max_val}")

            if custom and callable(custom):
                try:
                    ok = custom(value)
                    if not ok:
                        errors.setdefault(field, []).append("Invalid value")
                except Exception as e:
                    errors.setdefault(field, []).append(str(e))

        return errors


class TemplateRenderer:
    """Simple string.Template-based renderer with template registry."""

    def __init__(self):
        self._templates = {}

    def register(self, name, template_str):
        self._templates[name] = Template(template_str)

    def render(self, name, context=None):
        context = context or {}
        template = self._templates.get(name)
        if template is None:
            raise NotFoundError(f"Template '{name}' not found")
        try:
            return template.safe_substitute(**context)
        except Exception as e:
            raise ApplicationError(f"Template rendering failed: {e}")


