            if article_id == exclude_article_id:
                continue
            article_tags = set(t.lower() for t in article["tags"])
            overlap = len(tag_set & article_tags)
            if overlap > 0:
                scores[article_id] = overlap
        ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)
        return [self.articles[cid] for cid, _ in ranked[:limit]]

    def recommend_trending(self, limit=5, days=7):
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(days=days)).isoformat()
        scores = []
        for article_id, article in self.articles.items():
            data = self.analytics[article_id]
            recent_views = sum(1 for log in data["view_log"] if log["timestamp"] >= cutoff)
            trend_score = recent_views + data["likes"] * 0.5 + data["shares"] * 0.8
            scores.append((article_id, trend_score))
        scores.sort(key=lambda x: x[1], reverse=True)
        return [self.articles[aid] for aid, _ in scores[:limit] if aid in self.articles]

    def recommend_for_user(self, user_id, limit=5):
        viewed_articles = []
        for article_id, data in self.analytics.items():
            if user_id in data["unique_views"]:
                viewed_articles.append(article_id)

        if not viewed_articles:
            return self.recommend_trending(limit=limit)

        tag_pool = []
        category_pool = []
        for aid in viewed_articles:
            article = self.articles.get(aid)
            if article:
                tag_pool.extend(article["tags"])
                if article.get("category"):
                    category_pool.append(article["category"])

        top_tags = [tag for tag, _ in Counter(tag_pool).most_common(5)]
        recommendations = self.recommend_by_tags(top_tags, limit=limit * 2)

        filtered = [a for a in recommendations if a["id"] not in viewed_articles]
        return filtered[:limit]

    # ---------------------- Search ----------------------

    def search_articles(self, query, language=None):
        tokens = set(self._tokenize(query))
        scores = defaultdict(int)
        for token in tokens:
            for article_id in self.recommendation_index.get(token, set()):
                scores[article_id] += 1

        results = []
        for article_id, score in sorted(scores.items(), key=lambda x: x[1], reverse=True):
            article = self.articles.get(article_id)
            if article and (not language or article["language"] == language):
                results.append(article)
        return results

    # ---------------------- Audit ----------------------

    def get_audit_log(self, entity_id=None, entity_type=None):
        results = self.audit_log
        if entity_id:
            results = [log for log in results if log["entity_id"] == entity_id]
        if entity_type:
            results = [log for log in results if log["entity_type"] == entity_type]
