        article = self._require_article(article_id)
        if language and language != article["language"]:
            localized = self.localizations.get(article_id, {}).get(language)
            if localized:
                merged = dict(article)
                merged.update(localized)
                merged["language"] = language
                return merged
        return article

    def list_articles(self, status=None, category=None, tag=None, author=None):
        results = list(self.articles.values())
        if status:
