    def link_media_to_article(self, media_id, article_id):
        media = self._require_media(media_id)
        self._require_article(article_id)
        if article_id not in media["linked_articles"]:
            media["linked_articles"].append(article_id)
        self._log_action("link_media", "media", media_id, {"article_id": article_id})
        return media

    def unlink_media_from_article(self, media_id, article_id):
        media = self._require_media(media_id)
        if article_id in media["linked_articles"]:
            media["linked_articles"].remove(article_id)
