    def publish_article(self, article_id, scheduled_time=None):
        article = self._require_article(article_id)
        if scheduled_time and scheduled_time > self._now():
            article["status"] = "scheduled"
            article["scheduled_time"] = scheduled_time
        else:
            article["status"] = "published"
            article["published_at"] = self._now()
        self._log_action("publish", "article", article_id, {"scheduled": bool(scheduled_time)})
        return article

    def unpublish_article(self, article_id):
        article = self._require_article(article_id)
        article["status"] = "unpublished"
        self._log_action("unpublish", "article", article_id)
        return article

    def archive_article(self, article_id):
        article = self._require_article(article_id)
        article["status"] = "archived"
        self._log_action("archive", "article", article_id)
        return article

    def check_scheduled_publications(self):
        now = self._now()
        published = []
        for article_id, article in self.articles.items():
            if article["status"] == "scheduled" and article.get("scheduled_time", "") <= now:
                article["status"] = "published"
                article["published_at"] = now
                published.append(article_id)
        return published

    # ---------------------- Versioning ----------------------

    def _save_version(self, article_id, article, note="", editor=None):
        version_number = article["current_version"]
        snapshot = {
            "version": version_number,
            "title": article["title"],
            "body": article["body"],
            "tags": list(article["tags"]),
            "category": article["category"],
            "timestamp": self._now(),
            "editor": editor or article.get("author"),
            "note": note
        }
        self.versions[article_id].append(snapshot)
        return snapshot

    def get_version_history(self, article_id):
        if article_id not in self.versions:
            raise KeyError(f"No version history for article {article_id}")
        return self.versions[article_id]

    def get_version(self, article_id, version_number):
        history = self.get_version_history(article_id)
        for v in history:
            if v["version"] == version_number:
                return v
        raise KeyError(f"Version {version_number} not found for article {article_id}")

    def revert_to_version(self, article_id, version_number, editor=None):
        version = self.get_version(article_id, version_number)
        article = self._require_article(article_id)
        article["title"] = version["title"]
        article["body"] = version["body"]
        article["tags"] = list(version["tags"])
        article["category"] = version["category"]
        article["updated_at"] = self._now()
        article["current_version"] += 1
        self._save_version(article_id, article, note=f"Reverted to version {version_number}", editor=editor)
        self._log_action("revert", "article", article_id, {"to_version": version_number})
        return article

    def diff_versions(self, article_id, version_a, version_b):
        va = self.get_version(article_id, version_a)
        vb = self.get_version(article_id, version_b)
        diff = list(difflib.unified_diff(
            va["body"].splitlines(),
            vb["body"].splitlines(),
            lineterm="",
            fromfile=f"v{version_a}",
            tofile=f"v{version_b}"
        ))
        return diff

