    # ---------------------- SEO Optimization ----------------------

    def analyze_seo(self, article_id):
        article = self._require_article(article_id)
        title = article["title"] or ""
        body = article["body"] or ""
        tokens = self._tokenize(body)
        word_count = len(tokens)
        keyword_freq = Counter(tokens)
        top_keywords = [w for w, _ in keyword_freq.most_common(10) if len(w) > 3]

        issues = []
        score = 100

        if len(title) < 10:
            issues.append("Title too short")
            score -= 15
        if len(title) > 70:
            issues.append("Title too long for SEO")
            score -= 10
        if word_count < 300:
            issues.append("Content too short for good SEO ranking")
            score -= 20
        if not article.get("tags"):
            issues.append("No tags/keywords assigned")
            score -= 10

        meta_description = self.seo_data.get(article_id, {}).get("meta_description")
        if not meta_description:
            issues.append("Missing meta description")
            score -= 15
        elif len(meta_description) > 160:
            issues.append("Meta description too long")
            score -= 5

        slug = self.seo_data.get(article_id, {}).get("slug")
        if not slug:
            issues.append("Missing SEO slug")
            score -= 10

        score = max(0, score)

        result = {
            "word_count": word_count,
            "top_keywords": top_keywords,
            "score": score,
            "issues": issues
        }
        return result

    def set_seo_metadata(self, article_id, meta_title=None, meta_description=None, slug=None, keywords=None):
        self._require_article(article_id)
