    def get_top_articles(self, metric="views", limit=10):
        valid_metrics = {"views", "shares", "likes", "comments"}
        if metric not in valid_metrics:
            raise ValueError(f"Invalid metric: {metric}")
        scored = []
        for article_id in self.articles:
            value = self.analytics[article_id][metric]
            scored.append((article_id, value))
        scored.sort(key=lambda x: x[1], reverse=True)
