        pattern = self._compile_path(path)
        self.routes.append((method.upper(), pattern, handler, path))

    def _compile_path(self, path):
        pattern = re.sub(r"<(\w+)>", r"(?P<\1>[^/]+)", path)
        return re.compile(f"^{pattern}$")

    def route(self, method, path):
        def decorator(func):
