"""
Insurance System

This module implements a policy insurance system where adding a new
coverage type requires touching each of the ten subsystems listed below:

    1. Policy model
    2. Quote engine
    3. Underwriting rules
    4. Premium calculator
    5. Claim processor
    6. Billing system
    7. Renewal handler
    8. Compliance reporter
    9. Agent portal
    10. Customer portal

Each subsystem maintains its own registry/handling logic per coverage
type, and adding a new coverage type (e.g. "FLOOD") means writing new
code in each of the ten places below.
"""

from __future__ import annotations

import datetime
import uuid
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional


# ---------------------------------------------------------------------------
# Coverage Types
# ---------------------------------------------------------------------------

class CoverageType(Enum):
    AUTO_LIABILITY = "AUTO_LIABILITY"
    AUTO_COLLISION = "AUTO_COLLISION"
    HOME_FIRE = "HOME_FIRE"
    HOME_THEFT = "HOME_THEFT"
    LIFE_TERM = "LIFE_TERM"


# ---------------------------------------------------------------------------
# 1. POLICY MODEL
# ---------------------------------------------------------------------------

@dataclass
class Coverage:
    coverage_type: CoverageType
    limit: float
    deductible: float
    attributes: Dict = field(default_factory=dict)


@dataclass
class Policy:
    policy_id: str
    holder_name: str
    coverages: List[Coverage] = field(default_factory=list)
    start_date: datetime.date = field(default_factory=datetime.date.today)
    end_date: Optional[datetime.date] = None
    status: str = "ACTIVE"

    def add_coverage(self, coverage: Coverage) -> None:
        # Policy model must know how to validate structure per coverage type.
        if coverage.coverage_type == CoverageType.AUTO_LIABILITY:
            if coverage.limit <= 0:
                raise ValueError("AUTO_LIABILITY requires a positive limit")
        elif coverage.coverage_type == CoverageType.AUTO_COLLISION:
            if "vehicle_value" not in coverage.attributes:
                raise ValueError("AUTO_COLLISION requires vehicle_value attribute")
        elif coverage.coverage_type == CoverageType.HOME_FIRE:
            if "dwelling_value" not in coverage.attributes:
                raise ValueError("HOME_FIRE requires dwelling_value attribute")
        elif coverage.coverage_type == CoverageType.HOME_THEFT:
            if "personal_property_value" not in coverage.attributes:
                raise ValueError("HOME_THEFT requires personal_property_value attribute")
        elif coverage.coverage_type == CoverageType.LIFE_TERM:
            if "term_years" not in coverage.attributes:
                raise ValueError("LIFE_TERM requires term_years attribute")
        else:
            raise ValueError(f"Unsupported coverage type: {coverage.coverage_type}")

        self.coverages.append(coverage)

    def get_coverage(self, coverage_type: CoverageType) -> Optional[Coverage]:
        for c in self.coverages:
            if c.coverage_type == coverage_type:
                return c
        return None


# ---------------------------------------------------------------------------
# 2. QUOTE ENGINE
# ---------------------------------------------------------------------------

@dataclass
class QuoteRequest:
    holder_name: str
    coverage_type: CoverageType
    limit: float
    deductible: float
    attributes: Dict = field(default_factory=dict)


@dataclass
class Quote:
    quote_id: str
    coverage_type: CoverageType
    base_price: float
    valid_until: datetime.date


class QuoteEngine:
    """Generates quotes; each coverage type has its own base pricing logic."""

    def generate_quote(self, request: QuoteRequest) -> Quote:
        base_price = self._base_price_for(request)
        return Quote(
            quote_id=str(uuid.uuid4()),
            coverage_type=request.coverage_type,
            base_price=base_price,
            valid_until=datetime.date.today() + datetime.timedelta(days=30),
        )

    def _base_price_for(self, request: QuoteRequest) -> float:
        if request.coverage_type == CoverageType.AUTO_LIABILITY:
            return request.limit * 0.015
        elif request.coverage_type == CoverageType.AUTO_COLLISION:
            vehicle_value = request.attributes.get("vehicle_value", 0)
            return vehicle_value * 0.03
        elif request.coverage_type == CoverageType.HOME_FIRE:
            dwelling_value = request.attributes.get("dwelling_value", 0)
            return dwelling_value * 0.004
        elif request.coverage_type == CoverageType.HOME_THEFT:
            personal_property_value = request.attributes.get("personal_property_value", 0)
            return personal_property_value * 0.01
        elif request.coverage_type == CoverageType.LIFE_TERM:
            term_years = request.attributes.get("term_years", 1)
            return request.limit * 0.001 * term_years
        else:
            raise ValueError(f"Unsupported coverage type: {request.coverage_type}")


# ---------------------------------------------------------------------------
# 3. UNDERWRITING RULES
# ---------------------------------------------------------------------------

@dataclass
class ApplicantProfile:
    age: int
    risk_score: float
    prior_claims: int
    attributes: Dict = field(default_factory=dict)


class UnderwritingDecision(Enum):
    APPROVE = "APPROVE"
    DECLINE = "DECLINE"
    REFER = "REFER"


class UnderwritingRules:
    """Coverage-specific underwriting eligibility rules."""

    def evaluate(self, coverage_type: CoverageType, profile: ApplicantProfile) -> UnderwritingDecision:
        if coverage_type == CoverageType.AUTO_LIABILITY:
            if profile.age < 18:
                return UnderwritingDecision.DECLINE
            if profile.prior_claims > 3:
                return UnderwritingDecision.REFER
            return UnderwritingDecision.APPROVE

        elif coverage_type == CoverageType.AUTO_COLLISION:
            vehicle_age = profile.attributes.get("vehicle_age", 0)
            if vehicle_age > 20:
                return UnderwritingDecision.DECLINE
            if profile.risk_score > 0.8:
                return UnderwritingDecision.REFER
            return UnderwritingDecision.APPROVE

        elif coverage_type == CoverageType.HOME_FIRE:
            fire_risk_zone = profile.attributes.get("fire_risk_zone", "LOW")
            if fire_risk_zone == "HIGH":
                return UnderwritingDecision.REFER
            return UnderwritingDecision.APPROVE

        elif coverage_type == CoverageType.HOME_THEFT:
            crime_rate = profile.attributes.get("crime_rate", "LOW")
            if crime_rate == "HIGH":
                return UnderwritingDecision.REFER
            return UnderwritingDecision.APPROVE

        elif coverage_type == CoverageType.LIFE_TERM:
            if profile.age > 75:
                return UnderwritingDecision.DECLINE
            health_score = profile.attributes.get("health_score", 1.0)
            if health_score < 0.3:
                return UnderwritingDecision.REFER
            return UnderwritingDecision.APPROVE

        else:
            raise ValueError(f"Unsupported coverage type: {coverage_type}")


# ---------------------------------------------------------------------------
# 4. PREMIUM CALCULATOR
# ---------------------------------------------------------------------------

class PremiumCalculator:
    """Final premium calculation, including coverage-specific rating factors."""

    def calculate_premium(self, coverage: Coverage, profile: ApplicantProfile) -> float:
        if coverage.coverage_type == CoverageType.AUTO_LIABILITY:
            base = coverage.limit * 0.015
            age_factor = 1.5 if profile.age < 25 else 1.0
            claims_factor = 1 + (profile.prior_claims * 0.1)
            return round(base * age_factor * claims_factor, 2)

        elif coverage.coverage_type == CoverageType.AUTO_COLLISION:
            vehicle_value = coverage.attributes.get("vehicle_value", 0)
            deductible_discount = max(0, 1 - (coverage.deductible / 10000))
            return round(vehicle_value * 0.03 * deductible_discount, 2)

        elif coverage.coverage_type == CoverageType.HOME_FIRE:
            dwelling_value = coverage.attributes.get("dwelling_value", 0)
            zone_factor = {"LOW": 1.0, "MEDIUM": 1.3, "HIGH": 1.8}.get(
                profile.attributes.get("fire_risk_zone", "LOW"), 1.0
            )
            return round(dwelling_value * 0.004 * zone_factor, 2)

        elif coverage.coverage_type == CoverageType.HOME_THEFT:
            property_value = coverage.attributes.get("personal_property_value", 0)
            crime_factor = {"LOW": 1.0, "MEDIUM": 1.2, "HIGH": 1.5}.get(
                profile.attributes.get("crime_rate", "LOW"), 1.0
            )
            return round(property_value * 0.01 * crime_factor, 2)

        elif coverage.coverage_type == CoverageType.LIFE_TERM:
            term_years = coverage.attributes.get("term_years", 1)
            health_factor = 2 - profile.attributes.get("health_score", 1.0)
            return round(coverage.limit * 0.001 * term_years * health_factor, 2)

        else:
            raise ValueError(f"Unsupported coverage type: {coverage.coverage_type}")


# ---------------------------------------------------------------------------
# 5. CLAIM PROCESSOR
# ---------------------------------------------------------------------------

@dataclass
class Claim:
    claim_id: str
    policy_id: str
    coverage_type: CoverageType
    amount_requested: float
    details: Dict = field(default_factory=dict)
    status: str = "SUBMITTED"
    approved_amount: float = 0.0


class ClaimProcessor:
    """Coverage-specific claim validation and payout logic."""

    def process_claim(self, claim: Claim, coverage: Coverage) -> Claim:
        if claim.coverage_type == CoverageType.AUTO_LIABILITY:
            payout = min(claim.amount_requested, coverage.limit)
            claim.approved_amount = payout
            claim.status = "APPROVED"

        elif claim.coverage_type == CoverageType.AUTO_COLLISION:
            payout = max(0, min(claim.amount_requested, coverage.limit) - coverage.deductible)
            claim.approved_amount = payout
            claim.status = "APPROVED" if payout > 0 else "DENIED"

        elif claim.coverage_type == CoverageType.HOME_FIRE:
            fire_certified = claim.details.get("fire_department_report", False)
            if not fire_certified:
                claim.status = "DENIED"
                claim.approved_amount = 0.0
            else:
                payout = max(0, min(claim.amount_requested, coverage.limit) - coverage.deductible)
                claim.approved_amount = payout
                claim.status = "APPROVED"

        elif claim.coverage_type == CoverageType.HOME_THEFT:
            police_report = claim.details.get("police_report_number")
            if not police_report:
                claim.status = "DENIED"
                claim.approved_amount = 0.0
            else:
                payout = max(0, min(claim.amount_requested, coverage.limit) - coverage.deductible)
                claim.approved_amount = payout
                claim.status = "APPROVED"

        elif claim.coverage_type == CoverageType.LIFE_TERM:
            death_certificate = claim.details.get("death_certificate", False)
            if not death_certificate:
                claim.status = "DENIED"
                claim.approved_amount = 0.0
            else:
                claim.approved_amount = coverage.limit
                claim.status = "APPROVED"

        else:
            raise ValueError(f"Unsupported coverage type: {claim.coverage_type}")

        return claim


# ---------------------------------------------------------------------------
# 6. BILLING SYSTEM
# ---------------------------------------------------------------------------

class BillingSystem:
    """Coverage-specific billing schedules and fees."""

    def generate_billing_schedule(self, coverage: Coverage, premium: float) -> List[Dict]:
        if coverage.coverage_type == CoverageType.AUTO_LIABILITY:
            installments = 12
            fee_per_installment = 2.00
        elif coverage.coverage_type == CoverageType.AUTO_COLLISION:
            installments = 12
            fee_per_installment = 2.00
        elif coverage.coverage_type == CoverageType.HOME_FIRE:
            installments = 4
            fee_per_installment = 5.00
        elif coverage.coverage_type == CoverageType.HOME_THEFT:
            installments = 4
            fee_per_installment = 5.00
        elif coverage.coverage_type == CoverageType.LIFE_TERM:
            installments = 1
            fee_per_installment = 0.00
        else:
            raise ValueError(f"Unsupported coverage type: {coverage.coverage_type}")

        installment_amount = round(premium / installments, 2)
        schedule = []
        for i in range(installments):
            schedule.append({
                "installment_number": i + 1,
                "amount": installment_amount + fee_per_installment,
                "due_date": datetime.date.today() + datetime.timedelta(days=30 * i),
            })
        return schedule


