class RenewalHandler:
    """Coverage-specific renewal adjustments."""

    def renew_coverage(self, coverage: Coverage, prior_claims_count: int) -> Coverage:
        if coverage.coverage_type == CoverageType.AUTO_LIABILITY:
            new_limit = coverage.limit
            adjustment = 1 + (0.05 * prior_claims_count)
        elif coverage.coverage_type == CoverageType.AUTO_COLLISION:
            new_limit = coverage.limit * 0.95  # depreciate vehicle value
            adjustment = 1 + (0.05 * prior_claims_count)
        elif coverage.coverage_type == CoverageType.HOME_FIRE:
            new_limit = coverage.limit * 1.02  # inflation adjustment
            adjustment = 1 + (0.03 * prior_claims_count)
        elif coverage.coverage_type == CoverageType.HOME_THEFT:
            new_limit = coverage.limit
            adjustment = 1 + (0.03 * prior_claims_count)
        elif coverage.coverage_type == CoverageType.LIFE_TERM:
            new_limit = coverage.limit
            adjustment = 1.0  # term life typically doesn't reprice on claims
        else:
            raise ValueError(f"Unsupported coverage type: {coverage.coverage_type}")

        renewed = Coverage(
            coverage_type=coverage.coverage_type,
            limit=new_limit,
            deductible=coverage.deductible,
            attributes=dict(coverage.attributes),
        )
        renewed.attributes["renewal_adjustment_factor"] = adjustment
        return renewed


