class SagaStatus(Enum):
    IN_PROGRESS = "IN_PROGRESS"
    COMPLETED = "COMPLETED"
    COMPENSATING = "COMPENSATING"
    COMPENSATED = "COMPENSATED"
    FAILED = "FAILED"


class Saga:
    """Orchestration-based saga with automatic compensation on failure."""

    def __init__(self, name: str, event_store: Optional[EventStore] = None):
        self.saga_id = new_id()
        self.name = name
        self.steps: List[SagaStep] = []
        self.status = SagaStatus.IN_PROGRESS
        self.context: Dict[str, Any] = {}
        self._event_store = event_store

    def add_step(self, name: str, action: Callable[[Dict[str, Any]], Any],
                 compensation: Optional[Callable[[Dict[str, Any]], Any]] = None) -> "Saga":
        self.steps.append(SagaStep(name=name, action=action, compensation=compensation))
        return self

    def _record(self, event_type: str, data: Any) -> None:
        if self._event_store:
            self._event_store.append(f"saga:{self.saga_id}", event_type, data)

    def execute(self, initial_context: Optional[Dict[str, Any]] = None) -> bool:
        self.context = dict(initial_context or {})
        self._record("SagaStarted", {"name": self.name})

        executed_steps: List[SagaStep] = []
        for step in self.steps:
            try:
                step.result = step.action(self.context)
                step.status = SagaStepStatus.COMPLETED
                executed_steps.append(step)
                self._record("SagaStepCompleted", {"step": step.name, "result": step.result})
            except Exception as exc:
                step.status = SagaStepStatus.FAILED
                step.error = str(exc)
                self._record("SagaStepFailed", {"step": step.name, "error": str(exc)})
                self._compensate(executed_steps)
                self.status = SagaStatus.FAILED
                self._record("SagaFailed", {"name": self.name})
                return False

        self.status = SagaStatus.COMPLETED
        self._record("SagaCompleted", {"name": self.name})
        return True

    def _compensate(self, executed_steps: List[SagaStep]) -> None:
        self.status = SagaStatus.COMPENSATING
        self._record("SagaCompensating", {"name": self.name})
        for step in reversed(executed_steps):
            if step.compensation:
                try:
                    step.compensation(self.context)
                    step.status = SagaStepStatus.COMPENSATED
                    self._record("SagaStepCompensated", {"step": step.name})
                except Exception as exc:
                    step.error = f"compensation failed: {exc}"
                    self._record("SagaCompensationFailed", {"step": step.name, "error": str(exc)})
        self.status = SagaStatus.COMPENSATED


