class MessageType(Enum):
    REQUEST = "REQUEST"
    RESPONSE = "RESPONSE"
    EVENT = "EVENT"
    COMMAND = "COMMAND"
    ERROR = "ERROR"


@dataclass
class Message:
    type: MessageType
    channel: str
    payload: Any = None
    correlation_id: str = field(default_factory=new_id)
    reply_to: Optional[str] = None
    headers: Dict[str, Any] = field(default_factory=dict)
    timestamp: float = field(default_factory=time.time)
    message_id: str = field(default_factory=new_id)

    def copy(self) -> "Message":
        return copy.deepcopy(self)


# =====================================================================
# Service registry (for synchronous request-response calls)
# =====================================================================

ServiceHandler = Callable[[Any], Any]


class ServiceRegistry:
    def __init__(self):
        self._services: Dict[str, ServiceHandler] = {}
        self._lock = threading.RLock()

    def register(self, name: str, handler: ServiceHandler) -> None:
        with self._lock:
            self._services[name] = handler

    def unregister(self, name: str) -> None:
        with self._lock:
            self._services.pop(name, None)

    def get(self, name: str) -> ServiceHandler:
        with self._lock:
            handler = self._services.get(name)
        if handler is None:
            raise ServiceNotFoundError(f"Service '{name}' not registered")
        return handler

    def has(self, name: str) -> bool:
        with self._lock:
            return name in self._services


# =====================================================================
# Pub/Sub + Queue based async messaging
# =====================================================================

Subscriber = Callable[[Message], None]


class MessageBroker:
    """Simple in-memory broker supporting pub/sub topics and point-to-point queues."""

    def __init__(self, max_workers: int = 8):
        self._subscribers: Dict[str, List[Subscriber]] = {}
        self._lock = threading.RLock()
        self._queues: Dict[str, "queue.Queue[Message]"] = {}
        self._running = True
        self._workers: List[threading.Thread] = []
        self._dispatch_queue: "queue.Queue[Message]" = queue.Queue()
        for _ in range(max_workers):
            t = threading.Thread(target=self._worker_loop, daemon=True)
            t.start()
            self._workers.append(t)

    def _worker_loop(self):
        while self._running:
            try:
                msg = self._dispatch_queue.get(timeout=0.2)
            except queue.Empty:
                continue
            self._deliver(msg)
            self._dispatch_queue.task_done()

    def subscribe(self, topic: str, handler: Subscriber) -> Callable[[], None]:
        with self._lock:
            self._subscribers.setdefault(topic, []).append(handler)

        def unsubscribe():
            with self._lock:
                if topic in self._subscribers and handler in self._subscribers[topic]:
                    self._subscribers[topic].remove(handler)

        return unsubscribe

    def publish(self, message: Message, async_dispatch: bool = True) -> None:
        if async_dispatch:
            self._dispatch_queue.put(message)
        else:
            self._deliver(message)

    def _deliver(self, message: Message) -> None:
        with self._lock:
            handlers = list(self._subscribers.get(message.channel, []))
        for handler in handlers:
            try:
                handler(message)
            except Exception as exc:  # isolate subscriber failures
                err = Message(
                    type=MessageType.ERROR,
                    channel=f"{message.channel}.errors",
                    payload={"error": str(exc), "original": message.message_id},
                )
                self._dispatch_queue.put(err)

    def get_queue(self, name: str) -> "queue.Queue[Message]":
        with self._lock:
            if name not in self._queues:
                self._queues[name] = queue.Queue()
            return self._queues[name]

    def send_to_queue(self, name: str, message: Message) -> None:
        self.get_queue(name).put(message)

    def receive_from_queue(self, name: str, timeout: Optional[float] = None) -> Optional[Message]:
        try:
            return self.get_queue(name).get(timeout=timeout)
        except queue.Empty:
            return None

    def shutdown(self) -> None:
        self._running = False
        for t in self._workers:
            t.join(timeout=1)


