@dataclass
class DistributedTransaction:
    tx_id: str
    participants: List[TransactionParticipant]
    status: TransactionStatus = TransactionStatus.STARTED


class TransactionCoordinator:
    """Implements a basic two-phase commit protocol."""

    def __init__(self):
        self._transactions: Dict[str, DistributedTransaction] = {}
        self._lock = threading.RLock()

    def begin(self, participants: List[TransactionParticipant]) -> str:
        tx_id = new_id()
        with self._lock:
            self._transactions[tx_id] = DistributedTransaction(tx_id=tx_id, participants=participants)
        return tx_id

    def execute(self, participants: List[TransactionParticipant], payload: Any) -> bool:
        """Convenience: begin + full 2PC run in one call."""
        tx_id = self.begin(participants)
        return self.run(tx_id, payload)

    def run(self, tx_id: str, payload: Any) -> bool:
        with self._lock:
            tx = self._transactions.get(tx_id)
        if tx is None:
            raise ESBError(f"Unknown transaction {tx_id}")

        # Phase 1: prepare
        votes = []
        for participant in tx.participants:
            try:
                votes.append(participant.prepare(tx_id, payload))
            except Exception:
                votes.append(False)

        if all(votes):
            tx.status = TransactionStatus.PREPARED
            # Phase 2: commit
            for participant in tx.participants:
                try:
                    participant.commit(tx_id)
                except Exception:
                    pass
            tx.status = TransactionStatus.COMMITTED
            return True
        else:
            for participant in tx.participants:
                try:
                    participant.rollback(tx_id)
                except Exception:
                    pass
            tx.status = TransactionStatus.ROLLED_BACK
            return False

    def get_status(self, tx_id: str) -> TransactionStatus:
        with self._lock:
            tx = self._transactions.get(tx_id)
        if tx is None:
            raise ESBError(f"Unknown transaction {tx_id}")
        return tx.status


class FunctionTransactionParticipant(TransactionParticipant):
    """Wraps plain callables into a TransactionParticipant for convenience."""

    def __init__(self, prepare_fn: Callable[[str, Any], bool],
                 commit_fn: Callable[[str], None],
                 rollback_fn: Callable[[str], None]):
        self._prepare_fn = prepare_fn
        self._commit_fn = commit_fn
        self._rollback_fn = rollback_fn

    def prepare(self, tx_id: str, payload: Any) -> bool:
        return self._prepare_fn(tx_id, payload)

    def commit(self, tx_id: str) -> None:
        self._commit_fn(tx_id)

    def rollback(self, tx_id: str) -> None:
        self._rollback_fn(tx_id)


# =====================================================================
# The Enterprise Service Bus facade
# =====================================================================

class EnterpriseServiceBus:
    """
    Unified facade tying together:
      - synchronous request/response service calls
      - async pub/sub and queue messaging
      - event sourcing
      - saga orchestration
      - distributed transactions (2PC)
    """

    def __init__(self, max_workers: int = 8):
        self.registry = ServiceRegistry()
        self.broker = MessageBroker(max_workers=max_workers)
        self.event_store = EventStore()
        self.tx_coordinator = TransactionCoordinator()
        self._pending_requests: Dict[str, Future] = {}
        self._lock = threading.RLock()

    # ---------------- Synchronous request-response ----------------

    def register_service(self, name: str, handler: ServiceHandler) -> None:
        self.registry.register(name, handler)

    def unregister_service(self, name: str) -> None:
        self.registry.unregister(name)

    def call(self, service_name: str, payload: Any = None, timeout: Optional[float] = 30.0) -> Any:
        """Simple synchronous request-response call."""
        handler = self.registry.get(service_name)
        result_holder: Dict[str, Any] = {}
        exc_holder: Dict[str, BaseException] = {}
        done_event = threading.Event()

        def run():
            try:
                result_holder["result"] = handler(payload)
            except BaseException as exc:  # noqa: BLE001
                exc_holder["error"] = exc
            finally:
                done_event.set()

        t = threading.Thread(target=run, daemon=True)
        t.start()
        finished = done_event.wait(timeout)
        if not finished:
            raise TimeoutErrorESB(f"Call to service '{service_name}' timed out after {timeout}s")
        if "error" in exc_holder:
            raise exc_holder["error"]
        return result_holder.get("result")

    def call_direct(self, service_name: str, payload: Any = None) -> Any:
        """Direct in-thread call without extra thread overhead, for the simple case."""
        handler = self.registry.get(service_name)
        return handler(payload)

    # ---------------- Async messaging ----------------

    def publish_event(self, channel: str, payload: Any, headers: Optional[Dict[str, Any]] = None) -> None:
        message = Message(type=MessageType.EVENT, channel=channel, payload=payload, headers=headers or {})
        self.broker.publish(message)

    def subscribe(self, channel: str, handler: Subscriber) -> Callable[[], None]:
        return self.broker.subscribe(channel, handler)

    def send_command(self, queue_name: str, payload: Any, headers: Optional[Dict[str, Any]] = None) -> None:
        message = Message(type=MessageType.COMMAND, channel=queue_name, payload=payload, headers=headers or {})
        self.broker.send_to_queue(queue_name, message)

    def receive_command(self, queue_name: str, timeout: Optional[float] = None) -> Optional[Message]:
        return self.broker.receive_from_queue(queue_name, timeout=timeout)

    def request_async(self, service_name: str, payload: Any, timeout: Optional[float] = 30.0) -> Future:
        """Async request-response using futures, backed by the sync registry."""
        future: Future = Future()

        def worker():
            try:
                result = self.call(service_name, payload, timeout=timeout)
                future.set_result(result)
            except BaseException as exc:  # noqa: BLE001
                future.set_exception(exc)

        threading.Thread(target=worker, daemon=True).start()
        return future

    # ---------------- Event sourcing ----------------

    def append_event(self, stream_id: str, event_type: str, data: Any,
                      expected_version: Optional[int] = None) -> Event:
        return self.event_store.append(stream_id, event_type, data, expected_version)

    def get_events(self, stream_id: str) -> List[Event]:
        return self.event_store.get_stream(stream_id)

    # ---------------- Saga ----------------

    def create_saga(self, name: str) -> Saga:
        return Saga(name, event_store=self.event_store)

    # ---------------- Distributed transactions ----------------

    def run_distributed_transaction(self, participants: List[TransactionParticipant], payload: Any) -> bool:
        return self.tx_coordinator.execute(participants, payload)

    def shutdown(self) -> None:
        self.broker.shutdown()


# =====================================================================
# Simple usage example (only runs when executed directly)
# =====================================================================

if __name__ == "__main__":
    esb = EnterpriseServiceBus()

    # --- Simple synchronous request-response (the common case) ---
    esb.register_service("add", lambda payload: payload["a"] + payload["b"])
    result = esb.call("add", {"a": 2, "b": 3})
    print("Sync call result:", result)

    # --- Async pub/sub ---
    def on_order_created(msg: Message):
        print("Received event:", msg.channel, msg.payload)

    esb.subscribe("orders.created", on_order_created)
    esb.publish_event("orders.created", {"order_id": "123"})
