    print("Order events:", esb.get_events("order-123"))

    # --- Saga ---
    saga = esb.create_saga("order-fulfillment")
    saga.add_step(
        "reserve_inventory",
        action=lambda ctx: ctx.update({"inventory_reserved": True}),
        compensation=lambda ctx: ctx.update({"inventory_reserved": False}),
    )
    saga.add_step(
        "charge_payment",
        action=lambda ctx: (_ for _ in ()).throw(RuntimeError("payment failed")),
        compensation=lambda ctx: None,
    )
    success = saga.execute()
    print("Saga success:", success, "status:", saga.status)

    # --- Distributed transaction ---
    def make_participant(name):
        def prepare(tx_id, payload):
            print(f"{name} preparing tx {tx_id}")
            return True

        def commit(tx_id):
            print(f"{name} committing tx {tx_id}")

