        severity_lower = severity.lower() if isinstance(severity, str) else ""
        if severity_lower not in self.VALID_SEVERITIES:
            raise ValueError(f"severity must be one of {self.VALID_SEVERITIES}")

        self._parse_date(onset_date)
        if resolution_date:
            self._parse_date(resolution_date)

        event = {
            "subject_id": subject_id,
            "event_term": event_term,
            "severity": severity_lower,
            "onset_date": onset_date,
            "resolution_date": resolution_date,
            "related_to_treatment": related_to_treatment,
            "serious": serious,
        }

        self.adverse_events[subject_id].append(event)
        return event

    def get_adverse_events(self, subject_id: str) -> List[Dict]:
        return self.adverse_events.get(subject_id, [])

    def get_serious_adverse_events(self, subject_id: Optional[str] = None) -> List[Dict]:
        results = []
        subject_ids = [subject_id] if subject_id else self.adverse_events.keys()
        for sid in subject_ids:
            for event in self.adverse_events.get(sid, []):
                if event.get("serious"):
                    results.append(event)
        return results

    # ---------------- Protocol Deviations ----------------

    def record_protocol_deviation(self, subject_id: str, deviation: Tuple[str, ...]) -> bool:
        if subject_id not in self.subjects:
            raise ValueError(f"Unknown subject_id '{subject_id}'")
        if not isinstance(deviation, tuple):
            raise ValueError("deviation must be a tuple of strings")
        for item in deviation:
            if not isinstance(item, str):
                raise ValueError("all deviation tuple elements must be strings")

        self.protocol_deviations[subject_id].append(deviation)
        return True

    def get_protocol_deviations(self, subject_id: str) -> List[Tuple[str, ...]]:
        return self.protocol_deviations.get(subject_id, [])

    def get_all_deviations(self) -> Dict[str, List[Tuple[str, ...]]]:
        return {sid: devs for sid, devs in self.protocol_deviations.items() if devs}

    # ---------------- Reporting / Summary ----------------

    def get_site_summary(self, site_id: str) -> Dict:
        if site_id not in self.sites:
            raise ValueError(f"Unknown site_id '{site_id}'")

        subject_ids = self.get_subjects_by_site(site_id)
        total_visits = sum(len(self.visits.get(sid, [])) for sid in subject_ids)
        total_aes = sum(len(self.adverse_events.get(sid, [])) for sid in subject_ids)
        total_saes = sum(
            1
            for sid in subject_ids
            for e in self.adverse_events.get(sid, [])
            if e.get("serious")
        )
        total_deviations = sum(len(self.protocol_deviations.get(sid, [])) for sid in subject_ids)

        return {
            "site_id": site_id,
            "active": self.sites[site_id]["active"],
            "subject_count": len(subject_ids),
            "total_visits": total_visits,
            "total_adverse_events": total_aes,
            "total_serious_adverse_events": total_saes,
            "total_protocol_deviations": total_deviations,
        }

    def get_subject_summary(self, subject_id: str) -> Dict:
        if subject_id not in self.subjects:
            raise ValueError(f"Unknown subject_id '{subject_id}'")

        subject = self.subjects[subject_id]
        visits = self.visits.get(subject_id, [])
        aes = self.adverse_events.get(subject_id, [])
        deviations = self.protocol_deviations.get(subject_id, [])

        return {
            "subject_id": subject_id,
            "site_id": subject["site_id"],
            "status": subject["status"],
            "visit_count": len(visits),
            "adverse_event_count": len(aes),
            "serious_adverse_event_count": sum(1 for e in aes if e.get("serious")),
            "protocol_deviation_count": len(deviations),
        }

    def get_trial_summary(self) -> Dict:
        total_subjects = len(self.subjects)
        active_subjects = sum(1 for s in self.subjects.values() if s["status"] == "enrolled")
        withdrawn_subjects = sum(1 for s in self.subjects.values() if s["status"] == "withdrawn")
        total_sites = len(self.sites)
        active_sites = sum(1 for s in self.sites.values() if s["active"])

        total_visits = sum(len(v) for v in self.visits.values())
        total_aes = sum(len(v) for v in self.adverse_events.values())
        total_saes = sum(
            1 for events in self.adverse_events.values() for e in events if e.get("serious")
        )
        total_deviations = sum(len(v) for v in self.protocol_deviations.values())

        return {
            "total_subjects": total_subjects,
            "active_subjects": active_subjects,
            "withdrawn_subjects": withdrawn_subjects,
            "total_sites": total_sites,
            "active_sites": active_sites,
            "total_visits": total_visits,
            "total_adverse_events": total_aes,
            "total_serious_adverse_events": total_saes,
            "total_protocol_deviations": total_deviations,
        }
