class RiskAssessor:
    def __init__(self):
        self.risk_weights = {
            "income": 0.20,
            "employment": 0.15,
            "credit_history": 0.25,
            "assets": 0.10,
            "debts": 0.15,
            "loan_terms": 0.10,
            "market": 0.05,
        }

    def assess_loan_risk(self, applicant, loan, market):
        income_score = self._score_income(applicant.income, loan.amount)
        employment_score = self._score_employment(applicant.employment)
        credit_score = self._score_credit_history(applicant.credit_history)
        assets_score = self._score_assets(applicant.assets, loan.amount)
        debts_score = self._score_debts(applicant.debts, applicant.income)
        loan_terms_score = self._score_loan_terms(loan.amount, loan.term, applicant.income)
        market_score = self._score_market(market.rates, market.conditions)

        composite_score = (
            income_score * self.risk_weights["income"]
            + employment_score * self.risk_weights["employment"]
            + credit_score * self.risk_weights["credit_history"]
            + assets_score * self.risk_weights["assets"]
            + debts_score * self.risk_weights["debts"]
            + loan_terms_score * self.risk_weights["loan_terms"]
            + market_score * self.risk_weights["market"]
        )

        risk_level, approval_recommendation = self._determine_risk_level(composite_score)

        return {
            "composite_score": round(composite_score, 2),
            "risk_level": risk_level,
            "approval_recommendation": approval_recommendation,
            "component_scores": {
                "income": round(income_score, 2),
                "employment": round(employment_score, 2),
                "credit_history": round(credit_score, 2),
                "assets": round(assets_score, 2),
                "debts": round(debts_score, 2),
                "loan_terms": round(loan_terms_score, 2),
                "market": round(market_score, 2),
            },
        }

    def _score_income(self, income, loan_amount):
        if income <= 0:
            return 0.0

        loan_to_income_ratio = loan_amount / income

        if loan_to_income_ratio <= 1.0:
            return 100.0
        elif loan_to_income_ratio <= 2.0:
            return 85.0
        elif loan_to_income_ratio <= 3.0:
            return 65.0
        elif loan_to_income_ratio <= 4.0:
            return 45.0
        elif loan_to_income_ratio <= 5.0:
            return 25.0
        else:
            return 10.0

    def _score_employment(self, employment):
        status = getattr(employment, "status", "unemployed")
        years = getattr(employment, "years", 0)

        status_scores = {
            "employed": 90.0,
            "self_employed": 70.0,
            "retired": 75.0,
            "unemployed": 20.0,
            "contract": 60.0,
        }

        base_score = status_scores.get(status, 30.0)

        if years >= 10:
            stability_bonus = 10.0
        elif years >= 5:
            stability_bonus = 7.0
        elif years >= 2:
            stability_bonus = 4.0
        elif years >= 1:
            stability_bonus = 1.0
        else:
            stability_bonus = -5.0

        final_score = base_score + stability_bonus
        return max(0.0, min(100.0, final_score))

    def _score_credit_history(self, credit_history):
        credit_score = getattr(credit_history, "score", 0)
        late_payments = getattr(credit_history, "late_payments", 0)
        defaults = getattr(credit_history, "defaults", 0)
        bankruptcies = getattr(credit_history, "bankruptcies", 0)

        if credit_score >= 750:
            base_score = 95.0
        elif credit_score >= 700:
            base_score = 85.0
        elif credit_score >= 650:
            base_score = 70.0
        elif credit_score >= 600:
            base_score = 50.0
        elif credit_score >= 550:
            base_score = 30.0
        else:
            base_score = 10.0

        penalty = (late_payments * 2) + (defaults * 15) + (bankruptcies * 25)
        final_score = base_score - penalty

        return max(0.0, min(100.0, final_score))

    def _score_assets(self, assets, loan_amount):
        total_assets = getattr(assets, "total_value", 0)

        if loan_amount <= 0:
            return 100.0

        asset_to_loan_ratio = total_assets / loan_amount

        if asset_to_loan_ratio >= 2.0:
            return 100.0
        elif asset_to_loan_ratio >= 1.5:
            return 90.0
        elif asset_to_loan_ratio >= 1.0:
            return 75.0
        elif asset_to_loan_ratio >= 0.5:
            return 55.0
        elif asset_to_loan_ratio >= 0.25:
            return 35.0
        else:
            return 15.0

    def _score_debts(self, debts, income):
        total_debts = getattr(debts, "total_amount", 0)

        if income <= 0:
            return 0.0

        debt_to_income_ratio = total_debts / income

        if debt_to_income_ratio <= 0.1:
            return 100.0
        elif debt_to_income_ratio <= 0.2:
            return 85.0
        elif debt_to_income_ratio <= 0.35:
            return 65.0
        elif debt_to_income_ratio <= 0.5:
            return 40.0
        elif debt_to_income_ratio <= 0.7:
            return 20.0
        else:
            return 5.0

    def _score_loan_terms(self, loan_amount, loan_term, income):
        if income <= 0 or loan_term <= 0:
            return 0.0

        monthly_income = income / 12
        estimated_monthly_payment = loan_amount / loan_term
        payment_to_income_ratio = estimated_monthly_payment / monthly_income

        if payment_to_income_ratio <= 0.15:
            term_score = 100.0
        elif payment_to_income_ratio <= 0.25:
            term_score = 85.0
        elif payment_to_income_ratio <= 0.35:
            term_score = 65.0
        elif payment_to_income_ratio <= 0.45:
            term_score = 45.0
        else:
            term_score = 20.0

        if loan_term <= 36:
            term_length_adjustment = 5.0
        elif loan_term <= 60:
            term_length_adjustment = 2.0
        elif loan_term <= 120:
            term_length_adjustment = 0.0
        elif loan_term <= 240:
            term_length_adjustment = -3.0
        else:
            term_length_adjustment = -6.0

        final_score = term_score + term_length_adjustment
        return max(0.0, min(100.0, final_score))

    def _score_market(self, rates, conditions):
        base_rate = getattr(rates, "base_rate", 5.0)

        if base_rate <= 2.0:
            rate_score = 90.0
        elif base_rate <= 4.0:
            rate_score = 75.0
        elif base_rate <= 6.0:
            rate_score = 55.0
        elif base_rate <= 8.0:
            rate_score = 35.0
        else:
            rate_score = 15.0

        condition_status = getattr(conditions, "status", "stable")
        condition_scores = {
            "booming": 90.0,
            "growing": 80.0,
            "stable": 65.0,
            "declining": 35.0,
            "recession": 15.0,
        }
        condition_score = condition_scores.get(condition_status, 50.0)

        final_score = (rate_score * 0.5) + (condition_score * 0.5)
        return max(0.0, min(100.0, final_score))

    def _determine_risk_level(self, composite_score):
        if composite_score >= 80:
            return "Low Risk", "Approve"
        elif composite_score >= 65:
