from typing import Any, Dict, List, Optional

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger("etl_pipeline")


class ETLError(Exception):
    pass


class SchemaValidationError(ETLError):
    pass


class DataValidationError(ETLError):
    pass


class TransformError(ETLError):
    pass


class ETLPipeline:
    def __init__(self, sources_config: List[Dict[str, Any]]):
        self.sources_config = sources_config
        self.stats = {
            "sources_processed": 0,
            "sources_failed": 0,
            "tables_processed": 0,
            "tables_failed": 0,
            "partitions_processed": 0,
            "partitions_failed": 0,
            "records_processed": 0,
            "records_succeeded": 0,
            "records_failed": 0,
            "records_skipped": 0,
        }
        self.errors: List[Dict[str, Any]] = []
        self.output: List[Dict[str, Any]] = []

    def run(self) -> Dict[str, Any]:
        if not self.sources_config:
            logger.warning("No sources configured. Nothing to do.")
            return self._build_result()

        for source in self.sources_config:
            source_name = source.get("name", "UNKNOWN_SOURCE")

            if not source.get("enabled", True):
                logger.info(f"Source '{source_name}' is disabled. Skipping.")
                continue

            tables = source.get("tables")
            if not tables:
                logger.warning(f"Source '{source_name}' has no tables defined. Skipping.")
                self.stats["sources_failed"] += 1
                continue

            try:
                self._process_source(source)
                self.stats["sources_processed"] += 1
            except ETLError as e:
                logger.error(f"Source '{source_name}' failed entirely: {e}")
                self.stats["sources_failed"] += 1
                self.errors.append({
                    "level": "source",
                    "source": source_name,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })
            except Exception as e:
                logger.exception(f"Unexpected error processing source '{source_name}'")
                self.stats["sources_failed"] += 1
                self.errors.append({
                    "level": "source",
                    "source": source_name,
                    "error": f"Unexpected: {e}",
                    "timestamp": datetime.utcnow().isoformat(),
                })

        return self._build_result()

    def _process_source(self, source: Dict[str, Any]) -> None:
        source_name = source.get("name", "UNKNOWN_SOURCE")
        tables = source.get("tables", [])

        for table in tables:
            table_name = table.get("name", "UNKNOWN_TABLE")

            if not table.get("enabled", True):
                logger.info(f"Table '{source_name}.{table_name}' is disabled. Skipping.")
                continue

            partitions = table.get("partitions")
            if not partitions:
                logger.warning(f"Table '{source_name}.{table_name}' has no partitions. Skipping.")
                self.stats["tables_failed"] += 1
                continue

            schema = table.get("schema")
            if not schema:
                logger.warning(f"Table '{source_name}.{table_name}' has no schema defined. Skipping.")
                self.stats["tables_failed"] += 1
                continue

            try:
                self._process_table(source_name, table)
                self.stats["tables_processed"] += 1
            except ETLError as e:
                logger.error(f"Table '{source_name}.{table_name}' failed: {e}")
                self.stats["tables_failed"] += 1
                self.errors.append({
                    "level": "table",
                    "source": source_name,
                    "table": table_name,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })
            except Exception as e:
                logger.exception(f"Unexpected error processing table '{source_name}.{table_name}'")
                self.stats["tables_failed"] += 1
                self.errors.append({
                    "level": "table",
                    "source": source_name,
                    "table": table_name,
                    "error": f"Unexpected: {e}",
                    "timestamp": datetime.utcnow().isoformat(),
                })

    def _process_table(self, source_name: str, table: Dict[str, Any]) -> None:
        table_name = table.get("name", "UNKNOWN_TABLE")
        schema = table.get("schema", {})
        partitions = table.get("partitions", [])

        for partition in partitions:
            partition_id = partition.get("id", "UNKNOWN_PARTITION")

            if not partition.get("enabled", True):
                logger.info(
                    f"Partition '{source_name}.{table_name}.{partition_id}' is disabled. Skipping."
                )
                continue

            records = partition.get("records")
            if records is None:
                logger.warning(
                    f"Partition '{source_name}.{table_name}.{partition_id}' has no records. Skipping."
                )
                self.stats["partitions_failed"] += 1
                continue

            if not isinstance(records, list):
                logger.warning(
                    f"Partition '{source_name}.{table_name}.{partition_id}' records is not a list. Skipping."
                )
                self.stats["partitions_failed"] += 1
                continue

            try:
                self._process_partition(source_name, table_name, schema, partition)
                self.stats["partitions_processed"] += 1
            except ETLError as e:
                logger.error(
                    f"Partition '{source_name}.{table_name}.{partition_id}' failed: {e}"
                )
                self.stats["partitions_failed"] += 1
                self.errors.append({
                    "level": "partition",
                    "source": source_name,
                    "table": table_name,
                    "partition": partition_id,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })
            except Exception as e:
                logger.exception(
                    f"Unexpected error in partition '{source_name}.{table_name}.{partition_id}'"
                )
                self.stats["partitions_failed"] += 1
                self.errors.append({
                    "level": "partition",
                    "source": source_name,
                    "table": table_name,
                    "partition": partition_id,
                    "error": f"Unexpected: {e}",
                    "timestamp": datetime.utcnow().isoformat(),
                })

    def _process_partition(
        self,
        source_name: str,
        table_name: str,
        schema: Dict[str, Any],
        partition: Dict[str, Any],
    ) -> None:
        partition_id = partition.get("id", "UNKNOWN_PARTITION")
        records = partition.get("records", [])
        transforms = partition.get("transforms", [])

        for index, record in enumerate(records):
            self.stats["records_processed"] += 1
            record_ref = f"{source_name}.{table_name}.{partition_id}[{index}]"

            if record is None:
                logger.warning(f"Record {record_ref} is None. Skipping.")
                self.stats["records_skipped"] += 1
                continue

            if not isinstance(record, dict):
                logger.warning(f"Record {record_ref} is not a dict. Skipping.")
                self.stats["records_skipped"] += 1
                continue

            try:
                # Schema check
                self._validate_schema(record, schema, record_ref)

                # Data validation
                self._validate_data(record, schema, record_ref)

                # Apply transforms
                transformed_record = self._apply_transforms(record, transforms, record_ref)

                self.output.append(transformed_record)
                self.stats["records_succeeded"] += 1

            except SchemaValidationError as e:
                logger.warning(f"Schema validation failed for {record_ref}: {e}")
                self.stats["records_failed"] += 1
                self.errors.append({
                    "level": "record",
                    "type": "schema",
                    "record_ref": record_ref,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })
            except DataValidationError as e:
                logger.warning(f"Data validation failed for {record_ref}: {e}")
                self.stats["records_failed"] += 1
                self.errors.append({
                    "level": "record",
                    "type": "data",
                    "record_ref": record_ref,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })
            except TransformError as e:
                logger.warning(f"Transform failed for {record_ref}: {e}")
                self.stats["records_failed"] += 1
                self.errors.append({
                    "level": "record",
                    "type": "transform",
                    "record_ref": record_ref,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })
            except Exception as e:
                logger.exception(f"Unexpected error processing record {record_ref}")
                self.stats["records_failed"] += 1
                self.errors.append({
                    "level": "record",
                    "type": "unexpected",
                    "record_ref": record_ref,
                    "error": str(e),
                    "timestamp": datetime.utcnow().isoformat(),
                })

    def _validate_schema(
        self, record: Dict[str, Any], schema: Dict[str, Any], record_ref: str
    ) -> None:
        fields = schema.get("fields", {})
        if not fields:
            raise SchemaValidationError(f"Schema for {record_ref} has no fields defined")

        for field_name, field_spec in fields.items():
            required = field_spec.get("required", False)
            expected_type = field_spec.get("type")

            if field_name not in record:
                if required:
                    raise SchemaValidationError(
                        f"Missing required field '{field_name}' in {record_ref}"
                    )
                else:
                    continue

            value = record[field_name]

            if value is None:
                if required:
                    raise SchemaValidationError(
                        f"Required field '{field_name}' is None in {record_ref}"
                    )
                else:
                    continue

            if expected_type:
                if expected_type == "string" and not isinstance(value, str):
                    raise SchemaValidationError(
                        f"Field '{field_name}' expected string in {record_ref}, got {type(value).__name__}"
                    )
                elif expected_type == "int" and not isinstance(value, int):
                    raise SchemaValidationError(
                        f"Field '{field_name}' expected int in {record_ref}, got {type(value).__name__}"
                    )
                elif expected_type == "float" and not isinstance(value, (int, float)):
                    raise SchemaValidationError(
                        f"Field '{field_name}' expected float in {record_ref}, got {type(value).__name__}"
                    )
                elif expected_type == "bool" and not isinstance(value, bool):
                    raise SchemaValidationError(
                        f"Field '{field_name}' expected bool in {record_ref}, got {type(value).__name__}"
                    )
                elif expected_type == "list" and not isinstance(value, list):
                    raise SchemaValidationError(
                        f"Field '{field_name}' expected list in {record_ref}, got {type(value).__name__}"
                    )
                elif expected_type == "dict" and not isinstance(value, dict):
                    raise SchemaValidationError(
                        f"Field '{field_name}' expected dict in {record_ref}, got {type(value).__name__}"
                    )

        extra_fields = set(record.keys()) - set(fields.keys())
        if extra_fields and schema.get("strict", False):
            raise SchemaValidationError(
                f"Unexpected extra fields {extra_fields} in {record_ref} (strict schema)"
            )

    def _validate_data(
        self, record: Dict[str, Any], schema: Dict[str, Any], record_ref: str
    ) -> None:
        fields = schema.get("fields", {})

        for field_name, field_spec in fields.items():
            if field_name not in record:
                continue

            value = record[field_name]
            if value is None:
                continue

            min_value = field_spec.get("min")
            if min_value is not None:
                if isinstance(value, (int, float)) and value < min_value:
                    raise DataValidationError(
                        f"Field '{field_name}' value {value} below minimum {min_value} in {record_ref}"
                    )

            max_value = field_spec.get("max")
            if max_value is not None:
                if isinstance(value, (int, float)) and value > max_value:
                    raise DataValidationError(
                        f"Field '{field_name}' value {value} exceeds maximum {max_value} in {record_ref}"
                    )

            min_length = field_spec.get("min_length")
            if min_length is not None:
                if isinstance(value, (str, list)) and len(value) < min_length:
                    raise DataValidationError(
                        f"Field '{field_name}' length {len(value)} below minimum {min_length} in {record_ref}"
                    )

            allowed_values = field_spec.get("allowed_values")
            if allowed_values is not None:
                if value not in allowed_values:
                    raise DataValidationError(
                        f"Field '{field_name}' value '{value}' not in allowed values {allowed_values} in {record_ref}"
                    )

            pattern = field_spec.get("pattern")
            if pattern is not None and isinstance(value, str):
                import re
                if not re.match(pattern, value):
                    raise DataValidationError(
                        f"Field '{field_name}' value '{value}' does not match pattern '{pattern}' in {record_ref}"
                    )

        custom_rules = schema.get("custom_rules", [])
        for rule in custom_rules:
            rule_name = rule.get("name", "unnamed_rule")
            rule_fn = rule.get("fn")
            if rule_fn is not None and callable(rule_fn):
                try:
                    if not rule_fn(record):
                        raise DataValidationError(
                            f"Custom rule '{rule_name}' failed for {record_ref}"
                        )
                except DataValidationError:
                    raise
                except Exception as e:
                    raise DataValidationError(
                        f"Custom rule '{rule_name}' raised an error for {record_ref}: {e}"
                    )

    def _apply_transforms(
        self,
        record: Dict[str, Any],
        transforms: List[Dict[str, Any]],
        record_ref: str,
    ) -> Dict[str, Any]:
        result = copy.deepcopy(record)

        if not transforms:
            return result

        for transform in transforms:
            transform_type = transform.get("type")
            field_name = transform.get("field")

            if transform_type is None:
                continue

            if field_name is not None and field_name not in result:
                continue

            try:
                if transform_type == "uppercase":
                    if field_name and isinstance(result.get(field_name), str):
                        result[field_name] = result[field_name].upper()

                elif transform_type == "lowercase":
                    if field_name and isinstance(result.get(field_name), str):
                        result[field_name] = result[field_name].lower()

                elif transform_type == "trim":
                    if field_name and isinstance(result.get(field_name), str):
                        result[field_name] = result[field_name].strip()

                elif transform_type == "rename":
                    new_name = transform.get("new_name")
                    if new_name and field_name and field_name in result:
                        result[new_name] = result.pop(field_name)

                elif transform_type == "default":
                    default_value = transform.get("value")
                    if field_name and (
                        field_name not in result or result[field_name] is None
                    ):
                        result[field_name] = default_value

                elif transform_type == "cast":
                    target_type = transform.get("target_type")
                    if field_name and field_name in result and result[field_name] is not None:
                        result[field_name] = self._cast_value(
                            result[field_name], target_type, record_ref, field_name
                        )

                elif transform_type == "multiply":
                    factor = transform.get("factor", 1)
                    if field_name and isinstance(result.get(field_name), (int, float)):
                        result[field_name] = result[field_name] * factor

                elif transform_type == "concat":
                    target_field = transform.get("target_field")
                    source_fields = transform.get("source_fields", [])
                    separator = transform.get("separator", " ")
                    if target_field and source_fields:
                        parts = []
                        for sf in source_fields:
                            if sf in result and result[sf] is not None:
                                parts.append(str(result[sf]))
                        result[target_field] = separator.join(parts)

                elif transform_type == "custom":
                    fn = transform.get("fn")
                    if fn is not None and callable(fn):
                        result = fn(result)
                        if not isinstance(result, dict):
                            raise TransformError(
                                f"Custom transform did not return a dict for {record_ref}"
                            )

                else:
                    logger.debug(
                        f"Unknown transform type '{transform_type}' for {record_ref}. Skipping."
                    )

            except TransformError:
                raise
            except Exception as e:
                raise TransformError(
                    f"Transform '{transform_type}' failed on field '{field_name}' "
                    f"for {record_ref}: {e}"
                )

        return result

    def _cast_value(
        self, value: Any, target_type: Optional[str], record_ref: str, field_name: str
    ) -> Any:
        if target_type is None:
            return value

        try:
            if target_type == "int":
                return int(value)
            elif target_type == "float":
                return float(value)
            elif target_type == "str":
                return str(value)
            elif target_type == "bool":
                if isinstance(value, str):
                    return value.strip().lower() in ("true", "1", "yes")
                return bool(value)
            else:
                logger.debug(
                    f"Unknown cast target type '{target_type}' for field '{field_name}' "
                    f"in {record_ref}. Returning original value."
                )
                return value
        except (ValueError, TypeError) as e:
            raise TransformError(
                f"Failed to cast field '{field_name}' to '{target_type}' in {record_ref}: {e}"
            )

    def _build_result(self) -> Dict[str, Any]:
        return {
            "stats": self.stats,
            "errors": self.errors,
            "output": self.output,
        }


def run_etl_pipeline(sources_config: List[Dict[str, Any]]) -> Dict[str, Any]:
    pipeline = ETLPipeline(sources_config)
