            order = self.orders.get(order_id)
            if order and order.is_active():
                order.status = OrderStatus.CANCELLED
                order.updated_at = datetime.utcnow()
                if order in self._order_book[order.symbol]:
                    self._order_book[order.symbol].remove(order)
                return True
            return False

    def _on_price_update(self, symbol: str, price: float):
        with self._lock:
            for order in list(self._order_book.get(symbol, [])):
                if order.is_active():
                    self._try_execute(order)

    def _try_execute(self, order: Order):
        price = self.market_data.get_price(order.symbol)
        if price is None:
            return

        should_fill = False
        fill_price = price

        if order.order_type == OrderType.MARKET:
            should_fill = True
            fill_price = price
        elif order.order_type == OrderType.LIMIT:
            if order.side == OrderSide.BUY and price <= order.price:
                should_fill = True
                fill_price = order.price
            elif order.side == OrderSide.SELL and price >= order.price:
                should_fill = True
                fill_price = order.price
        elif order.order_type == OrderType.STOP:
            if order.side == OrderSide.BUY and price >= order.stop_price:
                should_fill = True
                fill_price = price
            elif order.side == OrderSide.SELL and price <= order.stop_price:
                should_fill = True
                fill_price = price

        if should_fill:
            self._execute_fill(order, order.remaining_quantity, fill_price)

    def _execute_fill(self, order: Order, quantity: float, price: float):
        if quantity <= 0:
            return

        fill = Fill(order_id=order.order_id, symbol=order.symbol, side=order.side,
                    quantity=quantity, price=price)
        self.fills.append(fill)

        total_prior_value = order.avg_fill_price * order.filled_quantity
        order.filled_quantity += quantity
        order.avg_fill_price = (total_prior_value + price * quantity) / order.filled_quantity

        if order.filled_quantity >= order.quantity - 1e-9:
            order.status = OrderStatus.FILLED
            if order in self._order_book[order.symbol]:
                self._order_book[order.symbol].remove(order)
        else:
            order.status = OrderStatus.PARTIALLY_FILLED

        order.updated_at = datetime.utcnow()

        position = self.positions.setdefault(order.symbol, Position(symbol=order.symbol))
        position.update_on_fill(order.side, quantity, price)

    def get_position(self, symbol: str) -> Position:
        with self._lock:
            return self.positions.get(symbol, Position(symbol=symbol))

    def get_open_orders(self, symbol: Optional[str] = None) -> List[Order]:
        with self._lock:
            if symbol:
                return [o for o in self._order_book.get(symbol, []) if o.is_active()]
            return [o for o in self.orders.values() if o.is_active()]


