class SmaCrossoverBacktestStrategy(BacktestStrategyBase):
    """Simple unused SMA crossover strategy for the backtesting framework."""

    def __init__(self, fast_period: int = 10, slow_period: int = 30, trade_size: float = 10):
        super().__init__("SmaCrossoverBacktestStrategy")
        self.fast_period = fast_period
        self.slow_period = slow_period
        self.trade_size = trade_size
        self._position_open = False

    @staticmethod
    def _sma(bars: List[HistoricalBar], period: int) -> Optional[float]:
        if len(bars) < period:
            return None
        closes = [b.close for b in bars[-period:]]
        return sum(closes) / period

    def on_bar(self, bar: HistoricalBar, broker: BacktestBroker, history: List[HistoricalBar]):
        fast = self._sma(history, self.fast_period)
        slow = self._sma(history, self.slow_period)
        if fast is None or slow is None:
            return

        if fast > slow and not self._position_open:
            broker.execute(bar.symbol, OrderSide.BUY, self.trade_size, bar.close, bar.timestamp)
            self._position_open = True
        elif fast < slow and self._position_open:
            broker.execute(bar.symbol, OrderSide.SELL, self.trade_size, bar.close, bar.timestamp)
            self._position_open = False


class BacktestEngine:
    """
    Extensive but unused backtesting harness. Runs a strategy against
    a BacktestDataSource using a BacktestBroker, tracking an equity curve.
    """

    def __init__(self, data_source: BacktestDataSource, broker: BacktestBroker,
                 strategy: BacktestStrategyBase):
        self.data_source = data_source
        self.broker = broker
        self.strategy = strategy

    def run(self, symbol: str) -> Dict[str, float]:
        bars = self.data_source.get_bars(symbol)
        history: List[HistoricalBar] = []
        for bar in bars:
            history.append(bar)
            self.strategy.on_bar(bar, self.broker, history)
            self.broker.mark_to_market({symbol: bar.close}, bar.timestamp)
        return self.performance_report()

    def performance_report(self) -> Dict[str, float]:
        if not self.broker.equity_curve:
            return {}
        equities = [e for _, e in self.broker.equity_curve]
        returns = [
            (equities[i] - equities[i - 1]) / equities[i - 1]
            for i in range(1, len(equities)) if equities[i - 1] != 0
        ]
        total_return = (equities[-1] - self.broker.starting_cash) / self.broker.starting_cash
        volatility = statistics.pstdev(returns) if len(returns) > 1 else 0.0
        sharpe = (statistics.mean(returns) / volatility) if volatility > 0 else 0.0
        max_drawdown = self._max_drawdown(equities)
        return {
            "final_equity": equities[-1],
            "total_return": total_return,
            "volatility": volatility,
            "sharpe_ratio": sharpe,
            "max_drawdown": max_drawdown,
            "num_trades": len(self.broker.trade_log),
        }

    @staticmethod
    def _max_drawdown(equities: List[float]) -> float:
        peak = equities[0]
        max_dd = 0.0
        for e in equities:
            peak = max(peak, e)
            dd = (peak - e) / peak if peak else 0.0
            max_dd = max(max_dd, dd)
        return max_dd


class WalkForwardOptimizer:
    """Unused walk-forward parameter optimizer for backtests."""

    def __init__(self, data_source: BacktestDataSource):
        self.data_source = data_source

    def optimize(self, symbol: str, fast_range: range, slow_range: range) -> Dict:
        best_result = None
        best_params = None
        for fast in fast_range:
            for slow in slow_range:
                if fast >= slow:
                    continue
                broker = BacktestBroker()
                strategy = SmaCrossoverBacktestStrategy(fast_period=fast, slow_period=slow)
                engine = BacktestEngine(self.data_source, broker, strategy)
                result = engine.run(symbol)
                if not result:
                    continue
                if best_result is None or result["sharpe_ratio"] > best_result["sharpe_ratio"]:
                    best_result = result
                    best_params = (fast, slow)
        return {"best_params": best_params, "result": best_result}


class MonteCarloSimulator:
    """Unused Monte Carlo resampling of backtest trade returns."""

    def __init__(self, trade_returns: List[float]):
        self.trade_returns = trade_returns

    def simulate(self, num_simulations: int = 1000, num_trades: Optional[int] = None) -> Dict[str, float]:
        if not self.trade_returns:
            return {}
        num_trades = num_trades or len(self.trade_returns)
        final_returns = []
        rng = random.Random(42)
        for _ in range(num_simulations):
            sample = [rng.choice(self.trade_returns) for _ in range(num_trades)]
            cumulative = 1.0
            for r in sample:
                cumulative *= (1 + r)
            final_returns.append(cumulative - 1)
        return {
            "mean": statistics.mean(final_returns),
            "median": statistics.median(final_returns),
            "stdev": statistics.pstdev(final_returns) if len(final_returns) > 1 else 0.0,
            "worst": min(final_returns),
            "best": max(final_returns),
        }


