class Position:
    symbol: str
    quantity: float = 0.0
    avg_price: float = 0.0
    realized_pnl: float = 0.0

    def update_on_fill(self, side: OrderSide, qty: float, price: float):
        signed_qty = qty if side == OrderSide.BUY else -qty
        new_quantity = self.quantity + signed_qty

        # Closing or reducing position -> realize pnl
        if self.quantity != 0 and (self.quantity > 0) != (new_quantity > 0) or \
           (self.quantity != 0 and abs(new_quantity) < abs(self.quantity)):
            closed_qty = min(abs(signed_qty), abs(self.quantity))
            direction = 1 if self.quantity > 0 else -1
            self.realized_pnl += direction * closed_qty * (price - self.avg_price)

        if new_quantity == 0:
            self.avg_price = 0.0
        elif self.quantity == 0 or (self.quantity > 0) == (signed_qty > 0):
            total_cost = self.avg_price * abs(self.quantity) + price * abs(signed_qty)
            self.avg_price = total_cost / (abs(self.quantity) + abs(signed_qty)) if (abs(self.quantity) + abs(signed_qty)) else price
        # else: reducing/flipping position keeps existing avg_price unless flipped
        if (self.quantity >= 0 and new_quantity < 0) or (self.quantity <= 0 and new_quantity > 0):
            self.avg_price = price

        self.quantity = new_quantity


