    """
    Active order execution engine: accepts orders, matches them against
    a live market data feed, and manages fills/positions in real time.
    """

    def __init__(self, market_data: MarketDataFeed):
        self.market_data = market_data
        self.orders: Dict[str, Order] = {}
        self.fills: List[Fill] = []
