    def load_lines(self, csv_lines: List[str]):
        self.csv_lines = csv_lines

    def parse(self) -> List[Dict[str, str]]:
        if not self.csv_lines:
            return []
        header = self.csv_lines[0].split(",")
        rows = []
        for line in self.csv_lines[1:]:
            values = line.split(",")
            row = dict(zip(header, values))
            rows.append(row)
        self.parsed_rows = rows
        return rows

    def to_bars(self, symbol: str) -> List[HistoricalBar]:
        bars = []
        for row in self.parsed_rows:
            try:
                bars.append(HistoricalBar(
                    timestamp=datetime.fromisoformat(row["timestamp"]),
                    symbol=symbol,
                    open=float(row["open"]),
                    high=float(row["high"]),
                    low=float(row["low"]),
                    close=float(row["close"]),
                    volume=float(row["volume"]),
                ))
            except (KeyError, ValueError):
                continue
        return bars


