        raise OrganizationValidationError(f"Organization '{org_id}' has no associated tenant_id.")

    if not users:
        raise ProvisioningError("No users provided for provisioning.")

    if len(users) > max_users_per_org:
        raise ProvisioningError(
            f"Batch size {len(users)} exceeds max_users_per_org limit of {max_users_per_org}."
        )

    seat_limit = org_record.get("seat_limit")
    current_seat_count = org_record.get("current_seat_count", 0)
    if seat_limit is not None:
        projected_total = current_seat_count + len(users)
        if projected_total > seat_limit:
            raise OrganizationValidationError(
                f"Provisioning {len(users)} users would exceed seat limit "
                f"({projected_total}/{seat_limit}) for organization '{org_id}'."
