                if not created_account or "id" not in created_account:
                    raise AccountCreationError(
                        f"Account creation returned invalid result for '{email}'."
                    )
                user_id = created_account["id"]
            except Exception as exc:
                raise AccountCreationError(f"Failed to create account for '{email}': {exc}") from exc

            _audit("account_created", {"email": email, "user_id": user_id})

            # ---------- Step 3: Assign role ----------
            try:
                db_client.assign_role(user_id, role)
            except Exception as exc:
                raise RoleAssignmentError(
                    f"Failed to assign role '{role}' to user '{user_id}': {exc}"
                ) from exc

            _audit("role_assigned", {"email": email, "user_id": user_id, "role": role})

            # ---------- Step 4: Configure permissions ----------
            try:
                base_permissions = set(DEFAULT_PERMISSIONS_BY_ROLE.get(role, set()))
                final_permissions = base_permissions.union(permission_overrides)
                db_client.set_permissions(user_id, sorted(final_permissions))
            except Exception as exc:
                raise PermissionConfigError(
                    f"Failed to configure permissions for user '{user_id}': {exc}"
                ) from exc

            _audit(
                "permissions_configured",
                {
                    "email": email,
                    "user_id": user_id,
                    "permissions": sorted(final_permissions),
                },
            )

            # ---------- Step 5: Initialize workspace ----------
            try:
                workspace = db_client.create_workspace(tenant_id, user_id)
                if not workspace or "id" not in workspace:
                    raise WorkspaceInitError(
                        f"Workspace creation returned invalid result for user '{user_id}'."
                    )
                workspace_id = workspace["id"]
            except Exception as exc:
                raise WorkspaceInitError(
                    f"Failed to initialize workspace for user '{user_id}': {exc}"
                ) from exc

            _audit(
                "workspace_initialized",
                {"email": email, "user_id": user_id, "workspace_id": workspace_id},
            )

            # ---------- Step 6: Send invitation ----------
            try:
                sent = email_client.send_invitation(
                    email, full_name, org_record.get("name", ""), workspace_id
                )
                if not sent:
                    raise InvitationError(f"Email client reported failure sending to '{email}'.")
            except Exception as exc:
                raise InvitationError(f"Failed to send invitation to '{email}': {exc}") from exc

            _audit(
                "invitation_sent",
                {"email": email, "user_id": user_id, "workspace_id": workspace_id},
            )

