            failed.append(
                {
                    "user": email,
                    "stage": exc.__class__.__name__,
                    "error": str(exc),
                    "user_id": user_id,
                }
            )
            _audit(
                "user_provisioning_failed",
                {
                    "email": email,
                    "user_id": user_id,
                    "error": str(exc),
                    "stage": exc.__class__.__name__,
                },
                "error",
            )
        except Exception as exc:
            failed.append(
                {
                    "user": email,
                    "stage": "unexpected_error",
                    "error": str(exc),
                    "user_id": user_id,
                }
            )
            _audit(
                "user_provisioning_failed",
                {
                    "email": email,
                    "user_id": user_id,
                    "error": str(exc),
                    "stage": "unexpected_error",
                },
                "error",
            )

    _audit(
        "batch_provisioning_completed",
        {
            "requested": len(users),
            "succeeded": len(provisioned),
            "failed": len(failed),
        },
    )

    return {
        "organization_id": org_id,
        "provisioned": provisioned,
        "failed": failed,
        "audit_trail": audit_trail,
    }
