# ---------------------------------------------------------------------------

class FulfillmentHandler(ABC):
    def __init__(self):
        self.fulfillment_log: List[str] = []

    @abstractmethod
    def fulfill(self, items: List[OrderItem]) -> bool:
        ...

    def _record(self, message: str) -> None:
        self.fulfillment_log.append(message)


class StandardFulfillmentHandler(FulfillmentHandler):
    def fulfill(self, items: List[OrderItem]) -> bool:
        self._record(f"Shipping {len(items)} item(s) from warehouse immediately")
        return True


class SubscriptionFulfillmentHandler(FulfillmentHandler):
    def __init__(self, cycle_days: int = 30):
        super().__init__()
        self.cycle_days = cycle_days
        self.next_ship_date = datetime.now() + timedelta(days=cycle_days)

    def fulfill(self, items: List[OrderItem]) -> bool:
        self._record(f"Shipping recurring box of {len(items)} item(s); next ship {self.next_ship_date.date()}")
        self.next_ship_date += timedelta(days=self.cycle_days)
        return True


class PreOrderFulfillmentHandler(FulfillmentHandler):
    def __init__(self, release_date: datetime):
        super().__init__()
        self.release_date = release_date

    def fulfill(self, items: List[OrderItem]) -> bool:
        if datetime.now() < self.release_date:
            self._record(f"Cannot fulfill yet; release date is {self.release_date.date()}")
            return False
        self._record(f"Releasing and shipping {len(items)} pre-ordered item(s)")
        return True


# ---------------------------------------------------------------------------
# Order hierarchy - orchestrates parallel hierarchies
# ---------------------------------------------------------------------------

class Order(ABC):
    def __init__(
        self,
        order_id: str,
        customer_email: str,
        items: List[OrderItem],
    ):
        self.order_id = order_id
        self.customer_email = customer_email
        self.items = items
        self.status = OrderStatus.CREATED
        self.created_at = datetime.now()

        self.fulfillment_handler: FulfillmentHandler = self._create_fulfillment_handler()
        self.billing_handler: BillingHandler = self._create_billing_handler()
        self.notifier: Notifier = self._create_notifier()

        self.notifier.notify_created()

    @abstractmethod
    def _create_fulfillment_handler(self) -> FulfillmentHandler:
        ...

    @abstractmethod
    def _create_billing_handler(self) -> BillingHandler:
        ...

    @abstractmethod
    def _create_notifier(self) -> Notifier:
        ...

    def process(self) -> None:
        self.status = OrderStatus.PROCESSING
        amount = self.billing_handler.charge(self.items)
        self.status = OrderStatus.BILLED
        self.notifier.notify_billed(amount)

        fulfilled = self.fulfillment_handler.fulfill(self.items)
        if fulfilled:
            self.status = OrderStatus.FULFILLED
            self.notifier.notify_fulfilled()

    def total_amount(self) -> float:
        return self.billing_handler.calculate_total(self.items)

    def __repr__(self) -> str:
        return f"<{self.__class__.__name__} {self.order_id} status={self.status.value}>"


class StandardOrder(Order):
    def __init__(self, order_id: str, customer_email: str, items: List[OrderItem], payment_token: str):
        self.payment_token = payment_token
        super().__init__(order_id, customer_email, items)

    def _create_fulfillment_handler(self) -> FulfillmentHandler:
        return StandardFulfillmentHandler()

    def _create_billing_handler(self) -> BillingHandler:
        return StandardBillingHandler(self.payment_token)

    def _create_notifier(self) -> Notifier:
        return StandardOrderNotifier(self.customer_email)


class SubscriptionOrder(Order):
    def __init__(
        self,
        order_id: str,
        customer_email: str,
        items: List[OrderItem],
        payment_token: str,
        cycle_days: int = 30,
        discount_rate: float = 0.1,
    ):
        self.payment_token = payment_token
        self.cycle_days = cycle_days
        self.discount_rate = discount_rate
        super().__init__(order_id, customer_email, items)

    def _create_fulfillment_handler(self) -> FulfillmentHandler:
        return SubscriptionFulfillmentHandler(self.cycle_days)

    def _create_billing_handler(self) -> BillingHandler:
        return SubscriptionBillingHandler(self.payment_token, self.discount_rate)

    def _create_notifier(self) -> Notifier:
        return SubscriptionOrderNotifier(self.customer_email)

    def renew(self) -> None:
        self.process()
        if isinstance(self.notifier, SubscriptionOrderNotifier):
            handler = self.fulfillment_handler
            if isinstance(handler, SubscriptionFulfillmentHandler):
                self.notifier.notify_renewal_upcoming(handler.next_ship_date)


class PreOrder(Order):
    def __init__(
        self,
        order_id: str,
        customer_email: str,
        items: List[OrderItem],
        payment_token: str,
        release_date: datetime,
        deposit_rate: float = 0.2,
    ):
        self.payment_token = payment_token
        self.release_date = release_date
        self.deposit_rate = deposit_rate
        super().__init__(order_id, customer_email, items)

    def _create_fulfillment_handler(self) -> FulfillmentHandler:
        return PreOrderFulfillmentHandler(self.release_date)

    def _create_billing_handler(self) -> BillingHandler:
        return PreOrderBillingHandler(self.payment_token, self.deposit_rate)

    def _create_notifier(self) -> Notifier:
        return PreOrderNotifier(self.customer_email)

    def take_deposit(self) -> float:
        handler = self.billing_handler
        if isinstance(handler, PreOrderBillingHandler):
            return handler.charge_deposit(self.items)
        return 0.0

    def delay_release(self, new_date: datetime) -> None:
        self.release_date = new_date
        handler = self.fulfillment_handler
        if isinstance(handler, PreOrderFulfillmentHandler):
            handler.release_date = new_date
        if isinstance(self.notifier, PreOrderNotifier):
            self.notifier.notify_release_delayed(new_date)


# ---------------------------------------------------------------------------
# Example usage (not executed on import)
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    items = [
        OrderItem(sku="ABC123", name="Widget", quantity=2, unit_price=19.99),
        OrderItem(sku="XYZ789", name="Gadget", quantity=1, unit_price=49.99),
    ]

    std_order = StandardOrder("ORD-1", "alice@example.com", items, payment_token="tok_visa")
    std_order.process()
    print(std_order, std_order.total_amount())

    sub_order = SubscriptionOrder(
        "ORD-2", "bob@example.com", items, payment_token="tok_mc", cycle_days=30
    )
    sub_order.renew()
    print(sub_order, sub_order.total_amount())

    pre_order = PreOrder(
        "ORD-3",
        "carol@example.com",
        items,
        payment_token="tok_amex",
        release_date=datetime.now() + timedelta(days=10),
    )
    pre_order.take_deposit()
    pre_order.process()
    print(pre_order, pre_order.total_amount())
