    # Safety report generation
    # ------------------------------------------------------------------
    def generate_safety_report(self) -> Dict[str, Any]:
        total_patients = len(self.validated_patients)
        total_events = sum(len(events) for events in self.adverse_events.values())

        events_by_severity: Dict[str, int] = {s: 0 for s in self.ADVERSE_EVENT_SEVERITIES}
        events_by_arm: Dict[str, int] = {arm: 0 for arm in self.treatment_arms}
        serious_events: List[Dict[str, Any]] = []
        treatment_related_events: List[Dict[str, Any]] = []

        for patient_id, events in self.adverse_events.items():
            for event in events:
                events_by_severity[event["severity"]] = events_by_severity.get(event["severity"], 0) + 1
                arm = event.get("treatment_arm")
                if arm in events_by_arm:
                    events_by_arm[arm] += 1
                if event["serious"]:
                    serious_events.append(event)
                if event["related_to_treatment"]:
                    treatment_related_events.append(event)

        patients_with_events = len(self.adverse_events)
        incidence_rate = (patients_with_events / total_patients) if total_patients else 0.0

        report = {
            "report_id": str(uuid.uuid4()),
            "trial_id": self.trial_id,
            "generated_at": datetime.utcnow().isoformat(),
            "total_patients_validated": total_patients,
            "total_patients_eligible": len(self.eligible_patients),
            "total_patients_randomized": len(self.randomization_assignments),
            "total_adverse_events": total_events,
            "patients_with_adverse_events": patients_with_events,
            "adverse_event_incidence_rate": round(incidence_rate, 4),
            "events_by_severity": events_by_severity,
            "events_by_treatment_arm": events_by_arm,
            "serious_adverse_event_count": len(serious_events),
            "serious_adverse_events": serious_events,
            "treatment_related_event_count": len(treatment_related_events),
            "randomization_arm_counts": dict(self._arm_counts),
        }

        self._log("SAFETY_REPORT_GENERATED", None,
                  f"Total events: {total_events}, serious: {len(serious_events)}")

        return report

    # ------------------------------------------------------------------
    # Regulatory submission
    # ------------------------------------------------------------------
    def submit_to_regulatory_database(self, safety_report: Optional[Dict[str, Any]] = None,
                                       submit_fn=None) -> Dict[str, Any]:
        if safety_report is None:
            safety_report = self.generate_safety_report()

        payload = {
            "trial_id": self.trial_id,
            "submission_timestamp": datetime.utcnow().isoformat(),
            "safety_report": safety_report,
            "patients": {
                pid: {
                    "arm": self.randomization_assignments.get(pid),
                    "adverse_event_count": len(self.adverse_events.get(pid, [])),
                }
                for pid in self.validated_patients
            },
        }

        payload_hash = hashlib.sha256(
            repr(sorted(payload.items())).encode("utf-8")
        ).hexdigest()
        payload["integrity_hash"] = payload_hash

        submission_record = {
            "submission_id": str(uuid.uuid4()),
            "trial_id": self.trial_id,
            "endpoint": self.regulatory_endpoint,
            "timestamp": payload["submission_timestamp"],
            "status": "pending",
            "integrity_hash": payload_hash,
        }

        try:
            if submit_fn is not None:
                response = submit_fn(self.regulatory_endpoint, payload)
                submission_record["status"] = "success"
                submission_record["response"] = response
            else:
                submission_record["status"] = "simulated"
                submission_record["response"] = {
                    "message": "No submit_fn provided; submission simulated locally.",
                    "payload_summary": {
                        "trial_id": payload["trial_id"],
                        "total_patients": len(payload["patients"]),
                        "integrity_hash": payload_hash,
                    },
                }
        except Exception as e:
            submission_record["status"] = "failed"
            submission_record["error"] = str(e)
            self._log("REGULATORY_SUBMISSION_FAILED", None, str(e))
            self.submission_log.append(submission_record)
            return submission_record

        self._log("REGULATORY_SUBMISSION_SUCCESS", None,
                  f"Submission ID: {submission_record['submission_id']}")
        self.submission_log.append(submission_record)
        return submission_record

    # ------------------------------------------------------------------
    # Full pipeline orchestration
    # ------------------------------------------------------------------
    def process_patient(self, record: Dict[str, Any],
                         inclusion_criteria: Optional[Dict[str, Any]] = None,
                         exclusion_criteria: Optional[Dict[str, Any]] = None,
                         auto_randomize: bool = True) -> Dict[str, Any]:
        result = {
            "patient_id": record.get("patient_id"),
            "validated": False,
            "validation_errors": [],
            "eligible": False,
            "eligibility_reasons": [],
            "treatment_arm": None,
        }

        is_valid, val_errors = self.validate_patient_record(record)
        result["validated"] = is_valid
        result["validation_errors"] = val_errors

        if not is_valid:
            return result

        patient_id = str(record["patient_id"])
        is_eligible, elig_reasons = self.check_eligibility(
            patient_id, inclusion_criteria, exclusion_criteria
        )
        result["eligible"] = is_eligible
        result["eligibility_reasons"] = elig_reasons

        if is_eligible and auto_randomize:
            arm = self.randomize_patient(patient_id)
            result["treatment_arm"] = arm

        return result

