        self.max_age = max_age
        self.required_fields = required_fields or [
            "patient_id", "first_name", "last_name", "date_of_birth",
            "sex", "diagnosis_code", "consent_given", "site_id"
        ]
        self.regulatory_endpoint = regulatory_endpoint

        self._rng = random.Random(seed)

        self.validated_patients: Dict[str, Dict[str, Any]] = {}
        self.eligible_patients: Dict[str, Dict[str, Any]] = {}
        self.ineligible_patients: Dict[str, str] = {}
        self.randomization_assignments: Dict[str, str] = {}
        self.adverse_events: Dict[str, List[Dict[str, Any]]] = {}
        self.audit_log: List[Dict[str, Any]] = []
        self.submission_log: List[Dict[str, Any]] = []

        self._arm_counts = {arm: 0 for arm in self.treatment_arms}

    # ------------------------------------------------------------------
    # Logging helper
    # ------------------------------------------------------------------
    def _log(self, action: str, patient_id: Optional[str], details: str = "") -> None:
        self.audit_log.append({
            "timestamp": datetime.utcnow().isoformat(),
            "trial_id": self.trial_id,
            "action": action,
            "patient_id": patient_id,
            "details": details,
        })

    # ------------------------------------------------------------------
    # Patient record validation
    # ------------------------------------------------------------------
    def validate_patient_record(self, record: Dict[str, Any]) -> Tuple[bool, List[str]]:
        errors = []

        for field in self.required_fields:
            if field not in record or record[field] in (None, "", []):
                errors.append(f"Missing required field: {field}")

        if errors:
            return False, errors

        patient_id = str(record.get("patient_id", ""))
        if not re.match(r"^[A-Za-z0-9\-_]+$", patient_id):
            errors.append("Invalid patient_id format")

        dob = record.get("date_of_birth")
        dob_parsed = self._parse_date(dob)
        if dob_parsed is None:
            errors.append("Invalid date_of_birth format (expected YYYY-MM-DD)")
        elif dob_parsed > date.today():
            errors.append("date_of_birth cannot be in the future")

        sex = str(record.get("sex", "")).strip().lower()
        if sex not in ("m", "f", "male", "female", "other", "unknown"):
            errors.append("Invalid sex value")

        diagnosis_code = str(record.get("diagnosis_code", ""))
        if not re.match(r"^[A-Za-z0-9\.\-]+$", diagnosis_code):
            errors.append("Invalid diagnosis_code format")

        consent = record.get("consent_given")
        if not isinstance(consent, bool):
            errors.append("consent_given must be boolean")
        elif consent is False:
            errors.append("Patient has not given consent")

        site_id = record.get("site_id")
        if not site_id or not re.match(r"^[A-Za-z0-9\-_]+$", str(site_id)):
            errors.append("Invalid site_id")

        weight = record.get("weight_kg")
        if weight is not None:
            try:
                w = float(weight)
                if w <= 0 or w > 500:
                    errors.append("weight_kg out of plausible range")
            except (ValueError, TypeError):
                errors.append("weight_kg must be numeric")

        is_valid = len(errors) == 0
        if is_valid:
            normalized = dict(record)
            normalized["date_of_birth"] = dob_parsed.isoformat() if dob_parsed else dob
            normalized["sex"] = sex
            self.validated_patients[patient_id] = normalized
            self._log("VALIDATION_PASSED", patient_id)
        else:
            self._log("VALIDATION_FAILED", record.get("patient_id"), "; ".join(errors))

        return is_valid, errors

    @staticmethod
    def _parse_date(value: Any) -> Optional[date]:
        if isinstance(value, date):
            return value
        if isinstance(value, str):
            for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d-%m-%Y"):
                try:
                    return datetime.strptime(value, fmt).date()
                except ValueError:
                    continue
        return None

    @staticmethod
    def _calculate_age(dob: date, as_of: Optional[date] = None) -> int:
        as_of = as_of or date.today()
        years = as_of.year - dob.year - ((as_of.month, as_of.day) < (dob.month, dob.day))
        return years

    # ------------------------------------------------------------------
    # Eligibility checking
    # ------------------------------------------------------------------
    def check_eligibility(self, patient_id: str,
                           inclusion_criteria: Optional[Dict[str, Any]] = None,
                           exclusion_criteria: Optional[Dict[str, Any]] = None) -> Tuple[bool, List[str]]:
        reasons = []
        patient = self.validated_patients.get(patient_id)

        if patient is None:
            reasons.append("Patient record not validated or not found")
            self.ineligible_patients[patient_id] = "; ".join(reasons)
            self._log("ELIGIBILITY_FAILED", patient_id, reasons[0])
            return False, reasons

        dob = self._parse_date(patient.get("date_of_birth"))
        if dob is None:
            reasons.append("Cannot determine age from date_of_birth")
        else:
            age = self._calculate_age(dob)
            if age < self.min_age:
                reasons.append(f"Age {age} below minimum {self.min_age}")
            if age > self.max_age:
                reasons.append(f"Age {age} above maximum {self.max_age}")

        if not patient.get("consent_given", False):
            reasons.append("Consent not provided")

        inclusion_criteria = inclusion_criteria or {}
        for field, expected in inclusion_criteria.items():
            actual = patient.get(field)
            if isinstance(expected, (list, tuple, set)):
                if actual not in expected:
                    reasons.append(f"Inclusion criterion failed for {field}: {actual} not in {expected}")
            else:
                if actual != expected:
                    reasons.append(f"Inclusion criterion failed for {field}: expected {expected}, got {actual}")

        exclusion_criteria = exclusion_criteria or {}
        for field, disallowed in exclusion_criteria.items():
            actual = patient.get(field)
            if isinstance(disallowed, (list, tuple, set)):
                if actual in disallowed:
                    reasons.append(f"Exclusion criterion triggered for {field}: {actual} in {disallowed}")
            else:
                if actual == disallowed:
                    reasons.append(f"Exclusion criterion triggered for {field}: {actual} == {disallowed}")

        is_eligible = len(reasons) == 0
        if is_eligible:
            self.eligible_patients[patient_id] = patient
            self._log("ELIGIBILITY_PASSED", patient_id)
        else:
            self.ineligible_patients[patient_id] = "; ".join(reasons)
            self._log("ELIGIBILITY_FAILED", patient_id, "; ".join(reasons))

        return is_eligible, reasons

    # ------------------------------------------------------------------
    # Randomization
    # ------------------------------------------------------------------
    def randomize_patient(self, patient_id: str, method: str = "weighted") -> Optional[str]:
        if patient_id not in self.eligible_patients:
            self._log("RANDOMIZATION_FAILED", patient_id, "Patient not eligible")
            return None

        if patient_id in self.randomization_assignments:
            self._log("RANDOMIZATION_SKIPPED", patient_id, "Already randomized")
            return self.randomization_assignments[patient_id]

        if method == "weighted":
            arm = self._weighted_random_choice()
        elif method == "block":
            arm = self._block_randomization()
        else:
            arm = self._rng.choice(self.treatment_arms)

        self.randomization_assignments[patient_id] = arm
        self._arm_counts[arm] += 1
        self._log("RANDOMIZED", patient_id, f"Assigned to arm: {arm}")
        return arm

    def _weighted_random_choice(self) -> str:
        total = sum(self.randomization_ratio)
        r = self._rng.uniform(0, total)
        upto = 0.0
        for arm, weight in zip(self.treatment_arms, self.randomization_ratio):
            upto += weight
            if r <= upto:
                return arm
        return self.treatment_arms[-1]

    def _block_randomization(self) -> str:
        target_props = [w / sum(self.randomization_ratio) for w in self.randomization_ratio]
        total_assigned = sum(self._arm_counts.values()) or 1
        deficits = []
        for arm, target_prop in zip(self.treatment_arms, target_props):
            current_prop = self._arm_counts[arm] / total_assigned
            deficits.append(target_prop - current_prop)
        max_deficit = max(deficits)
        candidates = [arm for arm, d in zip(self.treatment_arms, deficits) if d == max_deficit]
        return self._rng.choice(candidates)

    # ------------------------------------------------------------------
    # Adverse event tracking
    # ------------------------------------------------------------------
    def record_adverse_event(self, patient_id: str, description: str,
                              severity: str, grade: int,
                              onset_date: Optional[str] = None,
                              related_to_treatment: bool = False,
                              serious: bool = False,
                              outcome: str = "ongoing") -> Dict[str, Any]:
        severity_norm = severity.strip().lower()
        if severity_norm not in self.ADVERSE_EVENT_SEVERITIES:
            raise ValueError(f"Invalid severity: {severity}. Must be one of {self.ADVERSE_EVENT_SEVERITIES}")

        if grade not in self.ADVERSE_EVENT_GRADES:
            raise ValueError(f"Invalid grade: {grade}. Must be one of {self.ADVERSE_EVENT_GRADES}")

        if patient_id not in self.validated_patients:
            raise ValueError(f"Unknown patient_id: {patient_id}")

        onset_parsed = self._parse_date(onset_date) if onset_date else date.today()
        if onset_parsed is None:
            raise ValueError("Invalid onset_date format")

        event = {
            "event_id": str(uuid.uuid4()),
            "patient_id": patient_id,
            "trial_id": self.trial_id,
            "description": description,
            "severity": severity_norm,
            "grade": grade,
            "onset_date": onset_parsed.isoformat(),
            "related_to_treatment": related_to_treatment,
            "serious": serious or severity_norm in ("severe", "life-threatening", "death"),
            "outcome": outcome,
            "reported_timestamp": datetime.utcnow().isoformat(),
            "treatment_arm": self.randomization_assignments.get(patient_id),
        }

        self.adverse_events.setdefault(patient_id, []).append(event)
        self._log("ADVERSE_EVENT_RECORDED", patient_id,
                  f"{severity_norm} (grade {grade}) - serious={event['serious']}")

        return event

    # ------------------------------------------------------------------
    # Safety report generation
    # ------------------------------------------------------------------
    def generate_safety_report(self) -> Dict[str, Any]:
        total_patients = len(self.validated_patients)
        total_events = sum(len(events) for events in self.adverse_events.values())

        events_by_severity: Dict[str, int] = {s: 0 for s in self.ADVERSE_EVENT_SEVERITIES}
        events_by_arm: Dict[str, int] = {arm: 0 for arm in self.treatment_arms}
        serious_events: List[Dict[str, Any]] = []
        treatment_related_events: List[Dict[str, Any]] = []

        for patient_id, events in self.adverse_events.items():
            for event in events:
                events_by_severity[event["severity"]] = events_by_severity.get(event["severity"], 0) + 1
                arm = event.get("treatment_arm")
                if arm in events_by_arm:
                    events_by_arm[arm] += 1
                if event["serious"]:
                    serious_events.append(event)
                if event["related_to_treatment"]:
                    treatment_related_events.append(event)

        patients_with_events = len(self.adverse_events)
        incidence_rate = (patients_with_events / total_patients) if total_patients else 0.0

        report = {
            "report_id": str(uuid.uuid4()),
            "trial_id": self.trial_id,
            "generated_at": datetime.utcnow().isoformat(),
            "total_patients_validated": total_patients,
            "total_patients_eligible": len(self.eligible_patients),
            "total_patients_randomized": len(self.randomization_assignments),
            "total_adverse_events": total_events,
            "patients_with_adverse_events": patients_with_events,
            "adverse_event_incidence_rate": round(incidence_rate, 4),
            "events_by_severity": events_by_severity,
            "events_by_treatment_arm": events_by_arm,
            "serious_adverse_event_count": len(serious_events),
            "serious_adverse_events": serious_events,
            "treatment_related_event_count": len(treatment_related_events),
            "randomization_arm_counts": dict(self._arm_counts),
        }

        self._log("SAFETY_REPORT_GENERATED", None,
                  f"Total events: {total_events}, serious: {len(serious_events)}")

        return report

    # ------------------------------------------------------------------
    # Regulatory submission
    # ------------------------------------------------------------------
    def submit_to_regulatory_database(self, safety_report: Optional[Dict[str, Any]] = None,
                                       submit_fn=None) -> Dict[str, Any]:
        if safety_report is None:
            safety_report = self.generate_safety_report()

        payload = {
            "trial_id": self.trial_id,
            "submission_timestamp": datetime.utcnow().isoformat(),
            "safety_report": safety_report,
            "patients": {
                pid: {
                    "arm": self.randomization_assignments.get(pid),
                    "adverse_event_count": len(self.adverse_events.get(pid, [])),
                }
                for pid in self.validated_patients
            },
        }

        payload_hash = hashlib.sha256(
            repr(sorted(payload.items())).encode("utf-8")
        ).hexdigest()
        payload["integrity_hash"] = payload_hash

        submission_record = {
            "submission_id": str(uuid.uuid4()),
            "trial_id": self.trial_id,
            "endpoint": self.regulatory_endpoint,
            "timestamp": payload["submission_timestamp"],
            "status": "pending",
            "integrity_hash": payload_hash,
        }

        try:
            if submit_fn is not None:
                response = submit_fn(self.regulatory_endpoint, payload)
                submission_record["status"] = "success"
                submission_record["response"] = response
            else:
                submission_record["status"] = "simulated"
                submission_record["response"] = {
                    "message": "No submit_fn provided; submission simulated locally.",
                    "payload_summary": {
                        "trial_id": payload["trial_id"],
                        "total_patients": len(payload["patients"]),
                        "integrity_hash": payload_hash,
                    },
                }
        except Exception as e:
            submission_record["status"] = "failed"
            submission_record["error"] = str(e)
            self._log("REGULATORY_SUBMISSION_FAILED", None, str(e))
            self.submission_log.append(submission_record)
            return submission_record

        self._log("REGULATORY_SUBMISSION_SUCCESS", None,
                  f"Submission ID: {submission_record['submission_id']}")
        self.submission_log.append(submission_record)
        return submission_record

    # ------------------------------------------------------------------
    # Full pipeline orchestration
    # ------------------------------------------------------------------
    def process_patient(self, record: Dict[str, Any],
                         inclusion_criteria: Optional[Dict[str, Any]] = None,
                         exclusion_criteria: Optional[Dict[str, Any]] = None,
                         auto_randomize: bool = True) -> Dict[str, Any]:
        result = {
            "patient_id": record.get("patient_id"),
            "validated": False,
            "validation_errors": [],
            "eligible": False,
            "eligibility_reasons": [],
            "treatment_arm": None,
        }

        is_valid, val_errors = self.validate_patient_record(record)
        result["validated"] = is_valid
        result["validation_errors"] = val_errors

        if not is_valid:
            return result

        patient_id = str(record["patient_id"])
        is_eligible, elig_reasons = self.check_eligibility(
            patient_id, inclusion_criteria, exclusion_criteria
        )
        result["eligible"] = is_eligible
        result["eligibility_reasons"] = elig_reasons

        if is_eligible and auto_randomize:
            arm = self.randomize_patient(patient_id)
            result["treatment_arm"] = arm

        return result
