    def __init__(self, region_name="us-east-1", endpoint_url=None, aws_access_key_id=None, aws_secret_access_key=None):
        self.region_name = region_name
        self.endpoint_url = endpoint_url
        self.aws_access_key_id = aws_access_key_id
        self.aws_secret_access_key = aws_secret_access_key
        self._sent_messages = []

    def send_message(self, queue_url, message_body, delay_seconds=0, message_attributes=None,
                      message_group_id=None, message_deduplication_id=None):
        if not queue_url or not isinstance(queue_url, str):
            raise ValueError("queue_url must be a non-empty string")

        if delay_seconds < 0 or delay_seconds > 900:
            raise ValueError("delay_seconds must be between 0 and 900")

        if isinstance(message_body, (dict, list)):
            body_str = json.dumps(message_body)
        elif isinstance(message_body, str):
            body_str = message_body
        elif isinstance(message_body, bytes):
            body_str = message_body.decode("utf-8")
        else:
            body_str = json.dumps(message_body)

        if len(body_str.encode("utf-8")) > 262144:
            raise ValueError("message_body exceeds maximum size of 256KB")

        is_fifo = queue_url.endswith(".fifo")
        if is_fifo:
            if not message_group_id:
                raise ValueError("message_group_id is required for FIFO queues")
            if not message_deduplication_id:
                message_deduplication_id = uuid.uuid5(uuid.NAMESPACE_DNS, body_str).hex

        message_id = str(uuid.uuid4())
        md5_of_body = self._compute_md5(body_str)

        response = {
            "MessageId": message_id,
            "MD5OfMessageBody": md5_of_body,
            "SequenceNumber": str(int(time.time() * 1000)) if is_fifo else None,
        }

        if message_attributes:
            response["MD5OfMessageAttributes"] = self._compute_md5(json.dumps(message_attributes))

        self._sent_messages.append({
            "queue_url": queue_url,
            "body": body_str,
            "delay_seconds": delay_seconds,
            "message_attributes": message_attributes or {},
            "message_group_id": message_group_id,
            "message_deduplication_id": message_deduplication_id,
            "response": response,
        })

        return response

    def _compute_md5(self, text):
        import hashlib
        return hashlib.md5(text.encode("utf-8")).hexdigest()
