        product_id = self.sku_index.get(sku)
        if not product_id:
            raise ProductNotFoundError(f"Product with SKU {sku} not found")
        return self.products[product_id]

    # ---------- Categorization ----------
    def add_category(self, product_id, category):
        product = self._get_product_or_raise(product_id)
        self.category_index[product.category.lower()].discard(product_id)
        product.category = category
        product.updated_at = datetime.now()
        self.category_index[category.lower()].add(product_id)

    def get_products_by_category(self, category):
        ids = self.category_index.get(category.lower(), set())
        return [self.products[pid] for pid in ids]

