        if appt_date < datetime.datetime.now():
            return _error("Cannot schedule an appointment in the past.")

        # Check double booking for same doctor at same time
        for pid, appts in db["appointments"].items():
            for a in appts:
                if a["doctor"] == doctor and a["date"] == appt_date.isoformat():
                    return _error(f"Doctor {doctor} is already booked at that time.")

        appointment = {
            "appointment_id": _gen_id("APT"),
            "doctor": doctor,
            "date": appt_date.isoformat(),
            "reason": reason,
            "status": "scheduled",
            "created_on": _now(),
        }
        db["appointments"][patient_id].append(appointment)

        db["bills"][patient_id].append({
            "item": f"Appointment Scheduling Fee ({doctor})",
            "amount": BASE_COSTS["appointment_fee"],
