        existing_drugs = [p["drug_name"].lower() for p in db["prescriptions"].get(patient_id, [])]
        new_drug = drug_name.lower().strip()

        warnings = []
        for existing in existing_drugs:
            pair1 = (existing, new_drug)
            pair2 = (new_drug, existing)
            if pair1 in DRUG_INTERACTIONS:
                warnings.append(f"Interaction warning: {existing} + {new_drug} -> {DRUG_INTERACTIONS[pair1]}")
            elif pair2 in DRUG_INTERACTIONS:
                warnings.append(f"Interaction warning: {new_drug} + {existing} -> {DRUG_INTERACTIONS[pair2]}")

        prescription = {
            "prescription_id": _gen_id("RX"),
            "drug_name": drug_name,
            "dosage": dosage,
            "frequency": frequency or "As directed",
            "duration_days": duration_days or 7,
            "warnings": warnings,
            "date": _now(),
        }
        db["prescriptions"][patient_id].append(prescription)

        db["bills"][patient_id].append({
            "item": f"Prescription Fee ({drug_name})",
            "amount": BASE_COSTS["prescription_fee"],
            "timestamp": _now(),
        })

        return {
            "success": True,
            "message": f"Prescription for {drug_name} added." + (
                " WARNING: potential drug interactions detected." if warnings else ""
            ),
            "prescription": prescription,
            "warnings": warnings,
        }

    # ==================================================================
    # ACTION: discharge
    # ==================================================================
    elif action == "discharge":
        patient_id = request.get("patient_id")
        discharge_summary = request.get("discharge_summary", "")
        follow_up_instructions = request.get("follow_up_instructions", "")

        if not patient_id:
            return _error("Discharge requires 'patient_id'.")

        patient = _get_patient(patient_id)
        if not patient:
            return _error(f"No patient found with ID {patient_id}.")

        if patient.get("discharged"):
            return _error("Patient has already been discharged.")

        db["bills"][patient_id].append({
            "item": "Discharge Processing Fee",
