            "timestamp": _now(),
        })

        bills = db["bills"].get(patient_id, [])
        subtotal = sum(item["amount"] for item in bills)
        insurance_info = db["insurance"].get(patient_id, {})
        coverage_rate = insurance_info.get("coverage_rate", 0.0) if insurance_info.get("verified") else 0.0
        insurance_covered = round(subtotal * coverage_rate, 2)
        amount_due = round(subtotal - insurance_covered, 2)

        discharge_doc = {
