"""
Simple CMS demonstrating a content field that must be kept in sync
across: Model, Form, Serializer, Template, Search indexer,
Export handler, and API views.

This is a self-contained, runnable example using SQLite via
Python's built-in sqlite3 module (no external dependencies).
"""

import sqlite3
import json
import csv
import io
import re
from datetime import datetime
from html import escape


# ---------------------------------------------------------------------------
# Database setup
# ---------------------------------------------------------------------------

DB_PATH = "cms.db"


def get_connection():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_connection()
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS articles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            body TEXT NOT NULL,
            author TEXT NOT NULL,
            tags TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    conn.commit()
    conn.close()


# ---------------------------------------------------------------------------
# MODEL
# ---------------------------------------------------------------------------

class Article:
    """
    Model representing a CMS content item.

    Fields:
        id: int
        title: str
        body: str
        author: str
        tags: str (comma separated)
        created_at: str (ISO datetime)
    """

    FIELDS = ("title", "body", "author", "tags", "created_at")

    def __init__(self, id=None, title="", body="", author="", tags="",
                 created_at=None):
        self.id = id
        self.title = title
        self.body = body
        self.author = author
        self.tags = tags
        self.created_at = created_at or datetime.utcnow().isoformat()

    @classmethod
    def from_row(cls, row):
        if row is None:
            return None
        return cls(
            id=row["id"],
            title=row["title"],
            body=row["body"],
            author=row["author"],
            tags=row["tags"],
            created_at=row["created_at"],
        )

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "body": self.body,
            "author": self.author,
            "tags": self.tags,
            "created_at": self.created_at,
        }

    def save(self):
        conn = get_connection()
        cur = conn.cursor()
        if self.id is None:
            cur.execute(
                """
                INSERT INTO articles (title, body, author, tags, created_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (self.title, self.body, self.author, self.tags,
                 self.created_at),
            )
            self.id = cur.lastrowid
        else:
            cur.execute(
                """
                UPDATE articles
                SET title = ?, body = ?, author = ?, tags = ?, created_at = ?
                WHERE id = ?
                """,
                (self.title, self.body, self.author, self.tags,
                 self.created_at, self.id),
            )
        conn.commit()
        conn.close()
        return self

    @classmethod
    def get(cls, article_id):
        conn = get_connection()
        cur = conn.cursor()
        cur.execute("SELECT * FROM articles WHERE id = ?", (article_id,))
        row = cur.fetchone()
        conn.close()
        return cls.from_row(row)

    @classmethod
    def all(cls):
        conn = get_connection()
        cur = conn.cursor()
        cur.execute("SELECT * FROM articles ORDER BY id DESC")
        rows = cur.fetchall()
        conn.close()
        return [cls.from_row(r) for r in rows]

    @classmethod
    def delete(cls, article_id):
        conn = get_connection()
        cur = conn.cursor()
        cur.execute("DELETE FROM articles WHERE id = ?", (article_id,))
        conn.commit()
        conn.close()


# ---------------------------------------------------------------------------
# FORM
# ---------------------------------------------------------------------------

class ValidationError(Exception):
    def __init__(self, errors):
        super().__init__(str(errors))
        self.errors = errors


class ArticleForm:
    """
    Validates and cleans input data for creating/updating an Article.
    """

    REQUIRED_FIELDS = ("title", "body", "author")
    OPTIONAL_FIELDS = ("tags",)

    def __init__(self, data):
        self.raw_data = data or {}
        self.errors = {}
        self.cleaned_data = {}

    def is_valid(self):
        self.errors = {}
        self.cleaned_data = {}

        title = (self.raw_data.get("title") or "").strip()
        if not title:
            self.errors["title"] = "Title is required."
        elif len(title) > 200:
            self.errors["title"] = "Title must be 200 characters or fewer."
        else:
            self.cleaned_data["title"] = title

        body = (self.raw_data.get("body") or "").strip()
        if not body:
            self.errors["body"] = "Body is required."
        else:
            self.cleaned_data["body"] = body

        author = (self.raw_data.get("author") or "").strip()
        if not author:
            self.errors["author"] = "Author is required."
        else:
            self.cleaned_data["author"] = author

        tags = self.raw_data.get("tags", "")
        if tags is None:
            tags = ""
        tags = tags.strip() if isinstance(tags, str) else ""
        if tags and not re.match(r"^[\w\- ,]+$", tags):
            self.errors["tags"] = (
                "Tags may only contain letters, numbers, spaces, "
                "hyphens, and commas."
            )
        else:
            self.cleaned_data["tags"] = tags

        return not self.errors

    def save(self, instance=None):
        if self.errors:
            raise ValidationError(self.errors)
        if instance is None:
            instance = Article()
        instance.title = self.cleaned_data["title"]
        instance.body = self.cleaned_data["body"]
        instance.author = self.cleaned_data["author"]
        instance.tags = self.cleaned_data["tags"]
        instance.save()
        return instance


# ---------------------------------------------------------------------------
# SERIALIZER
# ---------------------------------------------------------------------------

class ArticleSerializer:
    """
    Converts Article model instances to/from JSON-serializable dicts.
    """

    FIELDS = ("id", "title", "body", "author", "tags", "created_at")

    @classmethod
    def serialize(cls, article: Article):
        return {field: getattr(article, field) for field in cls.FIELDS}

    @classmethod
    def serialize_many(cls, articles):
        return [cls.serialize(a) for a in articles]

    @classmethod
    def deserialize(cls, data):
        """
        Build an Article instance from a dict (does not save).
        """
        return Article(
            id=data.get("id"),
            title=data.get("title", ""),
            body=data.get("body", ""),
            author=data.get("author", ""),
            tags=data.get("tags", ""),
            created_at=data.get("created_at"),
        )


# ---------------------------------------------------------------------------
# TEMPLATE
