class ArticleTemplate:
    """
    Simple HTML rendering for Article content (no external template engine).
    """

    @staticmethod
    def render_detail(article: Article) -> str:
        tags_html = ""
        if article.tags:
            tag_list = [t.strip() for t in article.tags.split(",") if t.strip()]
            tags_html = "".join(
                f'<span class="tag">{escape(t)}</span>' for t in tag_list
            )

        return f"""
<article class="cms-article" data-id="{article.id}">
    <h1 class="title">{escape(article.title)}</h1>
    <div class="meta">
        <span class="author">By {escape(article.author)}</span>
        <span class="created_at">{escape(article.created_at)}</span>
    </div>
    <div class="body">{escape(article.body)}</div>
    <div class="tags">{tags_html}</div>
</article>
"""

    @staticmethod
    def render_list(articles) -> str:
        items = "\n".join(
            f"""<li class="cms-article-summary" data-id="{a.id}">
                <a href="/articles/{a.id}">{escape(a.title)}</a>
                <span class="author">{escape(a.author)}</span>
            </li>"""
            for a in articles
        )
        return f'<ul class="cms-article-list">\n{items}\n</ul>'


# ---------------------------------------------------------------------------
# SEARCH INDEXER
# ---------------------------------------------------------------------------

class SearchIndexer:
    """
    In-memory search index over Article content fields.
    """

    def __init__(self):
        self._index = {}  # article_id -> dict of indexed field data

    def _tokenize(self, text):
        return set(re.findall(r"[a-z0-9]+", (text or "").lower()))

    def index_article(self, article: Article):
        tokens = set()
        tokens |= self._tokenize(article.title)
        tokens |= self._tokenize(article.body)
        tokens |= self._tokenize(article.author)
        tokens |= self._tokenize(article.tags)

        self._index[article.id] = {
            "tokens": tokens,
            "title": article.title,
            "body": article.body,
            "author": article.author,
            "tags": article.tags,
        }

    def remove_article(self, article_id):
        self._index.pop(article_id, None)

    def rebuild(self):
        self._index.clear()
        for article in Article.all():
            self.index_article(article)

    def search(self, query):
        query_tokens = self._tokenize(query)
        if not query_tokens:
            return []
        results = []
        for article_id, data in self._index.items():
            if query_tokens & data["tokens"]:
                score = len(query_tokens & data["tokens"])
                results.append((score, article_id))
        results.sort(key=lambda x: (-x[0], x[1]))
        return [article_id for _, article_id in results]


# Singleton indexer instance used by the app
search_indexer = SearchIndexer()


# ---------------------------------------------------------------------------
# EXPORT HANDLER
