class EnrollmentManager(ABC):
    def __init__(self, target_enrollment: int):
        self.target_enrollment = target_enrollment
        self.enrolled_subjects: List[Dict[str, Any]] = []
        self.screen_failures: List[Dict[str, Any]] = []

    @abstractmethod
    def max_cohort_size(self) -> int:
        ...

    @abstractmethod
    def eligibility_criteria(self) -> List[str]:
        ...

    def screen_subject(self, subject_id: str, criteria_met: bool, reason: str = "") -> bool:
        if criteria_met and len(self.enrolled_subjects) < self.max_cohort_size():
            self.enroll_subject(subject_id)
            return True
        self.screen_failures.append({"subject_id": subject_id, "reason": reason,
                                      "timestamp": datetime.now()})
        return False

    def enroll_subject(self, subject_id: str) -> None:
        self.enrolled_subjects.append({
            "subject_id": subject_id,
            "enrolled_at": datetime.now(),
            "status": "active",
        })

    def enrollment_progress(self) -> float:
        if self.target_enrollment == 0:
            return 0.0
        return len(self.enrolled_subjects) / self.target_enrollment * 100

    def is_enrollment_complete(self) -> bool:
        return len(self.enrolled_subjects) >= self.target_enrollment


