# FORMATTING HELPERS
# ============================================================

def _apply_currency_and_decimals(value, formatting):
    decimals = formatting.get('decimals', 2)
    if formatting.get('currency'):
        return f"${value:,.{decimals}f}"
    return f"{value:.{decimals}f}" if isinstance(value, float) else str(value)


def _format_plain(records, formatting):
    if not records:
        return "No records found."
    lines = []
    for r in records:
        parts = []
        for k, v in r.items():
            if isinstance(v, (int, float)) and k in ('value', 'amount', 'total_spent', 'quantity'):
                parts.append(f"{k}={_apply_currency_and_decimals(v, formatting)}")
            else:
                parts.append(f"{k}={v}")
        lines.append(", ".join(parts))
    return "\n".join(lines)


def _format_table(records, formatting):
    if not records:
        return "No records found."
    headers = list(records[0].keys())
    col_widths = {h: max(len(h), max(len(str(r.get(h, ''))) for r in records)) for h in headers}

    header_line = " | ".join(h.ljust(col_widths[h]) for h in headers)
    separator = "-+-".join("-" * col_widths[h] for h in headers)
    lines = [header_line, separator]

    for r in records:
        row = []
        for h in headers:
            val = r.get(h, '')
            if isinstance(val, (int, float)) and h in ('value', 'amount', 'total_spent', 'quantity'):
                val = _apply_currency_and_decimals(val, formatting)
            row.append(str(val).ljust(col_widths[h]))
        lines.append(" | ".join(row))

    return "\n".join(lines)


def _format_csv(records, formatting):
    if not records:
        return "No records found."
    headers = list(records[0].keys())
    lines = [",".join(headers)]
    for r in records:
        row = []
        for h in headers:
            val = r.get(h, '')
            if isinstance(val, (int, float)) and h in ('value', 'amount', 'total_spent', 'quantity'):
                val = _apply_currency_and_decimals(val, formatting)
            row.append(str(val))
        lines.append(",".join(row))
    return "\n".join(lines)


def _format_json(records):
    import json
    return json.dumps(records, indent=2, default=str)


def _group_by(data, key):
    grouped = {}
    for record in data:
        group_key = record.get(key, 'Unknown')
        grouped.setdefault(group_key, []).append(record)
    return grouped


def _format_grouped_plain(grouped, formatting):
    if not grouped:
        return "No records found."
    lines = []
    for group_key, records in grouped.items():
        lines.append(f"--- {group_key} ---")
        lines.append(_format_plain(records, formatting))
    return "\n".join(lines)


def _format_grouped_table(grouped, formatting):
    if not grouped:
        return "No records found."
    lines = []
    for group_key, records in grouped.items():
        lines.append(f"--- {group_key} ---")
        lines.append(_format_table(records, formatting))
    return "\n".join(lines)


def _format_grouped_csv(grouped, formatting):
    if not grouped:
        return "No records found."
    lines = []
    for group_key, records in grouped.items():
        lines.append(f"--- {group_key} ---")
        lines.append(_format_csv(records, formatting))
    return "\n".join(lines)


