            ),
        }
    if hasattr(o, "__dict__"):
        return {"__type__": type(o).__name__, **{
            k: v for k, v in vars(o).items() if not k.startswith("_")
        }}
    return str(o)


def _get_environment_metadata() -> Dict[str, Any]:
    versions = {
        "python": sys.version,
        "platform": platform.platform(),
        "numpy": np.__version__,
        "pandas": pd.__version__,
    }
    if scipy is not None:
        versions["scipy"] = scipy.__version__
    if statsmodels is not None:
        versions["statsmodels"] = statsmodels.__version__
    return versions


# ---------------------------------------------------------------------------
# Reproducibility: seed management
# ---------------------------------------------------------------------------

class SeedManager:
    """
    Centralized, reproducible seed control across random, numpy, and scipy.

    Usage:
        sm = SeedManager(seed=42)
        sm.apply()
        ... run stochastic code ...

        with sm.scoped(seed=123):
            ... run code with a temporary seed, restored afterward ...
    """

    def __init__(self, seed: Optional[int] = None):
        self.seed = seed if seed is not None else self._generate_seed()
        self._numpy_rng: Optional[np.random.Generator] = None
        self._history: List[Dict[str, Any]] = []

    @staticmethod
    def _generate_seed() -> int:
        return int.from_bytes(os.urandom(4), "big")

    def apply(self) -> "SeedManager":
        random.seed(self.seed)
        np.random.seed(self.seed)
        self._numpy_rng = np.random.default_rng(self.seed)
        self._history.append({"seed": self.seed, "timestamp": _now_iso()})
        return self

    @property
    def rng(self) -> np.random.Generator:
        if self._numpy_rng is None:
            self._numpy_rng = np.random.default_rng(self.seed)
        return self._numpy_rng

    @contextmanager
    def scoped(self, seed: int):
        """Temporarily apply a different seed, restoring prior state afterward."""
        prev_seed = self.seed
        prev_py_state = random.getstate()
        prev_np_state = np.random.get_state()
        prev_rng = self._numpy_rng
        try:
            self.seed = seed
            self.apply()
            yield self
        finally:
            self.seed = prev_seed
            random.setstate(prev_py_state)
            np.random.set_state(prev_np_state)
            self._numpy_rng = prev_rng

    def history(self) -> List[Dict[str, Any]]:
        return list(self._history)

    def to_dict(self) -> Dict[str, Any]:
        return {"seed": self.seed, "history": self._history}


# Global default seed manager for convenience
_GLOBAL_SEED_MANAGER: Optional[SeedManager] = None


def set_global_seed(seed: int) -> SeedManager:
    """Set and apply a global reproducibility seed."""
    global _GLOBAL_SEED_MANAGER
    _GLOBAL_SEED_MANAGER = SeedManager(seed).apply()
    return _GLOBAL_SEED_MANAGER


def get_global_seed_manager() -> SeedManager:
    global _GLOBAL_SEED_MANAGER
    if _GLOBAL_SEED_MANAGER is None:
        _GLOBAL_SEED_MANAGER = SeedManager().apply()
    return _GLOBAL_SEED_MANAGER


