@dataclass
class ProvenanceRecord:
    op: str
    timestamp: str
    inputs_hash: List[str]
    output_hash: str
    params: Dict[str, Any] = field(default_factory=dict)
    note: Optional[str] = None


class ProvenanceTracker:
    """
    Tracks lineage of DataFrame transformations.

    Wraps DataFrames with a lightweight registry keyed by object id and
    content hash, recording each transformation applied.
    """

    def __init__(self):
        self._records: Dict[str, List[ProvenanceRecord]] = {}
        self._df_origin: Dict[str, str] = {}  # hash -> origin description

    def register_source(self, df: pd.DataFrame, source: str) -> str:
        h = _hash_dataframe(df)
        self._df_origin[h] = source
        self._records.setdefault(h, [])
        return h

    def record(
        self,
        op: str,
        inputs: Sequence[pd.DataFrame],
        output: pd.DataFrame,
        params: Optional[Dict[str, Any]] = None,
        note: Optional[str] = None,
    ) -> str:
        input_hashes = [_hash_dataframe(df) for df in inputs]
        output_hash = _hash_dataframe(output)
        rec = ProvenanceRecord(
            op=op,
            timestamp=_now_iso(),
            inputs_hash=input_hashes,
            output_hash=output_hash,
            params=params or {},
            note=note,
        )
        self._records.setdefault(output_hash, []).append(rec)
        return output_hash

    def lineage(self, df: pd.DataFrame) -> List[Dict[str, Any]]:
        h = _hash_dataframe(df)
        chain = []
        visited = set()

        def _walk(hash_key: str):
            if hash_key in visited:
                return
            visited.add(hash_key)
            recs = self._records.get(hash_key, [])
            for rec in recs:
                chain.append(asdict(rec))
                for in_hash in rec.inputs_hash:
                    _walk(in_hash)

        _walk(h)
        chain.reverse()
        return chain

    def origin_of(self, df: pd.DataFrame) -> Optional[str]:
        h = _hash_dataframe(df)
        return self._df_origin.get(h)


GLOBAL_PROVENANCE = ProvenanceTracker()


def track_transform(op: str, note: Optional[str] = None):
    """
    Decorator for pandas-transforming functions that automatically records
    provenance. The decorated function must accept DataFrame(s) as its first
    positional argument(s) (detected via inspection) and return a DataFrame.
    """

    def decorator(func: Callable) -> Callable:
        sig = inspect.signature(func)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            bound = sig.bind_partial(*args, **kwargs)
            bound.apply_defaults()
            input_dfs = [
                v for v in bound.arguments.values() if isinstance(v, pd.DataFrame)
            ]
            result = func(*args, **kwargs)
            if isinstance(result, pd.DataFrame) and input_dfs:
                params = {
                    k: v
                    for k, v in bound.arguments.items()
                    if not isinstance(v, pd.DataFrame)
                }
                GLOBAL_PROVENANCE.record(
                    op=op or func.__name__,
                    inputs=input_dfs,
                    output=result,
                    params=params,
                    note=note,
                )
            return result

        return wrapper

    return decorator


@pd.api.extensions.register_dataframe_accessor("provenance")
class ProvenanceAccessor:
    """
    Pandas accessor exposing provenance utilities directly on DataFrames:
        df.provenance.register("loaded_from_csv")
        df.provenance.lineage()
        df.provenance.hash()
    """

    def __init__(self, pandas_obj: pd.DataFrame):
        self._obj = pandas_obj

    def register(self, source: str) -> str:
        return GLOBAL_PROVENANCE.register_source(self._obj, source)

    def lineage(self) -> List[Dict[str, Any]]:
        return GLOBAL_PROVENANCE.lineage(self._obj)

    def hash(self) -> str:
        return _hash_dataframe(self._obj)

    def origin(self) -> Optional[str]:
        return GLOBAL_PROVENANCE.origin_of(self._obj)


