@dataclass
class VariableMetadata:
    name: str
    unit: Optional[str] = None
    description: Optional[str] = None
    dtype: Optional[str] = None


@dataclass
class ScientificResult:
    """
    Wraps a statistical result (from scipy.stats or statsmodels) with
    scientific metadata: units, citations, environment, and provenance.
    """

    result_type: str
    value: Any
    method: str
    variables: List[VariableMetadata] = field(default_factory=list)
    citation: Optional[str] = None
    units: Dict[str, str] = field(default_factory=dict)
    parameters: Dict[str, Any] = field(default_factory=dict)
    environment: Dict[str, Any] = field(default_factory=_get_environment_metadata)
    timestamp: str = field(default_factory=_now_iso)
    seed: Optional[int] = None
    notes: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["value"] = self._serialize_value(self.value)
        return d

    @staticmethod
    def _serialize_value(value: Any) -> Any:
        if hasattr(value, "_asdict"):  # namedtuple-like results (scipy)
            return {k: _json_default(v) if _needs_default(v) else v
                     for k, v in value._asdict().items()}
        if hasattr(value, "summary"):  # statsmodels results
            try:
                return {
                    "summary": value.summary().as_text(),
                    "params": dict(value.params) if hasattr(value, "params") else None,
                    "pvalues": dict(value.pvalues) if hasattr(value, "pvalues") else None,
                }
            except Exception:
                return str(value)
        if isinstance(value, dict):
            return {k: _json_default(v) if _needs_default(v) else v for k, v in value.items()}
        if _needs_default(value):
            return _json_default(value)
        return value

    def to_json(self, path: Optional[str] = None) -> str:
        payload = json.dumps(self.to_dict(), indent=2, default=_json_default)
        if path:
            with open(path, "w") as f:
                f.write(payload)
        return payload


def _needs_default(v: Any) -> bool:
    return isinstance(v, (np.integer, np.floating, np.ndarray, pd.Timestamp, datetime,
                          pd.DataFrame, pd.Series))


def wrap_scipy_result(
    method: str,
    result: Any,
    variables: Optional[List[VariableMetadata]] = None,
    citation: Optional[str] = None,
    units: Optional[Dict[str, str]] = None,
    parameters: Optional[Dict[str, Any]] = None,
    seed: Optional[int] = None,
) -> ScientificResult:
    return ScientificResult(
        result_type="scipy",
        value=result,
        method=method,
        variables=variables or [],
        citation=citation,
        units=units or {},
        parameters=parameters or {},
        seed=seed,
    )


def wrap_statsmodels_result(
    method: str,
    result: Any,
    variables: Optional[List[VariableMetadata]] = None,
    citation: Optional[str] = None,
    units: Optional[Dict[str, str]] = None,
    parameters: Optional[Dict[str, Any]] = None,
