@dataclass
class ExperimentRun:
    run_id: str
    name: str
    start_time: str
    end_time: Optional[str] = None
    params: Dict[str, Any] = field(default_factory=dict)
    metrics: Dict[str, List[Dict[str, Any]]] = field(default_factory=dict)
    artifacts: Dict[str, str] = field(default_factory=dict)
    tags: Dict[str, str] = field(default_factory=dict)
    environment: Dict[str, Any] = field(default_factory=_get_environment_metadata)
    seed: Optional[int] = None
    status: str = "running"
    data_hashes: Dict[str, str] = field(default_factory=dict)
    notes: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class ExperimentTracker:
    """
    Tracks experiment runs with parameters, metrics over steps, artifacts,
    and metadata. Supports persistence to a JSON-lines log file.

    Usage:
        tracker = ExperimentTracker(log_dir="./experiments")
        with tracker.start_run("baseline_model", params={"alpha": 0.5}) as run:
            run.log_metric("rmse", 0.23)
            run.log_artifact("model_summary", "text goes here")
    """

    def __init__(self, log_dir: Optional[str] = None):
        self.log_dir = log_dir
        if log_dir:
            os.makedirs(log_dir, exist_ok=True)
        self._runs: Dict[str, ExperimentRun] = {}
        self._active_run: Optional[str] = None

    @contextmanager
    def start_run(
        self,
        name: str,
        params: Optional[Dict[str, Any]] = None,
        tags: Optional[Dict[str, str]] = None,
        seed: Optional[int] = None,
    ):
        run_id = str(uuid.uuid4())
        used_seed = seed if seed is not None else get_global_seed_manager().seed
        run = ExperimentRun(
            run_id=run_id,
            name=name,
            start_time=_now_iso(),
            params=params or {},
            tags=tags or {},
            seed=used_seed,
        )
        self._runs[run_id] = run
        prev_active = self._active_run
        self._active_run = run_id
        handle = _RunHandle(self, run)
        try:
            yield handle
            run.status = "completed"
        except Exception as e:
            run.status = "failed"
            run.notes.append(f"Exception: {repr(e)}")
            raise
        finally:
            run.end_time = _now_iso()
            self._active_run = prev_active
            self._persist(run)

    def log_param(self, run_id: str, key: str, value: Any) -> None:
        self._runs[run_id].params[key] = value

    def log_metric(self, run_id: str, key: str, value: float, step: int = 0) -> None:
        run = self._runs[run_id]
        run.metrics.setdefault(key, []).append(
            {"step": step, "value": float(value), "timestamp": _now_iso()}
        )

    def log_artifact(self, run_id: str, key: str, content: Union[str, bytes]) -> str:
        run = self._runs[run_id]
        if self.log_dir:
            artifact_dir = os.path.join(self.log_dir, run_id, "artifacts")
            os.makedirs(artifact_dir, exist_ok=True)
            path = os.path.join(artifact_dir, key)
            mode = "wb" if isinstance(content, bytes) else "w"
            with open(path, mode) as f:
                f.write(content)
            run.artifacts[key] = path
            return path
        else:
            run.artifacts[key] = "<in-memory, not persisted>"
            return run.artifacts[key]

    def log_dataframe(self, run_id: str, key: str, df: pd.DataFrame) -> str:
        run = self._runs[run_id]
        h = _hash_dataframe(df)
        run.data_hashes[key] = h
        if self.log_dir:
            data_dir = os.path.join(self.log_dir, run_id, "data")
            os.makedirs(data_dir, exist_ok=True)
            path = os.path.join(data_dir, f"{key}.csv")
            df.to_csv(path, index=True)
        return h

    def add_note(self, run_id: str, note: str) -> None:
        self._runs[run_id].notes.append(note)

    def _persist(self, run: ExperimentRun) -> None:
        if not self.log_dir:
            return
        run_dir = os.path.join(self.log_dir, run.run_id)
        os.makedirs(run_dir, exist_ok=True)
        path = os.path.join(run_dir, "run.json")
        with open(path, "w") as f:
            json.dump(run.to_dict(), f, indent=2, default=_json_default)
        # Append to master log
        master_log = os.path.join(self.log_dir, "runs.jsonl")
        with open(master_log, "a") as f:
            f.write(json.dumps(run.to_dict(), default=_json_default) + "\n")

    def get_run(self, run_id: str) -> ExperimentRun:
        return self._runs[run_id]

    def list_runs(self) -> List[ExperimentRun]:
        return list(self._runs.values())

    def compare_runs(self, metric: str) -> pd.DataFrame:
        rows = []
        for run in self._runs.values():
            values = run.metrics.get(metric, [])
            last_val = values[-1]["value"] if values else None
            rows.append(
                {
                    "run_id": run.run_id,
                    "name": run.name,
                    "status": run.status,
                    metric: last_val,
                    **run.params,
                }
            )
        return pd.DataFrame(rows)


class _RunHandle:
    """Convenience handle bound to a specific active run within a tracker."""

    def __init__(self, tracker: ExperimentTracker, run: ExperimentRun):
        self._tracker = tracker
        self._run = run

    @property
    def run_id(self) -> str:
        return self._run.run_id

    @property
    def record(self) -> ExperimentRun:
        return self._run

    def log_param(self, key: str, value: Any) -> None:
        self._tracker.log_param(self._run.run_id, key, value)

    def log_metric(self, key: str, value: float, step: int = 0) -> None:
        self._tracker.log_metric(self._run.run_id, key, value, step)

    def log_artifact(self, key: str, content: Union[str, bytes]) -> str:
        return self._tracker.log_artifact(self._run.run_id, key, content)

    def log_dataframe(self, key: str, df: pd.DataFrame) -> str:
        return self._tracker.log_dataframe(self._run.run_id, key, df)

    def log_result(self, key: str, result: ScientificResult) -> str:
        return self._tracker.log_artifact(
            self._run.run_id, key, result.to_json()
        )

    def add_note(self, note: str) -> None:
        self._tracker.add_note(self._run.run_id, note)


