        self.clinical_notes[note_id]["signed"] = True
        self.clinical_notes[note_id]["signed_by"] = provider_id
        self.clinical_notes[note_id]["signed_at"] = self._now()
        self._log("sign_clinical_note", {"note_id": note_id})

