        claim["status"] = status
        claim["paid_amount"] = paid_amount
        claim["adjudication_notes"] = notes
        claim["adjudicated_at"] = self._now()

        if status == ClaimStatus.PAID and paid_amount > 0:
            self.apply_payment(claim["invoice_id"], paid_amount, payment_source="insurance")

        self._log("adjudicate_claim", {"claim_id": claim_id, "status": status.value})
