    def generate_regulatory_report(self, report_type, start_date, end_date):
        report_id = self._new_id("REP-")

        def in_range(timestamp_str):
            try:
                ts = datetime.datetime.fromisoformat(timestamp_str)
            except (ValueError, TypeError):
                return False
            return start_date <= ts <= end_date

        data = {}
        if report_type == "patient_census":
            data["total_patients"] = len(self.patients)
            data["active_patients"] = sum(1 for p in self.patients.values() if p["active"])
        elif report_type == "clinical_activity":
            data["total_notes"] = sum(1 for n in self.clinical_notes.values()
                                       if in_range(n["created_at"]))
            data["total_orders"] = sum(1 for o in self.orders.values()
                                        if in_range(o["created_at"]))
        elif report_type == "pharmacy_activity":
            data["total_prescriptions"] = sum(1 for rx in self.prescriptions.values()
