            data["total_collected"] = sum(i["amount_paid"] for i in self.invoices.values()
                                           if in_range(i["created_at"]))
        elif report_type == "quality":
            data["metrics"] = self.get_metrics_summary()
        else:
            raise ValueError(f"Unknown report type: {report_type}")

        report = {
            "report_id": report_id,
            "report_type": report_type,
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat(),
            "data": data,
            "generated_at": self._now()
        }
        self.regulatory_reports[report_id] = report
        self._log("generate_regulatory_report", {"report_id": report_id, "report_type": report_type})
        return report

