        market: Optional[str] = None,
        assume_naive_is: str = "UTC",
    ) -> Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]:
        """Localize naive datetimes to a market timezone (via an intermediate tz)."""
        tz = self.get_timezone(market)

        def _localize_index(idx: pd.DatetimeIndex) -> pd.DatetimeIndex:
            if idx.tz is None:
                idx = idx.tz_localize(assume_naive_is)
            return idx.tz_convert(tz)

        if isinstance(data, pd.DatetimeIndex):
            return _localize_index(data)
        elif isinstance(data, (pd.Series, pd.DataFrame)):
            new_data = data.copy()
            new_data.index = _localize_index(pd.DatetimeIndex(new_data.index))
            return new_data
        else:
            raise TypeError("Unsupported type for localization")

