        self,
        data: Union[pd.Series, pd.DataFrame, pd.DatetimeIndex],
        to_market: str,
    ) -> Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]:
        """Convert tz-aware data to another market's timezone."""
        tz = self.get_timezone(to_market)

        if isinstance(data, pd.DatetimeIndex):
            if data.tz is None:
                raise ValueError("Index must be tz-aware to convert")
            return data.tz_convert(tz)
        elif isinstance(data, (pd.Series, pd.DataFrame)):
            idx = pd.DatetimeIndex(data.index)
            if idx.tz is None:
                raise ValueError("Index must be tz-aware to convert")
            new_data = data.copy()
            new_data.index = idx.tz_convert(tz)
            return new_data
        else:
            raise TypeError("Unsupported type for conversion")

    def to_utc(
        self, data: Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]
    ) -> Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]:
        return self.convert(data, "UTC")

