class TradingCalendar:
    """Represents a market trading calendar with holidays and sessions."""

    def __init__(
        self,
        market: str = "NYSE",
        open_time: dt.time = dt.time(9, 30),
        close_time: dt.time = dt.time(16, 0),
        weekmask: str = "Mon Tue Wed Thu Fri",
    ):
        self.market = market
        self.open_time = open_time
        self.close_time = close_time
        self.weekmask = weekmask
        self._holiday_cache: Dict[int, List[pd.Timestamp]] = {}

    # -- holiday calculation helpers -----------------------------------

    @staticmethod
    def _nth_weekday(year: int, month: int, weekday: int, n: int) -> pd.Timestamp:
        """weekday: Monday=0 ... Sunday=6. n=1 for first occurrence, etc."""
        d = dt.date(year, month, 1)
        offset = (weekday - d.weekday()) % 7
        d = d + dt.timedelta(days=offset + 7 * (n - 1))
        return pd.Timestamp(d)

    @staticmethod
    def _last_weekday(year: int, month: int, weekday: int) -> pd.Timestamp:
        if month == 12:
            next_month = dt.date(year + 1, 1, 1)
        else:
            next_month = dt.date(year, month + 1, 1)
        d = next_month - dt.timedelta(days=1)
        offset = (d.weekday() - weekday) % 7
        d = d - dt.timedelta(days=offset)
        return pd.Timestamp(d)

    @staticmethod
    def _observed(date: pd.Timestamp) -> pd.Timestamp:
        """Adjust for weekend observance (Sat -> Fri, Sun -> Mon)."""
        if date.weekday() == 5:
            return date - pd.Timedelta(days=1)
        elif date.weekday() == 6:
            return date + pd.Timedelta(days=1)
        return date

    @staticmethod
    def _easter(year: int) -> dt.date:
        """Anonymous Gregorian algorithm for Easter Sunday."""
        a = year % 19
        b = year // 100
        c = year % 100
        d_ = b // 4
        e = b % 4
        f = (b + 8) // 25
        g = (b - f + 1) // 3
        h = (19 * a + b - d_ - g + 15) % 30
        i = c // 4
        k = c % 4
        l = (32 + 2 * e + 2 * i - h - k) % 7
        m = (a + 11 * h + 22 * l) // 451
        month = (h + l - 7 * m + 114) // 31
        day = ((h + l - 7 * m + 114) % 31) + 1
        return dt.date(year, month, day)

    def holidays(self, year: int) -> List[pd.Timestamp]:
        """Compute US market holidays for a given year (used for NYSE/NASDAQ style)."""
        if year in self._holiday_cache:
            return self._holiday_cache[year]

        h: List[pd.Timestamp] = []
        h.append(self._observed(pd.Timestamp(year, 1, 1)))  # New Year
        h.append(self._nth_weekday(year, 1, 0, 3))  # MLK day, 3rd Monday Jan
        h.append(self._nth_weekday(year, 2, 0, 3))  # Presidents day, 3rd Monday Feb
        easter = self._easter(year)
        good_friday = pd.Timestamp(easter) - pd.Timedelta(days=2)
        h.append(good_friday)
        h.append(self._last_weekday(year, 5, 0))  # Memorial day, last Monday May
        if year >= 2022:
            h.append(self._observed(pd.Timestamp(year, 6, 19)))  # Juneteenth
        h.append(self._observed(pd.Timestamp(year, 7, 4)))  # Independence day
        h.append(self._nth_weekday(year, 9, 0, 1))  # Labor day, 1st Monday Sept
        h.append(self._nth_weekday(year, 11, 3, 4))  # Thanksgiving, 4th Thursday Nov
        h.append(self._observed(pd.Timestamp(year, 12, 25)))  # Christmas

        h = sorted(set(h))
        self._holiday_cache[year] = h
        return h

    def holiday_index(self, start_year: int, end_year: int) -> pd.DatetimeIndex:
        all_holidays: List[pd.Timestamp] = []
        for y in range(start_year, end_year + 1):
            all_holidays.extend(self.holidays(y))
        return pd.DatetimeIndex(sorted(all_holidays))

    def schedule(self, start: Union[str, dt.date], end: Union[str, dt.date]) -> pd.DataFrame:
        """Return a DataFrame with market_open/market_close columns for each session."""
        start_ts = pd.Timestamp(start)
        end_ts = pd.Timestamp(end)
        holidays = self.holiday_index(start_ts.year - 1, end_ts.year + 1)

        sessions = np.busday_offset(
            np.arange(
                np.datetime64(start_ts.date()),
                np.datetime64(end_ts.date()) + np.timedelta64(1, "D"),
            ),
            0,
            roll="forward",
            weekmask=self.weekmask,
            holidays=holidays.values.astype("datetime64[D]"),
        )
        # np.busday_offset above just validates; better to filter directly
        all_days = pd.date_range(start_ts, end_ts, freq="D")
        holiday_set = set(holidays.date)
        valid_days = [
            d for d in all_days
            if d.weekday() < 5 and d.date() not in holiday_set
        ]
        idx = pd.DatetimeIndex(valid_days)

        opens = [pd.Timestamp.combine(d.date(), self.open_time) for d in idx]
        closes = [pd.Timestamp.combine(d.date(), self.close_time) for d in idx]

        return pd.DataFrame(
            {"market_open": opens, "market_close": closes}, index=idx
        )

    def is_trading_day(self, date: Union[str, dt.date]) -> bool:
        ts = pd.Timestamp(date)
        if ts.weekday() >= 5:
            return False
        return ts.normalize() not in [h.normalize() for h in self.holidays(ts.year)]

    def trading_days(
        self, start: Union[str, dt.date], end: Union[str, dt.date]
    ) -> pd.DatetimeIndex:
        return self.schedule(start, end).index

    def next_trading_day(self, date: Union[str, dt.date]) -> pd.Timestamp:
        ts = pd.Timestamp(date)
        candidate = ts + pd.Timedelta(days=1)
        while not self.is_trading_day(candidate):
            candidate += pd.Timedelta(days=1)
        return candidate.normalize()

    def previous_trading_day(self, date: Union[str, dt.date]) -> pd.Timestamp:
        ts = pd.Timestamp(date)
        candidate = ts - pd.Timedelta(days=1)
        while not self.is_trading_day(candidate):
            candidate -= pd.Timedelta(days=1)
        return candidate.normalize()

    def add_trading_days(self, date: Union[str, dt.date], n: int) -> pd.Timestamp:
        ts = pd.Timestamp(date).normalize()
        step = 1 if n >= 0 else -1
        remaining = abs(n)
        while remaining > 0:
            ts = ts + pd.Timedelta(days=step)
            if self.is_trading_day(ts):
                remaining -= 1
        return ts

    def sessions_between(
        self, start: Union[str, dt.date], end: Union[str, dt.date]
    ) -> int:
        return len(self.trading_days(start, end))


