class CorporateActionsManager:
    """Manages corporate actions and applies price/volume adjustments."""

    def __init__(self):
        self._actions: Dict[str, List[CorporateAction]] = {}

    def add_action(self, action: CorporateAction) -> None:
        self._actions.setdefault(action.symbol, []).append(action)
        self._actions[action.symbol].sort(key=lambda a: a.ex_date)

    def add_dividend(
        self, symbol: str, ex_date: Union[str, dt.date], amount: float, **kwargs
    ) -> None:
        self.add_action(
            CorporateAction(
                symbol=symbol,
                action_type=CorporateActionType.DIVIDEND,
                ex_date=pd.Timestamp(ex_date),
                value=amount,
                **kwargs,
            )
        )

    def add_split(
        self, symbol: str, ex_date: Union[str, dt.date], ratio: float, **kwargs
    ) -> None:
        """ratio = new_shares / old_shares, e.g. 2.0 for a 2-for-1 split."""
        self.add_action(
            CorporateAction(
                symbol=symbol,
                action_type=CorporateActionType.SPLIT,
                ex_date=pd.Timestamp(ex_date),
                value=ratio,
                **kwargs,
            )
        )

    def get_actions(
        self, symbol: str, action_type: Optional[CorporateActionType] = None
    ) -> List[CorporateAction]:
        actions = self._actions.get(symbol, [])
        if action_type is not None:
            actions = [a for a in actions if a.action_type == action_type]
        return actions

    def get_adjustment_factors(
        self, symbol: str, index: pd.DatetimeIndex
    ) -> pd.Series:
        """
        Compute cumulative price adjustment factor for each date in index,
        combining splits and dividends (back-adjusted, standard total-return style).
        Factor is applied by multiplying raw historical prices.
        """
        actions = self.get_actions(symbol)
        factors = pd.Series(1.0, index=index)
        if not actions:
            return factors

        # process from most recent to oldest, accumulating factor for dates before ex_date
        cum_factor = 1.0
        sorted_actions = sorted(actions, key=lambda a: a.ex_date, reverse=True)

        for action in sorted_actions:
            if action.action_type == CorporateActionType.SPLIT:
                # prices before split date get divided by ratio (for back-adjustment,
                # multiply by 1/ratio)
                local_factor = 1.0 / action.value
            elif action.action_type == CorporateActionType.DIVIDEND:
                # need close price at ex_date - 1 to compute properly; approximate
                # using simple factor placeholder of 1.0 unless price provided.
                local_factor = 1.0
            else:
                local_factor = 1.0

            mask = index < action.ex_date
            cum_factor *= local_factor
            factors.loc[mask] = factors.loc[mask] * local_factor

        return factors

    def adjust_dividend_factor(
        self, symbol: str, close_prices: pd.Series
    ) -> pd.Series:
        """
        Compute back-adjustment factors incorporating dividends using
        the standard formula: factor *= (1 - dividend / prev_close) applied
        cumulatively backwards through history.
        """
        actions = self.get_actions(symbol, CorporateActionType.DIVIDEND)
        factors = pd.Series(1.0, index=close_prices.index)
        if not actions:
            return factors

        sorted_actions = sorted(actions, key=lambda a: a.ex_date, reverse=True)
        cum_factor = 1.0

        for action in sorted_actions:
            ex_date = action.ex_date
            prior_dates = close_prices.index[close_prices.index < ex_date]
            if len(prior_dates) == 0:
                continue
