class TimeZoneManager:
    """Handles time zone conversions and localization for market data."""

    MARKET_TIMEZONES: Dict[str, str] = {
        "NYSE": "America/New_York",
        "NASDAQ": "America/New_York",
        "LSE": "Europe/London",
        "TSE": "Asia/Tokyo",
        "HKEX": "Asia/Hong_Kong",
        "SSE": "Asia/Shanghai",
        "ASX": "Australia/Sydney",
        "TSX": "America/Toronto",
        "EURONEXT": "Europe/Paris",
        "FRA": "Europe/Berlin",
        "UTC": "UTC",
    }

    def __init__(self, default_market: str = "NYSE"):
        self.default_market = default_market

    def get_timezone(self, market: Optional[str] = None) -> str:
        market = market or self.default_market
        if market not in self.MARKET_TIMEZONES:
            raise ValueError(f"Unknown market: {market}")
        return self.MARKET_TIMEZONES[market]

    def localize(
        self,
        data: Union[pd.Series, pd.DataFrame, pd.DatetimeIndex],
        market: Optional[str] = None,
        assume_naive_is: str = "UTC",
    ) -> Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]:
        """Localize naive datetimes to a market timezone (via an intermediate tz)."""
        tz = self.get_timezone(market)

        def _localize_index(idx: pd.DatetimeIndex) -> pd.DatetimeIndex:
            if idx.tz is None:
                idx = idx.tz_localize(assume_naive_is)
            return idx.tz_convert(tz)

        if isinstance(data, pd.DatetimeIndex):
            return _localize_index(data)
        elif isinstance(data, (pd.Series, pd.DataFrame)):
            new_data = data.copy()
            new_data.index = _localize_index(pd.DatetimeIndex(new_data.index))
            return new_data
        else:
            raise TypeError("Unsupported type for localization")

    def convert(
        self,
        data: Union[pd.Series, pd.DataFrame, pd.DatetimeIndex],
        to_market: str,
    ) -> Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]:
        """Convert tz-aware data to another market's timezone."""
        tz = self.get_timezone(to_market)

        if isinstance(data, pd.DatetimeIndex):
            if data.tz is None:
                raise ValueError("Index must be tz-aware to convert")
            return data.tz_convert(tz)
        elif isinstance(data, (pd.Series, pd.DataFrame)):
            idx = pd.DatetimeIndex(data.index)
            if idx.tz is None:
                raise ValueError("Index must be tz-aware to convert")
            new_data = data.copy()
            new_data.index = idx.tz_convert(tz)
            return new_data
        else:
            raise TypeError("Unsupported type for conversion")

    def to_utc(
        self, data: Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]
    ) -> Union[pd.Series, pd.DataFrame, pd.DatetimeIndex]:
        return self.convert(data, "UTC")

    def market_time_now(self, market: Optional[str] = None) -> pd.Timestamp:
        tz = self.get_timezone(market)
        return pd.Timestamp.now(tz=tz)

    def is_market_hours(
        self,
        timestamp: pd.Timestamp,
        market: Optional[str] = None,
        open_time: dt.time = dt.time(9, 30),
        close_time: dt.time = dt.time(16, 0),
    ) -> bool:
        tz = self.get_timezone(market)
        if timestamp.tzinfo is None:
            ts = timestamp.tz_localize(tz)
        else:
            ts = timestamp.tz_convert(tz)
        t = ts.time()
        return open_time <= t <= close_time


