            self.commit_inventory(order)
            order.set_status(OrderStatus.COMPLETED)
            self.send_notification(order, "order_completed")
        except OrderProcessingError as e:
            self.release_reserved_inventory(order)
            order.error_message = str(e)
            order.set_status(OrderStatus.FAILED)
            self.send_notification(order, "order_failed", {"error": str(e)})
            raise
        return order

    def cancel_order(self, order_id: str) -> Order:
        order = self._get_order(order_id)
        if order.status in (OrderStatus.COMPLETED, OrderStatus.SHIPPED):
            raise OrderProcessingError("Cannot cancel an order that has already shipped or completed.")
        self.release_reserved_inventory(order)
        order.set_status(OrderStatus.CANCELLED)
        self.send_notification(order, "order_cancelled")
