    def serialize_total_revenue(self) -> Dict[str, Any]:
        return {"metric": "total_revenue", "value": self.calculator.calculate_total_revenue()}

    def serialize_error_rate(self) -> Dict[str, Any]:
        return {"metric": "error_rate", "value": self.calculator.calculate_error_rate()}

    def build_response(self) -> Dict[str, Any]:
        return {
            "status": "ok",
            "metrics": [
