class Quantity:
    """
    A value (scalar or numpy array) associated with a physical unit.
    Supports arithmetic with automatic unit propagation and conversion.
    """

    __array_priority__ = 1000

    def __init__(self, value, unit="dimensionless"):
        self.value = np.asarray(value, dtype=float)
        if isinstance(unit, str):
            unit = UNITS[unit]
        self.unit = unit

    def to(self, target_unit):
        """Convert quantity to a compatible unit, returning a new Quantity."""
        if isinstance(target_unit, str):
            target_unit = UNITS[target_unit]
        if not self.unit.is_compatible(target_unit):
            raise UnitError(f"Cannot convert {self.unit} to {target_unit}")
        base_value = self.value * self.unit.scale + self.unit.offset
        new_value = (base_value - target_unit.offset) / target_unit.scale
        return Quantity(new_value, target_unit)

    def base_value(self):
        """Return the value expressed in SI base units."""
        return self.value * self.unit.scale + self.unit.offset

    def _binary_op(self, other, op, require_same_unit=False):
        if isinstance(other, Quantity):
            if require_same_unit:
                if not self.unit.is_compatible(other.unit):
                    raise UnitError(
                        f"Incompatible units: {self.unit} vs {other.unit}"
                    )
                other_val = other.to(self.unit).value
                result_val = op(self.value, other_val)
                return Quantity(result_val, self.unit)
            else:
                raise UnitError("Operation requires explicit unit handling")
        else:
            return Quantity(op(self.value, other), self.unit)

    def __add__(self, other):
        return self._binary_op(other, lambda a, b: a + b, require_same_unit=True)

    def __sub__(self, other):
        return self._binary_op(other, lambda a, b: a - b, require_same_unit=True)

    def __mul__(self, other):
        if isinstance(other, Quantity):
            new_val = self.value * other.value
            new_unit = self.unit * other.unit
            return Quantity(new_val, new_unit)
        return Quantity(self.value * other, self.unit)

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Quantity):
            new_val = self.value / other.value
            new_unit = self.unit / other.unit
            return Quantity(new_val, new_unit)
        return Quantity(self.value / other, self.unit)

    def __pow__(self, power):
        return Quantity(self.value ** power, self.unit ** power)

    def __neg__(self):
        return Quantity(-self.value, self.unit)

    def __repr__(self):
        return f"Quantity({self.value}, {self.unit!r})"

    def __array__(self, dtype=None):
        return np.asarray(self.value, dtype=dtype)


def quantity(value, unit):
    """Convenience constructor for Quantity."""
    return Quantity(value, unit)


def convert(value, from_unit, to_unit):
    """Convert a raw numeric value between two compatible units."""
    q = Quantity(value, from_unit)
    return q.to(to_unit).value


