class UncertainValue:
    """
    Represents a value with an associated standard uncertainty and supports
    linear (first-order) uncertainty propagation through arithmetic
    operations, assuming independent errors unless covariance is given.
    """

    __array_priority__ = 1000

    def __init__(self, value, uncertainty=0.0):
        self.value = np.asarray(value, dtype=float)
        self.uncertainty = np.abs(np.asarray(uncertainty, dtype=float))

    @property
    def nominal(self):
        return self.value

    @property
    def std(self):
        return self.uncertainty

    def __repr__(self):
        return f"UncertainValue({self.value} +/- {self.uncertainty})"

    def _as_uv(self, other):
        if isinstance(other, UncertainValue):
            return other
        return UncertainValue(other, 0.0)

    def __add__(self, other):
        o = self._as_uv(other)
        val = self.value + o.value
        unc = np.sqrt(self.uncertainty ** 2 + o.uncertainty ** 2)
        return UncertainValue(val, unc)

    __radd__ = __add__

    def __sub__(self, other):
        o = self._as_uv(other)
        val = self.value - o.value
        unc = np.sqrt(self.uncertainty ** 2 + o.uncertainty ** 2)
        return UncertainValue(val, unc)

    def __rsub__(self, other):
        o = self._as_uv(other)
        return o.__sub__(self)

    def __mul__(self, other):
        o = self._as_uv(other)
        val = self.value * o.value
        # partial derivatives: d(val)/d(self)=o.value, d(val)/d(other)=self.value
        unc = np.sqrt((o.value * self.uncertainty) ** 2 +
                      (self.value * o.uncertainty) ** 2)
        return UncertainValue(val, unc)

    __rmul__ = __mul__

    def __truediv__(self, other):
        o = self._as_uv(other)
        val = self.value / o.value
        d_self = 1.0 / o.value
        d_other = -self.value / (o.value ** 2)
        unc = np.sqrt((d_self * self.uncertainty) ** 2 +
                      (d_other * o.uncertainty) ** 2)
        return UncertainValue(val, unc)

    def __rtruediv__(self, other):
        o = self._as_uv(other)
        return o.__truediv__(self)

    def __pow__(self, power):
        val = self.value ** power
        deriv = power * self.value ** (power - 1)
        unc = np.abs(deriv) * self.uncertainty
        return UncertainValue(val, unc)

    def __neg__(self):
        return UncertainValue(-self.value, self.uncertainty)

    def __abs__(self):
        return UncertainValue(np.abs(self.value), self.uncertainty)

    def __array__(self, dtype=None):
        return np.asarray(self.value, dtype=dtype)


def _propagate_unary(uv, func, dfunc):
    """Generic helper for propagating uncertainty through a unary function."""
    val = func(uv.value)
    deriv = dfunc(uv.value)
    unc = np.abs(deriv) * uv.uncertainty
    return UncertainValue(val, unc)


def u_sin(uv):
    return _propagate_unary(uv, np.sin, np.cos)


def u_cos(uv):
    return _propagate_unary(uv, np.cos, lambda x: -np.sin(x))


def u_exp(uv):
    return _propagate_unary(uv, np.exp, np.exp)


def u_log(uv):
    return _propagate_unary(uv, np.log, lambda x: 1.0 / x)


def u_sqrt(uv):
    return _propagate_unary(uv, np.sqrt, lambda x: 0.5 / np.sqrt(x))


def combine_uncertainties(values, uncertainties, weights=None):
    """
    Combine multiple correlated-independent measurements using
    inverse-variance weighting (if weights not given), returning
    (combined_value, combined_uncertainty).
    """
    values = np.asarray(values, dtype=float)
    uncertainties = np.asarray(uncertainties, dtype=float)
    if weights is None:
        weights = 1.0 / (uncertainties ** 2)
    weights = np.asarray(weights, dtype=float)
    combined_value = np.sum(weights * values) / np.sum(weights)
    combined_unc = np.sqrt(1.0 / np.sum(weights))
    return combined_value, combined_unc


def covariance_propagate(jacobian, cov_matrix):
    """
    Propagate uncertainty through a linear(ized) transform.

    jacobian: shape (m, n) - derivatives of m outputs w.r.t. n inputs
    cov_matrix: shape (n, n) - covariance matrix of inputs

    Returns the (m, m) covariance matrix of outputs: J @ Cov @ J.T
    """
    J = np.asarray(jacobian, dtype=float)
    C = np.asarray(cov_matrix, dtype=float)
    return J @ C @ J.T


def monte_carlo_propagate(func, values, uncertainties, n_samples=100000,
                           random_state=None):
    """
    Estimate output uncertainty of `func` applied to inputs with given
    nominal values and (assumed Gaussian, independent) uncertainties,
    via Monte Carlo sampling.

    Returns (mean, std) of the output distribution.
    """
    rng = np.random.default_rng(random_state)
    values = np.asarray(values, dtype=float)
    uncertainties = np.asarray(uncertainties, dtype=float)
    n_inputs = values.shape[0]

    samples = rng.normal(
        loc=values[:, None],
        scale=uncertainties[:, None],
        size=(n_inputs, n_samples),
    )
    outputs = func(*samples)
    outputs = np.asarray(outputs, dtype=float)
    return np.mean(outputs), np.std(outputs)


