def normalize_signal(x, mode="zscore"):
    """
    Normalize a 1D or 2D (rows=channels) signal.

    mode: 'zscore', 'minmax', or 'unit_energy'
    """
    x = np.asarray(x, dtype=float)
    axis = -1

    if mode == "zscore":
        mean = np.mean(x, axis=axis, keepdims=True)
        std = np.std(x, axis=axis, keepdims=True)
        std = np.where(std == 0, 1.0, std)
        return (x - mean) / std

    elif mode == "minmax":
        mn = np.min(x, axis=axis, keepdims=True)
        mx = np.max(x, axis=axis, keepdims=True)
        rng = mx - mn
        rng = np.where(rng == 0, 1.0, rng)
        return (x - mn) / rng

    elif mode == "unit_energy":
        energy = np.sqrt(np.sum(x ** 2, axis=axis, keepdims=True))
        energy = np.where(energy == 0, 1.0, energy)
        return x / energy

    else:
        raise ValueError(f"Unknown normalization mode: {mode}")


def moving_average(x, window, mode="same"):
    """Compute a simple moving average using convolution."""
    x = np.asarray(x, dtype=float)
    kernel = np.ones(window) / window
    return np.convolve(x, kernel, mode=mode)


def moving_rms(x, window):
    """Compute moving root-mean-square of a signal."""
    x = np.asarray(x, dtype=float)
    kernel = np.ones(window) / window
    mean_sq = np.convolve(x ** 2, kernel, mode="same")
    return np.sqrt(mean_sq)


def next_pow2(n):
    """Return the next power of 2 >= n."""
    return 1 if n <= 1 else 2 ** int(math.ceil(math.log2(n)))


def fft_spectrum(x, fs=1.0, n=None, window=None, one_sided=True):
    """
    Compute the amplitude spectrum of a real signal using FFT.

    Returns (freqs, magnitude).
    """
    x = np.asarray(x, dtype=float)
    N = len(x) if n is None else n

    if window is not None:
        if callable(window):
            w = window(len(x))
        elif isinstance(window, str):
            w = get_window(window, len(x))
        else:
            w = np.asarray(window, dtype=float)
        x = x * w

    spectrum = np.fft.fft(x, n=N)
    freqs = np.fft.fftfreq(N, d=1.0 / fs)

    if one_sided:
        half = N // 2 + 1
        freqs = freqs[:half]
        magnitude = np.abs(spectrum[:half]) / N
        if N % 2 == 0:
            magnitude[1:-1] *= 2
        else:
            magnitude[1:] *= 2
    else:
        magnitude = np.abs(spectrum) / N

    return freqs, magnitude


def power_spectral_density(x, fs=1.0, window=None, n=None):
    """Compute a simple periodogram-based power spectral density."""
    x = np.asarray(x, dtype=float)
    N = len(x) if n is None else n

    if window is not None:
        if callable(window):
            w = window(len(x))
        elif isinstance(window, str):
            w = get_window(window, len(x))
        else:
            w = np.asarray(window, dtype=float)
        win_gain = np.sum(w ** 2)
        x = x * w
    else:
        win_gain = N

    spectrum = np.fft.fft(x, n=N)
    freqs = np.fft.fftfreq(N, d=1.0 / fs)

    half = N // 2 + 1
    freqs = freqs[:half]
    psd = (np.abs(spectrum[:half]) ** 2) / (fs * win_gain)
    if N % 2 == 0:
        psd[1:-1] *= 2
    else:
        psd[1:] *= 2

    return freqs, psd


def get_window(name, length):
    """Return a window function array by name."""
    name = name.lower()
    n = np.arange(length)
    if name == "hann":
        return 0.5 - 0.5 * np.cos(2 * np.pi * n / (length - 1))
    elif name == "hamming":
        return 0.54 - 0.46 * np.cos(2 * np.pi * n / (length - 1))
    elif name == "blackman":
        return (0.42 - 0.5 * np.cos(2 * np.pi * n / (length - 1)) +
                0.08 * np.cos(4 * np.pi * n / (length - 1)))
    elif name in ("rect", "rectangular", "boxcar"):
        return np.ones(length)
    elif name == "bartlett":
        return 1.0 - np.abs((n - (length - 1) / 2.0) / ((length - 1) / 2.0))
    else:
        raise ValueError(f"Unknown window: {name}")


def _design_lowpass_kernel(cutoff, fs, numtaps):
    """Design a windowed-sinc lowpass FIR filter kernel."""
    nyq = fs / 2.0
    normalized_cutoff = cutoff / nyq
    m = numtaps - 1
    n = np.arange(numtaps)
    h = np.sinc(normalized_cutoff * (n - m / 2.0))
    window = get_window("hamming", numtaps)
    h = h * window
    h = h / np.sum(h)
    return h


def lowpass_filter(x, cutoff, fs, numtaps=101):
    """Apply an FIR lowpass filter via convolution (zero-phase, same length)."""
    x = np.asarray(x, dtype=float)
    if numtaps % 2 == 0:
        numtaps += 1
    kernel = _design_lowpass_kernel(cutoff, fs, numtaps)
    return np.convolve(x, kernel, mode="same")


def highpass_filter(x, cutoff, fs, numtaps=101):
    """Apply an FIR highpass filter via spectral inversion of a lowpass kernel."""
    x = np.asarray(x, dtype=float)
    if numtaps % 2 == 0:
        numtaps += 1
    lp_kernel = _design_lowpass_kernel(cutoff, fs, numtaps)
    hp_kernel = -lp_kernel
    mid = numtaps // 2
    hp_kernel[mid] += 1.0
    return np.convolve(x, hp_kernel, mode="same")


def bandpass_filter(x, low_cutoff, high_cutoff, fs, numtaps=101):
    """Apply an FIR bandpass filter (lowpass followed by highpass cascade)."""
    x = np.asarray(x, dtype=float)
    stage1 = lowpass_filter(x, high_cutoff, fs, numtaps=numtaps)
    stage2 = highpass_filter(stage1, low_cutoff, fs, numtaps=numtaps)
    return stage2


def bandstop_filter(x, low_cutoff, high_cutoff, fs, numtaps=101):
    """Apply an FIR bandstop (notch) filter via lowpass+highpass sum."""
    x = np.asarray(x, dtype=float)
    lp = lowpass_filter(x, low_cutoff, fs, numtaps=numtaps)
    hp = highpass_filter(x, high_cutoff, fs, numtaps=numtaps)
    return lp + hp


def detrend(x, kind="linear"):
    """Remove a constant or linear trend from a signal."""
    x = np.asarray(x, dtype=float)
    if kind == "constant":
        return x - np.mean(x)
    elif kind == "linear":
        n = len(x)
        t = np.arange(n)
        A = np.vstack([t, np.ones(n)]).T
        coeffs, _, _, _ = np.linalg.lstsq(A, x, rcond=None)
        trend = A @ coeffs
        return x - trend
    else:
        raise ValueError(f"Unknown detrend kind: {kind}")


def find_peaks(x, height=None, distance=1, prominence=None):
    """
    Simple peak-finding algorithm.

    Returns indices of local maxima satisfying height/distance/prominence
    criteria.
    """
    x = np.asarray(x, dtype=float)
    n = len(x)
    candidates = []
    for i in range(1, n - 1):
