            discount_rate = self.provider_network[provider_id].get(
                'discount_rate', 0.0
            )
            return billed_amount * discount_rate

        return 0.0

    def _apply_deductible(self, amount):
        deductible_remaining = self.policy.get('deductible_remaining', 0.0)

        if deductible_remaining <= 0:
            return 0.0

        applied = min(amount, deductible_remaining)
        return applied

    def _calculate_copay(self, claim):
        if not self.coverage_results.get('is_covered', False):
            return 0.0

        service_type = claim.get('service_type', 'general')
        copay_schedule = self.policy.get('copay_schedule', {})

        return copay_schedule.get(service_type, 0.0)

    def _calculate_coinsurance(self, remaining_amount, claim):
        if not self.coverage_results.get('is_covered', False):
            return remaining_amount

        coverage_percentage = self.coverage_results.get(
            'coverage_percentage', 0
        )
        coinsurance_rate = 1.0 - (coverage_percentage / 100.0)

        return remaining_amount * coinsurance_rate
