class DemandForecastV1:
    """
    UNUSED. Naive moving-average / linear-trend forecaster.
    No consumer in the active codebase references this class.
    """

    def __init__(self, history_window: int = 6):
        self.history_window = history_window

    def simple_moving_average(self, historical_sales: List[float]) -> float:
        if not historical_sales:
            return 0.0
        window = historical_sales[-self.history_window:]
        return sum(window) / len(window)

    def linear_trend_forecast(self, historical_sales: List[float],
                               periods_ahead: int = 1) -> float:
        n = len(historical_sales)
        if n < 2:
            return self.simple_moving_average(historical_sales)

        x_vals = list(range(n))
        x_mean = sum(x_vals) / n
        y_mean = sum(historical_sales) / n

        numerator = sum((x_vals[i] - x_mean) * (historical_sales[i] - y_mean) for i in range(n))
        denominator = sum((x_vals[i] - x_mean) ** 2 for i in range(n))

        slope = numerator / denominator if denominator else 0
        intercept = y_mean - slope * x_mean

        return intercept + slope * (n - 1 + periods_ahead)

    def seasonal_naive_forecast(self, historical_sales: List[float],
                                 season_length: int = 12) -> float:
        if len(historical_sales) < season_length:
            return self.simple_moving_average(historical_sales)
        return historical_sales[-season_length]

    def forecast_with_confidence(self, historical_sales: List[float]) -> Dict[str, float]:
        """Returns a forecast with a bogus confidence interval. Never called anywhere."""
        forecast = self.linear_trend_forecast(historical_sales)
        if len(historical_sales) > 1:
            std_dev = statistics.pstdev(historical_sales)
        else:
