class StockMovementType(Enum):
    RECEIPT = "receipt"
    ISSUE = "issue"
    ADJUSTMENT = "adjustment"
    TRANSFER = "transfer"


@dataclass
class Product:
    sku: str
    name: str
    unit_cost: float
    reorder_point: int = 10
    reorder_qty: int = 50
    quantity_on_hand: int = 0
    warehouse_id: Optional[str] = None


@dataclass
class StockMovement:
    movement_id: str
    sku: str
    movement_type: StockMovementType
    quantity: int
    timestamp: datetime.datetime
    reference: str = ""


class InsufficientStockError(Exception):
    pass


class ProductNotFoundError(Exception):
    pass


class InventoryManager:
    """
    Fully working inventory management system.
    Handles product catalog, stock levels, movements, and reorder alerts.
    """

    def __init__(self):
        self._products: Dict[str, Product] = {}
        self._movements: List[StockMovement] = []

    # ---- Product catalog management ----

    def add_product(self, product: Product) -> None:
        if product.sku in self._products:
            raise ValueError(f"Product {product.sku} already exists")
        self._products[product.sku] = product

    def get_product(self, sku: str) -> Product:
        if sku not in self._products:
            raise ProductNotFoundError(f"Product {sku} not found")
        return self._products[sku]

    def remove_product(self, sku: str) -> None:
        self.get_product(sku)
        del self._products[sku]

    def list_products(self) -> List[Product]:
        return list(self._products.values())

    # ---- Stock operations ----

    def receive_stock(self, sku: str, quantity: int, reference: str = "") -> StockMovement:
        if quantity <= 0:
            raise ValueError("Quantity must be positive")
        product = self.get_product(sku)
        product.quantity_on_hand += quantity
        movement = self._record_movement(
            sku, StockMovementType.RECEIPT, quantity, reference
        )
        return movement

    def issue_stock(self, sku: str, quantity: int, reference: str = "") -> StockMovement:
        if quantity <= 0:
            raise ValueError("Quantity must be positive")
        product = self.get_product(sku)
        if product.quantity_on_hand < quantity:
            raise InsufficientStockError(
                f"Cannot issue {quantity} of {sku}, only "
                f"{product.quantity_on_hand} available"
            )
        product.quantity_on_hand -= quantity
        movement = self._record_movement(
            sku, StockMovementType.ISSUE, quantity, reference
        )
        return movement

    def adjust_stock(self, sku: str, delta: int, reference: str = "") -> StockMovement:
        product = self.get_product(sku)
        new_qty = product.quantity_on_hand + delta
        if new_qty < 0:
            raise InsufficientStockError("Adjustment would result in negative stock")
        product.quantity_on_hand = new_qty
        movement = self._record_movement(
            sku, StockMovementType.ADJUSTMENT, delta, reference
        )
        return movement

    def transfer_stock(self, sku: str, quantity: int, target_warehouse: str,
                        reference: str = "") -> StockMovement:
        product = self.get_product(sku)
        if product.quantity_on_hand < quantity:
            raise InsufficientStockError("Not enough stock to transfer")
        product.quantity_on_hand -= quantity
        product.warehouse_id = target_warehouse
        movement = self._record_movement(
            sku, StockMovementType.TRANSFER, quantity, reference
        )
        return movement

    def _record_movement(self, sku: str, movement_type: StockMovementType,
                          quantity: int, reference: str) -> StockMovement:
        movement = StockMovement(
            movement_id=str(uuid.uuid4()),
            sku=sku,
            movement_type=movement_type,
            quantity=quantity,
            timestamp=datetime.datetime.utcnow(),
            reference=reference,
        )
        self._movements.append(movement)
        return movement

    # ---- Reporting ----

    def get_movement_history(self, sku: Optional[str] = None) -> List[StockMovement]:
        if sku is None:
            return list(self._movements)
        return [m for m in self._movements if m.sku == sku]

    def get_reorder_alerts(self) -> List[Product]:
        return [
            p for p in self._products.values()
            if p.quantity_on_hand <= p.reorder_point
        ]

    def get_inventory_value(self) -> float:
        return sum(p.quantity_on_hand * p.unit_cost for p in self._products.values())

    def export_snapshot(self) -> str:
        snapshot = {
            sku: {
                "name": p.name,
                "quantity_on_hand": p.quantity_on_hand,
                "unit_cost": p.unit_cost,
                "warehouse_id": p.warehouse_id,
            }
            for sku, p in self._products.items()
        }
        return json.dumps(snapshot, indent=2)


