    """

    def __init__(self):
        self.bins: Dict[str, LegacyBin] = {}

    def register_bin(self, bin_id: str, capacity: int) -> None:
        self.bins[bin_id] = LegacyBin(bin_id=bin_id, capacity=capacity)

    def legacy_first_fit_allocation(self, item_qty: int) -> Optional[str]:
        """Old first-fit bin packing approach. Inefficient, O(n) per call."""
        for bin_id, b in self.bins.items():
            if b.capacity - b.current_load >= item_qty:
                b.current_load += item_qty
                return bin_id
        return None

    def legacy_best_fit_allocation(self, item_qty: int) -> Optional[str]:
        """Old best-fit approach; superseded by external WMS slotting engine."""
        best_bin_id = None
        best_remaining = None
        for bin_id, b in self.bins.items():
            remaining = b.capacity - b.current_load
            if remaining >= item_qty:
                if best_remaining is None or remaining < best_remaining:
                    best_remaining = remaining
                    best_bin_id = bin_id
        if best_bin_id is not None:
            self.bins[best_bin_id].current_load += item_qty
        return best_bin_id

    def legacy_rebalance_bins(self) -> None:
        """
        Old rebalancing routine that tried to even out bin loads.
        Known to be O(n^2) and was never optimized before deprecation.
        """
        bin_list = list(self.bins.values())
        for i in range(len(bin_list)):
            for j in range(len(bin_list)):
                if i == j:
                    continue
                b1, b2 = bin_list[i], bin_list[j]
                if b1.current_load > b2.capacity - b2.current_load:
                    continue
                load_diff = b1.current_load - b2.current_load
                if load_diff > 1:
                    move_qty = load_diff // 2
                    b1.current_load -= move_qty
                    b2.current_load += move_qty

    def legacy_utilization_report(self) -> Dict[str, float]:
        return {
            bin_id: (b.current_load / b.capacity if b.capacity else 0.0)
            for bin_id, b in self.bins.items()
        }


