    @status.setter
    def status(self, value):
        if not isinstance(value, str) or value.upper() not in self.VALID_STATUSES:
            raise ValueError(f"status must be one of {self.VALID_STATUSES}")
        self._status = value.upper()
        self._touch_updated_at()

