import csv
import os
import re
import sqlite3
import logging
import statistics
from datetime import datetime
from typing import Any, Dict, List, Optional, Union, Callable

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger("etl_pipeline")


class SchemaValidationError(Exception):
    """Raised when a record fails schema validation."""
    pass


class ETLPipeline:
    """
    A comprehensive ETL pipeline that:
      1. Reads from multiple CSV sources
      2. Cleans and normalizes data
      3. Handles missing values
      4. Validates against a schema
      5. Performs aggregations
      6. Transforms data into a target format
      7. Exports the result to a SQLite database
    """

    def __init__(
        self,
        schema: Dict[str, Dict[str, Any]],
        missing_value_strategy: str = "fill",
        default_fill_values: Optional[Dict[str, Any]] = None,
        strict_validation: bool = False,
    ):
        """
        :param schema: dict describing expected fields, e.g.
            {
                "id": {"type": int, "required": True},
                "name": {"type": str, "required": True},
                "amount": {"type": float, "required": False, "default": 0.0},
                "date": {"type": "date", "required": False},
            }
        :param missing_value_strategy: "fill", "drop", or "mean" (numeric fields)
        :param default_fill_values: fallback values per field if not in schema defaults
        :param strict_validation: if True, invalid records raise; else they're dropped/logged
        """
        self.schema = schema
        self.missing_value_strategy = missing_value_strategy
        self.default_fill_values = default_fill_values or {}
        self.strict_validation = strict_validation
        self.errors: List[str] = []
        self.stats = {
            "rows_read": 0,
            "rows_cleaned": 0,
            "rows_validated": 0,
            "rows_dropped": 0,
            "rows_exported": 0,
        }

    # ------------------------------------------------------------------
    # 1. EXTRACT
    # ------------------------------------------------------------------
    def read_csv_sources(self, file_paths: List[str], encoding: str = "utf-8") -> List[Dict[str, Any]]:
        """Read and merge multiple CSV files into a single list of dict records."""
        combined_records: List[Dict[str, Any]] = []

        for path in file_paths:
            if not os.path.isfile(path):
                logger.warning(f"File not found, skipping: {path}")
                self.errors.append(f"Missing file: {path}")
                continue

            try:
                with open(path, "r", encoding=encoding, newline="") as f:
                    reader = csv.DictReader(f)
                    if reader.fieldnames is None:
                        logger.warning(f"Empty CSV file: {path}")
                        continue

                    for row in reader:
                        row["_source_file"] = os.path.basename(path)
                        combined_records.append(row)
                        self.stats["rows_read"] += 1

                logger.info(f"Read {path} successfully.")
            except Exception as e:
                logger.error(f"Failed to read {path}: {e}")
                self.errors.append(f"Read error in {path}: {e}")

        return combined_records

    # ------------------------------------------------------------------
    # 2. CLEAN / NORMALIZE
    # ------------------------------------------------------------------
    def clean_record(self, record: Dict[str, Any]) -> Dict[str, Any]:
        """Trim whitespace, normalize case/keys, strip stray characters."""
        cleaned = {}
        for key, value in record.items():
            clean_key = key.strip().lower().replace(" ", "_") if isinstance(key, str) else key

            if isinstance(value, str):
                value = value.strip()
                if value == "":
                    value = None
                else:
                    # Normalize internal whitespace
                    value = re.sub(r"\s+", " ", value)

            cleaned[clean_key] = value

        return cleaned

    def normalize_field_types(self, record: Dict[str, Any]) -> Dict[str, Any]:
        """Cast fields according to schema type definitions."""
        normalized = dict(record)

        for field, rules in self.schema.items():
            if field not in normalized:
                continue

            value = normalized[field]
            if value is None:
                continue

            field_type = rules.get("type")

            try:
                if field_type == int:
                    normalized[field] = int(float(value))
                elif field_type == float:
                    normalized[field] = float(value)
                elif field_type == str:
                    normalized[field] = str(value)
                elif field_type == bool:
                    if isinstance(value, str):
                        normalized[field] = value.strip().lower() in ("true", "1", "yes", "y")
                    else:
                        normalized[field] = bool(value)
                elif field_type == "date":
                    normalized[field] = self._parse_date(value)
            except (ValueError, TypeError) as e:
                logger.debug(f"Type coercion failed for field '{field}' value '{value}': {e}")
                normalized[field] = None

        return normalized

    @staticmethod
    def _parse_date(value: Any) -> Optional[str]:
        """Attempt to parse various date formats into ISO 8601 string."""
        if isinstance(value, datetime):
            return value.date().isoformat()

        if not isinstance(value, str):
            return None

        formats = [
            "%Y-%m-%d",
            "%m/%d/%Y",
            "%d/%m/%Y",
            "%Y/%m/%d",
            "%d-%m-%Y",
            "%B %d, %Y",
            "%b %d, %Y",
            "%Y-%m-%dT%H:%M:%S",
        ]
        for fmt in formats:
            try:
                return datetime.strptime(value, fmt).date().isoformat()
            except ValueError:
                continue
        return None

    def clean_and_normalize(self, records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        cleaned_records = []
        for record in records:
            try:
                cleaned = self.clean_record(record)
                cleaned = self.normalize_field_types(cleaned)
                cleaned_records.append(cleaned)
                self.stats["rows_cleaned"] += 1
            except Exception as e:
                logger.error(f"Error cleaning record {record}: {e}")
                self.errors.append(f"Clean error: {e}")

        return cleaned_records

    # ------------------------------------------------------------------
    # 3. HANDLE MISSING VALUES
    # ------------------------------------------------------------------
    def handle_missing_values(self, records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not records:
            return records

        if self.missing_value_strategy == "drop":
            result = []
            for r in records:
                required_fields = [f for f, rules in self.schema.items() if rules.get("required")]
                if all(r.get(f) is not None for f in required_fields):
                    result.append(r)
                else:
                    self.stats["rows_dropped"] += 1
            return result

        elif self.missing_value_strategy == "mean":
            numeric_fields = [
                f for f, rules in self.schema.items()
                if rules.get("type") in (int, float)
            ]
            means = {}
            for field in numeric_fields:
                values = [r[field] for r in records if r.get(field) is not None]
                if values:
                    means[field] = statistics.mean(values)

            for r in records:
                for field in numeric_fields:
                    if r.get(field) is None and field in means:
                        r[field] = means[field]
                self._fill_non_numeric_defaults(r)
            return records

        else:  # "fill" strategy (default)
            for r in records:
                self._fill_all_defaults(r)
            return records

    def _fill_non_numeric_defaults(self, record: Dict[str, Any]) -> None:
        for field, rules in self.schema.items():
            if record.get(field) is None and rules.get("type") not in (int, float):
                default = rules.get("default", self.default_fill_values.get(field))
                if default is not None:
                    record[field] = default

    def _fill_all_defaults(self, record: Dict[str, Any]) -> None:
        for field, rules in self.schema.items():
            if record.get(field) is None:
                default = rules.get("default", self.default_fill_values.get(field))
                if default is not None:
                    record[field] = default

    # ------------------------------------------------------------------
    # 4. VALIDATE AGAINST SCHEMA
    # ------------------------------------------------------------------
    def validate_record(self, record: Dict[str, Any]) -> bool:
        for field, rules in self.schema.items():
            required = rules.get("required", False)
            value = record.get(field)

            if required and value is None:
                msg = f"Missing required field '{field}' in record: {record}"
                if self.strict_validation:
                    raise SchemaValidationError(msg)
                logger.warning(msg)
                return False

            if value is not None:
                expected_type = rules.get("type")
                if expected_type in (int, float, str, bool) and not isinstance(value, expected_type):
                    msg = f"Type mismatch for field '{field}': expected {expected_type}, got {type(value)}"
                    if self.strict_validation:
                        raise SchemaValidationError(msg)
                    logger.warning(msg)
                    return False

                validator: Optional[Callable[[Any], bool]] = rules.get("validator")
                if validator and not validator(value):
                    msg = f"Custom validation failed for field '{field}' with value '{value}'"
                    if self.strict_validation:
                        raise SchemaValidationError(msg)
                    logger.warning(msg)
                    return False

        return True

    def validate_records(self, records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        valid_records = []
        for record in records:
            try:
                if self.validate_record(record):
                    valid_records.append(record)
                    self.stats["rows_validated"] += 1
                else:
                    self.stats["rows_dropped"] += 1
            except SchemaValidationError as e:
                logger.error(str(e))
                self.errors.append(str(e))
                self.stats["rows_dropped"] += 1

        return valid_records

    # ------------------------------------------------------------------
    # 5. AGGREGATE
    # ------------------------------------------------------------------
    def aggregate(
        self,
        records: List[Dict[str, Any]],
        group_by: List[str],
        aggregations: Dict[str, str],
    ) -> List[Dict[str, Any]]:
        """
        Group records by given fields and compute aggregations.

        :param group_by: list of fields to group by
        :param aggregations: dict mapping field -> aggregation func name
                              ("sum", "mean", "min", "max", "count")
        """
        groups: Dict[tuple, List[Dict[str, Any]]] = {}

        for record in records:
            key = tuple(record.get(field) for field in group_by)
            groups.setdefault(key, []).append(record)

        aggregated_results = []
        for key, group_records in groups.items():
            result = dict(zip(group_by, key))

            for field, func_name in aggregations.items():
                values = [r[field] for r in group_records if r.get(field) is not None]

                if func_name == "sum":
                    result[f"{field}_sum"] = sum(values) if values else 0
                elif func_name == "mean":
                    result[f"{field}_mean"] = statistics.mean(values) if values else None
                elif func_name == "min":
                    result[f"{field}_min"] = min(values) if values else None
                elif func_name == "max":
                    result[f"{field}_max"] = max(values) if values else None
                elif func_name == "count":
                    result[f"{field}_count"] = len(values)
                else:
                    logger.warning(f"Unknown aggregation function: {func_name}")

            aggregated_results.append(result)

        return aggregated_results

    # ------------------------------------------------------------------
    # 6. TRANSFORM FOR TARGET FORMAT
    # ------------------------------------------------------------------
    def transform(
        self,
        records: List[Dict[str, Any]],
        field_mapping: Optional[Dict[str, str]] = None,
        computed_fields: Optional[Dict[str, Callable[[Dict[str, Any]], Any]]] = None,
        exclude_fields: Optional[List[str]] = None,
    ) -> List[Dict[str, Any]]:
        """
        Rename fields, add computed fields, and remove unwanted fields.

        :param field_mapping: old_name -> new_name
        :param computed_fields: new_field_name -> function(record) -> value
        :param exclude_fields: list of fields to drop from output
        """
        field_mapping = field_mapping or {}
        computed_fields = computed_fields or {}
        exclude_fields = exclude_fields or []

        transformed = []
        for record in records:
            new_record = {}

            for key, value in record.items():
                new_key = field_mapping.get(key, key)
                if new_key not in exclude_fields:
                    new_record[new_key] = value

            for new_field, func in computed_fields.items():
                try:
                    new_record[new_field] = func(record)
                except Exception as e:
                    logger.warning(f"Computed field '{new_field}' failed: {e}")
                    new_record[new_field] = None

            for field in exclude_fields:
                new_record.pop(field, None)

            transformed.append(new_record)

        return transformed

    # ------------------------------------------------------------------
    # 7. EXPORT TO DATABASE
    # ------------------------------------------------------------------
    def export_to_database(
        self,
        records: List[Dict[str, Any]],
        db_path: str,
        table_name: str,
        if_exists: str = "replace",
    ) -> None:
        """
        Export records to a SQLite database table.

        :param if_exists: "replace", "append", or "fail"
        """
        if not records:
            logger.warning("No records to export.")
            return

        all_fields: List[str] = []
        for record in records:
            for key in record.keys():
                if key not in all_fields:
                    all_fields.append(key)

        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        try:
            table_exists = cursor.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name=?",
                (table_name,),
            ).fetchone()

            if table_exists:
                if if_exists == "fail":
                    raise ValueError(f"Table '{table_name}' already exists.")
                elif if_exists == "replace":
                    cursor.execute(f'DROP TABLE IF EXISTS "{table_name}"')
                    table_exists = None

            if not table_exists:
                column_defs = ", ".join(f'"{field}" TEXT' for field in all_fields)
                cursor.execute(f'CREATE TABLE "{table_name}" ({column_defs})')

            placeholders = ", ".join("?" for _ in all_fields)
            column_names = ", ".join(f'"{f}"' for f in all_fields)
            insert_sql = f'INSERT INTO "{table_name}" ({column_names}) VALUES ({placeholders})'

            for record in records:
                row_values = [
                    str(record[field]) if record.get(field) is not None else None
                    for field in all_fields
                ]
                cursor.execute(insert_sql, row_values)
                self.stats["rows_exported"] += 1

            conn.commit()
            logger.info(f"Exported {len(records)} records to table '{table_name}' in {db_path}.")

        except Exception as e:
            conn.rollback()
            logger.error(f"Export failed: {e}")
            self.errors.append(f"Export error: {e}")
            raise
        finally:
            conn.close()

    # ------------------------------------------------------------------
    # ORCHESTRATOR
    # ------------------------------------------------------------------
    def run(
        self,
        file_paths: List[str],
        db_path: str,
        table_name: str,
        group_by: Optional[List[str]] = None,
        aggregations: Optional[Dict[str, str]] = None,
        field_mapping: Optional[Dict[str, str]] = None,
        computed_fields: Optional[Dict[str, Callable[[Dict[str, Any]], Any]]] = None,
        exclude_fields: Optional[List[str]] = None,
        if_exists: str = "replace",
    ) -> Dict[str, Any]:
        """
        Run the full ETL pipeline end-to-end.

        :return: dict summary with stats and errors
        """
        logger.info("Starting ETL pipeline run...")

        raw_records = self.read_csv_sources(file_paths)
        if not raw_records:
            logger.warning("No records read from source files. Aborting pipeline.")
            return {"stats": self.stats, "errors": self.errors}

        cleaned_records = self.clean_and_normalize(raw_records)
        filled_records = self.handle_missing_values(cleaned_records)
        valid_records = self.validate_records(filled_records)

        if not valid_records:
            logger.warning("No valid records after validation. Aborting pipeline.")
            return {"stats": self.stats, "errors": self.errors}

        working_records = valid_records
        if group_by and aggregations:
            working_records = self.aggregate(valid_records, group_by, aggregations)

        transformed_records = self.transform(
            working_records,
            field_mapping=field_mapping,
            computed_fields=computed_fields,
            exclude_fields=exclude_fields,
        )

        self.export_to_database(transformed_records, db_path, table_name, if_exists=if_exists)

        logger.info(f"ETL pipeline completed. Stats: {self.stats}")

        return {
            "stats": self.stats,
            "errors": self.errors,
            "records": transformed_records,
        }


def run_etl_pipeline(
    file_paths: List[str],
    schema: Dict[str, Dict[str, Any]],
    db_path: str,
    table_name: str,
    missing_value_strategy: str = "fill",
