        if data1 != data2:
            differences["value"] = {"old": data1, "new": data2}
        return differences

    def filter_data(self, data: Any, predicate: Any) -> Any:
        if isinstance(data, list):
            return [item for item in data if predicate(item)]
        if isinstance(data, dict):
            return {k: v for k, v in data.items() if predicate(v)}
        return data if predicate(data) else None

