def _parse_date(value):
    """Parses a date from a string (YYYY-MM-DD) or returns the date/datetime as-is."""
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, str):
        try:
            return datetime.datetime.strptime(value, "%Y-%m-%d").date()
        except ValueError:
            return None
    return None


def _is_currently_active(effective_date, expiration_date):
    today = datetime.date.today()
    return effective_date <= today <= expiration_date


def _generate_policy_number(policy_type, territory):
