        self._account_id = account_id
        self._owner_name = owner_name
        self._balance = balance
        self._overdraft_limit = overdraft_limit
        self._pending_holds = {}  # hold_id -> amount
        self._transactions = []
        self._fraud_score_threshold = 0.75

    def add_hold(self, amount):
        if amount <= 0:
            raise ValueError("Hold amount must be positive")
        hold_id = str(uuid.uuid4())
        self._pending_holds[hold_id] = amount
        return hold_id

    def release_hold(self, hold_id):
        if hold_id in self._pending_holds:
            del self._pending_holds[hold_id]
            return True
        return False

    def _total_holds(self):
        return sum(self._pending_holds.values())

    def available_balance(self):
        return self._balance - self._total_holds()

    def process_transaction(self, transaction):
        if not isinstance(transaction, Transaction):
            raise TypeError("Expected a Transaction instance")

        if transaction._authorization_code is None:
            transaction._status = "declined"
            transaction._decline_reason = "missing_authorization"
            self._transactions.append(transaction)
            return False

        if transaction._fraud_score >= self._fraud_score_threshold:
            transaction._status = "declined"
            transaction._decline_reason = "fraud_risk"
            self._transactions.append(transaction)
            return False

        amount = transaction._amount
        if transaction._type == "debit":
            available = self.available_balance()
            max_spend = available + self._overdraft_limit
            if amount > max_spend:
                transaction._status = "declined"
                transaction._decline_reason = "insufficient_funds"
                self._transactions.append(transaction)
                return False
            self._balance -= amount
            transaction._status = "completed"
        elif transaction._type == "credit":
            self._balance += amount
            transaction._status = "completed"
        else:
            transaction._status = "declined"
            transaction._decline_reason = "unknown_transaction_type"
            self._transactions.append(transaction)
            return False

        self._transactions.append(transaction)
        return True

    def get_balance(self):
        return self._balance

    def get_transaction_history(self):
        return list(self._transactions)

    def __repr__(self):
        return f"Account({self._account_id}, owner={self._owner_name}, balance={self._balance})"


