import uuid
import datetime
from copy import deepcopy

# =========================================================================
# GLOBAL SHARED STATE
# =========================================================================

patient_context = {}
encounter_state = {}
medication_orders = {}
allergy_alerts = {}
clinical_decision_support_state = {}
billing_context = {}
scheduling_state = {}
provider_context = {}
audit_trail = []


# =========================================================================
# AUDIT UTILITY
# =========================================================================

def _log_audit(module, action, actor, details=None):
    entry = {
        "id": str(uuid.uuid4()),
        "timestamp": datetime.datetime.now().isoformat(),
        "module": module,
        "action": action,
        "actor": actor,
        "details": details or {}
    }
    audit_trail.append(entry)
    return entry


def get_audit_trail(module=None, patient_id=None):
    results = audit_trail
    if module:
        results = [e for e in results if e["module"] == module]
    if patient_id:
        results = [e for e in results if e["details"].get("patient_id") == patient_id]
    return results


# =========================================================================
# REGISTRATION MODULE
# =========================================================================

class RegistrationModule:

    @staticmethod
    def register_patient(name, dob, gender, mrn=None, actor="registration_clerk"):
        patient_id = str(uuid.uuid4())
        mrn = mrn or f"MRN-{patient_id[:8].upper()}"

        patient_context[patient_id] = {
            "patient_id": patient_id,
            "mrn": mrn,
            "name": name,
            "dob": dob,
            "gender": gender,
            "created_at": datetime.datetime.now().isoformat(),
            "demographics": {},
            "insurance": {},
            "active": True
        }

        allergy_alerts[patient_id] = []
        medication_orders[patient_id] = []

        _log_audit("registration", "register_patient", actor,
                   {"patient_id": patient_id, "mrn": mrn, "name": name})

        return patient_id

    @staticmethod
    def update_demographics(patient_id, demographics, actor="registration_clerk"):
        if patient_id not in patient_context:
            raise ValueError("Patient not found")
        patient_context[patient_id]["demographics"].update(demographics)
        _log_audit("registration", "update_demographics", actor,
                   {"patient_id": patient_id, "fields": list(demographics.keys())})

    @staticmethod
    def update_insurance(patient_id, insurance_info, actor="registration_clerk"):
        if patient_id not in patient_context:
            raise ValueError("Patient not found")
        patient_context[patient_id]["insurance"].update(insurance_info)
        billing_context.setdefault(patient_id, {})["insurance"] = deepcopy(
            patient_context[patient_id]["insurance"]
        )
        _log_audit("registration", "update_insurance", actor,
                   {"patient_id": patient_id})

    @staticmethod
    def schedule_appointment(patient_id, provider_id, dept, appt_time, actor="scheduler"):
        if patient_id not in patient_context:
            raise ValueError("Patient not found")
        appt_id = str(uuid.uuid4())
        scheduling_state.setdefault(patient_id, [])
        appointment = {
            "appt_id": appt_id,
            "provider_id": provider_id,
            "department": dept,
            "time": appt_time,
            "status": "scheduled"
        }
        scheduling_state[patient_id].append(appointment)
        _log_audit("registration", "schedule_appointment", actor,
                   {"patient_id": patient_id, "appt_id": appt_id, "provider_id": provider_id})
        return appt_id

    @staticmethod
    def create_encounter(patient_id, encounter_type, provider_id, actor="registration_clerk"):
        if patient_id not in patient_context:
            raise ValueError("Patient not found")
        encounter_id = str(uuid.uuid4())
        encounter_state[encounter_id] = {
            "encounter_id": encounter_id,
            "patient_id": patient_id,
            "provider_id": provider_id,
            "type": encounter_type,
            "status": "open",
            "started_at": datetime.datetime.now().isoformat(),
            "vitals": {},
            "diagnoses": [],
            "notes": []
        }

        billing_context.setdefault(patient_id, {}).setdefault("encounters", []).append(encounter_id)

        _log_audit("registration", "create_encounter", actor,
                   {"patient_id": patient_id, "encounter_id": encounter_id})
        return encounter_id

    @staticmethod
    def close_encounter(encounter_id, actor="registration_clerk"):
        if encounter_id not in encounter_state:
            raise ValueError("Encounter not found")
        encounter_state[encounter_id]["status"] = "closed"
        encounter_state[encounter_id]["closed_at"] = datetime.datetime.now().isoformat()
        _log_audit("registration", "close_encounter", actor, {"encounter_id": encounter_id})


# =========================================================================
# PROVIDER MODULE HELPERS
# =========================================================================

class ProviderModule:

    @staticmethod
    def register_provider(name, specialty, npi, actor="admin"):
        provider_id = str(uuid.uuid4())
        provider_context[provider_id] = {
            "provider_id": provider_id,
            "name": name,
            "specialty": specialty,
            "npi": npi,
            "active": True
        }
        _log_audit("provider", "register_provider", actor,
                   {"provider_id": provider_id, "name": name})
        return provider_id

    @staticmethod
