# =========================================================================
# CLINICAL MODULE
# =========================================================================

class ClinicalModule:

    @staticmethod
    def record_allergy(patient_id, allergen, reaction, severity="moderate", actor="nurse"):
        if patient_id not in patient_context:
            raise ValueError("Patient not found")
        allergy_alerts.setdefault(patient_id, [])
        alert = {
            "allergen": allergen.lower(),
            "reaction": reaction,
            "severity": severity,
            "recorded_at": datetime.datetime.now().isoformat()
        }
        allergy_alerts[patient_id].append(alert)
        _log_audit("clinical", "record_allergy", actor,
                   {"patient_id": patient_id, "allergen": allergen, "severity": severity})

    @staticmethod
    def record_vitals(encounter_id, vitals, actor="nurse"):
        if encounter_id not in encounter_state:
            raise ValueError("Encounter not found")
        encounter_state[encounter_id]["vitals"].update(vitals)
        _log_audit("clinical", "record_vitals", actor,
                   {"encounter_id": encounter_id, "vitals": vitals})

    @staticmethod
    def add_diagnosis(encounter_id, icd_code, description, actor="physician"):
        if encounter_id not in encounter_state:
            raise ValueError("Encounter not found")
        diagnosis = {
            "icd_code": icd_code,
            "description": description,
            "recorded_at": datetime.datetime.now().isoformat()
        }
        encounter_state[encounter_id]["diagnoses"].append(diagnosis)

        patient_id = encounter_state[encounter_id]["patient_id"]
        billing_context.setdefault(patient_id, {}).setdefault("diagnoses", []).append(diagnosis)

        _log_audit("clinical", "add_diagnosis", actor,
                   {"encounter_id": encounter_id, "icd_code": icd_code})

    @staticmethod
    def add_note(encounter_id, note_text, actor="physician"):
        if encounter_id not in encounter_state:
            raise ValueError("Encounter not found")
        note = {
            "text": note_text,
            "author": actor,
            "timestamp": datetime.datetime.now().isoformat()
        }
        encounter_state[encounter_id]["notes"].append(note)
        _log_audit("clinical", "add_note", actor, {"encounter_id": encounter_id})

    @staticmethod
    def run_decision_support(patient_id, encounter_id, actor="cds_engine"):
        """Evaluate CDS rules: allergy conflicts, drug interactions, duplicate therapy."""
        alerts = []

        patient_allergies = {a["allergen"] for a in allergy_alerts.get(patient_id, [])}
        active_meds = [m for m in medication_orders.get(patient_id, []) if m["status"] == "active"]

        # Duplicate therapy check
        drug_classes_seen = {}
        for med in active_meds:
            drug_class = med.get("drug_class", "unknown")
            if drug_class in drug_classes_seen and drug_class != "unknown":
                alerts.append({
                    "type": "duplicate_therapy",
                    "message": f"Duplicate therapy detected in class '{drug_class}'",
                    "severity": "warning"
                })
            drug_classes_seen[drug_class] = med["medication_name"]

        # Allergy cross-check against active meds
        for med in active_meds:
            if med["medication_name"].lower() in patient_allergies:
                alerts.append({
                    "type": "allergy_conflict",
                    "message": f"Active order '{med['medication_name']}' conflicts with known allergy",
                    "severity": "critical"
                })

        clinical_decision_support_state[patient_id] = {
            "encounter_id": encounter_id,
            "alerts": alerts,
            "evaluated_at": datetime.datetime.now().isoformat()
        }

        _log_audit("clinical", "run_decision_support", actor,
                   {"patient_id": patient_id, "alert_count": len(alerts)})

        return alerts


# =========================================================================
# PHARMACY MODULE
# =========================================================================

class PharmacyModule:

    KNOWN_INTERACTIONS = {
        frozenset(["warfarin", "aspirin"]): "Increased bleeding risk",
        frozenset(["lisinopril", "spironolactone"]): "Hyperkalemia risk",
        frozenset(["simvastatin", "clarithromycin"]): "Risk of rhabdomyolysis",
    }

