    def _check_allergy(patient_id, medication_name):
        allergens = {a["allergen"] for a in allergy_alerts.get(patient_id, [])}
        return medication_name.lower() in allergens

    @staticmethod
    def _check_interactions(patient_id, new_medication):
        active_meds = [
            m["medication_name"].lower()
            for m in medication_orders.get(patient_id, [])
            if m["status"] == "active"
        ]
        interactions_found = []
        for existing in active_meds:
            pair = frozenset([existing, new_medication.lower()])
            if pair in PharmacyModule.KNOWN_INTERACTIONS:
