def _log_audit(module, action, actor, details=None):
    entry = {
        "id": str(uuid.uuid4()),
        "timestamp": datetime.datetime.now().isoformat(),
        "module": module,
        "action": action,
        "actor": actor,
        "details": details or {}
    }
    audit_trail.append(entry)
    return entry


def get_audit_trail(module=None, patient_id=None):
    results = audit_trail
    if module:
        results = [e for e in results if e["module"] == module]
    if patient_id:
        results = [e for e in results if e["details"].get("patient_id") == patient_id]
    return results


