def sum_money(items: list) -> Money:
    """Sum a non-empty iterable of Money objects, all same currency."""
    items = list(items)
    if not items:
        raise ValueError("cannot sum an empty sequence of Money")
    total = items[0]
    for m in items[1:]:
        total = total + m
    return total


def max_money(*items: Money) -> Money:
    if not items:
        raise ValueError("max_money requires at least one Money argument")
    result = items[0]
    for m in items[1:]:
        if m > result:
            result = m
    return result


def min_money(*items: Money) -> Money:
    if not items:
        raise ValueError("min_money requires at least one Money argument")
    result = items[0]
    for m in items[1:]:
        if m < result:
            result = m
    return result

