        total_units_int = int(self._amount / quant)

        raw_shares = [total_units_int * r / total_ratio for r in ratios]
        floor_shares = [int(s.to_integral_value(rounding=ROUND_DOWN)) for s in raw_shares]
        remainders = [s - f for s, f in zip(raw_shares, floor_shares)]

        allocated = sum(floor_shares)
        leftover = total_units_int - allocated

        # Distribute leftover units to entries with largest remainder first.
        order = sorted(range(len(ratios)), key=lambda i: remainders[i], reverse=True)
        idx = 0
        while leftover > 0 and order:
            floor_shares[order[idx % len(order)]] += 1
            leftover -= 1
            idx += 1

        results = [Money(Decimal(units) * quant, self._currency) for units in floor_shares]
        return results

