        show_code: bool = False,
        thousands_sep: str = ",",
        decimal_sep: str = ".",
        rounded: bool = True,
    ) -> str:
        """Locale-independent, configurable string formatting."""
        info = self.info
        amount = self.rounded()._amount if rounded else self._amount

        negative = amount < 0
        amount = abs(amount)

        exponent = info.exponent
        quant_str = format(amount, "f")

        if "." in quant_str:
            int_part, frac_part = quant_str.split(".")
        else:
            int_part, frac_part = quant_str, ""

        frac_part = (frac_part + "0" * exponent)[:exponent] if exponent > 0 else ""

        # Insert thousands separators into integer part.
        int_part = int_part.lstrip("-")
        groups = []
        while len(int_part) > 3:
            groups.append(int_part[-3:])
            int_part = int_part[:-3]
        groups.append(int_part)
        int_with_seps = thousands_sep.join(reversed(groups))

        number_str = int_with_seps
        if exponent > 0:
            number_str += decimal_sep + frac_part

        sign = "-" if negative else ""

        pieces = []
        if show_symbol and info.symbol_first:
            pieces.append(f"{sign}{info.symbol}{number_str}")
        elif show_symbol:
            pieces.append(f"{sign}{number_str}{info.symbol}")
        else:
            pieces.append(f"{sign}{number_str}")

        result = pieces[0]
        if show_code:
            result = f"{result} {info.code}"
        return result

