                errors.append(f"Field '{field}' expected str, got {type(value).__name__}")
                continue

            if "min" in rules and isinstance(value, (int, float)) and value < rules["min"]:
                errors.append(f"Field '{field}' value {value} below min {rules['min']}")
            if "max" in rules and isinstance(value, (int, float)) and value > rules["max"]:
                errors.append(f"Field '{field}' value {value} above max {rules['max']}")

            if "allowed" in rules and value not in rules["allowed"]:
                errors.append(f"Field '{field}' value '{value}' not in allowed set {rules['allowed']}")

            if "regex" in rules and isinstance(value, str):
                if not re.match(rules["regex"], value):
                    errors.append(f"Field '{field}' value '{value}' does not match pattern {rules['regex']}")

        return errors

    def validate(self) -> None:
        """Validate all cleaned rows against the schema."""
        valid_rows = []
        for row in self.clean_rows:
            errors = self._validate_row(row)
            if errors:
                if self.drop_invalid_rows:
                    self.stats["rows_dropped_invalid"] += 1
                    logger.debug(f"Dropping invalid row: {errors}")
                    continue
                else:
                    raise ETLValidationError(
                        f"Row failed validation: {errors} | row={row}"
                    )
            valid_rows.append(row)

        self.valid_rows = valid_rows
        logger.info(
            f"Validation complete: {len(valid_rows)} valid rows, "
            f"{self.stats['rows_dropped_invalid']} dropped as invalid."
        )

    # ------------------------------------------------------------------
    # 5. TRANSFORM
    # ------------------------------------------------------------------
    def transform(self, custom_transform: Optional[Callable[[Dict[str, Any]], Dict[str, Any]]] = None) -> None:
        """
        Transform validated rows into target format.
        Adds metadata fields and applies optional custom transform function.
        """
        transformed = []
        now_iso = datetime.utcnow().isoformat()

        for row in self.valid_rows:
            new_row = dict(row)

            for field, rules in self.schema.items():
                if rules.get("type") == "date" and new_row.get(field):
                    new_row[field] = str(new_row[field])

            for key, value in list(new_row.items()):
                if isinstance(value, str):
                    new_row[key] = value.strip()

            new_row["_etl_processed_at"] = now_iso

            if custom_transform is not None:
                try:
                    new_row = custom_transform(new_row)
                except Exception as e:
                    logger.warning(f"custom_transform failed for row {row}: {e}")
                    continue

            transformed.append(new_row)

        self.transformed_rows = transformed
        self.stats["rows_transformed"] = len(transformed)
        logger.info(f"Transformed {len(transformed)} rows")

    # ------------------------------------------------------------------
    # 6. AGGREGATE
    # ------------------------------------------------------------------
    _AGG_FUNCS = {
        "sum": sum,
        "mean": mean,
        "avg": mean,
        "median": median,
        "min": min,
        "max": max,
        "count": len,
    }

    def aggregate(self) -> None:
        """Perform grouped aggregations based on group_by_fields and agg_fields."""
        if not self.group_by_fields or not self.agg_fields:
            logger.info("No aggregation configuration provided; skipping aggregation.")
            self.aggregates = []
            return

        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self.transformed_rows:
            key = tuple(row.get(f) for f in self.group_by_fields)
            groups.setdefault(key, []).append(row)

        results = []
        for key, rows in groups.items():
            agg_result = dict(zip(self.group_by_fields, key))
            agg_result["_group_count"] = len(rows)

            for field, funcs in self.agg_fields.items():
                values = [
                    r[field] for r in rows
                    if r.get(field) is not None and isinstance(r[field], (int, float))
                ]
                for func_name in funcs:
                    func = self._AGG_FUNCS.get(func_name)
                    if func is None:
                        logger.warning(f"Unknown aggregation function: {func_name}")
                        continue
                    col_name = f"{field}_{func_name}"
                    try:
                        agg_result[col_name] = func(values) if values else None
                    except Exception as e:
                        logger.warning(f"Aggregation '{func_name}' on '{field}' failed: {e}")
                        agg_result[col_name] = None

            results.append(agg_result)

        self.aggregates = results
        logger.info(f"Computed {len(results)} aggregate groups")

    # ------------------------------------------------------------------
    # 7. LOAD / EXPORT
    # ------------------------------------------------------------------
    @staticmethod
    def _sql_type(value: Any) -> str:
        if isinstance(value, bool):
            return "INTEGER"
        if isinstance(value, int):
            return "INTEGER"
        if isinstance(value, float):
            return "REAL"
        return "TEXT"

    def _create_table(self, conn: sqlite3.Connection, table: str, rows: List[Dict[str, Any]]) -> List[str]:
        """Infer column types from rows and create table if not exists."""
        if not rows:
            return []

        columns: Dict[str, str] = {}
        for row in rows:
            for k, v in row.items():
                if k not in columns or columns[k] == "TEXT":
                    if v is not None:
                        columns[k] = self._sql_type(v)
                    else:
                        columns.setdefault(k, "TEXT")

        col_defs = ", ".join(f'"{col}" {ctype}' for col, ctype in columns.items())
        conn.execute(f'DROP TABLE IF EXISTS "{table}"')
        conn.execute(f'CREATE TABLE "{table}" ({col_defs})')
        return list(columns.keys())

    def _insert_rows(self, conn: sqlite3.Connection, table: str, rows: List[Dict[str, Any]], columns: List[str]) -> None:
        placeholders = ", ".join("?" for _ in columns)
        col_names = ", ".join(f'"{c}"' for c in columns)
        sql = f'INSERT INTO "{table}" ({col_names}) VALUES ({placeholders})'

        def coerce_for_sql(v):
            if isinstance(v, bool):
                return int(v)
            if isinstance(v, (dict, list)):
                return json.dumps(v)
            return v

        data = [
            tuple(coerce_for_sql(row.get(col)) for col in columns)
            for row in rows
        ]
        conn.executemany(sql, data)

    def load(self) -> None:
        """Export transformed rows and aggregates into the SQLite database."""
        conn = sqlite3.connect(self.db_path)
        try:
            if self.transformed_rows:
                columns = self._create_table(conn, self.table_name, self.transformed_rows)
                self._insert_rows(conn, self.table_name, self.transformed_rows, columns)
                logger.info(f"Loaded {len(self.transformed_rows)} rows into '{self.table_name}'")
            else:
                logger.warning("No transformed rows to load.")

            if self.aggregates:
                agg_columns = self._create_table(conn, self.agg_table_name, self.aggregates)
                self._insert_rows(conn, self.agg_table_name, self.aggregates, agg_columns)
                logger.info(f"Loaded {len(self.aggregates)} aggregate rows into '{self.agg_table_name}'")

            conn.commit()
        except Exception as e:
            conn.rollback()
            logger.error(f"Failed to load data into database: {e}")
            raise
        finally:
            conn.close()

    # ------------------------------------------------------------------
    # ORCHESTRATION
    # ------------------------------------------------------------------
    def run(
        self,
        custom_transform: Optional[Callable[[Dict[str, Any]], Dict[str, Any]]] = None
    ) -> Dict[str, Any]:
        """Execute the full ETL pipeline end-to-end and return run statistics."""
        logger.info("Starting ETL pipeline run")
        self.extract()
        self.clean()
        self.handle_missing()
        self.validate()
        self.transform(custom_transform=custom_transform)
        self.aggregate()
        self.load()
        logger.info(f"ETL pipeline run complete. Stats: {self.stats}")
        return {
            "stats": self.stats,
            "row_count": len(self.transformed_rows),
            "aggregate_count": len(self.aggregates),
        }


def run_etl_pipeline(
    source_files: List[str],
    schema: Dict[str, Dict[str, Any]],
    db_path: str = "etl_output.db",
    table_name: str = "etl_results",
    agg_table_name: str = "etl_aggregates",
    delimiter: str = ",",
    encoding: str = "utf-8",
    fill_strategy: str = "auto",
    drop_invalid_rows: bool = True,
    group_by_fields: Optional[List[str]] = None,
    agg_fields: Optional[Dict[str, List[str]]] = None,
    custom_transform: Optional[Callable[[Dict[str, Any]], Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    """
    Convenience function wrapping ETLPipeline for functional-style usage.

    Example:
        schema = {
            "id": {"type": int, "required": True},
            "name": {"type": str, "required": True, "regex": r"^[A-Za-z ]+$"},
            "amount": {"type": float, "required": True, "min": 0},
            "signup_date": {"type": "date", "required": False},
            "category": {"type": str, "required": False, "allowed": {"A", "B", "C"}},
        }

        stats = run_etl_pipeline(
            source_files=["sales1.csv", "sales2.csv"],
            schema=schema,
            db_path="warehouse.db",
            group_by_fields=["category"],
            agg_fields={"amount": ["sum", "mean", "max", "count"]},
        )
    """
    pipeline = ETLPipeline(
        source_files=source_files,
        schema=schema,
        db_path=db_path,
        table_name=table_name,
        agg_table_name=agg_table_name,
        delimiter=delimiter,
        encoding=encoding,
        fill_strategy=fill_strategy,
        drop_invalid_rows=drop_invalid_rows,
        group_by_fields=group_by_fields,
        agg_fields=agg_fields,
    )
    return pipeline.run(custom_transform=custom_transform)


if __name__ == "__main__":
    example_schema = {
        "id": {"type": int, "required": True},
        "name": {"type": str, "required": True},
        "amount": {"type": float, "required": True, "min": 0},
        "category": {"type": str, "required": False, "allowed": {"A", "B", "C"}},
        "signup_date": {"type": "date", "required": False},
    }

    result = run_etl_pipeline(
        source_files=["data1.csv", "data2.csv"],
        schema=example_schema,
        db_path="output.db",
        group_by_fields=["category"],
        agg_fields={"amount": ["sum", "mean", "max", "count"]},
    )
    print(json.dumps(result, indent=2))
