            symbol = candidate["symbol"]
            needed_quantity = candidate["quantity"]
            available_lots = sorted(
                self.tax_lots_db.get(symbol, []),
                key=lambda lot: lot.purchase_date
            )

            selected_lots = []
            remaining = needed_quantity
            for lot in available_lots:
                if remaining <= 0:
                    break
                if lot.quantity <= 0:
                    continue
                take_quantity = min(lot.quantity, remaining)
                selected_lots.append(TaxLot(
                    lot_id=lot.lot_id,
                    symbol=lot.symbol,
                    quantity=take_quantity,
                    cost_basis=lot.cost_basis,
                    purchase_date=lot.purchase_date,
