            self.tax_lot_selections[symbol] = selected_lots

    def _check_wash_sales(self, recent_sales: Dict[str, datetime]):
        self.wash_sale_checks = {}
        now = datetime.now()
        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]
            if candidate["action"] != "buy":
                self.wash_sale_checks[symbol] = False
                continue

            last_sale_date = recent_sales.get(symbol)
            if last_sale_date is None:
                self.wash_sale_checks[symbol] = False
                continue

            days_since_sale = (now - last_sale_date).days
            self.wash_sale_checks[symbol] = 0 <= days_since_sale <= self.wash_sale_window_days

    def _generate_orders(self):
        self.order_generation_state = {
            "orders": [],
            "skipped_due_to_wash_sale": [],
        }

        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]

            if candidate["action"] == "buy" and self.wash_sale_checks.get(symbol, False):
                self.order_generation_state["skipped_due_to_wash_sale"].append(symbol)
                continue

            order = {
                "symbol": symbol,
                "action": candidate["action"],
                "quantity": candidate["quantity"],
                "price": candidate["price"],
                "tax_lots_used": [
                    lot.lot_id for lot in self.tax_lot_selections.get(symbol, [])
                ] if candidate["action"] == "sell" else [],
            }
            self.order_generation_state["orders"].append(order)

    def _execute_orders(self, prices: Dict[str, float]):
        self.execution_status = {}
        orders = self.order_generation_state.get("orders", [])

        for order in orders:
            symbol = order["symbol"]
            price = prices.get(symbol)
            if price is None or price <= 0:
                self.execution_status[symbol] = "failed_no_price"
                continue
            if order["quantity"] <= 0:
                self.execution_status[symbol] = "skipped_zero_quantity"
                continue

            self.execution_status[symbol] = "executed"

    def _reconcile(self):
        self.reconciliation_data = {
            "total_orders": len(self.order_generation_state.get("orders", [])),
            "executed_count": sum(
                1 for status in self.execution_status.values() if status == "executed"
            ),
            "failed_count": sum(
                1 for status in self.execution_status.values() if status.startswith("failed")
            ),
            "skipped_count": sum(
                1 for status in self.execution_status.values() if status.startswith("skipped")
            ),
            "wash_sale_skips": len(
                self.order_generation_state.get("skipped_due_to_wash_sale", [])
            ),
        }

    def _attribute_performance(self, portfolio_value: float):
        self.performance_attribution = {}
        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]
            dollar_amount = candidate["dollar_amount"]
            contribution = dollar_amount / portfolio_value if portfolio_value else 0.0
            self.performance_attribution[symbol] = contribution

