        self.portfolio_id = portfolio_id
        self.tax_lots_db = tax_lots_db if tax_lots_db is not None else {}
        self.wash_sale_window_days = wash_sale_window_days

        # Temporary fields, only valid during a rebalancing operation
        self.current_allocations: Dict[str, float] = {}
        self.target_allocations: Dict[str, float] = {}
        self.drift_calculations: Dict[str, float] = {}
        self.trade_candidates: List[Dict[str, Any]] = []
        self.tax_lot_selections: Dict[str, List[TaxLot]] = {}
        self.wash_sale_checks: Dict[str, bool] = {}
        self.order_generation_state: Dict[str, Any] = {}
        self.execution_status: Dict[str, str] = {}
        self.reconciliation_data: Dict[str, Any] = {}
        self.performance_attribution: Dict[str, float] = {}

        self._in_rebalance = False

    def _reset_temp_state(self):
        """Reset all temporary fields to their initial empty state."""
        self.current_allocations = {}
        self.target_allocations = {}
        self.drift_calculations = {}
        self.trade_candidates = []
        self.tax_lot_selections = {}
        self.wash_sale_checks = {}
        self.order_generation_state = {}
        self.execution_status = {}
        self.reconciliation_data = {}
        self.performance_attribution = {}

    def rebalance(self, current_allocations: Dict[str, float],
                  target_allocations: Dict[str, float],
                  prices: Dict[str, float],
                  portfolio_value: float,
                  recent_sales: Optional[Dict[str, datetime]] = None) -> Dict[str, Any]:
        """
        Main entry point for a full rebalancing operation.
        All temporary fields are valid only during this call and are reset afterward.
        """
        self._reset_temp_state()
        self._in_rebalance = True

        try:
            self.current_allocations = dict(current_allocations)
            self.target_allocations = dict(target_allocations)

            self._calculate_drift()
            self._generate_trade_candidates(prices, portfolio_value)
            self._select_tax_lots()
            self._check_wash_sales(recent_sales or {})
            self._generate_orders()
            self._execute_orders(prices)
            self._reconcile()
            self._attribute_performance(portfolio_value)

            result = {
                "drift_calculations": dict(self.drift_calculations),
                "trade_candidates": list(self.trade_candidates),
                "tax_lot_selections": {
                    k: list(v) for k, v in self.tax_lot_selections.items()
                },
                "wash_sale_checks": dict(self.wash_sale_checks),
                "order_generation_state": dict(self.order_generation_state),
                "execution_status": dict(self.execution_status),
                "reconciliation_data": dict(self.reconciliation_data),
                "performance_attribution": dict(self.performance_attribution),
            }
            return result
        finally:
            self._in_rebalance = False
            self._reset_temp_state()

    def _calculate_drift(self):
        all_symbols = set(self.current_allocations) | set(self.target_allocations)
        self.drift_calculations = {}
        for symbol in all_symbols:
            current = self.current_allocations.get(symbol, 0.0)
            target = self.target_allocations.get(symbol, 0.0)
            self.drift_calculations[symbol] = current - target

    def _generate_trade_candidates(self, prices: Dict[str, float], portfolio_value: float):
        self.trade_candidates = []
        for symbol, drift in self.drift_calculations.items():
            if abs(drift) < 1e-9:
                continue
            price = prices.get(symbol)
            if price is None or price <= 0:
                continue
            dollar_amount = -drift * portfolio_value
            quantity = dollar_amount / price
            action = "buy" if quantity > 0 else "sell"
            self.trade_candidates.append({
                "symbol": symbol,
                "action": action,
                "quantity": abs(quantity),
                "price": price,
                "dollar_amount": abs(dollar_amount),
            })

    def _select_tax_lots(self):
        self.tax_lot_selections = {}
        for candidate in self.trade_candidates:
            if candidate["action"] != "sell":
                continue
            symbol = candidate["symbol"]
            needed_quantity = candidate["quantity"]
            available_lots = sorted(
                self.tax_lots_db.get(symbol, []),
                key=lambda lot: lot.purchase_date
            )

            selected_lots = []
            remaining = needed_quantity
            for lot in available_lots:
                if remaining <= 0:
                    break
                if lot.quantity <= 0:
                    continue
                take_quantity = min(lot.quantity, remaining)
                selected_lots.append(TaxLot(
                    lot_id=lot.lot_id,
                    symbol=lot.symbol,
                    quantity=take_quantity,
                    cost_basis=lot.cost_basis,
                    purchase_date=lot.purchase_date,
                ))
                remaining -= take_quantity

            self.tax_lot_selections[symbol] = selected_lots

    def _check_wash_sales(self, recent_sales: Dict[str, datetime]):
        self.wash_sale_checks = {}
        now = datetime.now()
        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]
            if candidate["action"] != "buy":
                self.wash_sale_checks[symbol] = False
                continue

            last_sale_date = recent_sales.get(symbol)
            if last_sale_date is None:
                self.wash_sale_checks[symbol] = False
                continue

            days_since_sale = (now - last_sale_date).days
            self.wash_sale_checks[symbol] = 0 <= days_since_sale <= self.wash_sale_window_days

    def _generate_orders(self):
        self.order_generation_state = {
            "orders": [],
            "skipped_due_to_wash_sale": [],
        }

        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]

            if candidate["action"] == "buy" and self.wash_sale_checks.get(symbol, False):
                self.order_generation_state["skipped_due_to_wash_sale"].append(symbol)
                continue

            order = {
                "symbol": symbol,
                "action": candidate["action"],
                "quantity": candidate["quantity"],
                "price": candidate["price"],
                "tax_lots_used": [
                    lot.lot_id for lot in self.tax_lot_selections.get(symbol, [])
                ] if candidate["action"] == "sell" else [],
            }
            self.order_generation_state["orders"].append(order)

    def _execute_orders(self, prices: Dict[str, float]):
        self.execution_status = {}
        orders = self.order_generation_state.get("orders", [])

        for order in orders:
            symbol = order["symbol"]
            price = prices.get(symbol)
            if price is None or price <= 0:
                self.execution_status[symbol] = "failed_no_price"
                continue
            if order["quantity"] <= 0:
                self.execution_status[symbol] = "skipped_zero_quantity"
                continue

            self.execution_status[symbol] = "executed"

    def _reconcile(self):
        self.reconciliation_data = {
            "total_orders": len(self.order_generation_state.get("orders", [])),
            "executed_count": sum(
                1 for status in self.execution_status.values() if status == "executed"
            ),
            "failed_count": sum(
                1 for status in self.execution_status.values() if status.startswith("failed")
            ),
            "skipped_count": sum(
                1 for status in self.execution_status.values() if status.startswith("skipped")
            ),
            "wash_sale_skips": len(
                self.order_generation_state.get("skipped_due_to_wash_sale", [])
            ),
        }

    def _attribute_performance(self, portfolio_value: float):
        self.performance_attribution = {}
        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]
            dollar_amount = candidate["dollar_amount"]
            contribution = dollar_amount / portfolio_value if portfolio_value else 0.0
            self.performance_attribution[symbol] = contribution
