    def create_pdf(self, content, options=None):
        """
        Creates a PDF document from the given content.

        :param content: str, list of str, or dict describing the content
        :param options: dict of generation options
        :return: dict with metadata about the generated document
        """
        if content is None:
            raise ValueError("Content cannot be None")

        merged_options = dict(self.default_options)
