            "page_size": merged_options["page_size"],
            "orientation": merged_options["orientation"],
            "content_length": len(full_document),
            "generated_at": datetime.now().isoformat(),
        }

    def _normalize_content(self, content):
        if isinstance(content, str):
            return [content]
        elif isinstance(content, list):
            return [str(item) for item in content]
        elif isinstance(content, dict):
            lines = []
            for key, value in content.items():
                lines.append(f"{key}: {value}")
            return lines
        else:
            return [str(content)]

    def _render_header(self, options):
        title = options.get("title", "Untitled Document")
        author = options.get("author", "Unknown")
