class ReportBuilder:
    """
    Builds structured reports from data using templates.
    """

    def __init__(self):
        self.available_templates = {
            "simple": self._build_simple_template,
            "detailed": self._build_detailed_template,
            "summary": self._build_summary_template,
        }

    def build_report(self, data, template="simple"):
        """
        Builds a report from data using the given template.

        :param data: dict or list containing report data
        :param template: str name of template, or dict for custom template
        :return: dict representing the built report
        """
        if data is None:
            raise ValueError("Data cannot be None")

        if isinstance(template, dict):
            return self._build_custom_template(data, template)

        if not isinstance(template, str):
            raise TypeError("template must be a string or a dictionary")

        builder_func = self.available_templates.get(template.lower())
        if builder_func is None:
            raise ValueError(
                f"Unknown template '{template}'. Available: {list(self.available_templates.keys())}"
            )

        normalized_data = self._normalize_data(data)
        return builder_func(normalized_data)

    def _normalize_data(self, data):
        if isinstance(data, dict):
            return data
        elif isinstance(data, list):
            return {"items": data}
        else:
            return {"value": data}

    def _build_simple_template(self, data):
        report = {
            "template": "simple",
            "generated_at": datetime.now().isoformat(),
            "content": {},
        }
        for key, value in data.items():
            report["content"][key] = value
        return report

    def _build_detailed_template(self, data):
        report = {
            "template": "detailed",
            "generated_at": datetime.now().isoformat(),
            "summary": self._generate_summary_text(data),
            "sections": [],
            "metadata": {
                "field_count": len(data) if isinstance(data, dict) else 0,
                "data_types": {},
            },
        }

        for key, value in data.items():
            section = {
                "name": key,
                "value": value,
                "type": type(value).__name__,
            }
            if isinstance(value, list):
                section["count"] = len(value)
            elif isinstance(value, dict):
                section["keys"] = list(value.keys())
            report["sections"].append(section)
            report["metadata"]["data_types"][key] = type(value).__name__

        return report

    def _build_summary_template(self, data):
        total_fields = len(data) if isinstance(data, dict) else 0
        numeric_fields = {}
        text_fields = {}

        for key, value in data.items():
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                numeric_fields[key] = value
            elif isinstance(value, str):
                text_fields[key] = value

        report = {
            "template": "summary",
            "generated_at": datetime.now().isoformat(),
            "total_fields": total_fields,
            "numeric_summary": {
                "count": len(numeric_fields),
                "fields": numeric_fields,
                "total": sum(numeric_fields.values()) if numeric_fields else 0,
                "average": (
                    sum(numeric_fields.values()) / len(numeric_fields)
                    if numeric_fields
                    else 0
                ),
            },
            "text_summary": {
                "count": len(text_fields),
                "fields": text_fields,
            },
        }
        return report

    def _build_custom_template(self, data, template):
        report = {
            "template": "custom",
            "generated_at": datetime.now().isoformat(),
            "content": {},
        }

        fields = template.get("fields", [])
        title = template.get("title", "Custom Report")
        report["title"] = title

        normalized_data = self._normalize_data(data)

        if fields:
            for field in fields:
                if isinstance(normalized_data, dict) and field in normalized_data:
                    report["content"][field] = normalized_data[field]
                else:
                    report["content"][field] = None
        else:
            report["content"] = normalized_data

        if "transform" in template and callable(template["transform"]):
            try:
                report["content"] = template["transform"](report["content"])
            except Exception as e:
                report["transform_error"] = str(e)

        return report

    def _generate_summary_text(self, data):
        if not isinstance(data, dict) or not data:
            return "No data available for summary."
        field_names = ", ".join(str(k) for k in data.keys())
        return f"Report contains {len(data)} field(s): {field_names}."


class DocumentWriter:
    """
    Writes documents composed of sections into various formats.
    """

    def __init__(self):
        self.supported_formats = ["text", "markdown", "html", "json"]

    def write_document(self, sections, format="text"):
        """
        Writes a document from a list of sections into the specified format.

        :param sections: list of dicts, each with 'title' and 'content' keys,
                          or list of strings
        :param format: str, one of 'text', 'markdown', 'html', 'json'
        :return: str representing the written document (or dict for json)
        """
        if sections is None:
            raise ValueError("Sections cannot be None")

        if not isinstance(sections, list):
            raise TypeError("sections must be a list")

        if not isinstance(format, str):
            raise TypeError("format must be a string")

        format_lower = format.lower()
        if format_lower not in self.supported_formats:
            raise ValueError(
                f"Unsupported format '{format}'. Supported formats: {self.supported_formats}"
            )

        normalized_sections = self._normalize_sections(sections)

        if format_lower == "text":
            return self._write_text(normalized_sections)
        elif format_lower == "markdown":
            return self._write_markdown(normalized_sections)
        elif format_lower == "html":
            return self._write_html(normalized_sections)
        elif format_lower == "json":
            return self._write_json(normalized_sections)

    def _normalize_sections(self, sections):
        normalized = []
        for idx, section in enumerate(sections):
            if isinstance(section, dict):
                title = section.get("title", f"Section {idx + 1}")
                content = section.get("content", "")
                level = section.get("level", 1)
                normalized.append({"title": title, "content": content, "level": level})
            elif isinstance(section, str):
                normalized.append(
                    {"title": f"Section {idx + 1}", "content": section, "level": 1}
                )
            else:
                normalized.append(
                    {"title": f"Section {idx + 1}", "content": str(section), "level": 1}
                )
        return normalized

    def _write_text(self, sections):
        lines = []
        for section in sections:
            title = section["title"]
            content = section["content"]
            lines.append(title)
            lines.append("-" * len(title))
            lines.append(str(content))
            lines.append("")
        return "\n".join(lines).strip() + "\n"

    def _write_markdown(self, sections):
        lines = []
        for section in sections:
            level = max(1, min(6, section.get("level", 1)))
            heading_prefix = "#" * level
            title = section["title"]
            content = section["content"]
            lines.append(f"{heading_prefix} {title}")
            lines.append("")
            lines.append(str(content))
            lines.append("")
        return "\n".join(lines).strip() + "\n"

    def _write_html(self, sections):
        html_parts = [
            "<!DOCTYPE html>",
            "<html>",
            "<head>",
            "<meta charset='utf-8'>",
            "<title>Document</title>",
            "</head>",
            "<body>",
        ]

        for section in sections:
            level = max(1, min(6, section.get("level", 1)))
            title = html.escape(str(section["title"]))
            content = html.escape(str(section["content"]))
            content_html = content.replace("\n", "<br>")
            html_parts.append(f"<h{level}>{title}</h{level}>")
            html_parts.append(f"<p>{content_html}</p>")

        html_parts.append("</body>")
        html_parts.append("</html>")

        return "\n".join(html_parts)

    def _write_json(self, sections):
        document = {
            "generated_at": datetime.now().isoformat(),
            "sections": sections,
        }
        return json.dumps(document, indent=2, ensure_ascii=False)

