            parsed["segment_order"].append(segment_id)
            parsed["segments"].setdefault(segment_id, []).append(segment_dict)

            if segment_id == "MSH":
                try:
                    parsed["message_type"] = self._get_component(parsed_fields, 8)
                    parsed["control_id"] = self._get_component(parsed_fields, 9)
                except IndexError:
                    pass

        return parsed

    def _parse_field(self, field: str) -> Any:
        if self.repetition_sep in field:
            reps = field.split(self.repetition_sep)
            return [self._parse_components(r) for r in reps]
        return self._parse_components(field)

    def _parse_components(self, field: str) -> Any:
        if self.component_sep in field:
            components = field.split(self.component_sep)
            return [self._parse_subcomponents(c) for c in components]
        return self._parse_subcomponents(field)

    def _parse_subcomponents(self, component: str) -> Any:
        if self.subcomponent_sep in component:
            return component.split(self.subcomponent_sep)
        return component

    def _get_component(self, fields: List[Any], index: int) -> Any:
        if index < len(fields):
            return fields[index]
        return None

    def get_segment(self, parsed_message: Dict[str, Any], segment_id: str, occurrence: int = 0) -> Optional[Dict]:
        segs = parsed_message.get("segments", {}).get(segment_id)
        if not segs or occurrence >= len(segs):
            return None
        return segs[occurrence]

    def get_field(self, parsed_message: Dict[str, Any], segment_id: str, field_index: int,
                   occurrence: int = 0) -> Any:
        segment = self.get_segment(parsed_message, segment_id, occurrence)
        if segment is None:
            return None
        fields = segment.get("fields", [])
        if field_index < len(fields):
            return fields[field_index]
        return None


class FhirClient:
    """
    Client for interacting with a FHIR REST API.
    Interface: read_resource(resource_type, id) -> dict (parsed FHIR resource)
    """

    def __init__(self, base_url: str, auth_token: Optional[str] = None, timeout: int = 30):
        if not base_url.endswith("/"):
            base_url += "/"
        self.base_url = base_url
        self.auth_token = auth_token
        self.timeout = timeout

    def read_resource(self, resource_type: str, id: str) -> Dict[str, Any]:
        if not resource_type or not id:
            raise ValueError("resource_type and id must be provided")

        url = urljoin(self.base_url, f"{resource_type}/{id}")
        headers = {
            "Accept": "application/fhir+json",
        }
        if self.auth_token:
            headers["Authorization"] = f"Bearer {self.auth_token}"

        request = urllib.request.Request(url, headers=headers, method="GET")

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw_body = response.read().decode("utf-8")
                status = response.status
        except urllib.error.HTTPError as e:
            raw_body = e.read().decode("utf-8") if e.fp else ""
            status = e.code
            return self._build_error_response(status, raw_body, resource_type, id)
        except urllib.error.URLError as e:
            raise ConnectionError(f"Failed to connect to FHIR server: {e.reason}") from e

        try:
            resource = json.loads(raw_body) if raw_body else {}
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON response from FHIR server: {e}") from e

        if status >= 400:
            return self._build_error_response(status, raw_body, resource_type, id)

        return {
            "resourceType": resource.get("resourceType", resource_type),
            "id": resource.get("id", id),
            "meta": resource.get("meta", {}),
            "data": resource,
            "status_code": status,
        }

    def _build_error_response(self, status: int, raw_body: str, resource_type: str, id: str) -> Dict[str, Any]:
        try:
            body = json.loads(raw_body) if raw_body else {}
        except json.JSONDecodeError:
            body = {"raw": raw_body}

        return {
            "resourceType": resource_type,
            "id": id,
            "error": True,
            "status_code": status,
            "data": body,
        }

    def search(self, resource_type: str, params: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
        if params is None:
            params = {}
        query_string = "&".join(f"{k}={v}" for k, v in params.items())
        url = urljoin(self.base_url, resource_type)
        if query_string:
            url = f"{url}?{query_string}"

        headers = {"Accept": "application/fhir+json"}
        if self.auth_token:
            headers["Authorization"] = f"Bearer {self.auth_token}"

        request = urllib.request.Request(url, headers=headers, method="GET")

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw_body = response.read().decode("utf-8")
        except urllib.error.HTTPError as e:
            raw_body = e.read().decode("utf-8") if e.fp else ""
            return {"error": True, "status_code": e.code, "data": raw_body}
        except urllib.error.URLError as e:
            raise ConnectionError(f"Failed to connect to FHIR server: {e.reason}") from e

        try:
            bundle = json.loads(raw_body) if raw_body else {}
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON response from FHIR server: {e}") from e

        return bundle


class CdaProcessor:
    """
    Processor for HL7 CDA (Clinical Document Architecture) XML documents.
    Interface: extract_document(cda_xml) -> structured dict
    """

    NAMESPACES = {
        "hl7": "urn:hl7-org:v3",
        "xsi": "http://www.w3.org/2001/XMLSchema-instance",
    }

    def __init__(self):
        for prefix, uri in self.NAMESPACES.items():
            ET.register_namespace(prefix if prefix != "hl7" else "", uri)

    def extract_document(self, cda_xml: str) -> Dict[str, Any]:
        if not cda_xml or not cda_xml.strip():
            raise ValueError("Empty CDA XML provided")

        try:
            root = ET.fromstring(cda_xml)
        except ET.ParseError as e:
            raise ValueError(f"Invalid CDA XML: {e}") from e

        ns = self._detect_namespace(root)

        result: Dict[str, Any] = {
            "document_id": self._extract_document_id(root, ns),
            "title": self._extract_text(root, f"{ns}title"),
            "effective_time": self._extract_effective_time(root, ns),
            "confidentiality_code": self._extract_attribute(
                root, f"{ns}confidentialityCode", "code"
            ),
            "language_code": self._extract_attribute(root, f"{ns}languageCode", "code"),
            "patient": self._extract_patient(root, ns),
            "author": self._extract_author(root, ns),
            "custodian": self._extract_custodian(root, ns),
            "sections": self._extract_sections(root, ns),
        }

        return result

    def _detect_namespace(self, root: ET.Element) -> str:
        if root.tag.startswith("{"):
            uri = root.tag[1:].split("}")[0]
            return f"{{{uri}}}"
        return ""

    def _extract_document_id(self, root: ET.Element, ns: str) -> Optional[str]:
        id_el = root.find(f"{ns}id")
        if id_el is None:
            return None
        root_attr = id_el.get("root", "")
        ext_attr = id_el.get("extension", "")
        if ext_attr:
            return f"{root_attr}^{ext_attr}"
        return root_attr or None

    def _extract_text(self, element: ET.Element, tag: str) -> Optional[str]:
        el = element.find(tag)
        if el is None:
            return None
        return el.text.strip() if el.text else None

    def _extract_attribute(self, element: ET.Element, tag: str, attr: str) -> Optional[str]:
        el = element.find(tag)
        if el is None:
            return None
        return el.get(attr)

    def _extract_effective_time(self, root: ET.Element, ns: str) -> Optional[str]:
        return self._extract_attribute(root, f"{ns}effectiveTime", "value")

    def _extract_patient(self, root: ET.Element, ns: str) -> Dict[str, Any]:
        patient_data: Dict[str, Any] = {
            "id": None,
            "given_name": None,
            "family_name": None,
            "gender": None,
            "birth_time": None,
            "address": None,
        }

        record_target = root.find(f".//{ns}recordTarget")
        if record_target is None:
            return patient_data

        patient_role = record_target.find(f"{ns}patientRole")
        if patient_role is None:
            return patient_data

        id_el = patient_role.find(f"{ns}id")
        if id_el is not None:
            root_attr = id_el.get("root", "")
            ext_attr = id_el.get("extension", "")
            patient_data["id"] = f"{root_attr}^{ext_attr}" if ext_attr else root_attr

        patient_el = patient_role.find(f"{ns}patient")
        if patient_el is not None:
            name_el = patient_el.find(f"{ns}name")
            if name_el is not None:
                patient_data["given_name"] = self._extract_text(name_el, f"{ns}given")
                patient_data["family_name"] = self._extract_text(name_el, f"{ns}family")

            gender_el = patient_el.find(f"{ns}administrativeGenderCode")
            if gender_el is not None:
                patient_data["gender"] = gender_el.get("code")

            birth_el = patient_el.find(f"{ns}birthTime")
            if birth_el is not None:
                patient_data["birth_time"] = birth_el.get("value")

        addr_el = patient_role.find(f"{ns}addr")
        if addr_el is not None:
            patient_data["address"] = {
                "street": self._extract_text(addr_el, f"{ns}streetAddressLine"),
                "city": self._extract_text(addr_el, f"{ns}city"),
                "state": self._extract_text(addr_el, f"{ns}state"),
                "postal_code": self._extract_text(addr_el, f"{ns}postalCode"),
                "country": self._extract_text(addr_el, f"{ns}country"),
            }

        return patient_data

    def _extract_author(self, root: ET.Element, ns: str) -> Dict[str, Any]:
        author_data: Dict[str, Any] = {"time": None, "name": None}

        author_el = root.find(f".//{ns}author")
        if author_el is None:
            return author_data

        time_el = author_el.find(f"{ns}time")
        if time_el is not None:
            author_data["time"] = time_el.get("value")

        assigned_author = author_el.find(f"{ns}assignedAuthor")
        if assigned_author is not None:
            person_el = assigned_author.find(f"{ns}assignedPerson")
            if person_el is not None:
                name_el = person_el.find(f"{ns}name")
                if name_el is not None:
                    given = self._extract_text(name_el, f"{ns}given")
                    family = self._extract_text(name_el, f"{ns}family")
                    author_data["name"] = " ".join(filter(None, [given, family])) or None

        return author_data

    def _extract_custodian(self, root: ET.Element, ns: str) -> Optional[str]:
        custodian_el = root.find(f".//{ns}custodian")
        if custodian_el is None:
            return None
        org_name_el = custodian_el.find(f".//{ns}representedCustodianOrganization/{ns}name")
        if org_name_el is not None and org_name_el.text:
            return org_name_el.text.strip()
        return None

    def _extract_sections(self, root: ET.Element, ns: str) -> List[Dict[str, Any]]:
        sections = []
        component_els = root.findall(f".//{ns}component/{ns}structuredBody/{ns}component")

        if not component_els:
            component_els = root.findall(f".//{ns}structuredBody/{ns}component")

        for component in component_els:
            section_el = component.find(f"{ns}section")
            if section_el is None:
                continue

            section_data = {
                "code": self._extract_attribute(section_el, f"{ns}code", "code"),
                "code_system": self._extract_attribute(section_el, f"{ns}code", "codeSystem"),
                "title": self._extract_text(section_el, f"{ns}title"),
                "text": self._extract_section_text(section_el, ns),
            }
            sections.append(section_data)

        return sections

    def _extract_section_text(self, section_el: ET.Element, ns: str) -> Optional[str]:
        text_el = section_el.find(f"{ns}text")
        if text_el is None:
            return None
        text_parts = []
        if text_el.text:
            text_parts.append(text_el.text.strip())
        for child in text_el.iter():
            if child.text and child is not text_el:
                text_parts.append(child.text.strip())
            if child.tail:
                text_parts.append(child.tail.strip())
        combined = " ".join(p for p in text_parts if p)
        return re.sub(r"\s+", " ", combined).strip() or None
