class ComputationCacheModule:
    """LRU-ish cache for expensive computations shared across modules."""

    def get(self, key):
        with computation_cache["lock"]:
            entry = computation_cache["store"].get(key)
            if entry is None:
                return None
            entry["hits"] += 1
            try:
                computation_cache["eviction_order"].remove(key)
            except ValueError:
                pass
            computation_cache["eviction_order"].append(key)
            return copy.deepcopy(entry["value"])

    def put(self, key, value):
        with computation_cache["lock"]:
            if key in computation_cache["store"]:
                try:
                    computation_cache["eviction_order"].remove(key)
                except ValueError:
                    pass
            elif len(computation_cache["store"]) >= computation_cache["max_size"]:
                self._evict()

            computation_cache["store"][key] = {
                "value": value,
                "timestamp": _now(),
                "hits": 0,
            }
            computation_cache["eviction_order"].append(key)

    def _evict(self):
        while computation_cache["eviction_order"] and len(computation_cache["store"]) >= computation_cache["max_size"]:
            oldest_key = computation_cache["eviction_order"].popleft()
            computation_cache["store"].pop(oldest_key, None)

    def clear(self):
        with computation_cache["lock"]:
            computation_cache["store"].clear()
            computation_cache["eviction_order"].clear()

    def stats(self):
        with computation_cache["lock"]:
            return {
                "size": len(computation_cache["store"]),
                "max_size": computation_cache["max_size"],
                "keys": list(computation_cache["store"].keys()),
            }


