class AnalysisModule:
    """Runs analyses over datasets, records results, uses cache."""

    def compute(self, exp_id, dataset_id, analysis_fn, analysis_name="analysis", cache=True):
        dataset_record = DataPipelineModule().get_dataset(dataset_id)
        if dataset_record is None:
            raise KeyError(f"Unknown dataset {dataset_id}")
        data = dataset_record["data"]

        result_value = None
        cache_key = None
        if cache:
            cache_key = f"{exp_id}:{dataset_id}:{analysis_name}:{_hash_obj(str(data))}"
            cached_result = ComputationCacheModule().get(cache_key)
            if cached_result is not None:
                result_value = cached_result

        if result_value is None:
            result_value = analysis_fn(data)
            if cache:
                ComputationCacheModule().put(cache_key, result_value)

        result_record = {
            "id": _new_id("result"),
            "experiment_id": exp_id,
            "dataset_id": dataset_id,
            "analysis_name": analysis_name,
            "value": result_value,
            "timestamp": _now(),
        }

        with result_accumulator["lock"]:
            result_accumulator["results"][exp_id].append(result_record)

        return result_record

    def aggregate(self, exp_id, aggregator_fn=None):
        with result_accumulator["lock"]:
            results = list(result_accumulator["results"].get(exp_id, []))

        if aggregator_fn is None:
            def aggregator_fn(values):
                numeric = [v for v in values if isinstance(v, (int, float))]
                if not numeric:
                    return {"count": len(values)}
                return {
                    "count": len(numeric),
                    "sum": sum(numeric),
                    "mean": sum(numeric) / len(numeric),
                    "min": min(numeric),
                    "max": max(numeric),
                }

        values = [r["value"] for r in results]
        agg = aggregator_fn(values)

        with result_accumulator["lock"]:
            result_accumulator["aggregates"][exp_id] = agg

        return agg

    def get_results(self, exp_id):
        with result_accumulator["lock"]:
            return copy.deepcopy(result_accumulator["results"].get(exp_id, []))

    def get_aggregate(self, exp_id):
        with result_accumulator["lock"]:
            return copy.deepcopy(result_accumulator["aggregates"].get(exp_id))


