def _now():
    return time.time()


def _new_id(prefix="id"):
    return f"{prefix}_{uuid.uuid4().hex[:12]}"


def _hash_obj(obj):
    try:
        payload = json.dumps(obj, sort_keys=True, default=str)
    except TypeError:
        payload = str(obj)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


