class ExperimentModule:
    """Handles creation, configuration, and lifecycle of experiments."""

    def create_experiment(self, name, config=None, researcher_id=None, seed=None, cpu=1, memory_gb=1):
        config = config or {}
        exp_id = _new_id("exp")

        with experiment_context["lock"]:
            experiment_context["active_experiments"][exp_id] = {
                "id": exp_id,
                "name": name,
                "config": copy.deepcopy(config),
                "status": "created",
                "created_at": _now(),
                "researcher_id": researcher_id,
                "dataset_ids": [],
            }
            experiment_context["history"].append(exp_id)
            experiment_context["current_experiment_id"] = exp_id

        # Track reproducibility metadata
        with reproducibility_tracker["lock"]:
            actual_seed = seed if seed is not None else uuid.uuid4().int % (2**32)
            reproducibility_tracker["seeds"][exp_id] = actual_seed
            reproducibility_tracker["environment_snapshots"][exp_id] = {
                "python_version": "3.x",
                "timestamp": _now(),
            }
            reproducibility_tracker["code_hashes"][exp_id] = _hash_obj(config)
            reproducibility_tracker["run_log"].append({
                "experiment_id": exp_id,
                "event": "created",
                "timestamp": _now(),
            })

        # Allocate resources
        self.allocate_resources(exp_id, cpu=cpu, memory_gb=memory_gb)

        return exp_id

    def allocate_resources(self, exp_id, cpu=1, memory_gb=1):
        with resource_allocation["lock"]:
            if resource_allocation["available_cpu"] < cpu or resource_allocation["available_memory_gb"] < memory_gb:
                raise RuntimeError(
                    f"Insufficient resources: requested cpu={cpu}, memory_gb={memory_gb}; "
                    f"available cpu={resource_allocation['available_cpu']}, "
                    f"memory_gb={resource_allocation['available_memory_gb']}"
                )
            resource_allocation["allocated"][exp_id] = {"cpu": cpu, "memory_gb": memory_gb}
            resource_allocation["available_cpu"] -= cpu
            resource_allocation["available_memory_gb"] -= memory_gb

    def release_resources(self, exp_id):
        with resource_allocation["lock"]:
            alloc = resource_allocation["allocated"].pop(exp_id, None)
            if alloc:
                resource_allocation["available_cpu"] += alloc["cpu"]
                resource_allocation["available_memory_gb"] += alloc["memory_gb"]

