            if exp is None:
                raise KeyError(f"Unknown experiment {exp_id}")
            exp["dataset_ids"].append(dataset_id)

    def complete_experiment(self, exp_id):
        self.set_status(exp_id, "completed")
        self.release_resources(exp_id)

    def get_experiment(self, exp_id):
        with experiment_context["lock"]:
            return copy.deepcopy(experiment_context["active_experiments"].get(exp_id))

    def list_experiments(self):
        with experiment_context["lock"]:
            return list(experiment_context["history"])


